def _try_click_tab_chip(
    d: u2.Device, selector, height: int, name: str, *, wait_timeout: float = 0.12
) -> bool:
    try:
        if not selector.wait(timeout=wait_timeout):
            return False
        b = selector.info["bounds"]
        cy = (b["top"] + b["bottom"]) // 2
        if cy > int(height * _TAB_CHIP_MAX_Y_RATIO):
            return False
        selector.click()
        log("info", "accounts_tab_opened", strategy=name, y=cy)
        time.sleep(0.12)
        return True
    except Exception:
        return False


def _accounts_tab_selectors_for_label(d: u2.Device, label: str) -> list[tuple[str, object]]:
    """Pairs (strategy_name, selector object)."""
    return [
        (f"text={label}", d(className="android.widget.TextView", text=label)),
        (f"textContains={label}", d(className="android.widget.TextView", textContains=label)),
        (f"desc={label}", d(description=label)),
        (f"descContains={label}", d(descriptionContains=label)),
    ]


def open_accounts_tab(d: u2.Device) -> bool:
    """
    Select the Accounts / People / … chip if present (short budget — then mixed-results mode).
    """
    deadline = time.monotonic() + config.ACCOUNTS_TAB_TRY_MAX_S
    _w, h = d.window_size()
    chip_wait = min(0.08, max(0.04, config.ACCOUNTS_TAB_TRY_MAX_S / 20))

    for label in _ACCOUNTS_TAB_LABELS:
        if time.monotonic() >= deadline:
            break
        for strat, sel in _accounts_tab_selectors_for_label(d, label):
            if time.monotonic() >= deadline:
                break
            if _try_click_tab_chip(d, sel, h, strat, wait_timeout=chip_wait):
                return True

    log(
        "warning",
        "accounts_tab_not_found",
        budget_s=config.ACCOUNTS_TAB_TRY_MAX_S,
        message="Switching to mixed_results search UI mode.",
    )
    if getattr(config, "ACCOUNTS_TAB_DEBUG_DUMP", False):
        _dump_accounts_tab_debug(d)
    return False


def open_search(
    d: u2.Device,
    *,
    _surface_recovery_depth: int = 0,
    source_profile_username: str = "",
    allow_percent_fallback: bool = True,
    block_if_dm_thread: bool = False,
) -> bool:
    """Open bottom-nav Search: resource-id first, short settle, exit as soon as EditText exists."""
    global _perf
    settle = min(float(getattr(config, "OPEN_SEARCH_SETTLE_S", 0.12)), 0.12)
    pkg = config.INSTAGRAM_PACKAGE
    src_user = str(source_profile_username or "").strip()

    if block_if_dm_thread and is_dm_thread_screen(d, pkg):
        log(
            "error",
            "dm_sender_open_search_blocked_from_dm_thread",
            source_profile_username=src_user or None,
            foreground_package=_current_foreground_package(d),
        )
        return False

    if should_reuse_search_surface(d, pkg):
        if is_followers_list_surface_quick(d, source_profile_username=src_user):
            invalidate_search_surface_cache("followers_list_local_search")
            _log_followers_local_search_rejected(
                phase="open_search_cache_reuse",
                source_profile_username=src_user,
                detail="cache_hit_blocked",
            )
        elif apply_search_surface_reuse_metrics(
            d, pkg, "cache_ttl", source_profile_username=src_user
        ):
            log("info", "search_surface_cache_hit", message="TTL cache + EditText ok")
            return True

    if is_lightweight_search_screen(d, pkg):
        if is_followers_list_surface_quick(d, source_profile_username=src_user):
            invalidate_search_surface_cache("followers_list_local_search")
            _log_followers_local_search_rejected(
                phase="open_search_lightweight",
                source_profile_username=src_user,
                detail="lightweight_blocked",
            )
        elif apply_search_surface_reuse_metrics(
            d, pkg, "lightweight_signals", source_profile_username=src_user
        ):
            return True

    _perf["search_surface_reused"] = False
    _perf["search_open_skipped_ms"] = 0.0
    t_click_phase = time.perf_counter()
    clicked = False
    click_name: str | None = None

    for suffix in _SEARCH_TAB_RID_SUFFIXES:
        try:
            sel = d(resourceIdMatches=f".*:id/{suffix}")
            if sel.wait(timeout=0.06):
                sel.click()
                clicked = True
                click_name = f"rid_matches_{suffix}"
                log("info", "open_search_clicked", selector=click_name)
                break
        except Exception as e:
            log("debug", "open_search_rid_failed", suffix=suffix, error=str(e))

    if not clicked:
        for ipkg in _instagram_package_candidates(d):
            for suffix in _SEARCH_TAB_RID_SUFFIXES:
                rid = f"{ipkg}:id/{suffix}"
                try:
                    s = d(resourceId=rid)
                    if s.wait(timeout=0.05):
                        s.click()
                        clicked = True
                        click_name = rid
                        log("info", "open_search_clicked", selector=click_name)
                        break
                except Exception:
                    continue
            if clicked:
                break

    if not clicked:
        selectors: list[tuple[str, Callable[[], object]]] = [
            ("desc_en", lambda: d(descriptionContains="Search")),
            ("desc_fr", lambda: d(descriptionContains="Recherche")),
            ("desc_explore", lambda: d(descriptionContains="Search and explore")),
            ("desc_explorer", lambda: d(descriptionContains="Explorer")),
        ]
        for name, factory in selectors:
            try:
                o = factory()
                if o.wait(timeout=0.05):
                    o.click()
                    clicked = True
                    click_name = name
                    log("info", "open_search_clicked", selector=name)
                    break
            except Exception as e:
                log("debug", "open_search_attempt_failed", selector=name, error=str(e))

    if not clicked:
        if not allow_percent_fallback:
            log(
                "error",
                "open_search_no_selector_percent_fallback_disabled",
                source_profile_username=src_user or None,
                block_if_dm_thread=bool(block_if_dm_thread),
            )
            return False
        w, h = d.window_size()
        d.click(int(w * 0.72), int(h * 0.94))
        click_name = "percent_fallback"
        _perf["recovery_used"] = True
        log("warning", "open_search_fallback_tap", x_ratio=0.72, y_ratio=0.94)

    search_click_ms = (time.perf_counter() - t_click_phase) * 1000
    time.sleep(settle)

    t_wait = time.perf_counter()
    ed = retry_until(
        lambda: _wait_search_edittext(d),
        timeout_s=config.OPEN_SEARCH_MAX_WAIT_S,
        poll_s=config.UI_FAST_POLL_S,
        desc="open_search_edittext",
    )
    if ed is None:
        ed = _wait_search_edittext(d)
    search_field_ready_ms = (time.perf_counter() - t_wait) * 1000
    ok = ed is not None

    _perf["search_click_ms"] = search_click_ms
    _perf["search_field_ready_ms"] = search_field_ready_ms
    log(
        "info",
        "open_search_timing",
        search_click_ms=round(search_click_ms, 2),
        search_field_ready_ms=round(search_field_ready_ms, 2),
        selector=click_name,
        ok=ok,
    )
    if not ok:
        invalidate_search_surface_cache("open_search_no_edittext")
        return False

    strict_ok, strict_why = instagram_search_surface_strict_ok(
        d, ed, pkg=pkg, source_profile_username=src_user
    )
    if strict_ok:
        log(
            "info",
            "instagram_search_surface_verified",
            phase="open_search",
            detail="post_edittext",
            selector=click_name,
        )
        _mark_search_surface_ok(d, pkg)
        return True

    log(
        "info",
        "wrong_search_surface_detected",
        phase="open_search",
        detail=strict_why,
        selector=click_name,
        foreground_package=_current_foreground_package(d),
        edittext_package=_edittext_package_name(ed),
        instagram_package=pkg,
    )
    invalidate_search_surface_cache(f"open_search_strict_surface_failed:{strict_why}")
    if _surface_recovery_depth >= 1:
        log(
            "error",
            "search_surface_wrong_app_launcher",
            phase="open_search",
            after_recovery=False,
            verify_reason=strict_why,
            foreground_package=_current_foreground_package(d),
        )
        return False

    if recover_instagram_search_surface_after_launcher_mixup(
        d,
        phase="open_search",
        detail=strict_why,
        source_profile_username="",
        source_account_context=None,
    ):
        return open_search(
            d,
            _surface_recovery_depth=_surface_recovery_depth + 1,
            source_profile_username=src_user,
        )

    return False


def _wait_search_edittext(d: u2.Device):
    ed = d(className="android.widget.EditText")
    if ed.wait(timeout=0.08):
        return ed
    return None


def _normalize_search_field_visible_text(s: str | None) -> str:
    return " ".join((s or "").split()).strip().lower()


# Instagram search bar shows hint/placeholder as get_text() on some builds — treat as empty.
_SEARCH_PLACEHOLDER_NORMALIZED: frozenset[str] = frozenset(
    _normalize_search_field_visible_text(x)
    for x in (
        "Search",
        "Search with Meta AI",
        "Recherche",
        "Rechercher",
        "Search or type URL",
    )
)


def _is_search_placeholder(text: str | None) -> bool:
    if text is None:
        return True
    key = _normalize_search_field_visible_text(text)
    if not key:
        return True
    return key in _SEARCH_PLACEHOLDER_NORMALIZED


def _search_edittext_text_strip(ed) -> str:
    try:
        return (ed.get_text() or "").strip()
    except Exception:
        return ""


def _current_foreground_package(d: u2.Device) -> str:
    try:
        cur = d.app_current()
        return str((cur or {}).get("package") or "").strip()
    except Exception:
        return ""


def _edittext_package_name(ed) -> str:
    try:
        info = ed.info or {}
        return str(info.get("packageName") or info.get("package") or "").strip()
    except Exception:
        return ""


def _visible_text_suggests_android_launcher_search(txt: str | None) -> bool:
    key = _normalize_search_field_visible_text(txt)
    if not key:
        return False
    markers = (
        "search apps, web and more",
        "search apps",
        "web and more",
    )
    return any(m in key for m in markers)


def is_followers_list_surface_quick(
    d: u2.Device,
    *,
    source_profile_username: str = "",
) -> bool:
    """
    Fast live U2 probe for own unified followers list chrome (no XML cache / full detect).
    Used in global-search strict checks and post-exit verification hot paths.
    """
    _ = source_profile_username
    try:
        tab = d(resourceIdMatches=r".*:id/unified_follow_list_tab_layout$")
        rows = d(resourceIdMatches=r".*:id/follow_list_username$")
        if tab.exists(timeout=0.05) and rows.exists(timeout=0.05):
            return True
        try:
            if int(rows.count) >= 1 and tab.exists(timeout=0.04):
                return True
        except Exception:
            pass
    except Exception:
        pass
    return False


def is_followers_list_local_search_surface(
    d: u2.Device,
    *,
    source_profile_username: str = "",
) -> bool:
    """
    True when the visible search field belongs to a Followers list, not global Explore.
    May consult cached followers hierarchy from the last scan scroll — not safe after navigation.
    Use ``is_followers_list_local_search_surface_fresh`` after back / surface transitions.
    """
    try:
        det = detect_followers_list_screen(
            d,
            source_profile_username=str(source_profile_username or "").strip(),
        )
        return bool(det.get("is_followers_list"))
    except Exception:
        return False


def followers_dump_fresh_hierarchy(
    d: u2.Device,
    *,
    store_in_cache: bool = False,
) -> str:
    """dump_hierarchy after clearing followers detect cache (avoids stale scan XML)."""
    followers_clear_detect_hierarchy_cache()
    try:
        try:
            hier = d.dump_hierarchy(compressed=False)
        except TypeError:
            hier = d.dump_hierarchy()
        text = hier if isinstance(hier, str) else str(hier or "")
    except Exception:
        return ""
    text = str(text or "").strip()
    if store_in_cache and text:
        _followers_store_detect_hierarchy_xml(text)
    return text


def detect_followers_list_screen_fresh(
    d: u2.Device,
    *,
    source_profile_username: str = "",
    hierarchy_xml: str | None = None,
) -> tuple[dict[str, Any], str]:
    """
    Followers-list detect for post-navigation checks: never reads pre-transition cache.
    Returns (det, fresh_hierarchy_xml).
    """
    fresh_xml = str(hierarchy_xml or "").strip()
    if not fresh_xml:
        fresh_xml = followers_dump_fresh_hierarchy(d, store_in_cache=False)
    else:
        followers_clear_detect_hierarchy_cache()
    det = detect_followers_list_screen(
        d,
        source_profile_username=str(source_profile_username or "").strip(),
        hierarchy_xml=fresh_xml or None,
    )
    det["followers_detect_hierarchy_source"] = (
        "fresh_dump" if fresh_xml else "live_only_no_dump"
    )
    if str(_LAST_FOLLOWERS_DETECT_HIERARCHY_XML or "").strip():
        det["followers_detect_stale_cache_present"] = True
    else:
        det["followers_detect_stale_cache_present"] = False
    return det, fresh_xml


def observe_followers_list_surface_fresh(
    d: u2.Device,
    *,
    source_profile_username: str = "",
    artifact_stem: str,
) -> dict[str, Any]:
    """
    Fresh hierarchy detect + screenshot/XML artifacts (DM sender exit forensics).
    """
    _ensure_debug_dirs()
    stem = str(artifact_stem or "dm_sender_followers_exit").strip()
    shot_path = _SCREENSHOTS_DIR / f"{stem}.png"
    xml_path = _XML_DIR / f"{stem}.xml"
    out: dict[str, Any] = {
        "artifact_stem": stem,
        "screenshot_path": None,
        "xml_path": None,
        "followers_detected_fresh": False,
        "fresh_hierarchy_len": 0,
    }
    try:
        screenshot(d, str(shot_path))
        out["screenshot_path"] = str(shot_path)
    except Exception as e:
        out["screenshot_error"] = str(e)[:200]

    fresh_xml = followers_dump_fresh_hierarchy(d, store_in_cache=False)
    out["fresh_hierarchy_len"] = len(fresh_xml)
    try:
        xml_path.write_text(fresh_xml, encoding="utf-8")
        _bump_xml_fetch()
        out["xml_path"] = str(xml_path)
    except Exception as e:
        out["xml_write_error"] = str(e)[:200]

    det, _ = detect_followers_list_screen_fresh(
        d,
        source_profile_username=source_profile_username,
        hierarchy_xml=fresh_xml,
    )
    out["followers_detected_fresh"] = bool(det.get("is_followers_list"))
    out["current_package"] = det.get("current_package")
    out["current_activity"] = det.get("current_activity")
    out["action_bar_title"] = det.get("action_bar_title")
    out["signals"] = list(det.get("signals") or [])[:12]
    out["own_unified_followers_list_detected"] = bool(
        det.get("own_unified_followers_list_detected")
    )
    out["open_detection_method"] = det.get("open_detection_method")
    out["relaxed_list_open"] = bool(det.get("relaxed_list_open"))
    out["strict_list_open"] = bool(det.get("strict_list_open"))
    out["followers_detect_hierarchy_source"] = det.get("followers_detect_hierarchy_source")
    out["followers_detect_stale_cache_present"] = det.get(
        "followers_detect_stale_cache_present"
    )
    out["detection"] = det
    return out


def is_followers_list_local_search_surface_fresh(
    d: u2.Device,
    *,
    source_profile_username: str = "",
) -> tuple[bool, dict[str, Any]]:
    """Fresh detect only; returns (is_followers_list, observation dict)."""
    obs = observe_followers_list_surface_fresh(
        d,
        source_profile_username=source_profile_username,
        artifact_stem="dm_sender_followers_exit_probe",
    )
    return bool(obs.get("followers_detected_fresh")), obs


def tap_instagram_action_bar_back_button(
    d: u2.Device,
    pkg: str | None = None,
) -> tuple[bool, str]:
    """
    Tap the Instagram action-bar Back control (followers list / sub-screens).
    Returns (clicked, method).
    """
    pkg = str(pkg or getattr(config, "INSTAGRAM_PACKAGE", "") or "com.instagram.android")
    for ipkg in _instagram_package_candidates(d):
        rid = f"{ipkg}:id/action_bar_button_back"
        try:
            sel = d(resourceId=rid)
            if sel.wait(timeout=0.1):
                sel.click()
                return True, rid
        except Exception:
            continue
    try:
        sel = d(resourceIdMatches=r".*:id/action_bar_button_back")
        if sel.wait(timeout=0.1):
            sel.click()
            return True, "rid_matches_action_bar_button_back"
    except Exception:
        pass
    for desc in ("Back", "Navigate up", "Retour"):
        for factory in (
            lambda t=desc: d(description=t),
            lambda t=desc: d(descriptionContains=t),
        ):
            try:
                o = factory()
                if o.wait(timeout=0.08):
                    o.click()
                    return True, f"description_{desc}"
            except Exception:
                continue
    return False, "action_bar_back_not_found"


def exit_followers_list_surface(
    d: u2.Device,
    *,
    source_profile_username: str = "",
    pkg: str | None = None,
    action_bar_settle_s: float | None = None,
    hardware_back_max: int | None = None,
) -> tuple[bool, str]:
    """
    Leave a Followers list: action-bar Back first, then bounded hardware Back fallback.
    Returns (ok, method).
    """
    pkg = str(pkg or getattr(config, "INSTAGRAM_PACKAGE", "") or "com.instagram.android")
    src = str(source_profile_username or "").strip()
    settle = float(
        action_bar_settle_s
        if action_bar_settle_s is not None
        else getattr(config, "DM_SENDER_FOLLOWERS_EXIT_SETTLE_S", 0.45) or 0.45
    )
    hw_max = max(
        0,
        int(
            hardware_back_max
            if hardware_back_max is not None
            else getattr(config, "DM_SENDER_FOLLOWERS_EXIT_HARDWARE_BACK_MAX", 3) or 3
        ),
    )

    det0, _ = detect_followers_list_screen_fresh(d, source_profile_username=src)
    if not bool(det0.get("is_followers_list")):
        return True, "not_on_followers_list"

    clicked, tap_method = tap_instagram_action_bar_back_button(d, pkg)
    if clicked:
        time.sleep(settle)
        det_ab, _ = detect_followers_list_screen_fresh(d, source_profile_username=src)
        if not bool(det_ab.get("is_followers_list")):
            return True, f"action_bar_back:{tap_method}"

    for step in range(hw_max):
        try:
            d.press("back")
        except Exception:
            pass
        time.sleep(settle)
        det_hw, _ = detect_followers_list_screen_fresh(d, source_profile_username=src)
        if not bool(det_hw.get("is_followers_list")):
            return True, f"hardware_back:{step + 1}"

    return False, "still_on_followers_list"


def _log_followers_local_search_rejected(
    *,
    phase: str,
    source_profile_username: str = "",
    detail: str = "",
) -> None:
    log(
        "info",
        "dm_sender_local_followers_search_surface_rejected",
        phase=phase,
        source_profile_username=str(source_profile_username or "")[:160],
        detail=detail,
    )


def instagram_search_surface_strict_ok(
    d: u2.Device,
    ed,
    *,
    pkg: str | None = None,
    source_profile_username: str = "",
) -> tuple[bool, str]:
    """
    True only when Instagram is foreground, the focused search EditText is from IG,
    and the field text is not the Android launcher / universal search placeholder.
    Rejects Followers-list local search bars (DM sender / global search must not reuse them).
    """
    pkg = str(pkg or getattr(config, "INSTAGRAM_PACKAGE", "") or "")
    fg = _current_foreground_package(d)
    if fg != pkg:
        return False, f"foreground_package_mismatch:{fg}"
    ed_pkg = _edittext_package_name(ed)
    if ed_pkg and ed_pkg != pkg:
        return False, f"edittext_package_mismatch:{ed_pkg}"
    if is_followers_list_surface_quick(
        d, source_profile_username=source_profile_username
    ):
        _log_followers_local_search_rejected(
            phase="instagram_search_surface_strict_ok",
            source_profile_username=source_profile_username,
            detail="followers_list_quick_probe",
        )
        return False, "followers_list_local_search_surface"
    txt = _search_edittext_text_strip(ed)
    if _visible_text_suggests_android_launcher_search(txt):
        return False, "launcher_search_hint_in_field"
    return True, "ok"


def _field_still_matches_previous_query(cur: str, previous_username: str | None) -> bool:
    if not previous_username or not cur:
        return False
    if _is_search_placeholder(cur):
        return False
    prev = _normalize_handle(previous_username)
    cur_n = _normalize_handle(cur)
    if not prev:
        return False
    return prev == cur_n or cur_n.startswith(prev) or prev in cur_n


def _search_field_clear_snapshot_ok(txt: str, previous_username: str | None) -> bool:
    """True when field is empty, placeholder hint, or otherwise safe to type a new query."""
    if not (txt or "").strip():
        return True
    if _is_search_placeholder(txt):
        return True
    if previous_username and _field_still_matches_previous_query(txt, previous_username):
        return False
    return False


def _log_search_field_clear_success(
    txt: str,
    methods: list[str],
    *,
    extra_method_suffix: str = "",
) -> str:
    """Log success path; returns method string for return tuple."""
    method = "+".join(methods) if methods else "clear_text"
    if extra_method_suffix:
        method = f"{method}+{extra_method_suffix}" if method else extra_method_suffix
    if _is_search_placeholder(txt):
        log(
            "info",
            "search_field_placeholder_detected",
            placeholder_preview=(txt or "")[:120],
        )
        log("info", "search_field_effectively_empty", state="placeholder")
    else:
        log("info", "search_field_effectively_empty", state="empty")
    log("info", "search_field_clear_success", search_field_clear_method=method)
    return method


def clear_search_field_robust(
    d: u2.Device,
    serial: str | None,
    *,
    ed: object | None = None,
    previous_username: str | None = None,
    intended_username: str = "",
) -> tuple[bool, str]:
    """
    Clear Instagram search EditText before typing (multi-target safe). No XML.
    Returns (success, method_summary).
    """
    log(
        "info",
        "search_field_clear_started",
        intended_username=intended_username,
        has_previous=bool(previous_username),
    )
    if ed is None:
        ed = _wait_search_edittext(d)
    if ed is None:
        log("error", "search_field_clear_failed", reason="no_edittext", search_field_clear_method="none")
        return False, "none"

    try:
        pre_txt = _search_edittext_text_strip(ed)
    except Exception:
        pre_txt = ""
    if _search_field_clear_snapshot_ok(pre_txt, previous_username):
        log(
            "info",
            "search_field_clear_skipped_already_empty",
            intended_username=intended_username,
            text_preview=(pre_txt or "")[:120],
            is_placeholder=_is_search_placeholder(pre_txt),
        )
        return True, "skipped_already_empty"

    try:
        ed.click()
        time.sleep(0.05)
    except Exception:
        pass

    methods: list[str] = []

    def _refresh_ed():
        nonlocal ed
        try:
            nxt = _wait_search_edittext(d)
            if nxt is not None:
                ed = nxt
        except Exception:
            pass

    def _snapshot() -> str:
        return _search_edittext_text_strip(ed)

    # A–D: clear_text + verify (empty and localized placeholders count as clear)
    try:
        ed.clear_text()
        methods.append("clear_text")
    except Exception as e:
        log("debug", "search_field_clear_text_failed", error=str(e))
    time.sleep(0.05)
    txt = _snapshot()
    if _search_field_clear_snapshot_ok(txt, previous_username):
        m = _log_search_field_clear_success(txt, methods)
        return True, m

    try:
        ed.set_text("")
        methods.append("set_text_empty")
    except Exception:
        pass
    time.sleep(0.05)
    txt = _snapshot()
    if _search_field_clear_snapshot_ok(txt, previous_username):
        m = _log_search_field_clear_success(txt, methods)
        return True, m

    # E: KEYCODE_DEL (67) via adb in batches (e.g. stuck real query; hints may reappear as placeholder)
    max_ev = int(getattr(config, "SEARCH_FIELD_CLEAR_MAX_DEL_EVENTS", 120))
    batch = int(getattr(config, "SEARCH_FIELD_CLEAR_DEL_BATCH_SIZE", 12))
    sent = 0
    del_batches = 0
    while sent < max_ev:
        chunk = min(batch, max_ev - sent)
        try:
            keys = " ".join(["67"] * chunk)
            code, _, _ = shell(d, f"input keyevent {keys}")
            if code != 0:
                for _ in range(chunk):
                    shell(d, "input keyevent 67")
        except Exception:
            for _ in range(chunk):
                try:
                    shell(d, "input keyevent 67")
                except Exception:
                    pass
        sent += chunk
        del_batches += 1
        time.sleep(0.04)
        _refresh_ed()
        txt = _snapshot()
        if _search_field_clear_snapshot_ok(txt, previous_username):
            extra = f"keyevent_67_batches_{del_batches}_total_{sent}"
            m = _log_search_field_clear_success(txt, methods, extra_method_suffix=extra)
            return True, f"del_total_{sent}"

    txt = _snapshot()
    if _search_field_clear_snapshot_ok(txt, previous_username):
        m = _log_search_field_clear_success(
            txt,
            methods,
            extra_method_suffix=f"keyevent_67_batches_{del_batches}_edge",
        )
        return True, "edge_empty_after_del"

    still_prev = bool(previous_username) and _field_still_matches_previous_query(
        txt, previous_username
    )
    unknown_typed = bool((txt or "").strip()) and not _is_search_placeholder(txt)
    log(
        "error",
        "search_field_clear_failed",
        remaining_preview=txt[:120],
        search_field_clear_method="+".join(methods + [f"keyevent_67_batches_{del_batches}"]),
        remaining_len=len(txt),
        still_matches_previous=still_prev,
        non_placeholder_unknown=unknown_typed and not still_prev,
    )
    return False, "incomplete"


def _typing_confirmed(d: u2.Device, ed, username: str) -> bool:
    """
    After fast IME broadcast (or any typing): success when search EditText shows the handle
    OR a row_search_user_username element matches the exact username.
    """
    try:
        cur = ed.get_text() or ""
        if username in cur or _normalize_handle(cur) == _normalize_handle(username):
            return True
    except Exception:
        pass
    if find_username_elements_by_resource_id(d, username):
        return True
    return False


def _resolve_search_edittext_for_type_search(
    d: u2.Device,
    *,
    follow_ct_typing: bool,
    desc: str,
) -> object | None:
    if follow_ct_typing:
        t0 = time.perf_counter()
        ed = _wait_search_edittext(d)
        if ed is not None:
            log(
                "info",
                "follow_ct_search_edittext_short_wait_used",
                phase=desc,
                immediate_probe=True,
                wait_ms=round((time.perf_counter() - t0) * 1000, 2),
            )
            return ed
        short_s = float(
            getattr(config, "FOLLOW_CT_SEARCH_FIELD_WAIT_S", 0.4) or 0.4
        )
        short_s = max(0.2, min(0.5, short_s))
        ed = retry_until(
            lambda: _wait_search_edittext(d),
            timeout_s=short_s,
            poll_s=config.UI_FAST_POLL_S,
            desc=f"{desc}_follow_ct_short",
        )
        log(
            "info",
            "follow_ct_search_edittext_short_wait_used",
            phase=desc,
            immediate_probe=False,
            short_retry_s=short_s,
            wait_ms=round((time.perf_counter() - t0) * 1000, 2),
            found=ed is not None,
        )
        return ed
    return retry_until(
        lambda: _wait_search_edittext(d),
        timeout_s=config.SEARCH_FIELD_WAIT_S,
        poll_s=config.UI_FAST_POLL_S,
        desc=desc,
    )


def type_search(
    d: u2.Device,
    username: str,
    *,
    previous_username: str | None = None,
    follow_ct_surface_confirmed: bool = False,
) -> bool:
    """Robust clear, then FastIME or set_text; fused row detect when FastIME."""
    global _perf, _TYPE_SEARCH_FAILURE_REASON
    _TYPE_SEARCH_FAILURE_REASON = None
    _clear_pending_fused_fast_ime_row()
    follow_ct_typing = bool(follow_ct_surface_confirmed) or is_follow_ct_search_context_active()
    if follow_ct_surface_confirmed or consume_search_surface_fresh_for_follow_ct():
        log(
            "info",
            "follow_ct_search_surface_fast_path_used",
            username=str(username or "")[:80],
        )
    t_typ = time.perf_counter()
    ed = _resolve_search_edittext_for_type_search(
        d, follow_ct_typing=follow_ct_typing, desc="search_edittext"
    )
    if ed is None:
        log(
            "warning",
            "search_edittext_missing_try_fallback_tap",
            message="Tapping top search bar area then retrying EditText detection.",
        )
        _perf["recovery_used"] = True
        _tap_search_bar_fallback(d)
        retry_s = (
            float(getattr(config, "FOLLOW_CT_SEARCH_FIELD_WAIT_S", 0.4))
            if follow_ct_typing
            else float(config.SEARCH_EDITTEXT_RETRY_AFTER_TAP_S)
        )
        if follow_ct_typing:
            retry_s = max(0.2, min(0.5, retry_s))
            ed = retry_until(
                lambda: _wait_search_edittext(d),
                timeout_s=retry_s,
                poll_s=config.UI_FAST_POLL_S,
                desc="search_edittext_after_fallback_tap_follow_ct",
            )
        else:
            ed = retry_until(
                lambda: _wait_search_edittext(d),
                timeout_s=config.SEARCH_EDITTEXT_RETRY_AFTER_TAP_S,
                poll_s=config.UI_FAST_POLL_S,
                desc="search_edittext_after_fallback_tap",
            )
    if ed is None:
        log("error", "search_edittext_not_found")
        invalidate_search_surface_cache("no_edittext")
        _dump_search_edittext_debug(d)
        _perf["typing_command_ms"] = (time.perf_counter() - t_typ) * 1000
        _perf["typing_confirm_ms"] = 0.0
        return False

    pkg_ig = str(getattr(config, "INSTAGRAM_PACKAGE", "") or "")
    ok_surf, surf_why = instagram_search_surface_strict_ok(d, ed, pkg=pkg_ig)
    if ok_surf:
        log(
            "info",
            "instagram_search_surface_verified",
            phase="type_search_precheck",
            detail="initial",
        )
    else:
        log(
            "info",
            "wrong_search_surface_detected",
            phase="type_search_precheck",
            detail=surf_why,
            foreground_package=_current_foreground_package(d),
            edittext_package=_edittext_package_name(ed),
            instagram_package=pkg_ig,
        )
        if not recover_instagram_search_surface_after_launcher_mixup(
            d,
            phase="type_search_precheck",
            detail=surf_why,
            source_profile_username="",
            source_account_context=None,
        ):
            _TYPE_SEARCH_FAILURE_REASON = "search_surface_wrong_app_launcher"
            _perf["typing_command_ms"] = (time.perf_counter() - t_typ) * 1000
            _perf["typing_confirm_ms"] = 0.0
            log("error", "type_search_aborted", reason="search_surface_wrong_app_launcher")
            return False
        if not open_search(d):
            _TYPE_SEARCH_FAILURE_REASON = "search_surface_wrong_app_launcher"
            _perf["typing_command_ms"] = (time.perf_counter() - t_typ) * 1000
            _perf["typing_confirm_ms"] = 0.0
            log(
                "error",
                "search_surface_wrong_app_launcher",
                phase="type_search_precheck",
                stage="open_search_after_recovery_failed",
                foreground_package=_current_foreground_package(d),
            )
            log("error", "type_search_aborted", reason="search_surface_wrong_app_launcher")
            return False
        ed = retry_until(
            lambda: _wait_search_edittext(d),
            timeout_s=config.SEARCH_FIELD_WAIT_S,
            poll_s=config.UI_FAST_POLL_S,
            desc="search_edittext_after_launcher_recovery",
        )
        if ed is None:
            _TYPE_SEARCH_FAILURE_REASON = "search_surface_wrong_app_launcher"
            _perf["typing_command_ms"] = (time.perf_counter() - t_typ) * 1000
            _perf["typing_confirm_ms"] = 0.0
            log(
                "error",
                "search_surface_wrong_app_launcher",
                phase="type_search_precheck",
                stage="no_edittext_after_recovery",
                foreground_package=_current_foreground_package(d),
            )
            log("error", "type_search_aborted", reason="search_surface_wrong_app_launcher")
            return False
        ok_surf2, surf_why2 = instagram_search_surface_strict_ok(d, ed, pkg=pkg_ig)
        if not ok_surf2:
            _TYPE_SEARCH_FAILURE_REASON = "search_surface_wrong_app_launcher"
            _perf["typing_command_ms"] = (time.perf_counter() - t_typ) * 1000
            _perf["typing_confirm_ms"] = 0.0
            log(
                "error",
                "search_surface_wrong_app_launcher",
                phase="type_search_precheck",
                after_recovery=True,
                verify_reason=surf_why2,
                foreground_package=_current_foreground_package(d),
            )
            log("error", "type_search_aborted", reason="search_surface_wrong_app_launcher")
            return False
        log(
            "info",
            "instagram_search_surface_verified",
            phase="type_search_precheck",
            detail="after_recovery",
        )

    serial = get_device_serial(d)
    t_cmd_start = time.perf_counter()
    ok_clear, clear_method = clear_search_field_robust(
        d,
        serial,
        ed=ed,
        previous_username=previous_username,
        intended_username=username,
    )
    log(
        "info",
        "search_field_clear_method",
        search_field_clear_method=clear_method,
        ok=ok_clear,
    )
    if not ok_clear:
        _TYPE_SEARCH_FAILURE_REASON = "search_field_not_cleared"
        _perf["typing_command_ms"] = (time.perf_counter() - t_typ) * 1000
        _perf["typing_confirm_ms"] = 0.0
        log("error", "type_search_aborted", reason="search_field_not_cleared")
        return False

    ed = _wait_search_edittext(d) or ed
    preview = _search_edittext_text_strip(ed)
    log(
        "info",
        "search_field_before_typing_text",
        text_preview=preview[:100],
        text_len=len(preview),
        username=username,
    )
    if not _search_field_clear_snapshot_ok(preview, previous_username):
        _TYPE_SEARCH_FAILURE_REASON = "search_field_not_cleared"
        _perf["typing_command_ms"] = (time.perf_counter() - t_typ) * 1000
        _perf["typing_confirm_ms"] = 0.0
        log(
            "error",
            "search_field_clear_failed",
            reason="non_empty_before_type",
            preview=preview[:80],
            is_placeholder=_is_search_placeholder(preview),
            still_matches_previous=_field_still_matches_previous_query(
                preview, previous_username
            ),
        )
        return False

    focused = False
    try:
        focused = bool((ed.info or {}).get("focused"))
    except Exception:
        pass
    if not focused:
        try:
            ed.click()
            time.sleep(0.04)
        except Exception:
            pass

    typing_method = "set_text"
    used_fast_path = False
    fast_ime = getattr(config, "FAST_IME", "") or ""
    fast_ime_switch_ok: bool | None = None
    fast_ime_broadcast_ok: bool | None = None

    if follow_ct_typing:
        log(
            "info",
            "follow_ct_search_direct_set_text_used",
            username=str(username or "")[:80],
        )
        try:
            ed.set_text(username)
            typing_method = "set_text"
        except Exception:
            typing_method = "send_keys"
            try:
                d.send_keys(username)
            except Exception:
                typing_method = "shell_input"
                safe = username.replace(" ", "%s")
                shell(d, f"input text {safe}")
    elif fast_ime and is_fast_ime_available(serial):
        ok_cmd, tag, fast_ime_switch_ok, fast_ime_broadcast_ok = run_fast_ime_input(
            serial, username, fast_ime_id=fast_ime
        )
        log(
            "info",
            "fast_ime_typing",
            typing_method="fast_ime",
            fast_ime_switch_ok=fast_ime_switch_ok,
            fast_ime_broadcast_ok=fast_ime_broadcast_ok,
            command_ok=ok_cmd,
        )
        if ok_cmd:
            typing_method = tag
            used_fast_path = True

    if not follow_ct_typing and not used_fast_path:
        try:
            ed.set_text(username)
            typing_method = "set_text"
        except Exception:
            typing_method = "send_keys"
            try:
                d.send_keys(username)
            except Exception:
                typing_method = "shell_input"
                safe = username.replace(" ", "%s")
                shell(d, f"input text {safe}")

    if used_fast_path:
        settle = min(
            0.15,
            float(getattr(config, "FAST_IME_POST_BROADCAST_SETTLE_S", 0.15)),
        )
        time.sleep(settle)
        typing_command_ms = (time.perf_counter() - t_cmd_start) * 1000
        _perf["typing_command_ms"] = typing_command_ms
        _perf["typing_confirm_ms"] = 0.0
        _set_pending_fused_fast_ime_row(username)
        st_log: dict = {
            "username": username,
            "typing_method": typing_method,
            "typing_confirm_ms": 0.0,
            "ok": True,
            "fused_row_confirm_deferred": True,
        }
        if fast_ime_switch_ok is not None:
            st_log["fast_ime_switch_ok"] = fast_ime_switch_ok
            st_log["fast_ime_broadcast_ok"] = bool(fast_ime_broadcast_ok)
        log("info", "search_typed", **st_log)
        _follow_ct_prewarm_serp_band_cache(d)
        return True

    typing_command_ms = (time.perf_counter() - t_cmd_start) * 1000
    _perf["typing_command_ms"] = typing_command_ms

    def _confirm_typing_deadline() -> float:
        return time.monotonic() + float(
            getattr(config, "TYPING_CONFIRM_MAX_S", config.TYPE_SEARCH_CONFIRM_S)
        )

    # Non-fastIME: field text or row_search_user_username (exact handle).
    t_confirm_start = time.perf_counter()
    deadline = _confirm_typing_deadline()
    while time.monotonic() < deadline:
        if _typing_confirmed(d, ed, username):
            break
        time.sleep(config.UI_FAST_POLL_S)
    typing_confirm_ms = (time.perf_counter() - t_confirm_start) * 1000

    ok = _typing_confirmed(d, ed, username)

    _perf["typing_confirm_ms"] = typing_confirm_ms
    st_log: dict = {
        "username": username,
        "typing_method": typing_method,
        "typing_confirm_ms": round(typing_confirm_ms, 2),
        "ok": ok,
    }
    if fast_ime_switch_ok is not None:
        st_log["fast_ime_switch_ok"] = fast_ime_switch_ok
        st_log["fast_ime_broadcast_ok"] = bool(fast_ime_broadcast_ok)
    log("info", "search_typed", **st_log)
    if ok:
        _mark_search_surface_ok(d, config.INSTAGRAM_PACKAGE)
        if follow_ct_typing:
            _follow_ct_prewarm_serp_band_cache(d)
    else:
        invalidate_search_surface_cache("type_not_confirmed")
    return ok


def find_exact_account_result(d: u2.Device, username: str):
    """Alias for real-account selection (avatar-aware)."""
    return find_real_account_text_element(d, username)


def _bounds_contain(outer: dict, inner: dict) -> bool:
    return (
        outer["left"] <= inner["left"]
        and outer["right"] >= inner["right"]
        and outer["top"] <= inner["top"]
        and outer["bottom"] >= inner["bottom"]
    )


def _tap_bounds_for_account_row(d: u2.Device, el) -> dict:
    """Username view center, or a larger clickable ancestor row if the view is a thin label."""
    w, _h = d.window_size()
    try:
        b = {k: int(el.info["bounds"][k]) for k in ("left", "top", "right", "bottom")}
    except Exception:
        return {}
    row_h = b["bottom"] - b["top"]
    min_h = _scale_px(48, w)
    if row_h >= min_h:
        return b
    try:
        ax = el.xpath('ancestor::*[@clickable="true"]')
        ancestors = ax.all() if hasattr(ax, "all") else []
        for anc in ancestors[:8]:
            try:
                b2 = {k: int(anc.info["bounds"][k]) for k in ("left", "top", "right", "bottom")}
                if b2["bottom"] - b2["top"] >= max(min_h, int(row_h * 1.12)) and _bounds_contain(
                    b2, b
                ):
                    return b2
            except Exception:
                continue
    except Exception:
        pass
    return b


def _tap_hot_username_center_jitter(d: u2.Device, el) -> tuple[int, int, dict]:
    """Direct tap on username view bounds center ± tiny jitter (no parent traversal)."""
    try:
        b = {k: int(el.info["bounds"][k]) for k in ("left", "top", "right", "bottom")}
    except Exception:
        return 0, 0, {}
    j = 2
    cx = (b["left"] + b["right"]) // 2 + random.randint(-j, j)
    cy = (b["top"] + b["bottom"]) // 2 + random.randint(-j, j)
    w, h = d.window_size()
    cx = max(1, min(w - 1, cx))
    cy = max(1, min(h - 1, cy))
    return cx, cy, b


def _try_dismiss_keyboard_light(d: u2.Device) -> None:
    """Avoid false negatives when IME still up; does not rely on back (navigation)."""
    try:
        ed = d(className="android.widget.EditText")
        if not ed.wait(timeout=0.05):
            return
        info = ed.info
        if not info.get("focused"):
            return
        w, h = d.window_size()
        d.click(w // 2, int(h * 0.38))
        time.sleep(0.08)
    except Exception:
        pass


def _profile_signal_a_header_ids(d: u2.Device) -> str | None:
    try:
        if d(resourceIdMatches=".*:id/profile_header.*").wait(timeout=0.08):
            return "header_resource_id"
    except Exception:
        pass
    try:
        if d(resourceIdMatches=".*profile_header.*").wait(timeout=0.06):
            return "header_resource_id"
    except Exception:
        pass
    try:
        if d(resourceIdMatches=".*:id/action_bar_title").wait(timeout=0.08):
            return "action_bar_title_resource_id"
    except Exception:
        pass
    try:
        if d(resourceIdMatches=".*action_bar_title.*").wait(timeout=0.06):
            return "action_bar_title_resource_id"
    except Exception:
        pass
    return None


def _profile_signal_b_username_top_band(d: u2.Device, username: str) -> str | None:
    """Exact handle TextView in top ~35% — UiSelector only, no XML walk."""
    w, h = d.window_size()
    y_max = int(h * 0.35)
    target = _normalize_handle(username)
    for disp in _account_row_search_texts(username):
        try:
            o = d(className="android.widget.TextView", text=disp)
            if not o.wait(timeout=0.05):
                continue
            b = o.info["bounds"]
            if int(b["top"]) > y_max:
                continue
            if _normalize_handle(o.get_text() or "") != target:
                continue
            return "username_top_band"
        except Exception:
            continue
    return None


def _profile_signal_c_chrome(d: u2.Device, package: str) -> str | None:
    """Instagram foreground + any common profile chrome control."""
    try:
        cur = d.app_current()
        if (cur or {}).get("package", "") != package:
            return None
    except Exception:
        return None

    checks: list[tuple[str, list[Callable[[], object]]]] = [
        (
            "follow_button",
            [
                lambda: d(textContains="Follow"),
                lambda: d(descriptionContains="Follow"),
                lambda: d(text="Following"),
                lambda: d(text="Suivre"),
                lambda: d(descriptionContains="Suivre"),
            ],
        ),
        (
            "message_button",
            [
                lambda: d(textContains="Message"),
                lambda: d(text="Message"),
                lambda: d(descriptionContains="Message"),
            ],
        ),
        (
            "professional_dashboard",
            [
                lambda: d(textContains="Professional"),
                lambda: d(textContains="professional"),
            ],
        ),
        (
            "profile_tabs",
            [
                lambda: d(descriptionContains="Grid"),
                lambda: d(descriptionContains="Reels"),
                lambda: d(text="Posts"),
                lambda: d(resourceIdMatches=".*profile_tab.*"),
            ],
        ),
        (
            "bio_container",
            [
                lambda: d(resourceIdMatches=".*:id/profile_bio.*"),
                lambda: d(resourceIdMatches=".*profile_bio.*"),
                lambda: d(resourceIdMatches=".*:id/user_bio.*"),
            ],
        ),
        (
            "follower_counters",
            [
                lambda: d(textContains="followers"),
                lambda: d(textContains="Followers"),
                lambda: d(textContains="following"),
                lambda: d(textContains="abonnés"),
            ],
        ),
    ]

    for name, factories in checks:
        for fact in factories:
            try:
                el = fact()
                if el.wait(timeout=0.045):
                    return name
            except Exception:
                continue
    return None


def _early_profile_transition_signal(d: u2.Device, username: str) -> str | None:
    """
    First profile-open hints after row tap (tight resource-ids + chrome).
    Used only for transition timing; verify_profile remains authoritative.
    """
    rid_pairs = (
        ("action_bar_title", "com.instagram.android:id/action_bar_title"),
        ("profile_header", "com.instagram.android:id/profile_header"),
        ("profile_tabs_container", "com.instagram.android:id/profile_tabs_container"),
    )
    for name, rid in rid_pairs:
        try:
            o = d(resourceId=rid)
            if o.wait(timeout=0.04):
                return name
        except Exception:
            continue
    try:
        if _profile_signal_b_username_top_band(d, username):
            return "username_top_band"
    except Exception:
        pass
    quick_chrome: list[tuple[str, Callable[[], object]]] = [
        ("message", lambda: d(textContains="Message")),
        ("follow", lambda: d(textContains="Follow")),
        ("following", lambda: d(text="Following")),
        ("suivre", lambda: d(text="Suivre")),
    ]
    for name, fact in quick_chrome:
        try:
            el = fact()
            if el.wait(timeout=0.04):
                return name
        except Exception:
            continue
    return None


def _try_profile_signals_once(d: u2.Device, username: str, package: str) -> str | None:
    s = _profile_signal_a_header_ids(d)
    if s:
        return s
    s = _profile_signal_b_username_top_band(d, username)
    if s:
        return s
    s = _profile_signal_c_chrome(d, package)
    if s:
        return s
    return None


def tap_account_result(
    d: u2.Device,
    username: str,
    *,
    nav_timing_origin: float | None = None,
    follow_ct_search_context: bool = False,
) -> bool:
    """Tap chosen row: FastIME+fused uses hot resource-id poll + direct tap; else legacy find."""
    follow_ct_active = _follow_ct_search_active(explicit=follow_ct_search_context)
    try:
        log(
            "info",
            "follow_ct_search_tap_context_snapshot",
            username=username,
            follow_ct_search_context=bool(follow_ct_search_context),
            global_context_active=is_follow_ct_search_context_active(),
            follow_ct_active=bool(follow_ct_active),
            fast_ok=None,
            search_ui_mode=get_search_ui_mode(),
            resource_id="",
        )
    except Exception:
        pass

    def scan_once():
        return find_real_account_text_element(
            d,
            username,
            dump_on_failure=False,
            follow_ct_search_context=follow_ct_search_context,
        )

    def scan_once_hot():
        if not follow_ct_active:
            return None
        hot = find_first_row_search_username_hot(d, username)
        if hot is None:
            return None
        ev_hot = evaluate_row_search_username_element(
            d,
            hot,
            username,
            mixed_results=True,
            follow_ct_search_context=True,
            resource_id_hint=ROW_SEARCH_USERNAME_EXACT_RES,
        )
        if ev_hot.get("accept"):
            return hot
        return None

    def _log_first_result_seen(el_seen: object, *, via: str) -> None:
        if first_result_at[0] is not None:
            return
        first_result_at[0] = time.perf_counter()
        ms = (
            round((first_result_at[0] - t_origin) * 1000.0, 2)
            if nav_timing_origin is not None
            else None
        )
        log(
            "info",
            "dm_sender_search_result_first_seen",
            username=username,
            via=via,
            username_type_to_first_result_ms=ms,
        )

    def _log_exact_match_ready(el_match: object, *, via: str) -> None:
        if exact_match_at[0] is not None:
            return
        exact_match_at[0] = time.perf_counter()
        first_ms = (
            round((exact_match_at[0] - first_result_at[0]) * 1000.0, 2)
            if first_result_at[0] is not None
            else None
        )
        log(
            "info",
            "dm_sender_exact_result_match_ready",
            username=username,
            via=via,
            first_result_to_exact_match_ms=first_ms,
        )

    global _perf
    t_origin = (
        float(nav_timing_origin)
        if nav_timing_origin is not None
        else time.perf_counter()
    )
    first_result_at: list[float | None] = [None]
    exact_match_at: list[float | None] = [None]

    fused = _peek_pending_fused_fast_ime_row(username)
    if fused:
        _clear_pending_fused_fast_ime_row()

    hot_el_found = False
    el = None
    fast_accept_used = False
    t_detect = time.perf_counter()
    poll_s = float(getattr(config, "HOT_ROW_POLL_S", 0.12))

    if fused:
        if get_search_ui_mode() == "mixed_results":
            timeout_s = float(getattr(config, "MIXED_HOT_ROW_DETECT_MAX_S", 4.0))
        else:
            timeout_s = float(config.ACCOUNTS_RESULT_WAIT_S)
        deadline = time.monotonic() + timeout_s
        while time.monotonic() < deadline:
            hot_probe = find_first_row_search_username_hot(d, username)
            if hot_probe is not None:
                _log_first_result_seen(hot_probe, via="hot_row")
            el = hot_probe
            if el is not None:
                hot_el_found = True
                _log_exact_match_ready(el, via="hot_row")
                log(
                    "info",
                    "row_hot_path_first_match",
                    username=username,
                    search_ui_mode=get_search_ui_mode(),
                )
                break
            time.sleep(poll_s)
        if el is None:
            timeout_legacy = (
                float(getattr(config, "MIXED_RESULTS_ROW_DETECT_MAX_S", 2.5))
                if get_search_ui_mode() == "mixed_results"
                else float(config.ACCOUNTS_RESULT_WAIT_S)
            )

            def _legacy_scan():
                found = scan_once()
                if found is not None:
                    _log_first_result_seen(found, via="legacy_scan")
                    _log_exact_match_ready(found, via="legacy_scan")
                return found

            el = retry_until_jitter(
                _legacy_scan,
                timeout_s=timeout_legacy,
                poll_min_s=0.05,
                poll_max_s=0.07,
                desc="real_account_textview_after_hot_miss",
            )
            hot_el_found = False
    else:
        el = None
        fast_accept_used = False
        if get_search_ui_mode() == "mixed_results":
            if follow_ct_active:
                found_hot = scan_once_hot()
                if found_hot is not None:
                    el = found_hot
                    fast_accept_used = True
                    _log_first_result_seen(el, via="follow_ct_hot_row")
                    _log_exact_match_ready(el, via="follow_ct_hot_row")
                    log(
                        "info",
                        "exact_account_row_fast_accept_used",
                        username=username,
                        via="follow_ct_hot_row",
                    )
            fast_deadline = time.monotonic() + float(
                getattr(config, "EXACT_ACCOUNT_ROW_FAST_POLL_MAX_S", 2.0)
            )
            fast_poll_s = float(getattr(config, "EXACT_ACCOUNT_ROW_FAST_POLL_S", 0.10))
            while time.monotonic() < fast_deadline and el is None:
                found_fast = scan_once_hot() if follow_ct_active else scan_once()
                if found_fast is not None:
                    el = found_fast
                    fast_accept_used = True
                    _log_first_result_seen(el, via="fast_poll")
                    _log_exact_match_ready(el, via="fast_poll")
                    log(
                        "info",
                        "exact_account_row_fast_accept_used",
                        username=username,
                        via="fast_poll",
                    )
                    break
                time.sleep(fast_poll_s)

        if el is None:
            timeout = (
                float(getattr(config, "MIXED_RESULTS_ROW_DETECT_MAX_S", 2.5))
                if get_search_ui_mode() == "mixed_results"
                else float(config.ACCOUNTS_RESULT_WAIT_S)
            )

            def _full_scan():
                found = scan_once()
                if found is not None:
                    _log_first_result_seen(found, via="full_scan")
                    _log_exact_match_ready(found, via="full_scan")
                return found

            el = retry_until_jitter(
                _full_scan,
                timeout_s=timeout,
                poll_min_s=0.05,
                poll_max_s=0.07,
                desc="real_account_textview",
            )

    _perf["row_detect_ms"] = (time.perf_counter() - t_detect) * 1000
    if el is None:
        _perf["row_tap_command_ms"] = 0.0
        _perf["post_tap_settle_ms"] = 0.0
        _perf["profile_transition_wait_ms"] = 0.0
        _dump_no_real_account_row_debug(d, username)
        log("error", "tap_account_no_element", username=username)
        return False
    _perf["row_tap_command_ms"] = 0.0
    _perf["post_tap_settle_ms"] = 0.0
    _perf["profile_transition_wait_ms"] = 0.0
    try:
        if hot_el_found:
            cx, cy, b = _tap_hot_username_center_jitter(d, el)
            tap_mode = "hot_center_jitter"
        elif fast_accept_used:
            cached_tb = (
                _peek_follow_ct_exact_row_tap_bounds() if follow_ct_active else None
            )
            if cached_tb:
                b = cached_tb
                cx = (b["left"] + b["right"]) // 2
                cy = (b["top"] + b["bottom"]) // 2
                tap_mode = "follow_ct_cached_bounds_center"
                try:
                    log(
                        "info",
                        "follow_ct_exact_row_cached_bounds_tap_used",
                        username=username,
                        bounds=b,
                        x=cx,
                        y=cy,
                    )
                except Exception:
                    pass
            else:
                try:
                    tb_fast = {
                        k: int(el.info["bounds"][k])
                        for k in ("left", "top", "right", "bottom")
                    }
                    cx = (tb_fast["left"] + tb_fast["right"]) // 2
                    cy = (tb_fast["top"] + tb_fast["bottom"]) // 2
                    b = tb_fast
                    tap_mode = "fast_accept_username_center"
                except Exception:
                    b = _tap_bounds_for_account_row(d, el)
                    if not b:
                        b = {
                            k: int(el.info["bounds"][k])
                            for k in ("left", "top", "right", "bottom")
                        }
                    cx = (b["left"] + b["right"]) // 2
                    cy = (b["top"] + b["bottom"]) // 2
                    tap_mode = "legacy_bounds"
        else:
            b = _tap_bounds_for_account_row(d, el)
            if not b:
                b = {k: int(el.info["bounds"][k]) for k in ("left", "top", "right", "bottom")}
            cx = (b["left"] + b["right"]) // 2
            cy = (b["top"] + b["bottom"]) // 2
            tap_mode = "legacy_bounds"

        exact_to_tap_ms = (
            round((time.perf_counter() - exact_match_at[0]) * 1000.0, 2)
            if exact_match_at[0] is not None
            else None
        )
        if fast_accept_used:
            log(
                "info",
                "exact_account_row_fast_tap_used",
                username=username,
                exact_match_to_tap_ms=exact_to_tap_ms,
            )
        log(
            "info",
            "dm_sender_account_result_tap_started",
            username=username,
            exact_match_to_tap_ms=exact_to_tap_ms,
        )
        t_click = time.perf_counter()
        d.click(cx, cy)
        row_tap_ms = (time.perf_counter() - t_click) * 1000
        _perf["row_tap_command_ms"] = row_tap_ms
        log(
            "info",
            "dm_sender_account_result_tapped",
            username=username,
            row_tap_command_ms=round(row_tap_ms, 2),
            x=cx,
            y=cy,
            tap_mode=tap_mode,
        )
        log(
            "info",
            "row_tap_command_done",
            row_tap_command_ms=round(row_tap_ms, 2),
            x=cx,
            y=cy,
            username=username,
            tap_mode=tap_mode,
            search_ui_mode=get_search_ui_mode(),
        )

        settle_s = min(
            0.15,
            float(getattr(config, "POST_TAP_SETTLE_S", 0.12)),
        )
        t_settle = time.perf_counter()
        time.sleep(settle_s)
        _perf["post_tap_settle_ms"] = (time.perf_counter() - t_settle) * 1000

        t_trans = time.perf_counter()
        trans_deadline = time.monotonic() + float(
            getattr(config, "PROFILE_TRANSITION_POLL_MAX_S", 4.0)
        )
        trans_signal: str | None = None
        sleep_lo = float(getattr(config, "PROFILE_TRANSITION_POLL_SLEEP_MIN_S", 0.08))
        sleep_hi = float(getattr(config, "PROFILE_TRANSITION_POLL_SLEEP_MAX_S", 0.12))
        while time.monotonic() < trans_deadline:
            trans_signal = _early_profile_transition_signal(d, username)
            if trans_signal:
                log(
                    "info",
                    "profile_transition_signal_early",
                    signal=trans_signal,
                    username=username,
                )
                break
            time.sleep(random.uniform(sleep_lo, sleep_hi))
        _perf["profile_transition_wait_ms"] = (time.perf_counter() - t_trans) * 1000

        log(
            "info",
            "account_row_tapped",
            x=cx,
            y=cy,
            username=username,
            search_ui_mode=get_search_ui_mode(),
            tap_bounds=b,
            tap_mode=tap_mode,
        )
        log("info", "real_account_row_tap_center", x=cx, y=cy, username=username)
        if fused or hot_el_found:
            _mark_search_surface_ok(d, config.INSTAGRAM_PACKAGE)
        return True
    except Exception as e:
        log("error", "account_row_tap_failed", error=str(e))
        _perf["post_tap_settle_ms"] = 0.0
        _perf["profile_transition_wait_ms"] = 0.0
        return False


def verify_profile(d: u2.Device, username: str) -> bool:
    """
    Lightweight multi-signal profile open detection (no XML dumps, no single-selector dependency).
    """
    global _perf
    t0 = time.perf_counter()
    pkg = config.INSTAGRAM_PACKAGE
    time.sleep(config.PROFILE_POST_TAP_STABILIZE_S)
    deadline = time.monotonic() + config.PROFILE_VERIFY_LIGHTWEIGHT_MAX_S
    attempt = 0

    try:
        while time.monotonic() < deadline:
            attempt += 1
            _try_dismiss_keyboard_light(d)

            signal = _try_profile_signals_once(d, username, pkg)
            if signal:
                log(
                    "info",
                    "profile_open_detected",
                    username=username,
                    signal=signal,
                    attempt=attempt,
                )
                log(
                    "info",
                    "profile_verify_signal_found",
                    username=username,
                    signal=signal,
                    attempt=attempt,
                )
                log(
                    "info",
                    "profile_verify_success",
                    username=username,
                    signal=signal,
                    attempts=attempt,
                )
                try:
                    from followers_inter_candidate_perf import (
                        inter_candidate_on_profile_verify_success,
                    )

                    inter_candidate_on_profile_verify_success(username=username)
                except Exception:
                    pass
                return True

            log(
                "info",
                "profile_verify_retry",
                username=username,
                attempt=attempt,
                max_wait_s=config.PROFILE_VERIFY_LIGHTWEIGHT_MAX_S,
            )
            time.sleep(config.PROFILE_VERIFY_POLL_S)

        log(
            "error",
            "profile_verify_failed",
            username=username,
            reason="no_signal_within_lightweight_window",
            waited_s=config.PROFILE_VERIFY_LIGHTWEIGHT_MAX_S,
        )
        return False
    finally:
        _perf["profile_verify_ms"] = (time.perf_counter() - t0) * 1000


def _dm_parse_bounds_attr_xml(raw: str | None) -> dict[str, int] | None:
    """Parse Android bounds '[l,t][r,b]' from hierarchy XML."""
    if not raw or "[" not in raw:
        return None
    try:
        inner = raw.replace("][", ",").replace("[", "").replace("]", "")
        parts = [int(x.strip()) for x in inner.split(",") if x.strip()]
        if len(parts) != 4:
            return None
        l, t, r, b = parts
        return {"left": l, "top": t, "right": r, "bottom": b}
    except Exception:
        return None


def _dm_bounds_intersect_bottom_band(
    bd: dict[str, int], screen_h: int, bottom_fraction: float
) -> bool:
    cut_top = int(screen_h * max(0.0, min(1.0, 1.0 - bottom_fraction)) + 0.5)
    top = int(bd.get("top", 0))
    bottom = int(bd.get("bottom", 0))
    return bottom > cut_top and top < screen_h


def _dm_nearest_clickable_xml_ancestor(
    elem: ET.Element, parent_map: dict[ET.Element, ET.Element | None]
) -> ET.Element | None:
    cur = parent_map.get(elem)
    while cur is not None:
        if cur.get("clickable", "").lower() == "true":
            return cur
        cur = parent_map.get(cur)
    return None


def _dm_visible_from_xml(elem: ET.Element) -> bool:
    for key in ("visible-to-user", "displayed", "visible"):
        v = elem.get(key)
        if v is not None:
            return str(v).lower() != "false"
    return True


def _dm_bottom_ui_dump_from_hierarchy(
    xml_text: str,
    composer_bounds: dict | None,
    screen_w: int,
    screen_h: int,
    *,
    bottom_fraction: float = 0.45,
    max_nodes: int = 250,
) -> dict[str, Any]:
    """
    Parse saved hierarchy XML; collect nodes intersecting the bottom fraction of the screen.
    No class or clickable filtering. Sorted bottom-first, then toward the right.
    """
    cb = composer_bounds or {}
    cright = int(cb.get("right", 0)) if cb else 0
    out: dict[str, Any] = {
        "bottom_ui_dump_node_count": 0,
        "bottom_ui_dump_bottom_fraction": bottom_fraction,
        "bottom_ui_dump_max_nodes": max_nodes,
        "nodes": [],
    }
    text = (xml_text or "").strip()
    if not text:
        return out
    try:
        try:
            root = ET.fromstring(text)
        except ET.ParseError:
            root = ET.fromstring(f"<_root>{text}</_root>")
        parent_map: dict[ET.Element, ET.Element | None] = {root: None}

        def index_parents(el: ET.Element) -> None:
            for ch in list(el):
                parent_map[ch] = el
                index_parents(ch)

        index_parents(root)
        candidates: list[tuple[int, int, dict[str, Any]]] = []
        for el in root.iter():
            if el is root and root.tag in ("_root",):
                continue
            bd = _dm_parse_bounds_attr_xml(el.get("bounds"))
            if not bd:
                continue
            if not _dm_bounds_intersect_bottom_band(bd, screen_h, bottom_fraction):
                continue
            left, top, right, bottom = (
                int(bd["left"]),
                int(bd["top"]),
                int(bd["right"]),
                int(bd["bottom"]),
            )
            wi = abs(right - left)
            hi = abs(bottom - top)
            cx = (left + right) // 2
            cy = (top + bottom) // 2
            cls = el.get("class") or el.get("className") or el.tag or ""
            rid = el.get("resource-id") or el.get("resourceId")
            txt = el.get("text") or ""
            cdesc = el.get("content-desc") or el.get("contentDescription") or ""
            clk = el.get("clickable", "")
            en = el.get("enabled", "")
            rec: dict[str, Any] = {
                "className": cls,
                "resourceId": rid,
                "text": txt,
                "contentDescription": cdesc,
                "bounds": dict(bd),
                "clickable": True
                if clk.lower() == "true"
                else False
                if clk.lower() == "false"
                else None,
                "enabled": True
                if en.lower() == "true"
                else False
                if en.lower() == "false"
                else None,
                "visible": _dm_visible_from_xml(el),
                "center_x": cx,
                "center_y": cy,
                "width": wi,
                "height": hi,
                "right_of_composer": bool(cb) and cx >= cright - 140,
                "distance_to_composer_right": (cx - cright) if cb else None,
                "lower_screen_half": cy >= (screen_h // 2),
            }
            anc = _dm_nearest_clickable_xml_ancestor(el, parent_map)
            if anc is not None:
                ap = _dm_parse_bounds_attr_xml(anc.get("bounds"))
                rec["nearest_clickable_ancestor"] = {
                    "className": anc.get("class") or anc.get("className"),
                    "resourceId": anc.get("resource-id") or anc.get("resourceId"),
                    "clickable": anc.get("clickable"),
                    "enabled": anc.get("enabled"),
                    "bounds": dict(ap) if ap else None,
                }
            else:
                rec["nearest_clickable_ancestor"] = None
            par_el = parent_map.get(el)
            if par_el is not None:
                pp = _dm_parse_bounds_attr_xml(par_el.get("bounds"))
                rec["parent"] = {
                    "className": par_el.get("class") or par_el.get("className"),
                    "resourceId": par_el.get("resource-id") or par_el.get("resourceId"),
                    "clickable": par_el.get("clickable"),
                    "enabled": par_el.get("enabled"),
                    "bounds": dict(pp) if pp else None,
                }
                try:
                    sibs = list(par_el)
                    ix = sibs.index(el)
                    if ix + 1 < len(sibs):
                        nx = sibs[ix + 1]
                        np = _dm_parse_bounds_attr_xml(nx.get("bounds"))
                        rec["next_sibling"] = {
                            "className": nx.get("class") or nx.get("className"),
                            "resourceId": nx.get("resource-id") or nx.get("resourceId"),
                            "clickable": nx.get("clickable"),
                            "bounds": dict(np) if np else None,
                        }
                    else:
                        rec["next_sibling"] = None
                except (ValueError, IndexError):
                    rec["next_sibling"] = None
            else:
                rec["parent"] = None
                rec["next_sibling"] = None
            # Sort: lower on screen first (larger cy), then more to the right (larger cx).
            candidates.append((-cy, cx, rec))
        candidates.sort(key=lambda t: (t[0], t[1]))
        nodes = [t[2] for t in candidates[:max_nodes]]
        out["nodes"] = nodes
        out["bottom_ui_dump_node_count"] = len(nodes)
        return out
    except Exception as e:
        out["nodes"] = []
        out["bottom_ui_dump_node_count"] = 0
        out["error"] = str(e)
        return out


def _dm_send_button_debug_artifacts(
    *,
    hierarchy_xml: str,
    composer_bounds: dict | None,
    screen_w: int,
    screen_h: int,
    debug_screenshot_path: str | None = None,
    debug_xml_path: str | None = None,
    bottom_fraction: float = 0.45,
    max_nodes: int = 250,
) -> dict[str, Any]:
    """
    After screenshot + hierarchy XML are saved (draft still visible), build telemetry for send_out.

    Correct _dm_bottom_ui_dump_from_hierarchy call order:
    (hierarchy_xml, composer_bounds, screen_w, screen_h) — never (xml, w, h, bounds).
    """
    dump_payload = _dm_bottom_ui_dump_from_hierarchy(
        hierarchy_xml,
        composer_bounds,
        screen_w,
        screen_h,
        bottom_fraction=bottom_fraction,
        max_nodes=max_nodes,
    )
    out: dict[str, Any] = {
        "dm_send_bottom_ui_dump": dump_payload,
        "bottom_ui_dump_node_count": dump_payload["bottom_ui_dump_node_count"],
        "bottom_ui_dump_bottom_fraction": dump_payload["bottom_ui_dump_bottom_fraction"],
        "bottom_ui_dump_max_nodes": dump_payload["bottom_ui_dump_max_nodes"],
    }
    if debug_screenshot_path is not None:
        out["debug_screenshot_path"] = debug_screenshot_path
    if debug_xml_path is not None:
        out["debug_xml_path"] = debug_xml_path
    if dump_payload.get("error"):
        out["bottom_ui_dump_error"] = dump_payload["error"]
    return out


_DM_SEND_POSITION_NOISE: tuple[str, ...] = (
    "camera",
    "mic",
    "microphone",
    "gallery",
    "emoji",
    "plus",
    "attach",
    "sticker",
    "stickers",
    "gif",
    "like",
    "row_thread_right_composer_button_write_with_ai",
    "row_thread_composer_button_sticker_shortcut",
)


def _dm_position_fallback_obvious_noise(rid: str, desc: str, txt: str) -> bool:
    blob = f"{rid} {desc} {txt}".lower()
    for frag in _DM_SEND_POSITION_NOISE:
        if frag in blob:
            return True
    return False


def _dm_position_fallback_class_ok(class_name: str) -> bool:
    if not class_name:
        return False
    cn = class_name
    if "FrameLayout" in cn:
        return True
    if "ImageView" in cn or "ImageButton" in cn:
        return True
    if cn == "android.view.View" or cn.endswith("android.view.View"):
        return True
    return False


def _dm_gather_send_raw_candidates(
    xml_text: str, screen_w: int, screen_h: int
) -> list[dict[str, Any]]:
    """
    Broad visual scan for send-like controls in lower-right zone.
    Intentionally permissive: no strict keyword/rid filtering at this stage.
    """
    out: list[dict[str, Any]] = []
    text = (xml_text or "").strip()
    if not text:
        return out
    try:
        try:
            root = ET.fromstring(text)
        except ET.ParseError:
            root = ET.fromstring(f"<_root>{text}</_root>")
    except ET.ParseError:
        return out

    allowed_classes = (
        "android.widget.ImageView",
        "android.widget.ImageButton",
        "android.view.View",
        "android.widget.FrameLayout",
    )
    for el in root.iter():
        bd = _dm_parse_bounds_attr_xml(el.get("bounds"))
        if not bd:
            continue
        left, top, right, bottom = (
            int(bd["left"]),
            int(bd["top"]),
            int(bd["right"]),
            int(bd["bottom"]),
        )
        wi, hi = abs(right - left), abs(bottom - top)
        if not (30 <= wi <= 200 and 30 <= hi <= 200):
            continue
        cx = (left + right) // 2
        cy = (top + bottom) // 2
        if cx < int(screen_w * 0.5):
            continue
        if cy < int(screen_h * 0.5):
            continue
        cn = (el.get("class") or el.get("className") or "").strip()
        if cn not in allowed_classes and not (
            cn.endswith("ImageView")
            or cn.endswith("ImageButton")
            or cn.endswith("android.view.View")
            or cn.endswith("FrameLayout")
        ):
            continue
        if not _dm_xml_enabled_visible_ok(el):
            continue

        out.append(
            {
                "className": cn,
                "resourceId": el.get("resource-id") or el.get("resourceId") or "",
                "text": el.get("text") or "",
                "contentDescription": el.get("content-desc")
                or el.get("contentDescription")
                or "",
                "bounds": dict(bd),
                "center_x": cx,
                "center_y": cy,
                "width": wi,
                "height": hi,
            }
        )
    return out


_DM_EXACT_SEND_RIDS: tuple[str, ...] = (
    "com.instagram.android:id/row_thread_composer_send_button_container",
    "com.instagram.android:id/row_thread_composer_send_button_background",
    "com.instagram.android:id/row_thread_composer_send_button_icon",
)


def _dm_extract_xml_node_candidate(el: ET.Element) -> dict[str, Any] | None:
    bd = _dm_parse_bounds_attr_xml(el.get("bounds"))
    if not bd:
        return None
    left, top, right, bottom = (
        int(bd["left"]),
        int(bd["top"]),
        int(bd["right"]),
        int(bd["bottom"]),
    )
    wi, hi = abs(right - left), abs(bottom - top)
    return {
        "className": (el.get("class") or el.get("className") or ""),
        "resourceId": el.get("resource-id") or el.get("resourceId") or "",
        "text": el.get("text") or "",
        "contentDescription": el.get("content-desc") or el.get("contentDescription") or "",
        "bounds": dict(bd),
        "center_x": (left + right) // 2,
        "center_y": (top + bottom) // 2,
        "width": wi,
        "height": hi,
        "clickable": str(el.get("clickable", "")).lower() == "true",
        "enabled": str(el.get("enabled", "true")).lower() != "false",
    }


def _dm_find_exact_instagram_send_candidate(
    xml_text: str,
    composer_bounds: dict[str, int],
    screen_h: int,
) -> dict[str, Any]:
    """
    Priority path for known Instagram send ids.
    Returns:
      {
        "selected": candidate|None,
        "seen": [candidate...],
        "rejected": [{"candidate":..., "reject_reason": "..."}...]
      }
    """
    out: dict[str, Any] = {"selected": None, "seen": [], "rejected": []}
    text = (xml_text or "").strip()
    if not text:
        return out
    try:
        try:
            root = ET.fromstring(text)
        except ET.ParseError:
            root = ET.fromstring(f"<_root>{text}</_root>")
    except ET.ParseError:
        return out

    parent_map: dict[ET.Element, ET.Element | None] = {root: None}

    def index_parents(el: ET.Element) -> None:
        for ch in list(el):
            parent_map[ch] = el
            index_parents(ch)

    index_parents(root)

    cright = int(composer_bounds.get("right", 0))
    ctop = int(composer_bounds.get("top", 0))
    cbot = int(composer_bounds.get("bottom", 0))
    y_lo = ctop - 120
    y_hi = cbot + 120
    lower_half_cut = int(screen_h * 0.5)

    for el in root.iter():
        rid = (el.get("resource-id") or el.get("resourceId") or "").strip()
        if rid not in _DM_EXACT_SEND_RIDS:
            continue

        raw = _dm_extract_xml_node_candidate(el)
        if raw is None:
            continue
        raw["matched_resource_id"] = rid
        out["seen"].append(raw)

        # For background/icon, prefer clickable ancestor container.
        target_el = el
        target_reason = ""
        if rid.endswith("row_thread_composer_send_button_background") or rid.endswith(
            "row_thread_composer_send_button_icon"
        ):
            anc = _dm_nearest_clickable_xml_ancestor(el, parent_map)
            if anc is None:
                target_reason = "no_clickable_ancestor"
            else:
                anc_rid = (anc.get("resource-id") or anc.get("resourceId") or "").strip()
                anc_click = str(anc.get("clickable", "")).lower() == "true"
                anc_enabled = str(anc.get("enabled", "true")).lower() != "false"
                if (
                    anc_rid
                    == "com.instagram.android:id/row_thread_composer_send_button_container"
                    and anc_click
                    and anc_enabled
                ):
                    target_el = anc
                else:
                    target_reason = "ancestor_not_clickable_send_container"

        target = _dm_extract_xml_node_candidate(target_el)
        if target is None:
            out["rejected"].append({"candidate": raw, "reject_reason": "invalid_target_bounds"})
            continue
        target_rid = str(target.get("resourceId") or "")
        target_clickable = bool(target.get("clickable"))
        target_enabled = bool(target.get("enabled"))
        cx = int(target.get("center_x") or 0)
        cy = int(target.get("center_y") or 0)
        ttop = int((target.get("bounds") or {}).get("top", 0))
        tbot = int((target.get("bounds") or {}).get("bottom", 0))
        right_of_composer = cx > (cright - 20)
        in_vertical_band = not (tbot < y_lo or ttop > y_hi)
        lower_half = cy >= lower_half_cut

        reject_reason = ""
        if target_reason:
            reject_reason = target_reason
        elif target_rid != "com.instagram.android:id/row_thread_composer_send_button_container":
            reject_reason = "target_not_send_container"
        elif not target_clickable:
            reject_reason = "target_not_clickable"
        elif not target_enabled:
            reject_reason = "target_not_enabled"
        elif not right_of_composer:
            reject_reason = "target_not_right_of_composer"
        elif not in_vertical_band:
            reject_reason = "target_not_in_composer_vertical_band"
        elif not lower_half:
            reject_reason = "target_not_in_lower_half"

        target["matched_resource_id"] = rid
        target["right_of_composer"] = right_of_composer
        target["lower_screen_half"] = lower_half
        target["in_composer_vertical_band"] = in_vertical_band

        if reject_reason:
            out["rejected"].append({"candidate": target, "reject_reason": reject_reason})
            continue

        out["selected"] = target
        return out

    return out


def _dm_visual_send_candidates_from_hierarchy_xml(
    xml_text: str,
    composer_bounds: dict[str, int],
    screen_w: int,
    screen_h: int,
) -> dict[str, Any]:
    cright = int(composer_bounds.get("right", 0))
    ctop = int(composer_bounds.get("top", 0))
    cbot = int(composer_bounds.get("bottom", 0))
    out: dict[str, Any] = {
        "candidates": [],
        "surviving_candidates": [],
        "visual_candidates_rejected": [],
        "rejection_breakdown": {},
    }
    raw = _dm_gather_send_raw_candidates(xml_text, screen_w, screen_h)
    out["surviving_candidates"] = raw
    survivors: list[dict[str, Any]] = []
    rejected: list[dict[str, Any]] = []
    reasons_count: dict[str, int] = {}

    for c in raw:
        reason = ""
        cn = str(c.get("className") or "")
        rid = str(c.get("resourceId") or "")
        txt = str(c.get("text") or "")
        desc = str(c.get("contentDescription") or "")
        cx = int(c.get("center_x") or 0)
        cy = int(c.get("center_y") or 0)
        wi = int(c.get("width") or 0)
        hi = int(c.get("height") or 0)

        right_of_composer = cx > (cright - 20)
        lower_screen_half = cy >= int(screen_h * 0.5)
        near_composer_vertical = (ctop - 120) <= cy <= (cbot + 120)
        class_plausible = (
            "ImageView" in cn
            or "ImageButton" in cn
            or cn == "android.view.View"
            or cn.endswith("android.view.View")
            or "FrameLayout" in cn
        )
        size_plausible = 30 <= wi <= 200 and 30 <= hi <= 200

        if not class_plausible:
            reason = "class_not_plausible"
        elif not size_plausible:
            reason = "size_not_plausible"
        elif not right_of_composer:
            reason = "not_right_of_composer"
        elif not lower_screen_half:
            reason = "not_lower_half"
        elif not near_composer_vertical:
            reason = "not_near_composer_vertical"
        elif _dm_position_fallback_obvious_noise(rid.lower(), desc.lower(), txt.lower()):
            reason = "obvious_noise"

        c["right_of_composer"] = bool(right_of_composer)
        c["lower_screen_half"] = bool(lower_screen_half)
        c["near_composer_vertical"] = bool(near_composer_vertical)

        if reason:
            c["reject_reason"] = reason
            rejected.append(c)
            reasons_count[reason] = int(reasons_count.get(reason, 0)) + 1
            continue
        survivors.append(c)

    out["candidates"] = survivors
    out["visual_candidates_rejected"] = rejected
    out["rejection_breakdown"] = reasons_count
    return out


def _dm_screen_size_for_dm(d: u2.Device) -> tuple[int, int]:
    try:
        w, h = d.window_size()
        return int(w), int(h)
    except Exception:
        return 1080, 1920


def _dm_composer_bounds_u2(composer) -> dict[str, int]:
    try:
        inf = composer.info or {}
        b = inf.get("bounds") or {}
        return {k: int(b[k]) for k in ("left", "top", "right", "bottom") if k in b}
    except Exception:
        return {}


def _dm_xml_enabled_visible_ok(elem: ET.Element) -> bool:
    en = elem.get("enabled", "")
    if en and en.lower() == "false":
        return False
    return _dm_visible_from_xml(elem)


def _dm_position_fallback_candidates_from_hierarchy_xml(
    xml_text: str,
    composer_bounds: dict[str, int],
    screen_w: int,
    screen_h: int,
) -> list[dict[str, Any]]:
    """Compatibility wrapper: return only surviving visual candidates."""
    info = _dm_visual_send_candidates_from_hierarchy_xml(
        xml_text, composer_bounds, screen_w, screen_h
    )
    return list(info.get("candidates") or [])


def _dm_coordinate_send_point_from_composer(
    composer_bounds: dict[str, int], screen_w: int
) -> tuple[int, int]:
    cright = int(composer_bounds["right"])
    ctop = int(composer_bounds["top"])
    cbot = int(composer_bounds["bottom"])
    x = int(cright + (screen_w - cright) / 2)
    y = (ctop + cbot) // 2
    return x, y


class _DmSendTapOnce:
    """Single physical tap (guards accidental double-click on same target)."""

    __slots__ = ("_d", "_x", "_y", "_spent")

    def __init__(self, d: u2.Device, x: int, y: int) -> None:
        self._d = d
        self._x = int(x)
        self._y = int(y)
        self._spent = False

    def click(self) -> None:
        if self._spent:
            log("warning", "dm_send_tap_ignored_already_clicked", x=self._x, y=self._y)
            return
        self._d.click(self._x, self._y)
        self._spent = True


def _dm_try_unique_send_resource_u2(d: u2.Device) -> Any | None:
    for pat in (
        ".*:id/.*send.*",
        ".*:id/.*direct_send.*",
        ".*:id/.*row_thread_composer_button_send.*",
        ".*:id/.*button_send.*",
        ".*:id/.*composer.*send.*",
    ):
        try:
            sel = d(resourceIdMatches=pat)
            objs = sel.all() if hasattr(sel, "all") else []
            if len(objs) == 1:
                return objs[0]
        except Exception:
            continue
    return None


def wait_for_dm_send_button_after_draft(
    d: u2.Device,
    composer,
    *,
    thread_state: str,
    draft_matches_expected: bool = True,
) -> tuple[Any | None, str, dict[str, Any]]:
    """
    Poll for a unique Send control. For empty_new_thread + draft verified, adds hierarchy position
    fallback (paper-plane zone right of composer) and optional coordinate fallback (config-gated).
    """
    w, h = _dm_screen_size_for_dm(d)
    composer_bounds = _dm_composer_bounds_u2(composer)
    max_wait = float(getattr(config, "DM_SEND_BUTTON_WAIT_MAX_S", 1.5))
    poll_s = float(getattr(config, "DM_SEND_BUTTON_POLL_S", 0.1))
    deadline = time.monotonic() + max_wait
    meta: dict[str, Any] = {
        "send_button_candidate_count": 0,
        "send_button_position_fallback": False,
        "send_button_coordinate_fallback": False,
        "surviving_candidates": [],
        "visual_candidates_rejected": [],
        "rejection_breakdown": {},
    }
    allow_pos = (
        (thread_state or "").strip() == "empty_new_thread"
        and draft_matches_expected
        and bool(composer_bounds)
    )
    coord_fb = bool(getattr(config, "ENABLE_COORDINATE_SEND_FALLBACK", False))
    log(
        "info",
        "dm_send_button_wait_started",
        max_wait_s=max_wait,
        poll_s=poll_s,
        position_fallback_allowed=allow_pos,
    )
    while time.monotonic() < deadline:
        u = _dm_try_unique_send_resource_u2(d)
        if u is not None:
            meta["send_button_candidate_count"] = 1
            log("info", "dm_send_button_wait_ok", path="resource_id")
            return u, "ok", meta

        if allow_pos:
            try:
                hier = d.dump_hierarchy(compressed=False)
            except Exception:
                hier = d.dump_hierarchy()
            exact = _dm_find_exact_instagram_send_candidate(hier, composer_bounds, h)
            for s in list(exact.get("seen") or []):
                log(
                    "info",
                    "dm_send_exact_instagram_candidate_seen",
                    matched_resource_id=s.get("matched_resource_id"),
                    used_click_target_resource_id=s.get("resourceId"),
                    used_click_target_class=s.get("className"),
                    used_click_target_bounds=s.get("bounds"),
                    composer_bounds=composer_bounds,
                    thread_state=thread_state,
                )
            for rej in list(exact.get("rejected") or []):
                c = rej.get("candidate") or {}
                log(
                    "info",
                    "dm_send_exact_instagram_candidate_rejected",
                    reject_reason=rej.get("reject_reason"),
                    matched_resource_id=c.get("matched_resource_id"),
                    used_click_target_resource_id=c.get("resourceId"),
                    used_click_target_class=c.get("className"),
                    used_click_target_bounds=c.get("bounds"),
                    composer_bounds=composer_bounds,
                    thread_state=thread_state,
                )
            ex_sel = exact.get("selected")
            if isinstance(ex_sel, dict):
                log(
                    "info",
                    "dm_send_exact_instagram_candidate_selected",
                    matched_resource_id=ex_sel.get("matched_resource_id"),
                    used_click_target_resource_id=ex_sel.get("resourceId"),
                    used_click_target_class=ex_sel.get("className"),
                    used_click_target_bounds=ex_sel.get("bounds"),
                    composer_bounds=composer_bounds,
                    thread_state=thread_state,
                )
                meta["send_button_candidate_count"] = 1
                meta["send_button_position_fallback"] = True
                return _DmSendTapOnce(d, ex_sel["center_x"], ex_sel["center_y"]), "ok", meta
            info = _dm_visual_send_candidates_from_hierarchy_xml(
                hier, composer_bounds, w, h
            )
            pos = list(info.get("candidates") or [])
            meta["send_button_candidate_count"] = len(pos)
            meta["surviving_candidates"] = list(info.get("surviving_candidates") or [])
            meta["visual_candidates_rejected"] = list(
                info.get("visual_candidates_rejected") or []
            )
            meta["rejection_breakdown"] = dict(info.get("rejection_breakdown") or {})
            if len(pos) == 1:
                c = pos[0]
                log(
                    "info",
                    "dm_send_button_detected_visual_only",
                    className=c.get("className"),
                    resourceId=c.get("resourceId"),
                    text=c.get("text"),
                    contentDescription=c.get("contentDescription"),
                    bounds=c.get("bounds"),
                    center_x=c.get("center_x"),
                    center_y=c.get("center_y"),
                    width=c.get("width"),
                    height=c.get("height"),
                    right_of_composer=c.get("right_of_composer"),
                    lower_screen_half=c.get("lower_screen_half"),
                    candidate=c,
                    thread_state=thread_state,
                )
                meta["send_button_position_fallback"] = True
                tap = _DmSendTapOnce(d, c["center_x"], c["center_y"])
                return tap, "ok", meta
        time.sleep(poll_s)

    meta["send_button_candidate_count"] = 0
    try:
        hier = d.dump_hierarchy(compressed=False)
    except Exception:
        hier = d.dump_hierarchy()
    if allow_pos and composer_bounds:
        exact = _dm_find_exact_instagram_send_candidate(hier, composer_bounds, h)
        for s in list(exact.get("seen") or []):
            log(
                "info",
                "dm_send_exact_instagram_candidate_seen",
                matched_resource_id=s.get("matched_resource_id"),
                used_click_target_resource_id=s.get("resourceId"),
                used_click_target_class=s.get("className"),
                used_click_target_bounds=s.get("bounds"),
                composer_bounds=composer_bounds,
                thread_state=thread_state,
            )
        for rej in list(exact.get("rejected") or []):
            c = rej.get("candidate") or {}
            log(
                "info",
                "dm_send_exact_instagram_candidate_rejected",
                reject_reason=rej.get("reject_reason"),
                matched_resource_id=c.get("matched_resource_id"),
                used_click_target_resource_id=c.get("resourceId"),
                used_click_target_class=c.get("className"),
                used_click_target_bounds=c.get("bounds"),
                composer_bounds=composer_bounds,
                thread_state=thread_state,
            )
        ex_sel = exact.get("selected")
        if isinstance(ex_sel, dict):
            log(
                "info",
                "dm_send_exact_instagram_candidate_selected",
                matched_resource_id=ex_sel.get("matched_resource_id"),
                used_click_target_resource_id=ex_sel.get("resourceId"),
                used_click_target_class=ex_sel.get("className"),
                used_click_target_bounds=ex_sel.get("bounds"),
                composer_bounds=composer_bounds,
                thread_state=thread_state,
            )
            meta["send_button_candidate_count"] = 1
            meta["send_button_position_fallback"] = True
            return _DmSendTapOnce(d, ex_sel["center_x"], ex_sel["center_y"]), "ok", meta
        info = _dm_visual_send_candidates_from_hierarchy_xml(
            hier, composer_bounds, w, h
        )
        pos = list(info.get("candidates") or [])
        meta["send_button_candidate_count"] = len(pos)
        meta["surviving_candidates"] = list(info.get("surviving_candidates") or [])
        meta["visual_candidates_rejected"] = list(
            info.get("visual_candidates_rejected") or []
        )
        meta["rejection_breakdown"] = dict(info.get("rejection_breakdown") or {})
        if len(pos) == 1:
            c = pos[0]
            log(
                "info",
                "dm_send_button_detected_visual_only",
                className=c.get("className"),
                resourceId=c.get("resourceId"),
                text=c.get("text"),
                contentDescription=c.get("contentDescription"),
                bounds=c.get("bounds"),
                center_x=c.get("center_x"),
                center_y=c.get("center_y"),
                width=c.get("width"),
                height=c.get("height"),
                right_of_composer=c.get("right_of_composer"),
                lower_screen_half=c.get("lower_screen_half"),
                candidate=c,
                thread_state=thread_state,
            )
            meta["send_button_position_fallback"] = True
            tap = _DmSendTapOnce(d, c["center_x"], c["center_y"])
            return tap, "ok", meta
        log(
            "info",
            "dm_send_candidate_summary",
            thread_state=thread_state,
            candidate_count=len(pos),
            surviving_candidates=meta.get("surviving_candidates"),
            rejection_breakdown=meta.get("rejection_breakdown"),
            visual_candidates_rejected=meta.get("visual_candidates_rejected"),
        )
        if len(pos) == 0:
            rx, ry = _dm_coordinate_send_point_from_composer(composer_bounds, w)
            log(
                "info",
                "dm_send_coordinate_candidate_from_composer",
                x=rx,
                y=ry,
                thread_state=thread_state,
                coordinate_fallback_enabled=coord_fb,
            )
            if coord_fb:
                meta["send_button_coordinate_fallback"] = True
                meta["send_button_candidate_count"] = 1
                return _DmSendTapOnce(d, rx, ry), "ok", meta

    return None, "missing", meta


def _dm_read_composer_text_len(d: u2.Device) -> int:
    try:
        cur = _dm_find_focus_composer(d)
        if cur is None:
            return 0
        return len(str(cur.get_text() or ""))
    except Exception:
        return 0


def _dm_post_send_signal_poll(
    d: u2.Device, *, pre_send_text_len: int
) -> tuple[bool, str]:
    """
    Short bounded poll: thread/delivery hints or composer text shrinking after send.
    """
    max_s = float(getattr(config, "DM_POST_SEND_SIGNAL_MAX_S", 2.0))
    poll_s = float(getattr(config, "DM_POST_SEND_SIGNAL_POLL_S", 0.12))
    deadline = time.monotonic() + max_s
    reason = ""
    while time.monotonic() < deadline:
        try:
            for frag in ("Sent", "Delivered", "Envoyé", "Envoye", "Vu"):
                if d(textContains=frag).exists(timeout=0.04):
                    reason = f"text_marker:{frag}"
                    return True, reason
        except Exception:
            pass
        try:
            cur_len = _dm_read_composer_text_len(d)
            if pre_send_text_len > 0 and cur_len < max(0, pre_send_text_len - 3):
                reason = "composer_text_shortened"
                return True, reason
            if pre_send_text_len > 0 and cur_len == 0:
                reason = "composer_empty"
                return True, reason
        except Exception:
            pass
        time.sleep(poll_s)
    reason = "timeout"
    return False, reason


def finalize_after_real_send(
    d: u2.Device,
    username: str,
    pkg: str | None = None,
    *,
    use_fast_reset_between_targets: bool = False,
    pre_send_composer_text_len: int = 0,
    restore_global_search: bool = True,
) -> dict[str, Any]:
    """
    Best-effort post-real-send: short UI signal poll, draft cleanup, profile, optional search.
    Does not click Send again. Instrumented for metrics and logs.

    DM sender sets restore_global_search=False so global Search is restored only via
    prepare_dm_sender_global_search_surface (no percent-fallback open_search from DM thread).
    """
    global _perf
    pkg = pkg or config.INSTAGRAM_PACKAGE
    t_total = time.perf_counter()
    out: dict[str, Any] = {
        "post_send_signal_ok": False,
        "post_send_signal_reason": "",
        "back_to_profile_ok": False,
        "back_to_search_ok": False,
        "post_send_cleanup_reason": "",
    }
    log("info", "dm_send_post_finalize_started", username=username)

    t_sig = time.perf_counter()
    sig_ok, sig_reason = _dm_post_send_signal_poll(
        d, pre_send_text_len=int(pre_send_composer_text_len or 0)
    )
    post_detect_ms = (time.perf_counter() - t_sig) * 1000
    out["post_send_signal_ok"] = bool(sig_ok)
    out["post_send_signal_reason"] = sig_reason
    set_perf_metric("post_send_detect_ms", post_detect_ms)
    if sig_ok:
        log(
            "info",
            "dm_send_post_signal_detected",
            username=username,
            reason=sig_reason,
            post_send_detect_ms=round(post_detect_ms, 2),
        )
    else:
        log(
            "warning",
            "dm_send_post_signal_timeout",
            username=username,
            reason=sig_reason,
            post_send_detect_ms=round(post_detect_ms, 2),
        )

    try:
        clear_dm_draft(d)
    except Exception:
        pass
    try:
        finalize_dm_draft_before_back(d)
    except Exception:
        pass

    t_prof = time.perf_counter()
    ok_profile = return_to_profile_from_dm(d, username, pkg)
    back_prof_ms = (time.perf_counter() - t_prof) * 1000
    out["back_to_profile_ok"] = bool(ok_profile)
    set_perf_metric("post_send_back_to_profile_ms", back_prof_ms)
    if ok_profile:
        log(
            "info",
            "dm_send_post_back_to_profile_ok",
            username=username,
            ms=round(back_prof_ms, 2),
        )
    else:
        log(
            "warning",
            "dm_send_post_back_to_profile_failed",
            username=username,
            ms=round(back_prof_ms, 2),
        )

    t_search = time.perf_counter()
    ok_search = False
    if restore_global_search:
        if use_fast_reset_between_targets:
            ok_search = bool(reset_to_search_for_next_target(d, pkg))
        else:
            ok_search = bool(return_to_search_from_profile(d, pkg))
            if not ok_search:
                try:
                    ok_search = bool(open_search(d))
                except Exception:
                    ok_search = False
        search_ms = (time.perf_counter() - t_search) * 1000
        out["back_to_search_ok"] = bool(ok_search)
        set_perf_metric("post_send_profile_to_search_ms", search_ms)
        if ok_search:
            log(
                "info",
                "dm_send_post_back_to_search_ok",
                username=username,
                ms=round(search_ms, 2),
            )
        else:
            log(
                "warning",
                "dm_send_post_back_to_search_failed",
                username=username,
                ms=round(search_ms, 2),
            )
    else:
        out["back_to_search_ok"] = False
        log(
            "info",
            "dm_send_post_search_restore_deferred",
            username=username,
            reason="dm_sender_prepare_post_job",
        )

    # Do not reset DM send/thread snapshots here: runner still reads them for Supabase logs.
    invalidate_search_surface_cache("after_real_dm_sent")

    total_ms = (time.perf_counter() - t_total) * 1000
    set_perf_metric("post_send_finalize_total_ms", total_ms)
    if not restore_global_search:
        cleanup = "profile_only_search_deferred" if ok_profile else "profile_failed_search_deferred"
    elif ok_profile and ok_search:
        cleanup = "complete"
    elif ok_profile:
        cleanup = "partial_search_failed"
    elif ok_search:
        cleanup = "partial_profile_failed"
    else:
        cleanup = "partial_profile_and_search_failed"
    out["post_send_cleanup_reason"] = cleanup
    set_perf_metric("post_send_cleanup_reason", cleanup)
    log(
        "info",
        "dm_send_post_finalize_done",
        username=username,
        post_send_cleanup_reason=cleanup,
        post_send_finalize_total_ms=round(total_ms, 2),
    )
    return out


def find_visible_followers_row_by_username(
    d: u2.Device,
    username: str,
    *,
    source_profile_username: str = "",
    force_fresh_hierarchy: bool = True,
    screen_index: int = 0,
) -> dict[str, Any] | None:
    """
    Locate a visible followers-list row (same harvest path as welcome scan).
    """
    target = _normalize_handle(username)
    if not target:
        return None
    src = str(source_profile_username or "").strip()
    rows, _meta = harvest_visible_followers_rows(
        d,
        source_profile_username=src,
        runtime_seen=set(),
        force_fresh_hierarchy=bool(force_fresh_hierarchy),
        screen_index=int(screen_index),
    )
    for row in rows:
        if _normalize_handle(str(row.get("username") or "")) == target:
            return dict(row)
    return None


def scroll_followers_list_to_find_row(
    d: u2.Device,
    username: str,
    *,
    source_profile_username: str = "",
    max_scrolls: int | None = None,
    screen_index: int = 0,
) -> tuple[dict[str, Any] | None, int, list[str]]:
    """
    Bounded forward scroll only — caller must prove target absent from visible snapshot first.
    Returns (row, scroll_count, visible_usernames_after_last_scroll).
    """
    src = str(source_profile_username or "").strip()
    cap = int(
        max_scrolls
        if max_scrolls is not None
        else getattr(config, "WELCOME_LIST_SENDER_MAX_SCROLL_FIND", 3) or 3
    )
    cap = max(0, cap)
    settle_s = float(
        getattr(config, "WELCOME_LIST_SENDER_SCROLL_SETTLE_S", 0.45) or 0.45
    )
    last_visible: list[str] = []

    for scroll_idx in range(1, cap + 1):
        if not scroll_followers_list_forward(
            d,
            source_profile_username=src,
            bypass_post_tap_capture_gate=True,
            bypass_scroll_xml_guards=True,
        ):
            break
        followers_clear_detect_hierarchy_cache()
        if settle_s > 0:
            time.sleep(min(settle_s, 1.5))
        rows, _meta = harvest_visible_followers_rows(
            d,
            source_profile_username=src,
            runtime_seen=set(),
            force_fresh_hierarchy=True,
            screen_index=int(screen_index) + scroll_idx,
        )
        last_visible = [str(r.get("username") or "") for r in rows if r.get("username")]
        target = _normalize_handle(username)
        for row in rows:
            if _normalize_handle(str(row.get("username") or "")) == target:
                return dict(row), scroll_idx, last_visible
    return None, cap, last_visible


def tap_followers_list_username_row(
    d: u2.Device,
    row: dict[str, Any],
    *,
    username: str,
) -> tuple[bool, int, int]:
    """Tap center of a harvested followers row. Returns (ok, tap_x, tap_y)."""
    bounds = dict(row.get("tap_bounds") or row.get("bounds") or {})
    if bounds:
        cx = (int(bounds["left"]) + int(bounds["right"])) // 2
        cy = (int(bounds["top"]) + int(bounds["bottom"])) // 2
    else:
        rc = row.get("row_center") or [0, 0]
        cx = int(rc[0])
        cy = int(rc[1])
    try:
        d.click(cx, cy)
        return True, cx, cy
    except Exception as e:
        log(
            "error",
            "welcome_list_sender_row_tap_failed",
            username=username,
            error=str(e)[:200],
            bounds=bounds,
        )
        return False, cx, cy


def return_welcome_list_from_dm_to_followers(
    d: u2.Device,
    username: str,
    pkg: str | None = None,
    *,
    source_profile_username: str = "",
    pre_send_composer_text_len: int = 0,
) -> dict[str, Any]:
    """
  Welcome list-native post-send / post-skip: DM → action-bar back → profile → action-bar back → followers.
  No global Search, no percent_fallback, no open_search.
    """
    pkg = pkg or config.INSTAGRAM_PACKAGE
    src = str(source_profile_username or "").strip()
    settle_s = float(
        getattr(config, "WELCOME_LIST_SENDER_BACK_SETTLE_S", 0.45) or 0.45
    )
    out: dict[str, Any] = {
        "back_to_profile_ok": False,
        "followers_surface_ok": False,
    }

    sig_ok, sig_reason = _dm_post_send_signal_poll(
        d, pre_send_text_len=int(pre_send_composer_text_len or 0)
    )
    out["post_send_signal_ok"] = bool(sig_ok)
    out["post_send_signal_reason"] = sig_reason
    try:
        clear_dm_draft(d)
    except Exception:
        pass
    try:
        finalize_dm_draft_before_back(d)
    except Exception:
        pass

    log(
        "info",
        "welcome_list_sender_back_dm_to_profile_started",
        username=username,
        source_profile_username=src or None,
    )
    t0 = time.perf_counter()
    tapped, tap_method = tap_instagram_action_bar_back_button(d, pkg)
    if tapped and settle_s > 0:
        time.sleep(settle_s)
    prof_ok = bool(tapped) and verify_profile(d, username)
    out["back_to_profile_ok"] = prof_ok
    log(
        "info",
        "welcome_list_sender_back_dm_to_profile_done",
        username=username,
        tapped=bool(tapped),
        tap_method=tap_method,
        profile_verified=prof_ok,
        ms=round((time.perf_counter() - t0) * 1000.0, 2),
    )

    log(
        "info",
        "welcome_list_sender_back_profile_to_followers_started",
        username=username,
        source_profile_username=src or None,
    )
    t1 = time.perf_counter()
    tapped2, tap_method2 = tap_instagram_action_bar_back_button(d, pkg)
    if tapped2 and settle_s > 0:
        time.sleep(settle_s)

    poll_attempts = int(
        getattr(config, "WELCOME_LIST_SENDER_BACK_PROFILE_POLL_ATTEMPTS", 4) or 4
    )
    poll_interval_s = float(
        getattr(config, "WELCOME_LIST_SENDER_BACK_PROFILE_POLL_INTERVAL_S", 0.35)
        or 0.35
    )
    poll_attempts = max(1, poll_attempts)

    log(
        "info",
        "welcome_list_sender_back_profile_to_followers_poll_started",
        username=username,
        source_profile_username=src or None,
        poll_attempts=poll_attempts,
        poll_interval_s=poll_interval_s,
    )

    followers_ok = False
    det: dict[str, Any] = {}
    fresh_hierarchy_xml = ""
    extra_back_tapped = False

    def _poll_followers_once() -> tuple[bool, dict[str, Any], str]:
        det_loc, fresh_xml = detect_followers_list_screen_fresh(
            d, source_profile_username=src
        )
        return bool(det_loc.get("is_followers_list")), det_loc, str(fresh_xml or "")

    def _repoll_after_extra_back() -> None:
        nonlocal followers_ok, det, fresh_hierarchy_xml, extra_back_tapped
        for repoll_attempt in range(poll_attempts):
            if repoll_attempt > 0 and poll_interval_s > 0:
                time.sleep(poll_interval_s)
            followers_ok, det, fresh_hierarchy_xml = _poll_followers_once()
            if followers_ok:
                log(
                    "info",
                    "welcome_list_sender_back_profile_to_followers_poll_success",
                    username=username,
                    source_profile_username=src or None,
                    poll_attempt=repoll_attempt + 1,
                    extra_back_tapped=True,
                    action_bar_title=det.get("action_bar_title"),
                )
                break

    for attempt in range(poll_attempts):
        if attempt > 0 and poll_interval_s > 0:
            time.sleep(poll_interval_s)
        followers_ok, det, fresh_hierarchy_xml = _poll_followers_once()
        if followers_ok:
            log(
                "info",
                "welcome_list_sender_back_profile_to_followers_poll_success",
                username=username,
                source_profile_username=src or None,
                poll_attempt=attempt + 1,
                extra_back_tapped=extra_back_tapped,
                action_bar_title=det.get("action_bar_title"),
            )
            break

        ab_title = str(det.get("action_bar_title") or "")
        on_recipient_profile = _normalize_handle(ab_title) == _normalize_handle(
            username
        )
        if on_recipient_profile:
            log(
                "info",
                "welcome_list_sender_back_profile_to_followers_early_extra_back_triggered",
                username=username,
                source_profile_username=src or None,
                action_bar_title=ab_title,
                poll_attempt=attempt + 1,
                reason="recipient_profile_detected_early",
            )
            log(
                "info",
                "welcome_list_sender_back_profile_to_followers_extra_back_tapped",
                username=username,
                source_profile_username=src or None,
                action_bar_title=ab_title,
            )
            tapped3, _tap_method3 = tap_instagram_action_bar_back_button(d, pkg)
            extra_back_tapped = bool(tapped3)
            if tapped3 and settle_s > 0:
                time.sleep(settle_s)
            _repoll_after_extra_back()
            break

    if not followers_ok and not extra_back_tapped:
        ab_title = str(det.get("action_bar_title") or "")
        on_recipient_profile = _normalize_handle(ab_title) == _normalize_handle(
            username
        )
        if on_recipient_profile:
            log(
                "info",
                "welcome_list_sender_back_profile_to_followers_extra_back_tapped",
                username=username,
                source_profile_username=src or None,
                action_bar_title=ab_title,
            )
            tapped3, _tap_method3 = tap_instagram_action_bar_back_button(d, pkg)
            extra_back_tapped = bool(tapped3)
            if tapped3 and settle_s > 0:
                time.sleep(settle_s)
            _repoll_after_extra_back()

    if not followers_ok:
        log(
            "info",
            "welcome_list_sender_back_profile_to_followers_poll_failed",
            username=username,
            source_profile_username=src or None,
            extra_back_tapped=extra_back_tapped,
            action_bar_title=det.get("action_bar_title"),
            signals=det.get("signals"),
        )

    out["followers_surface_ok"] = followers_ok
    out["extra_back_tapped"] = extra_back_tapped
    log(
        "info",
        "welcome_list_sender_back_profile_to_followers_done",
        username=username,
        tapped=bool(tapped2),
        tap_method=tap_method2,
        followers_detected_fresh=followers_ok,
        ms=round((time.perf_counter() - t1) * 1000.0, 2),
        action_bar_title=det.get("action_bar_title"),
        signals=det.get("signals"),
        extra_back_tapped=extra_back_tapped,
    )
    if followers_ok:
        log(
            "info",
            "welcome_list_sender_followers_surface_restored",
            username=username,
            source_profile_username=src or None,
            followers_detect_hierarchy_source=det.get("followers_detect_hierarchy_source"),
            fresh_hierarchy_xml_len=len(fresh_hierarchy_xml),
            via="profile_to_followers_poll",
            extra_back_tapped=extra_back_tapped,
        )
    return out


def set_perf_metric(key: str, value: float | int | str) -> None:
    global _perf
    _perf[key] = value


def set_wait_event_callback(cb: Callable[..., None] | None) -> None:
    global _WAIT_EVENT_CALLBACK
    _WAIT_EVENT_CALLBACK = cb


def _emit_wait_event(wait_reason: str, wait_duration_ms: float) -> None:
    cb = _WAIT_EVENT_CALLBACK
    if cb is None:
        return
    try:
        cb(wait_reason, wait_duration_ms)
    except Exception:
        pass


def reset_dm_send_run_state() -> None:
    global _LAST_DM_SEND_RESULT
    _LAST_DM_SEND_RESULT = {}


def reset_dm_thread_probe_state() -> None:
    global _LAST_DM_THREAD_ATTEMPTED, _LAST_DM_THREAD_STATE, _LAST_DM_THREAD_CLASSIFY_SNAPSHOT
    _LAST_DM_THREAD_ATTEMPTED = False
    _LAST_DM_THREAD_STATE = "unknown"
    _LAST_DM_THREAD_CLASSIFY_SNAPSHOT = {}


def get_last_dm_thread_classify_snapshot() -> dict[str, Any]:
    return dict(_LAST_DM_THREAD_CLASSIFY_SNAPSHOT)


def get_last_dm_send_result() -> dict[str, Any]:
    return dict(_LAST_DM_SEND_RESULT)


def get_last_dm_thread_attempted() -> bool:
    return bool(_LAST_DM_THREAD_ATTEMPTED)


def get_last_dm_thread_state() -> str:
    return str(_LAST_DM_THREAD_STATE or "unknown")


def detect_unsupported_start_surface(d: u2.Device) -> str | None:
    try:
        if (
            (d(text="Allow").exists(timeout=0.05) or d(textContains="Allow").exists(timeout=0.05))
            and (
                d(textContains="photos and videos").exists(timeout=0.05)
                or d(textContains="Photos").exists(timeout=0.05)
            )
        ):
            return "android_permission_dialog"
    except Exception:
        pass
    return None


def detect_unexpected_android_media_permission_dialog(
    d: u2.Device,
) -> tuple[bool, str]:
    """
    Detect Android permission controller (e.g. photos/videos) — do not auto-allow.
    """
    fg = _current_foreground_package(d)
    if "permissioncontroller" in fg or "packageinstaller" in fg:
        return True, f"foreground:{fg}"
    needles = (
        "Allow Instagram to access photos",
        "access photos and videos",
        "Select photos and videos",
        "Allow all",
    )
    for frag in needles:
        try:
            if d(textContains=frag).exists(timeout=0.06):
                return True, f"text:{frag[:40]}"
        except Exception:
            continue
    return False, ""


def dismiss_android_permission_dialog(d: u2.Device) -> bool:
    for label in ("Don't allow", "Deny", "Refuser", "OK", "ALLOW"):
        try:
            o = d(text=label)
            if o.exists(timeout=0.08):
                o.click()
                return True
        except Exception:
            continue
    return False


def is_dm_thread_screen(d, pkg=None) -> bool:
    try:
        if not verify_app_foreground(d, pkg or config.INSTAGRAM_PACKAGE):
            return False
        w, h = d.window_size()
        for ed in d(className="android.widget.EditText").all():
            b = (ed.info or {}).get("bounds") or {}
            if int(b.get("top", 0)) > h * 0.25:
                return True
    except Exception:
        pass
    return False


def reset_to_search_for_next_target(d: u2.Device, pkg: str | None = None) -> bool:
    return return_to_search_from_profile(d, pkg)


def _dm_find_focus_composer(d: u2.Device) -> Any | None:
    """Bottom-half Instagram DM composer EditText (best-effort)."""
    w, h = d.window_size()
    # Prefer explicit composer resource id when available.
    try:
        cur_pkg = (d.app_current() or {}).get("package") or config.INSTAGRAM_PACKAGE
    except Exception:
        cur_pkg = config.INSTAGRAM_PACKAGE

    bottom_y_min = int(h * 0.5)
    rid_candidates = (
        "com.instagram.android:id/row_thread_composer_edittext",
        f"{cur_pkg}:id/row_thread_composer_edittext",
    )
    for rid in rid_candidates:
        try:
            el = d(resourceId=rid)
            if el.wait(timeout=0.08):
                b = ((el.info or {}).get("bounds") or {})
                top = int(b.get("top", 0))
                if top >= bottom_y_min:
                    return el
        except Exception:
            continue

    # ResourceIdMatches fallback (package-agnostic).
    try:
        sel = d(resourceIdMatches=r".*:id/row_thread_composer_edittext.*")
        objs = sel.all() if hasattr(sel, "all") else []
        for ed in objs:
            b = ((ed.info or {}).get("bounds") or {})
            top = int(b.get("top", 0))
            if top >= bottom_y_min:
                return ed
    except Exception:
        pass

    # Generic: bottom-half EditText.
    y_min = int(h * 0.28)
    best = None
    best_top = -1
    try:
        for ed in d(className="android.widget.EditText").all():
            info = ed.info or {}
            b = info.get("bounds") or {}
            top = int(b.get("top", 0))
            if top < y_min:
                continue
            if top >= best_top:
                best_top = top
                best = ed
    except Exception:
        return None
    return best


def _dm_restricted_surfaces(d: u2.Device) -> bool:
    try:
        needles = (
            "can't message",
            "Cannot message",
            "can't reply",
            "Message unavailable",
            "restricted",
            "Ne peut pas envoyer",
        )
        for frag in needles:
            if d(textContains=frag).exists(timeout=0.05):
                return True
    except Exception:
        pass
    return False


def _dm_hierarchy_suggests_existing_thread(hier: str) -> bool:
    if not hier:
        return False
    markers = (
        "row_thread_message",
        "direct_message_text",
        "message_content",
        "thread_message",
        "inbox_message",
        "message_bubble",
    )
    blob = hier.lower()
    return any(m in blob for m in markers)


def _dm_message_keyword_blobs() -> tuple[str, ...]:
    # Covers: Message / Send message / Envoyer un message / Écrire un message
    return (
        "Message",
        "Send message",
        "Envoyer un message",
        "Ecrire un message",
        "Écrire un message",
        "Write a message",
    )


def _dm_detect_composer_signal(
    d: u2.Device, *, current_pkg: str, timeout_s: float
) -> tuple[bool, str, dict[str, int] | None, Any | None]:
    """
    Best-effort composer detection.
    Returns: (composer_visible, composer_signal, composer_bounds, composer_el)
    """
    deadline = time.monotonic() + float(timeout_s)
    w, h = d.window_size()
    bottom_y_min = int(h * 0.5)
    composer_el: Any | None = None
    composer_signal = ""
    composer_bounds: dict[str, int] | None = None
    exact_rid = "com.instagram.android:id/row_thread_composer_edittext"
    pkg_rid = f"{current_pkg}:id/row_thread_composer_edittext"

    # 1) resource-id exact
    while time.monotonic() < deadline:
        try:
            el = d(resourceId=exact_rid)
            if el.wait(timeout=0.05):
                b = (el.info or {}).get("bounds") or {}
                top = int(b.get("top", 0))
                if top >= bottom_y_min:
                    composer_el = el
                    composer_bounds = b
                    composer_signal = "resource_id_exact_composer"
                    break
        except Exception:
            pass

        # 2) resourceIdMatches
        try:
            sel = d(resourceIdMatches=r".*:id/row_thread_composer_edittext.*")
            objs = sel.all() if hasattr(sel, "all") else []
            for ed in objs:
                b = (ed.info or {}).get("bounds") or {}
                top = int(b.get("top", 0))
                if top >= bottom_y_min:
                    composer_el = ed
                    composer_bounds = b
                    composer_signal = "resource_id_matches_composer"
                    break
            if composer_el is not None:
                break
        except Exception:
            pass

        # 3) pkg-specific exact rid
        try:
            el = d(resourceId=pkg_rid)
            if el.wait(timeout=0.05):
                b = (el.info or {}).get("bounds") or {}
                top = int(b.get("top", 0))
                if top >= bottom_y_min:
                    composer_el = el
                    composer_bounds = b
                    composer_signal = "resource_id_exact_composer_pkg"
                    break
        except Exception:
            pass

        # 4) className EditText in lower half
        try:
            for ed in d(className="android.widget.EditText").all():
                b = (ed.info or {}).get("bounds") or {}
                top = int(b.get("top", 0))
                if top >= bottom_y_min:
                    composer_el = ed
                    composer_bounds = b
                    composer_signal = "edittext_bottom_half_composer"
                    break
            if composer_el is not None:
                break
        except Exception:
            pass

        time.sleep(float(getattr(config, "DM_THREAD_POLL_S", 0.08)))

    if composer_el is None:
        return False, "", None, None

    # 5) hint/text/content-desc containing keywords
    try:
        info = composer_el.info or {}
        # uiautomator2 may expose hint via contentDescription depending on node.
        blob = " ".join(
            str(info.get(k, "") or "")
            for k in ("text", "contentDescription", "description", "resourceName")
        )
        try:
            t = composer_el.get_text() or ""
        except Exception:
            t = ""
        blob = f"{blob} {t}".lower()
        if any(kw.lower() in blob for kw in _dm_message_keyword_blobs()):
            if composer_signal:
                composer_signal = f"{composer_signal}+hint_message_keyword"
            else:
                composer_signal = "hint_message_keyword"
    except Exception:
        pass

    return True, composer_signal, composer_bounds, composer_el


def _dm_detect_history_signal(
    d: u2.Device, *, composer_bounds: dict[str, int] | None
) -> tuple[bool, bool, str]:
    """Best-effort history detection in DM thread."""
    # 1) resource-id containing message_container
    try:
        if d(resourceIdMatches=r".*:id/.*message_container.*").exists(timeout=0.06):
            return True, True, "resource_message_container"
    except Exception:
        pass

    # 2) resource-id exact direct_text_message_text_view (package-agnostic)
    try:
        if d(resourceIdMatches=r".*:id/direct_text_message_text_view").exists(timeout=0.06):
            return True, True, "resource_direct_text_message_text_view"
    except Exception:
        pass

    # 3) resource-id containing direct_text_message
    try:
        if d(resourceIdMatches=r".*:id/.*direct_text_message.*").exists(timeout=0.06):
            return True, True, "resource_direct_text_message"
    except Exception:
        pass

    # 4) recycler/list with messages above composer
    composer_top = None
    try:
        if composer_bounds:
            composer_top = int(composer_bounds.get("top"))
    except Exception:
        composer_top = None

    if composer_top is not None:
        # Keep it simple: if a list/recycler view exists and is mostly above the composer,
        # treat that as history visible.
        for cls in (
            "androidx.recyclerview.widget.RecyclerView",
            "android.widget.ListView",
        ):
            try:
                for el in d(className=cls).all():
                    b = (el.info or {}).get("bounds") or {}
                    top = int(b.get("top", 0))
                    bottom = int(b.get("bottom", 0))
                    if bottom <= composer_top and top < composer_top:
                        return True, True, "recycler_list_above_composer"
            except Exception:
                pass

    # 5) day/status texts
    for txt in ("Today", "Yesterday", "Vu", "Delivered", "Sent", "Envoyé", "Envoye"):
        try:
            if d(textContains=txt).exists(timeout=0.06):
                return True, True, "status_text_marker"
        except Exception:
            pass

    return False, False, ""


def detect_dm_thread_state(
    d: u2.Device,
    username: str,
    pkg: str | None = None,
    *,
    composer_timeout_s: float | None = None,
) -> tuple[str, dict[str, Any]]:
    """
    Detect DM thread state after opening Message:
    - empty_new_thread: composer visible, no history after short probe window
    - existing_thread: composer visible and history signal present
    Never returns unknown when composer is visible.
    """
    start = time.perf_counter()
    current_pkg = pkg or (d.app_current() or {}).get("package") or config.INSTAGRAM_PACKAGE
    # Snapshot fields requested by runner debugging.
    snap: dict[str, Any] = {
        "thread_state": "unknown",
        "composer_visible": False,
        "composer_signal": "",
        "has_history": False,
        "has_history_signal": False,
        "history_signal_type": "",
        "draft_only_fast": False,
        "package": current_pkg,
        "username": username,
    }

    if composer_timeout_s is None:
        composer_timeout_s = float(getattr(config, "DM_THREAD_DETECT_MAX_S", 2.5))
    else:
        composer_timeout_s = float(composer_timeout_s)
    composer_visible = False
    composer_signal = ""
    composer_bounds: dict[str, int] | None = None

    # Wait for composer to appear using multiple strategies.
    composer_visible, composer_signal, composer_bounds, _ = _dm_detect_composer_signal(
        d, current_pkg=current_pkg, timeout_s=composer_timeout_s
    )
    snap["composer_visible"] = bool(composer_visible)
    snap["composer_signal"] = str(composer_signal or "")

    if not composer_visible:
        return "unknown", snap

    # Restricted surfaces should stay as their own state.
    if _dm_restricted_surfaces(d):
        snap["thread_state"] = "restricted_account"
        log(
            "info",
            "dm_thread_state_detected",
            username=username,
            thread_state="restricted_account",
            dm_thread_detect_ms=round((time.perf_counter() - start) * 1000, 2),
        )
        return "restricted_account", snap

    log(
        "info",
        "dm_thread_composer_signal_seen",
        username=username,
        composer_visible=True,
        composer_signal=snap["composer_signal"],
    )

    has_history, has_hist_signal, hist_type = _dm_detect_history_signal(
        d, composer_bounds=composer_bounds
    )
    snap["has_history"] = bool(has_history)
    snap["has_history_signal"] = bool(has_hist_signal)
    snap["history_signal_type"] = str(hist_type or "")

    log(
        "info",
        "dm_thread_existing_history_signal",
        username=username,
        has_history=bool(has_history),
        history_signal_type=snap["history_signal_type"],
    )

    if has_history:
        snap["thread_state"] = "existing_thread"
        return "existing_thread", snap

    # No history yet: short probe window.
    snap["draft_only_fast"] = True
    probe_s = float(getattr(config, "DM_EXISTING_THREAD_PROBE_S", 0.8))
    poll_s = float(getattr(config, "DM_EXISTING_THREAD_POLL_S", 0.1))
    probe_deadline = time.monotonic() + probe_s
    thread_state = "empty_new_thread"

    while time.monotonic() < probe_deadline:
        has_history, has_hist_signal, hist_type = _dm_detect_history_signal(
            d, composer_bounds=composer_bounds
        )
        if has_history:
            thread_state = "existing_thread"
            snap["has_history"] = True
            snap["has_history_signal"] = True
            snap["history_signal_type"] = str(hist_type or "")
            snap["draft_only_fast"] = False
            break
        time.sleep(poll_s)

    snap["thread_state"] = thread_state
    return thread_state, snap


def _welcome_dm_forensics_username_key(username: str) -> str:
    raw = str(username or "").strip().lstrip("@")
    key = re.sub(r"[^a-zA-Z0-9._-]+", "_", raw).strip("_")
    return (key[:80] if key else "unknown")


def _welcome_dm_message_button_factories(
    d: u2.Device,
) -> tuple[tuple[str, Callable[[], Any]], ...]:
    return (
        ("text:Message", lambda: d(text="Message")),
        ("textContains:Message", lambda: d(textContains="Message")),
        ("description:Message", lambda: d(descriptionContains="Message")),
    )


def _welcome_dm_message_button_present(d: u2.Device) -> bool:
    for _label, factory in _welcome_dm_message_button_factories(d):
        try:
            if factory().exists(timeout=0.05):
                return True
        except Exception:
            continue
    return False


def _welcome_dm_try_tap_message_button(
    d: u2.Device,
    *,
    wait_s: float = 0.4,
) -> tuple[bool, str, str, int | None, int | None]:
    """
    Resolve Message CTA fresh and tap once.
    Returns: tapped, button_signal, click_method, tap_x, tap_y.
    """
    for label, factory in _welcome_dm_message_button_factories(d):
        try:
            el = factory()
            if not el.wait(timeout=float(wait_s)):
                continue
            info = el.info or {}
            bounds = dict(info.get("bounds") or {})
            center = _followers_bounds_center(bounds)
            if center is not None:
                tap_x, tap_y = int(center[0]), int(center[1])
                d.click(tap_x, tap_y)
                return True, label, "bounds_center_click", tap_x, tap_y
            el.click()
            return True, label, "u2_selector_click", None, None
        except Exception:
            continue
    return False, "", "", None, None


def _welcome_dm_quick_composer_visible(d: u2.Device, pkg: str) -> bool:
    if is_dm_thread_screen(d, pkg):
        return True
    visible, _sig, _bounds, _el = _dm_detect_composer_signal(
        d, current_pkg=pkg, timeout_s=0.25
    )
    return bool(visible)


def _welcome_dm_still_on_profile_with_message_cta(d: u2.Device, pkg: str) -> bool:
    """True when DM thread is not open but profile Message CTA is still visible."""
    if is_dm_thread_screen(d, pkg):
        return False
    if _welcome_dm_quick_composer_visible(d, pkg):
        return False
    return bool(_welcome_dm_message_button_present(d))


def _welcome_dm_read_action_bar_title(d: u2.Device) -> str:
    try:
        ab = d(resourceIdMatches=r".*:id/action_bar_title.*")
        if ab.exists(timeout=0.08):
            return str(ab.get_text() or "").strip()
    except Exception:
        pass
    return ""


def _welcome_dm_modal_signal(d: u2.Device) -> str:
    if _session_modal_or_crash(d):
        return "session_modal_or_crash"
    try:
        if d(className="android.app.AlertDialog").exists(timeout=0.05):
            return "alert_dialog"
        if d(classNameMatches=r".*[Dd]ialog.*").exists(timeout=0.05):
            return "dialog_class"
    except Exception:
        pass
    try:
        unsupported = detect_unsupported_start_surface(d)
        if unsupported:
            return str(unsupported)
    except Exception:
        pass
    return ""


def _capture_welcome_dm_forensics_artifacts(
    d: u2.Device,
    username: str,
    *,
    artifact_suffix: str,
) -> dict[str, Any]:
    """
    Welcome list-native DM forensics: screenshot + hierarchy XML under logs/.
    artifact_suffix: post_message_tap | thread_unknown
    """
    _ensure_debug_dirs()
    key = _welcome_dm_forensics_username_key(username)
    stem = f"welcome_dm_{artifact_suffix}_{key}"
    shot_path = _SCREENSHOTS_DIR / f"{stem}.png"
    xml_path = _XML_DIR / f"{stem}.xml"
    out: dict[str, Any] = {
        "artifact_stem": stem,
        "screenshot_path": None,
        "xml_path": None,
    }
    try:
        screenshot(d, str(shot_path))
        out["screenshot_path"] = str(shot_path)
    except Exception as e:
        out["screenshot_error"] = str(e)[:200]
    try:
        try:
            hier = d.dump_hierarchy(compressed=False)
        except TypeError:
            hier = d.dump_hierarchy()
        xml_path.write_text(hier, encoding="utf-8")
        out["xml_path"] = str(xml_path)
    except Exception as e:
        out["xml_write_error"] = str(e)[:200]
    return out


def _observe_welcome_dm_classification_surface(
    d: u2.Device,
    username: str,
    *,
    pkg: str,
    snap: dict[str, Any] | None = None,
    artifacts: dict[str, Any] | None = None,
    detection_elapsed_ms: float | None = None,
    button_signal: str = "",
) -> dict[str, Any]:
    """Structured observation for welcome_dm_*_observed logs (no business decisions)."""
    snap = dict(snap or {})
    artifacts = dict(artifacts or {})
    meta = _followers_current_pkg_activity(d)
    current_pkg = str(meta.get("current_package") or pkg or "")
    composer_visible = bool(snap.get("composer_visible"))
    has_history = bool(snap.get("has_history") or snap.get("has_history_signal"))
    message_present = _welcome_dm_message_button_present(d)
    obs: dict[str, Any] = {
        "username": str(username or "").strip(),
        "current_package": current_pkg or None,
        "current_activity": meta.get("current_activity"),
        "action_bar_title": _welcome_dm_read_action_bar_title(d),
        "composer_visible": composer_visible,
        "composer_signal": str(snap.get("composer_signal") or ""),
        "existing_history_signal": has_history,
        "history_signal_type": str(snap.get("history_signal_type") or ""),
        "restricted_signal": bool(_dm_restricted_surfaces(d)),
        "dm_not_available_signal": not message_present,
        "message_button_present": message_present,
        "modal_signal": _welcome_dm_modal_signal(d) or None,
        "button_signal": str(button_signal or "") or None,
        "screenshot_path": artifacts.get("screenshot_path"),
        "xml_path": artifacts.get("xml_path"),
        "is_dm_thread_screen": bool(is_dm_thread_screen(d, current_pkg or pkg)),
        "current_screen_guess": _guess_profile_screen(d, current_pkg or pkg, username),
    }
    if detection_elapsed_ms is not None:
        obs["detection_elapsed_ms"] = round(float(detection_elapsed_ms), 2)
    return obs


def _welcome_dm_forensics_debug_enabled() -> bool:
    env_raw = os.environ.get("WELCOME_DM_FORENSICS_DEBUG")
    if env_raw is not None:
        return str(env_raw).strip().lower() in ("1", "true", "yes", "on")
    return bool(getattr(config, "WELCOME_DM_FORENSICS_DEBUG", False))


def _welcome_dm_should_capture_forensics_artifacts(thread_state: str) -> bool:
    if str(thread_state or "") == "unknown":
        return True
    return _welcome_dm_forensics_debug_enabled()


def _log_welcome_dm_thread_unknown_observed(
    d: u2.Device,
    username: str,
    *,
    pkg: str,
    snap: dict[str, Any],
    button_signal: str,
    detection_elapsed_ms: float,
) -> None:
    artifacts: dict[str, Any] = {}
    if _welcome_dm_should_capture_forensics_artifacts("unknown"):
        artifacts = _capture_welcome_dm_forensics_artifacts(
            d, username, artifact_suffix="thread_unknown"
        )
    obs = _observe_welcome_dm_classification_surface(
        d,
        username,
        pkg=pkg,
        snap=snap,
        artifacts=artifacts,
        detection_elapsed_ms=detection_elapsed_ms,
        button_signal=button_signal,
    )
    log("info", "welcome_dm_thread_unknown_observed", **obs)


def open_dm_thread_from_profile(
    d: u2.Device, username: str, *, welcome_list_native: bool = False
) -> str:
    global _LAST_DM_THREAD_ATTEMPTED, _LAST_DM_THREAD_STATE, _LAST_DM_THREAD_CLASSIFY_SNAPSHOT
    _LAST_DM_THREAD_ATTEMPTED = True
    try:
        pkg = (d.app_current() or {}).get("package") or config.INSTAGRAM_PACKAGE
    except Exception:
        pkg = config.INSTAGRAM_PACKAGE
    _LAST_DM_THREAD_STATE = "unknown"

    t_open = time.perf_counter()
    tapped, button_signal, click_method, tap_x, tap_y = _welcome_dm_try_tap_message_button(
        d, wait_s=0.4
    )
    dm_open_click_ms = (time.perf_counter() - t_open) * 1000
    _perf["dm_open_click_ms"] = dm_open_click_ms

    if not tapped:
        log("error", "dm_message_button_missing", username=username)
        _LAST_DM_THREAD_STATE = "dm_not_available"
        return "dm_not_available"

    log(
        "info",
        "dm_message_button_clicked",
        username=username,
        button_signal=button_signal,
        click_method=click_method,
        dm_open_click_ms=round(dm_open_click_ms, 2),
        tap_x=tap_x,
        tap_y=tap_y,
        click_attempt=1,
        welcome_list_native=bool(welcome_list_native),
    )

    post_open_settle_s = float(getattr(config, "DM_THREAD_POST_OPEN_SETTLE_S", 0.45))
    time.sleep(post_open_settle_s)

    message_click_attempts = 1
    if welcome_list_native and _welcome_dm_still_on_profile_with_message_cta(d, pkg):
        log(
            "info",
            "welcome_dm_message_click_retry_scheduled",
            username=username,
            button_signal=button_signal,
            first_click_method=click_method,
            post_open_settle_s=round(post_open_settle_s, 3),
        )
        t_retry = time.perf_counter()
        retry_tapped, retry_signal, retry_method, retry_x, retry_y = (
            _welcome_dm_try_tap_message_button(d, wait_s=0.35)
        )
        retry_click_ms = (time.perf_counter() - t_retry) * 1000
        if retry_tapped:
            message_click_attempts = 2
            button_signal = retry_signal or button_signal
            log(
                "info",
                "welcome_dm_message_click_retry_tapped",
                username=username,
                button_signal=button_signal,
                click_method=retry_method,
                dm_retry_click_ms=round(retry_click_ms, 2),
                tap_x=retry_x,
                tap_y=retry_y,
                click_attempt=2,
            )
            time.sleep(post_open_settle_s)
        else:
            log(
                "warning",
                "welcome_dm_message_click_retry_failed",
                username=username,
                dm_retry_click_ms=round(retry_click_ms, 2),
                reason="message_button_not_found_on_retry",
            )

    # detect_dm_thread_state (must be called after clicking Message)
    t_detect = time.perf_counter()
    detect_timeout_s = float(getattr(config, "DM_THREAD_DETECT_MAX_S", 2.5))
    if welcome_list_native:
        detect_timeout_s = float(
            getattr(config, "WELCOME_DM_THREAD_DETECT_MAX_S", 9.0) or 9.0
        )
        log(
            "info",
            "welcome_dm_thread_detect_started",
            username=username,
            composer_timeout_s=detect_timeout_s,
            welcome_list_native=True,
        )
    thread_state, snap = detect_dm_thread_state(
        d,
        username,
        pkg=pkg,
        composer_timeout_s=detect_timeout_s,
    )
    dm_thread_detect_ms = (time.perf_counter() - t_detect) * 1000
    _perf["dm_thread_detect_ms"] = dm_thread_detect_ms
    _LAST_DM_THREAD_STATE = thread_state
    _LAST_DM_THREAD_CLASSIFY_SNAPSHOT = snap

    log(
        "info",
        "dm_thread_state_detected",
        username=username,
        thread_state=thread_state,
        dm_thread_detect_ms=round(float(dm_thread_detect_ms), 2),
        message_click_attempts=int(message_click_attempts),
    )

    if thread_state not in ("unknown", "dm_not_available"):
        log(
            "info",
            "dm_thread_opened",
            username=username,
            thread_state=thread_state,
            button_signal=button_signal,
            dm_open_click_ms=round(dm_open_click_ms, 2),
            message_click_attempts=int(message_click_attempts),
            composer_visible=bool(snap.get("composer_visible")),
        )

    if welcome_list_native and thread_state == "unknown":
        _log_welcome_dm_thread_unknown_observed(
            d,
            username,
            pkg=pkg,
            snap=dict(snap),
            button_signal=button_signal,
            detection_elapsed_ms=dm_thread_detect_ms,
        )

    return thread_state


def verify_dm_composer_safe(d: u2.Device, pkg: str | None = None) -> tuple[bool, str]:
    p = pkg or config.INSTAGRAM_PACKAGE
    if not verify_app_foreground(d, p):
        return False, "not_foreground"
    if is_lightweight_search_screen(d, p):
        return False, "on_search_not_dm_accepts"
    acc = float(getattr(config, "FAST_DM_COMPOSER_ACCEPT_S", 1.45))
    w0 = time.perf_counter()
    composer: Any | None = None
    while (time.perf_counter() - w0) < acc:
        composer = _dm_find_focus_composer(d)
        if composer is not None:
            return True, "ok"
        time.sleep(0.08)
    _emit_wait_event("dm_composer_wait", (time.perf_counter() - w0) * 1000)
    return False, "no_dm_composer"


def type_dm_draft_only(
    d: u2.Device,
    draft: str,
    pkg: str | None = None,
    *,
    force_method: str | None = None,
) -> tuple[bool, Any]:
    _ = pkg or config.INSTAGRAM_PACKAGE
    t0 = time.perf_counter()
    ed = _dm_find_focus_composer(d)
    if ed is None:
        return False, "no_composer"
    try:
        ed.click()
        time.sleep(0.05)
    except Exception:
        pass
    text = str(draft or "")

    def _read_composer_text() -> str:
        try:
            cur = _dm_find_focus_composer(d) or ed
            return str((cur.get_text() if cur is not None else "") or "")
        except Exception:
            return ""

    def _prefix20(s: str) -> str:
        return str(s or "")[:20]

    def _closeness(actual: str, expected: str) -> float:
        a = str(actual or "")
        e = str(expected or "")
        if not e:
            return 1.0
        # Prefix-oriented similarity for truncated FastIME behavior.
        n = min(len(a), len(e))
        i = 0
        while i < n and a[i] == e[i]:
            i += 1
        return float(i) / float(len(e))

    serial = get_device_serial(d)
    fast_ime = (getattr(config, "FAST_IME", "") or "").strip()
    type_meta: dict[str, Any] = {
        "method": "",
        "fastime_used": False,
        "set_text_used": False,
        "composer_visible": True,
        "expected_text_len": len(text),
        "actual_text_len": 0,
        "text_prefix_preview": "",
        "verify_will_continue": False,
        "fastime_partial_text": False,
        "fastime_truncated": False,
        "fallback_set_text_started": False,
        "fallback_set_text_ok": False,
        "fallback_set_text_failed": False,
        "actual_text_len_after_fastime": 0,
        "text_prefix_after_fastime": "",
        "actual_text_len_after_set_text": 0,
        "text_prefix_after_set_text": "",
    }

    use_fast_ime = (
        force_method != "set_text"
        and bool(fast_ime)
        and is_fast_ime_available(serial)
        and force_method in (None, "", "fast_ime")
    )
    if use_fast_ime:
        cmd_ok, _, sw_ok, br_ok = run_fast_ime_input(serial, text, fast_ime_id=fast_ime)
        fastime_ok = bool(cmd_ok and (sw_ok or br_ok))
        type_meta["method"] = "fast_ime"
        type_meta["fastime_used"] = True
        if not fastime_ok:
            _perf["dm_draft_typing_ms"] = (time.perf_counter() - t0) * 1000
            return False, "fast_ime_failed"

        actual_fastime = _read_composer_text()
        type_meta["actual_text_len_after_fastime"] = len(actual_fastime)
        type_meta["text_prefix_after_fastime"] = _prefix20(actual_fastime)
        clos_fastime = _closeness(actual_fastime, text)
        truncated = len(actual_fastime) < len(text)
        sufficient_portion = clos_fastime >= 0.75
        partial_fastime = truncated or (not sufficient_portion)
        type_meta["fastime_truncated"] = bool(truncated)
        type_meta["fastime_partial_text"] = bool(partial_fastime)

        if partial_fastime:
            type_meta["fallback_set_text_started"] = True
            type_meta["set_text_used"] = True
            try:
                ed.set_text(text)
            except Exception as e:
                type_meta["fallback_set_text_failed"] = True
                type_meta["actual_text_len"] = len(actual_fastime)
                type_meta["text_prefix_preview"] = _prefix20(actual_fastime)
                _perf["dm_draft_typing_ms"] = (time.perf_counter() - t0) * 1000
                return False, {"reason": str(e), **type_meta}

            actual_set = _read_composer_text()
            type_meta["actual_text_len_after_set_text"] = len(actual_set)
            type_meta["text_prefix_after_set_text"] = _prefix20(actual_set)
            clos_set = _closeness(actual_set, text)
            if clos_set >= clos_fastime:
                type_meta["fallback_set_text_ok"] = True
                type_meta["method"] = "set_text"
                type_meta["actual_text_len"] = len(actual_set)
                type_meta["text_prefix_preview"] = _prefix20(actual_set)
                type_meta["verify_will_continue"] = True
                _perf["dm_draft_typing_ms"] = (time.perf_counter() - t0) * 1000
                return True, type_meta

            type_meta["fallback_set_text_failed"] = True
            type_meta["actual_text_len"] = len(actual_set)
            type_meta["text_prefix_preview"] = _prefix20(actual_set)
            _perf["dm_draft_typing_ms"] = (time.perf_counter() - t0) * 1000
            return False, {
                "reason": "set_text_not_better_than_fastime",
                **type_meta,
            }

        type_meta["actual_text_len"] = len(actual_fastime)
        type_meta["text_prefix_preview"] = _prefix20(actual_fastime)
        type_meta["verify_will_continue"] = True
        _perf["dm_draft_typing_ms"] = (time.perf_counter() - t0) * 1000
        return True, type_meta
    else:
        ok = False
        try:
            ed.set_text(text)
            ok = True
        except Exception as e:
            return False, str(e)
        actual_set = _read_composer_text()
        type_meta["method"] = "set_text"
        type_meta["set_text_used"] = True
        type_meta["actual_text_len_after_set_text"] = len(actual_set)
        type_meta["text_prefix_after_set_text"] = _prefix20(actual_set)
        type_meta["actual_text_len"] = len(actual_set)
        type_meta["text_prefix_preview"] = _prefix20(actual_set)
        type_meta["verify_will_continue"] = bool(ok)

    _perf["dm_draft_typing_ms"] = (time.perf_counter() - t0) * 1000
    if not ok:
        return False, "fast_ime_failed"
    return True, type_meta


def verify_dm_draft_text(d: u2.Device, expected: str) -> bool:
    t0 = time.perf_counter()
    ed = _dm_find_focus_composer(d)
    if ed is None:
        return False
    try:
        got = ed.get_text() or ""
    except Exception:
        return False
    _perf["dm_draft_verify_ms"] = (time.perf_counter() - t0) * 1000
    return got.strip() == str(expected).strip()


# --- Follow SAFE V1 (profile header; single tap; bounded verify) ---

_FOLLOW_RID_PATTERNS: tuple[str, ...] = (
    r".*:id/profile_header_follow_button",
    r".*:id/action_bar_button_follow",
    r".*:id/action_bar_follow_button",
    r".*:id/button_follow",
)

_FOLLOW_ACCEPT_TEXT: frozenset[str] = frozenset({"follow", "suivre"})

_FOLLOW_REJECT_TEXT: frozenset[str] = frozenset(
    {
        "following",
        "requested",
        "message",
        "contact",
        "add friend",
        "inviter",
        "invite",
        "suivi",
        "abonné",
        "abonnée",
        "demande envoyée",
        "en attente",
    }
)


def _follow_norm(s: str | None) -> str:
    return (s or "").strip().lower()


def _follow_safe_info(el: Any) -> dict[str, Any]:
    try:
        return dict(el.info or {})
    except Exception:
        return {}


def _follow_bounds_center_y(info: dict[str, Any], screen_h: int) -> int | None:
    b = info.get("bounds") or {}
    try:
        t = int(b.get("top", 0))
        bot = int(b.get("bottom", 0))
    except Exception:
        return None
    if bot <= t:
        return None
    cy = (t + bot) // 2
    if cy < 0 or cy > int(screen_h * 1.05):
        return None
    return cy


def _follow_ui_state_snapshot(d: u2.Device) -> str:
    """Coarse header state for logging and post-tap verification."""
    try:
        h = int(d.window_size()[1])
    except Exception:
        h = 1920
    y_lim = int(h * 0.52)

    def _exists_near_top(text: str) -> bool:
        sel = d(text=text)
        if not sel.exists(timeout=0.05):
            return False
        cy = _follow_bounds_center_y(_follow_safe_info(sel), h)
        return cy is not None and cy <= y_lim

    for lab in ("Requested", "Demande envoyée", "En attente"):
        if _exists_near_top(lab):
            return "requested"
    for lab in ("Following", "Abonné", "Abonnée", "Suivi"):
        if _exists_near_top(lab):
            return "following"
    try:
        if d(textContains="Follow back").exists(timeout=0.05) or d(
            textContains="Suivre en retour"
        ).exists(timeout=0.03):
            return "follow_back"
    except Exception:
        pass
    if d(text="Follow").exists(timeout=0.06) or d(text="Suivre").exists(timeout=0.06):
        return "follow"
    return "unknown"


def _follow_rid_suspicious(rid: str) -> bool:
    r = _follow_norm(rid)
    if not r:
        return False
    if re.search(
        r"(following|requested|message|messenger|contact|friend|invite|inviter)(?!.*follow)",
        r,
    ):
        return True
    if re.search(r"_following|_requested|_message\b", r):
        return True
    return False


def _follow_score_candidate(
    d: u2.Device,
    el: Any,
    *,
    username: str,
    header_band_relaxed: bool = False,
) -> tuple[int, dict[str, Any]] | tuple[None, dict[str, Any]]:
    inf = _follow_safe_info(el)
    rid = str(inf.get("resourceName") or "")
    txt = _follow_norm(inf.get("text"))
    desc = _follow_norm(inf.get("contentDescription"))
    try:
        h = int(d.window_size()[1])
    except Exception:
        h = 1920
    cy = _follow_bounds_center_y(inf, h)
    meta: dict[str, Any] = {
        "resource_id": rid,
        "text": inf.get("text"),
        "content_description": inf.get("contentDescription"),
        "clickable": bool(inf.get("clickable")),
        "enabled": bool(inf.get("enabled")),
        "center_y": cy,
        "screen_h": h,
        "target_username": username,
    }
    if cy is None:
        return None, {**meta, "reject": "no_bounds"}
    # Header band: avoid bottom-sheet / list rows (relaxed when profile already open / visual row tap)
    _y_top = int(h * 0.05) if header_band_relaxed else int(h * 0.07)
    _y_bot = int(h * 0.52) if header_band_relaxed else int(h * 0.44)
    if cy < _y_top or cy > _y_bot:
        return None, {**meta, "reject": "off_header_band"}
    if _follow_rid_suspicious(rid):
        return None, {**meta, "reject": "rid_blocked"}
    if txt in _FOLLOW_REJECT_TEXT or desc in _FOLLOW_REJECT_TEXT:
        return None, {**meta, "reject": "text_blocked"}
    blob = f"{txt} {desc}"
    if any(b in blob for b in ("following", "requested", "message", "contact", "friend", "invite")):
        return None, {**meta, "reject": "blob_blocked"}
    rid_l = _follow_norm(rid)
    accept_text = (txt in _FOLLOW_ACCEPT_TEXT) or (desc in _FOLLOW_ACCEPT_TEXT)
    rid_followish = ("follow" in rid_l) and not _follow_rid_suspicious(rid)
    if not accept_text and not rid_followish:
        return None, {**meta, "reject": "not_follow_control"}
    if not inf.get("enabled", True):
        return None, {**meta, "reject": "disabled"}
    cn = str(inf.get("className") or "")
    if not inf.get("clickable") and "Button" not in cn:
        return None, {**meta, "reject": "not_clickable"}
    score = 0
    if rid_followish:
        score += 120
    if txt in _FOLLOW_ACCEPT_TEXT:
        score += 80
    elif desc in _FOLLOW_ACCEPT_TEXT:
        score += 60
    if inf.get("clickable"):
        score += 40
    ideal = int(h * 0.20)
    score += max(0, 35 - abs(cy - ideal) // 25)
    return score, meta


def _follow_collect_elements(d: u2.Device) -> list[Any]:
    seen: set[tuple[Any, ...]] = set()
    out: list[Any] = []

    def _add(el: Any) -> None:
        sig = (
            _follow_safe_info(el).get("resourceName"),
            (_follow_safe_info(el).get("bounds") or {}).get("top"),
            (_follow_safe_info(el).get("bounds") or {}).get("left"),
        )
        if sig in seen:
            return
        seen.add(sig)
        out.append(el)

    for pat in _FOLLOW_RID_PATTERNS:
        try:
            for el in d(resourceIdMatches=pat).all():
                _add(el)
        except Exception:
            continue
    for lab in ("Follow", "Suivre"):
        try:
            for el in d(text=lab).all():
                _add(el)
        except Exception:
            continue
    return out


def wait_for_follow_button_safe(
    d: u2.Device,
    username: str,
    pkg: str | None = None,
    *,
    profile_already_open: bool = False,
    visual_candidate_id: str | None = None,
) -> tuple[Any | None, dict[str, Any]]:
    """
    Wait for a single safe Follow / Suivre control. Rejects Following, Requested, Message, etc.
    Returns (element, meta). meta includes 'events' list of (event_name, payload) for Supabase mirroring.

    When ``profile_already_open`` is True, skip username-based assumptions and use a slightly relaxed
    header vertical band so the Follow pill on the already-open profile can be scored.
    """
    pkg = pkg or getattr(config, "INSTAGRAM_PACKAGE", "") or ""
    events: list[tuple[str, dict[str, Any]]] = []
    deadline = time.monotonic() + float(getattr(config, "FOLLOW_BUTTON_WAIT_S", 4.0))
    poll_s = float(getattr(config, "POLL_INTERVAL_S", 0.08) or 0.08)
    last_ui = "unknown"

    def _record(event: str, payload: dict[str, Any]) -> None:
        events.append((event, dict(payload)))
        log("info", event, **payload)

    while time.monotonic() < deadline:
        if not verify_app_foreground(d, pkg):
            time.sleep(poll_s)
            continue
        last_ui = _follow_ui_state_snapshot(d)
        if last_ui in ("following", "requested", "follow_back"):
            return None, {
                "outcome": "already_connected",
                "ui_state": last_ui,
                "already_following": True,
                "events": events,
            }

        candidates = _follow_collect_elements(d)
        best: tuple[int, Any, dict[str, Any]] | None = None
        for el in candidates:
            scored = _follow_score_candidate(
                d,
                el,
                username=username,
                header_band_relaxed=bool(profile_already_open),
            )
            score, meta = scored
            _record(
                "follow_button_candidate_seen",
                {
                    **meta,
                    "target_username": username,
                    "score": score,
                    "navigation_state": "profile",
                },
            )
            if score is None:
                _record(
                    "follow_button_candidate_rejected",
                    {
                        "target_username": username,
                        "reason": meta.get("reject", "rejected"),
                        "resource_id": meta.get("resource_id"),
                        "text": meta.get("text"),
                        "navigation_state": "profile",
                    },
                )
                continue
            if best is None or int(score) > best[0]:
                best = (int(score), el, meta)

        if best is not None:
            _sc, el_pick, meta_pick = best
            _record(
                "follow_button_candidate_selected",
                {
                    "target_username": username,
                    "score": _sc,
                    "resource_id": meta_pick.get("resource_id"),
                    "text": meta_pick.get("text"),
                    "center_y": meta_pick.get("center_y"),
                    "navigation_state": "profile",
                },
            )
            return el_pick, {
                "outcome": "ready",
                "pick_meta": meta_pick,
                "events": events,
            }
        time.sleep(poll_s)

    _record(
        "follow_button_not_found",
        {
            "target_username": username,
            "last_ui_state": last_ui,
            "wait_s": round(float(getattr(config, "FOLLOW_BUTTON_WAIT_S", 4.0)), 3),
            "navigation_state": "profile",
            "profile_already_open": bool(profile_already_open),
            "visual_candidate_id": str(visual_candidate_id or ""),
        },
    )
    return None, {"outcome": "not_found", "last_ui_state": last_ui, "events": events}


_REVIEW_BEFORE_FOLLOW_TITLE_NEEDLES = (
    "Review this account before following",
    "Review this account",
)
_REVIEW_BEFORE_FOLLOW_BODY_NEEDLES = (
    "before you follow",
    "To be safe",
    "check any public info",
)
_REVIEW_SHEET_FOLLOW_LABELS: tuple[str, ...] = (
    "Follow",
    "Suivre",
    "Seguir",
)
_REVIEW_SHEET_CANCEL_LABELS: tuple[str, ...] = (
    "Cancel",
    "Annuler",
    "Cancelar",
)
FOLLOW_REVIEW_POPUP_UNHANDLED_FAILURE_CODE = 74


def _review_sheet_geometry(wh: int) -> dict[str, int]:
    return {
        "y_sheet_min": int(wh * 0.42),
        "y_profile_exclude_max": int(wh * 0.38),
        "y_cta_min": int(wh * 0.64),
        "y_cta_max": int(wh * 0.94),
    }


def _review_follow_label_matches(text: str, desc: str) -> tuple[bool, str]:
    t = (text or "").strip()
    d = (desc or "").strip()
    tl = t.lower()
    dl = d.lower()
    if tl in ("follow", "suivre", "seguir"):
        return True, "text_exact"
    if dl in ("follow", "suivre", "seguir"):
        return True, "content_desc_exact"
    if tl == "follow" or dl.startswith("follow"):
        return True, "text_or_desc_follow"
    return False, ""


def _review_bounds_center(bd: dict[str, Any]) -> tuple[int, int] | None:
    try:
        l = int(bd["left"])
        t = int(bd["top"])
        r = int(bd["right"])
        b = int(bd["bottom"])
    except (KeyError, TypeError, ValueError):
        return None
    if r <= l or b <= t:
        return None
    return (l + r) // 2, (t + b) // 2


def _review_sheet_follow_candidate_score(
    *,
    cy: int,
    geo: dict[str, int],
    match_kind: str,
    clickable: bool,
    cancel_top: int | None,
) -> float:
    score = 0.0
    if geo["y_cta_min"] <= cy <= geo["y_cta_max"]:
        score += 40.0
    if cy >= geo["y_sheet_min"]:
        score += 20.0
    if cy <= geo["y_profile_exclude_max"]:
        score -= 200.0
    if match_kind == "text_exact":
        score += 35.0
    elif match_kind == "content_desc_exact":
        score += 28.0
    elif match_kind == "hierarchy_xml":
        score += 22.0
    elif match_kind == "geometry_cancel_anchor":
        score += 18.0
    elif match_kind == "geometry_primary_cta":
        score += 12.0
    if clickable:
        score += 8.0
    score += min(30.0, max(0.0, (cy - geo["y_cta_min"]) / 12.0))
    if cancel_top is not None and cy < cancel_top:
        score += 15.0
    return score


def _find_review_sheet_follow_candidates(
    d: u2.Device,
    *,
    ww: int,
    wh: int,
) -> list[dict[str, Any]]:
    geo = _review_sheet_geometry(wh)
    cancel_tops: list[int] = []
    for lab in _REVIEW_SHEET_CANCEL_LABELS:
        try:
            for el in d(text=lab).all() or []:
                inf = _follow_safe_info(el)
                cy = _follow_bounds_center_y(inf, wh)
                if cy is None or cy < geo["y_sheet_min"]:
                    continue
                cancel_tops.append(int(cy))
        except Exception:
            continue
    cancel_top = min(cancel_tops) if cancel_tops else None

    raw: list[dict[str, Any]] = []

    def _add(
        *,
        cx: int,
        cy: int,
        detection_method: str,
        text: str = "",
        content_desc: str = "",
        resource_id: str = "",
        bounds: dict[str, Any] | None = None,
        clickable: bool = False,
    ) -> None:
        if cy <= geo["y_profile_exclude_max"]:
            return
        if cy < geo["y_sheet_min"] and detection_method not in (
            "geometry_cancel_anchor",
            "geometry_primary_cta",
        ):
            return
        sc = _review_sheet_follow_candidate_score(
            cy=cy,
            geo=geo,
            match_kind=detection_method,
            clickable=clickable,
            cancel_top=cancel_top,
        )
        raw.append(
            {
                "center_x": cx,
                "center_y": cy,
                "score": sc,
                "detection_method": detection_method,
                "text": text[:80],
                "content_desc": content_desc[:120],
                "resource_id": resource_id[:160],
                "bounds": bounds or {},
                "clickable": bool(clickable),
            }
        )

    for lab in _REVIEW_SHEET_FOLLOW_LABELS:
        probes: list[tuple[str, Any]] = [
            ("u2_text", lambda l=lab: d(text=l)),
            ("u2_text_contains", lambda l=lab: d(textContains=l)),
            ("u2_desc_contains", lambda l=lab: d(descriptionContains=l)),
        ]
        for probe_name, sel_factory in probes:
            try:
                els = sel_factory().all()
            except Exception:
                els = []
            for el in els or []:
                inf = _follow_safe_info(el)
                cy = _follow_bounds_center_y(inf, wh)
                bd = inf.get("bounds") or {}
                center = _review_bounds_center(bd) if bd else None
                if cy is None and center:
                    cy = center[1]
                if cy is None or center is None:
                    continue
                cx = center[0]
                ok, mk = _review_follow_label_matches(
                    str(inf.get("text") or lab),
                    str(inf.get("contentDescription") or ""),
                )
                if not ok:
                    continue
                _add(
                    cx=cx,
                    cy=cy,
                    detection_method=f"{probe_name}:{mk}",
                    text=str(inf.get("text") or ""),
                    content_desc=str(inf.get("contentDescription") or ""),
                    resource_id=str(inf.get("resourceName") or ""),
                    bounds=bd if isinstance(bd, dict) else {},
                    clickable=bool(inf.get("clickable")) or bool(inf.get("enabled")),
                )

    try:
        xml_raw = d.dump_hierarchy(compressed=False)
    except Exception:
        xml_raw = ""
    if xml_raw:
        try:
            root = ET.fromstring(xml_raw)
            for node in root.iter():
                text = str(node.attrib.get("text") or "")
                desc = str(node.attrib.get("content-desc") or "")
                ok, mk = _review_follow_label_matches(text, desc)
                if not ok:
                    continue
                bd = _dm_parse_bounds_attr_xml(node.attrib.get("bounds"))
                if not bd:
                    continue
                center = _review_bounds_center(bd)
                if not center:
                    continue
                cx, cy = center
                clickable = node.attrib.get("clickable") == "true"
                _add(
                    cx=cx,
                    cy=cy,
                    detection_method=f"hierarchy_xml:{mk}",
                    text=text,
                    content_desc=desc,
                    resource_id=str(node.attrib.get("resource-id") or ""),
                    bounds=bd,
                    clickable=clickable,
                )
        except Exception:
            pass

    if cancel_top is not None:
        anchor_cy = max(geo["y_cta_min"], cancel_top - int(wh * 0.12))
        _add(
            cx=ww // 2,
            cy=anchor_cy,
            detection_method="geometry_cancel_anchor",
            text="Follow",
            bounds={
                "left": ww // 10,
                "top": anchor_cy - 40,
                "right": ww - ww // 10,
                "bottom": anchor_cy + 40,
            },
            clickable=True,
        )

    if not raw:
        fallback_cy = int(wh * 0.82)
        _add(
            cx=ww // 2,
            cy=fallback_cy,
            detection_method="geometry_primary_cta",
            text="Follow",
            bounds={
                "left": ww // 10,
                "top": fallback_cy - 44,
                "right": ww - ww // 10,
                "bottom": fallback_cy + 44,
            },
            clickable=True,
        )

    deduped: list[dict[str, Any]] = []
    for cand in sorted(raw, key=lambda c: -float(c.get("score") or 0.0)):
        dup = False
        for kept in deduped:
            if (
                abs(int(cand["center_x"]) - int(kept["center_x"])) < 48
                and abs(int(cand["center_y"]) - int(kept["center_y"])) < 48
            ):
                dup = True
                break
        if not dup:
            deduped.append(cand)
    return deduped


def _review_before_follow_popup_visible(d: u2.Device) -> bool:
    """True when Instagram's pre-follow review bottom sheet is on screen."""
    title_hit = False
    for needle in _REVIEW_BEFORE_FOLLOW_TITLE_NEEDLES:
        try:
            if d(textContains=needle).exists(timeout=0.06):
                title_hit = True
                break
        except Exception:
            continue
    if not title_hit:
        return False
    for needle in _REVIEW_BEFORE_FOLLOW_BODY_NEEDLES:
        try:
            if d(textContains=needle).exists(timeout=0.05):
                return True
        except Exception:
            continue
    try:
        if d(text="Cancel").exists(timeout=0.05) and d(text="Follow").exists(timeout=0.05):
            return True
    except Exception:
        pass
    return title_hit


# Micro-fenêtre post-tap sheet : couvre ~2 s de convergence observée en run réel,
# sans dupliquer le follow verify global (perform_follow_safe).
_REVIEW_POPUP_DISMISS_POLL_INTERVAL_S = 0.12
_REVIEW_POPUP_DISMISS_POLL_MAX_S = 2.2


def _poll_review_sheet_dismissed_after_follow_tap(
    d: u2.Device,
    *,
    target_username: str = "",
    visual_candidate_id: str = "",
    attempt: int = 1,
    tap_x: int = 0,
    tap_y: int = 0,
    detection_method: str = "",
) -> bool:
    """
    After a sheet Follow tap, micro-poll until the sheet disappears or follow UI converges.

    Does not run a full follow verify — hands off to ``perform_follow_safe`` verify loop.
    """
    t0 = time.monotonic()
    polls = 0

    def _poll_success(*, exit_via: str, follow_state_after: str) -> bool:
        elapsed_ms = round((time.monotonic() - t0) * 1000.0, 2)
        try:
            log(
                "info",
                "follow_review_popup_follow_dismiss_poll_completed",
                target_username=str(target_username or ""),
                visual_candidate_id=str(visual_candidate_id or ""),
                attempt=int(attempt),
                dismissed=exit_via == "sheet_dismissed",
                exit_via=str(exit_via),
                follow_state_after=str(follow_state_after or ""),
                poll_count=polls,
                elapsed_ms=elapsed_ms,
            )
            if exit_via == "sheet_dismissed":
                log(
                    "info",
                    "follow_review_popup_dismissed_after_follow",
                    target_username=str(target_username or ""),
                    visual_candidate_id=str(visual_candidate_id or ""),
                    attempt=int(attempt),
                )
            log(
                "info",
                "follow_review_popup_follow_tap_success",
                target_username=str(target_username or ""),
                visual_candidate_id=str(visual_candidate_id or ""),
                tap_x=int(tap_x),
                tap_y=int(tap_y),
                detection_method=str(detection_method or ""),
                attempt=int(attempt),
                exit_via=str(exit_via),
            )
            log(
                "info",
                "follow_review_popup_verify_resumed",
                target_username=str(target_username or ""),
                visual_candidate_id=str(visual_candidate_id or ""),
            )
        except Exception:
            pass
        return True

    try:
        log(
            "info",
            "follow_review_popup_follow_dismiss_poll_started",
            target_username=str(target_username or ""),
            visual_candidate_id=str(visual_candidate_id or ""),
            attempt=int(attempt),
            poll_interval_s=_REVIEW_POPUP_DISMISS_POLL_INTERVAL_S,
            poll_max_s=_REVIEW_POPUP_DISMISS_POLL_MAX_S,
        )
    except Exception:
        pass
    while (time.monotonic() - t0) < _REVIEW_POPUP_DISMISS_POLL_MAX_S:
        polls += 1
        try:
            follow_st = _follow_ui_state_snapshot(d)
        except Exception:
            follow_st = ""
        if follow_st in ("following", "requested"):
            return _poll_success(
                exit_via="follow_converged", follow_state_after=follow_st
            )
        if not _review_before_follow_popup_visible(d):
            return _poll_success(
                exit_via="sheet_dismissed", follow_state_after=follow_st
            )
        remaining = _REVIEW_POPUP_DISMISS_POLL_MAX_S - (time.monotonic() - t0)
        if remaining <= 0:
            break
        time.sleep(min(_REVIEW_POPUP_DISMISS_POLL_INTERVAL_S, remaining))
    elapsed_ms = round((time.monotonic() - t0) * 1000.0, 2)
    try:
        log(
            "info",
            "follow_review_popup_follow_dismiss_poll_completed",
            target_username=str(target_username or ""),
            visual_candidate_id=str(visual_candidate_id or ""),
            attempt=int(attempt),
            dismissed=False,
            poll_count=polls,
            elapsed_ms=elapsed_ms,
        )
        log(
            "warning",
            "follow_review_popup_follow_tap_failed",
            target_username=str(target_username or ""),
            visual_candidate_id=str(visual_candidate_id or ""),
            reason="sheet_still_visible_after_tap",
            attempt=int(attempt),
            tap_x=int(tap_x),
            tap_y=int(tap_y),
        )
    except Exception:
        pass
    return False


def _try_review_before_follow_popup_confirm(
    d: u2.Device,
    *,
    target_username: str = "",
    visual_candidate_id: str = "",
) -> bool:
    """
    If the review sheet is open, tap its primary Follow CTA (sheet band only, not profile header).
    Returns True only when the sheet is dismissed after a sheet Follow tap.
    """
    if not _review_before_follow_popup_visible(d):
        return False
    try:
        log(
            "info",
            "follow_review_popup_detected",
            target_username=str(target_username or ""),
            visual_candidate_id=str(visual_candidate_id or ""),
        )
    except Exception:
        pass
    try:
        ww, wh = d.window_size()
    except Exception:
        ww, wh = 1080, 2400

    candidates = _find_review_sheet_follow_candidates(d, ww=ww, wh=wh)
    if not candidates:
        try:
            log(
                "warning",
                "follow_review_popup_follow_tap_failed",
                target_username=str(target_username or ""),
                visual_candidate_id=str(visual_candidate_id or ""),
                reason="no_sheet_follow_button",
                candidate_count=0,
            )
        except Exception:
            pass
        return False

    for attempt_idx, cand in enumerate(candidates[:3]):
        cx = int(cand["center_x"])
        cy = int(cand["center_y"])
        try:
            log(
                "info",
                "follow_review_popup_follow_button_candidate_found",
                target_username=str(target_username or ""),
                visual_candidate_id=str(visual_candidate_id or ""),
                attempt=attempt_idx + 1,
                detection_method=str(cand.get("detection_method") or ""),
                text=str(cand.get("text") or ""),
                content_desc=str(cand.get("content_desc") or ""),
                resource_id=str(cand.get("resource_id") or ""),
                bounds=cand.get("bounds") or {},
                tap_x=cx,
                tap_y=cy,
                score=round(float(cand.get("score") or 0.0), 2),
                clickable=bool(cand.get("clickable")),
            )
        except Exception:
            pass
        try:
            d.click(cx, cy)
        except Exception as e:
            try:
                log(
                    "warning",
                    "follow_review_popup_follow_tap_failed",
                    target_username=str(target_username or ""),
                    visual_candidate_id=str(visual_candidate_id or ""),
                    reason=f"click_failed:{e}",
                    attempt=attempt_idx + 1,
                    tap_x=cx,
                    tap_y=cy,
                )
            except Exception:
                pass
            continue
        try:
            log(
                "info",
                "follow_review_popup_follow_tap_sent",
                target_username=str(target_username or ""),
                visual_candidate_id=str(visual_candidate_id or ""),
                tap_x=cx,
                tap_y=cy,
                detection_method=str(cand.get("detection_method") or ""),
                attempt=attempt_idx + 1,
            )
        except Exception:
            pass
        if _poll_review_sheet_dismissed_after_follow_tap(
            d,
            target_username=str(target_username or ""),
            visual_candidate_id=str(visual_candidate_id or ""),
            attempt=attempt_idx + 1,
            tap_x=cx,
            tap_y=cy,
            detection_method=str(cand.get("detection_method") or ""),
        ):
            return True

    try:
        log(
            "warning",
            "follow_review_popup_follow_tap_failed",
            target_username=str(target_username or ""),
            visual_candidate_id=str(visual_candidate_id or ""),
            reason="sheet_still_visible_after_all_candidates",
            candidates_tried=min(3, len(candidates)),
        )
    except Exception:
        pass
    return False


def _follow_review_popup_unhandled_abort(
    d: u2.Device,
    *,
    target_username: str,
    visual_candidate_id: str,
    events: list[tuple[str, dict[str, Any]]],
    record: Callable[..., Any],
    state_before: str,
    state_after: str,
    reason: str,
) -> dict[str, Any] | None:
    """Safe-stop payload when the review sheet cannot be confirmed reliably.

    Returns ``None`` when a late reconcile shows the sheet is gone and follow converged.
    """
    popup_still_visible = bool(_review_before_follow_popup_visible(d))
    if not popup_still_visible and state_after in ("following", "requested"):
        try:
            log(
                "info",
                "follow_review_popup_late_success_reconciled",
                target_username=str(target_username or ""),
                visual_candidate_id=str(visual_candidate_id or ""),
                follow_state_before=state_before,
                follow_state_after=state_after,
                popup_still_visible=False,
                reason="popup_dismissed_after_initial_sheet_visible_check",
                original_abort_reason=str(reason or ""),
            )
        except Exception:
            pass
        try:
            record(
                "follow_review_popup_late_success_reconciled",
                {
                    "target_username": target_username,
                    "visual_candidate_id": str(visual_candidate_id or ""),
                    "follow_state_before": state_before,
                    "follow_state_after": state_after,
                    "popup_still_visible": False,
                    "reason": "popup_dismissed_after_initial_sheet_visible_check",
                    "original_abort_reason": str(reason or ""),
                },
            )
        except Exception:
            pass
        return None
    try:
        log(
            "error",
            "follow_review_popup_unhandled_safe_stop",
            target_username=str(target_username or ""),
            visual_candidate_id=str(visual_candidate_id or ""),
            reason=str(reason or ""),
            follow_state_before=state_before,
            follow_state_after=state_after,
            popup_still_visible=popup_still_visible,
        )
    except Exception:
        pass
    record(
        "follow_review_popup_unhandled_safe_stop",
        {
            "target_username": target_username,
            "visual_candidate_id": str(visual_candidate_id or ""),
            "reason": str(reason or ""),
            "follow_state_before": state_before,
            "follow_state_after": state_after,
            "failure_code": FOLLOW_REVIEW_POPUP_UNHANDLED_FAILURE_CODE,
        },
    )
    record(
        "follow_completed",
        {
            "target_username": target_username,
            "ok": False,
            "failure_code": FOLLOW_REVIEW_POPUP_UNHANDLED_FAILURE_CODE,
            "follow_state_before": state_before,
            "follow_state_after": state_after,
            "navigation_state": "profile",
        },
    )
    return {
        "ok": False,
        "failure_code": FOLLOW_REVIEW_POPUP_UNHANDLED_FAILURE_CODE,
        "failure_reason": "review_popup_unhandled",
        "tapped": True,
        "follow_state_before": state_before,
        "follow_state_after": state_after,
        "verify_attempts": 0,
        "events": events,
    }


def perform_follow_safe(
    d: u2.Device,
    username: str,
    pkg: str | None = None,
    *,
    profile_already_open: bool = False,
    visual_candidate_id: str | None = None,
    source_profile_username: str | None = None,
) -> dict[str, Any]:
    """
    Single-tap follow with bounded verification (Following or Requested). No retries / multi-tap.

    When ``profile_already_open`` is True, resolve the Follow control on the current profile surface
    without requiring a non-empty ``username`` (visual / open-profile follow path).
    """
    pkg = pkg or getattr(config, "INSTAGRAM_PACKAGE", "") or ""
    events: list[tuple[str, dict[str, Any]]] = []
    t_all = time.perf_counter()

    def _record(event: str, payload: dict[str, Any]) -> None:
        events.append((event, dict(payload)))
        log("info", event, **payload)

    def _visual_reconcile_failure(
        failure_code: int,
        *,
        attempted_tap: bool,
        verify_attempts: int,
        state_after_hint: str | None = None,
    ) -> dict[str, Any] | None:
        if not profile_already_open:
            return None
        partial = {
            "ok": False,
            "failure_code": int(failure_code),
            "events": list(events),
            "follow_state_before": state_before,
            "follow_state_after": state_after_hint
            if state_after_hint is not None
            else meta.get("last_ui_state"),
        }
        reco = visual_follow_post_action_reconcile(
            d,
            follow_out=partial,
            profile_already_open=True,
            visual_candidate_id=str(visual_candidate_id or ""),
        )
        if not reco.get("inferred_follow_success"):
            return None
        st_fix = str(reco.get("current_follow_state") or "")
        if st_fix not in ("following", "requested"):
            st_fix = _poll_follow_state_for_reconcile(d, rounds=8, delay_s=0.12)
        if st_fix not in ("following", "requested"):
            st_fix = str(
                state_after_hint
                or meta.get("last_ui_state")
                or state_before
                or "following"
            )
        had_tap_ev = any(
            isinstance(e, (list, tuple))
            and len(e) >= 1
            and e[0]
            in ("follow_tap_sent", "follow_action_exact_follow_tap_sent")
            for e in events
        )
        skipped = not (bool(attempted_tap) or had_tap_ev)
        _record(
            "follow_completed",
            {
                "target_username": username,
                "profile_already_open": True,
                "visual_candidate_id": str(visual_candidate_id or ""),
                "follow_state_before": state_before,
                "follow_state_after": st_fix,
                "verify_attempts": verify_attempts,
                "navigation_state": "profile",
                "reconciled_inferred_success": True,
                "reconciled_reason": str(reco.get("reason") or ""),
                "timings_ms": {"total": round((time.perf_counter() - t_all) * 1000, 2)},
            },
        )
        log(
            "info",
            "visual_follow_perform_follow_reconciled_to_success",
            target_username=str(username or ""),
            visual_candidate_id=str(visual_candidate_id or ""),
            prior_failure_code=int(failure_code),
            follow_state_after=st_fix,
            reconciled_reason=str(reco.get("reason") or ""),
        )
        log(
            "info",
            "visual_follow_direct_profile_action_success",
            target_username=str(username or ""),
            visual_candidate_id=str(visual_candidate_id or ""),
            follow_state_after=st_fix,
            verify_attempts=verify_attempts,
            note="reconciled_after_reported_failure",
        )
        return {
            "ok": True,
            "failure_code": None,
            "tapped": bool(attempted_tap or had_tap_ev),
            "skipped_tap": skipped,
            "follow_state_before": state_before,
            "follow_state_after": st_fix,
            "verify_attempts": verify_attempts,
            "events": events,
            "reconciled_inferred_success": True,
            "reconciled_reason": str(reco.get("reason") or ""),
        }

    if profile_already_open:
        log(
            "info",
            "visual_follow_profile_already_open_mode",
            target_username=str(username or ""),
            visual_candidate_id=str(visual_candidate_id or ""),
            header_band_relaxed=True,
        )

    state_before = _follow_ui_state_snapshot(d)
    if state_before in ("following", "requested", "follow_back"):
        _record(
            "follow_completed",
            {
                "target_username": username,
                "follow_state_before": state_before,
                "follow_state_after": state_before,
                "verify_attempts": 0,
                "navigation_state": "profile",
                "skipped_tap": True,
                "timings_ms": {"total": round((time.perf_counter() - t_all) * 1000, 2)},
                "note": "header_non_follow_cta_before_wait",
            },
        )
        return {
            "ok": True,
            "failure_code": None,
            "tapped": False,
            "skipped_tap": True,
            "already_following": True,
            "follow_state_before": state_before,
            "follow_state_after": state_before,
            "verify_attempts": 0,
            "events": events,
        }
    _record(
        "follow_started",
        {
            "target_username": username,
            "profile_already_open": bool(profile_already_open),
            "visual_candidate_id": str(visual_candidate_id or ""),
            "follow_state_before": state_before,
            "follow_state_after": None,
            "verify_attempts": 0,
            "navigation_state": "profile",
            "timings_ms": {"phase": 0.0},
        },
    )

    _use_follow_action_v2 = bool(profile_already_open)
    _src_prof = str(source_profile_username or "").strip()

    btn, meta = (None, {})
    if _use_follow_action_v2:
        from follow_action_engine import follow_action_surface_wait_and_select_element

        btn, meta = follow_action_surface_wait_and_select_element(
            d,
            username,
            pkg or "",
            visual_candidate_id=str(visual_candidate_id or ""),
            source_profile_username=_src_prof,
        )
    else:
        btn, meta = wait_for_follow_button_safe(
            d,
            username,
            pkg,
            profile_already_open=profile_already_open,
            visual_candidate_id=visual_candidate_id,
        )
    events.extend(meta.get("events") or [])

    if meta.get("already_following"):
        _record(
            "follow_completed",
            {
                "target_username": username,
                "follow_state_before": meta.get("ui_state", state_before),
                "follow_state_after": meta.get("ui_state"),
                "verify_attempts": 0,
                "navigation_state": "profile",
                "skipped_tap": True,
                "timings_ms": {"total": round((time.perf_counter() - t_all) * 1000, 2)},
            },
        )
        return {
            "ok": True,
            "failure_code": None,
            "tapped": False,
            "skipped_tap": True,
            "already_following": True,
            "follow_state_before": meta.get("ui_state", state_before),
            "follow_state_after": meta.get("ui_state"),
            "verify_attempts": 0,
            "events": events,
        }

    if btn is None:
        if profile_already_open:
            lu = str(meta.get("last_ui_state") or meta.get("ui_state") or "").strip()
            if lu in ("following", "requested", "follow_back"):
                _record(
                    "follow_completed",
                    {
                        "target_username": username,
                        "follow_state_before": lu,
                        "follow_state_after": lu,
                        "verify_attempts": 0,
                        "navigation_state": "profile",
                        "skipped_tap": True,
                        "timings_ms": {"total": round((time.perf_counter() - t_all) * 1000, 2)},
                        "visual_candidate_id": str(visual_candidate_id or ""),
                        "note": "header_already_connected_before_reconcile",
                    },
                )
                return {
                    "ok": True,
                    "failure_code": None,
                    "tapped": False,
                    "skipped_tap": True,
                    "already_following": True,
                    "follow_state_before": lu,
                    "follow_state_after": lu,
                    "verify_attempts": 0,
                    "events": events,
                }
            _reco_none = _visual_reconcile_failure(
                33, attempted_tap=False, verify_attempts=0
            )
            if _reco_none is not None:
                return _reco_none
            log(
                "info",
                "visual_follow_direct_profile_action_failed",
                reason="visual_follow_button_not_found_on_open_profile",
                failure_code=33,
                target_username=str(username or ""),
                visual_candidate_id=str(visual_candidate_id or ""),
            )
            return {
                "ok": False,
                "failure_code": 33,
                "tapped": False,
                "follow_state_before": state_before,
                "follow_state_after": meta.get("last_ui_state"),
                "verify_attempts": 0,
                "events": events,
                "visual_follow_failure_reason": "visual_follow_button_not_found_on_open_profile",
            }
        return {
            "ok": False,
            "failure_code": 33,
            "tapped": False,
            "follow_state_before": state_before,
            "follow_state_after": meta.get("last_ui_state"),
            "verify_attempts": 0,
            "events": events,
        }

    tap_exact = bool(_use_follow_action_v2 and meta.get("exact_follow_fast_path"))
    tap_cx, tap_cy = 0, 0
    tap_coords_ready = False
    if tap_exact:
        _eb = _follow_safe_info(btn).get("bounds") or {}
        try:
            l0, t0, r0, b0 = (
                int(_eb["left"]),
                int(_eb["top"]),
                int(_eb["right"]),
                int(_eb["bottom"]),
            )
            if r0 > l0 and b0 > t0:
                tap_cx, tap_cy = (l0 + r0) // 2, (t0 + b0) // 2
                if not (l0 <= tap_cx <= r0 and t0 <= tap_cy <= b0):
                    tap_cx, tap_cy = (l0 + r0) // 2, (t0 + b0) // 2
                tap_coords_ready = True
        except (KeyError, TypeError, ValueError):
            tap_coords_ready = False

    if profile_already_open:
        log(
            "info",
            "visual_follow_direct_profile_action_started",
            target_username=str(username or ""),
            visual_candidate_id=str(visual_candidate_id or ""),
            follow_state_before=state_before,
            follow_action_engine_v2=_use_follow_action_v2,
            exact_follow_fast_path=tap_exact,
        )

    if tap_exact:
        log(
            "info",
            "follow_action_exact_follow_tap_ready",
            target_username=str(username or ""),
            visual_candidate_id=str(visual_candidate_id or ""),
            bounds=dict(_follow_safe_info(btn).get("bounds") or {}),
            derived_click_target=[tap_cx, tap_cy],
            center_x=tap_cx,
            center_y=tap_cy,
            tap_coords_ready=tap_coords_ready,
        )
    elif _use_follow_action_v2:
        log(
            "info",
            "follow_action_tap_started",
            target_username=str(username or ""),
            visual_candidate_id=str(visual_candidate_id or ""),
            follow_state_before=state_before,
        )
        events.append(
            (
                "follow_action_tap_started",
                {
                    "target_username": username,
                    "visual_candidate_id": str(visual_candidate_id or ""),
                    "follow_state_before": state_before,
                },
            )
        )

    try:
        if tap_exact and tap_coords_ready:
            d.click(tap_cx, tap_cy)
        else:
            btn.click()
    except Exception as e:
        _record(
            "follow_verify_failed",
            {
                "target_username": username,
                "follow_state_before": state_before,
                "follow_state_after": _follow_ui_state_snapshot(d),
                "verify_attempts": 0,
                "navigation_state": "profile",
                "error": str(e),
                "timings_ms": {"total": round((time.perf_counter() - t_all) * 1000, 2)},
            },
        )
        _reco_exc = _visual_reconcile_failure(
            34,
            attempted_tap=True,
            verify_attempts=0,
            state_after_hint=_follow_ui_state_snapshot(d),
        )
        if _reco_exc is not None:
            return _reco_exc
        _record(
            "follow_completed",
            {
                "target_username": username,
                "ok": False,
                "failure_code": 34,
                "navigation_state": "profile",
                "timings_ms": {"total": round((time.perf_counter() - t_all) * 1000, 2)},
            },
        )
        if profile_already_open:
            log(
                "info",
                "visual_follow_direct_profile_action_failed",
                reason="follow_tap_click_exception",
                failure_code=34,
                error=str(e),
                visual_candidate_id=str(visual_candidate_id or ""),
            )
        return {
            "ok": False,
            "failure_code": 34,
            "tapped": True,
            "follow_state_before": state_before,
            "follow_state_after": _follow_ui_state_snapshot(d),
            "verify_attempts": 0,
            "events": events,
        }

    if tap_exact:
        log(
            "info",
            "follow_action_exact_follow_tap_sent",
            target_username=str(username or ""),
            visual_candidate_id=str(visual_candidate_id or ""),
            center_x=tap_cx,
            center_y=tap_cy,
            tap_coords_ready=tap_coords_ready,
        )
        events.append(
            (
                "follow_action_exact_follow_tap_sent",
                {
                    "target_username": username,
                    "visual_candidate_id": str(visual_candidate_id or ""),
                    "center_x": tap_cx,
                    "center_y": tap_cy,
                },
            )
        )

    _record(
        "follow_tap_sent",
        {
            "target_username": username,
            "profile_already_open": bool(profile_already_open),
            "visual_candidate_id": str(visual_candidate_id or ""),
            "follow_state_before": state_before,
            "follow_state_after": None,
            "verify_attempts": 0,
            "navigation_state": "profile",
            "timings_ms": {"to_tap_ms": round((time.perf_counter() - t_all) * 1000, 2)},
            "exact_follow_fast_path": tap_exact,
        },
    )

    time.sleep(0.1 if tap_exact else 0.16)
    if _try_review_before_follow_popup_confirm(
        d,
        target_username=str(username or ""),
        visual_candidate_id=str(visual_candidate_id or ""),
    ):
        time.sleep(0.05)
    elif _review_before_follow_popup_visible(d):
        _review_abort = _follow_review_popup_unhandled_abort(
            d,
            target_username=str(username or ""),
            visual_candidate_id=str(visual_candidate_id or ""),
            events=events,
            record=_record,
            state_before=state_before,
            state_after=_follow_ui_state_snapshot(d),
            reason="review_sheet_visible_after_initial_follow_tap",
        )
        if _review_abort is not None:
            return _review_abort

    verify_timeout_ms = int(getattr(config, "FOLLOW_VERIFY_TIMEOUT_MS", 4000) or 4000)
    if tap_exact:
        verify_timeout_ms = min(verify_timeout_ms, 2800)
    verify_deadline = time.monotonic() + verify_timeout_ms / 1000.0
    poll_v = 0.055 if tap_exact else 0.12
    attempts = 0
    state_after = state_before
    review_popup_handled_once = False
    while time.monotonic() < verify_deadline:
        attempts += 1
        state_after = _follow_ui_state_snapshot(d)
        if (
            not review_popup_handled_once
            and attempts <= 2
            and state_after == state_before == "follow"
        ):
            if _try_review_before_follow_popup_confirm(
                d,
                target_username=str(username or ""),
                visual_candidate_id=str(visual_candidate_id or ""),
            ):
                review_popup_handled_once = True
                verify_deadline = verify_deadline + 1.2
                state_after = _follow_ui_state_snapshot(d)
            elif _review_before_follow_popup_visible(d):
                _review_abort = _follow_review_popup_unhandled_abort(
                    d,
                    target_username=str(username or ""),
                    visual_candidate_id=str(visual_candidate_id or ""),
                    events=events,
                    record=_record,
                    state_before=state_before,
                    state_after=state_after,
                    reason="review_sheet_visible_during_follow_verify_poll",
                )
                if _review_abort is not None:
                    return _review_abort
        if _use_follow_action_v2 and (
            attempts == 1
            or attempts % 5 == 0
            or state_after != state_before
        ):
            _pvv = {
                "target_username": username,
                "visual_candidate_id": str(visual_candidate_id or ""),
                "verify_attempts": attempts,
                "follow_state_after": state_after,
                "follow_state_before": state_before,
            }
            events.append(("follow_action_post_verify", dict(_pvv)))
            log("info", "follow_action_post_verify", **_pvv)
        if state_after in ("following", "requested"):
            if tap_exact:
                log(
                    "info",
                    "follow_action_exact_follow_verified",
                    target_username=str(username or ""),
                    visual_candidate_id=str(visual_candidate_id or ""),
                    follow_state_before=state_before,
                    follow_state_after=state_after,
                    verify_attempts=attempts,
                )
                events.append(
                    (
                        "follow_action_exact_follow_verified",
                        {
                            "target_username": username,
                            "visual_candidate_id": str(visual_candidate_id or ""),
                            "follow_state_after": state_after,
                            "verify_attempts": attempts,
                        },
                    )
                )
            _verify_phase_ms = round((time.perf_counter() - t_all) * 1000, 2)
            _record(
                "follow_verify_success",
                {
                    "target_username": username,
                    "profile_already_open": bool(profile_already_open),
                    "visual_candidate_id": str(visual_candidate_id or ""),
                    "follow_state_before": state_before,
                    "follow_state_after": state_after,
                    "verify_attempts": attempts,
                    "navigation_state": "profile",
                    "timings_ms": {"verify_phase_ms": _verify_phase_ms},
                },
            )
            try:
                from followers_inter_candidate_perf import (
                    inter_candidate_on_follow_verify_success,
                )

                inter_candidate_on_follow_verify_success(
                    target_username=str(username or ""),
                    verify_phase_ms=_verify_phase_ms,
                )
            except Exception:
                pass
            _record(
                "follow_completed",
                {
                    "target_username": username,
                    "profile_already_open": bool(profile_already_open),
                    "visual_candidate_id": str(visual_candidate_id or ""),
                    "follow_state_before": state_before,
                    "follow_state_after": state_after,
                    "verify_attempts": attempts,
                    "navigation_state": "profile",
                    "timings_ms": {"total": round((time.perf_counter() - t_all) * 1000, 2)},
                },
            )
            if profile_already_open:
                log(
                    "info",
                    "visual_follow_direct_profile_action_success",
                    target_username=str(username or ""),
                    visual_candidate_id=str(visual_candidate_id or ""),
                    follow_state_after=state_after,
                    verify_attempts=attempts,
                )
            if _use_follow_action_v2:
                _fav = {
                    "target_username": username,
                    "visual_candidate_id": str(visual_candidate_id or ""),
                    "follow_state_after": state_after,
                    "verify_attempts": attempts,
                }
                events.append(("follow_action_verified", dict(_fav)))
                log("info", "follow_action_verified", **_fav)
            return {
                "ok": True,
                "failure_code": None,
                "tapped": True,
                "follow_state_before": state_before,
                "follow_state_after": state_after,
                "verify_attempts": attempts,
                "events": events,
            }
        time.sleep(poll_v)

    if tap_exact and state_after not in ("following", "requested"):
        log(
            "warning",
            "follow_action_exact_follow_verify_failed",
            target_username=str(username or ""),
            visual_candidate_id=str(visual_candidate_id or ""),
            follow_state_before=state_before,
            follow_state_after=state_after,
            verify_attempts=attempts,
        )
        events.append(
            (
                "follow_action_exact_follow_verify_failed",
                {
                    "target_username": username,
                    "visual_candidate_id": str(visual_candidate_id or ""),
                    "follow_state_after": state_after,
                    "verify_attempts": attempts,
                },
            )
        )

    if _use_follow_action_v2 and not tap_exact:
        _unv = {
            "target_username": username,
            "visual_candidate_id": str(visual_candidate_id or ""),
            "follow_state_before": state_before,
            "follow_state_after": state_after,
            "verify_attempts": attempts,
            "reason": "follow_action_unverified",
        }
        events.append(("follow_action_unverified", dict(_unv)))
        log("info", "follow_action_unverified", **_unv)

    _reco_verify = _visual_reconcile_failure(
        34,
        attempted_tap=True,
        verify_attempts=attempts,
        state_after_hint=state_after,
    )
    if _reco_verify is not None:
        return _reco_verify

    _record(
        "follow_verify_failed",
        {
            "target_username": username,
            "profile_already_open": bool(profile_already_open),
            "visual_candidate_id": str(visual_candidate_id or ""),
            "follow_state_before": state_before,
            "follow_state_after": state_after,
            "verify_attempts": attempts,
            "navigation_state": "profile",
            "timings_ms": {"total": round((time.perf_counter() - t_all) * 1000, 2)},
        },
    )
    _record(
        "follow_completed",
        {
            "target_username": username,
            "profile_already_open": bool(profile_already_open),
            "visual_candidate_id": str(visual_candidate_id or ""),
            "ok": False,
            "failure_code": 34,
            "follow_state_before": state_before,
            "follow_state_after": state_after,
            "verify_attempts": attempts,
            "navigation_state": "profile",
        },
    )
    if profile_already_open:
        log(
            "info",
            "visual_follow_direct_profile_action_failed",
            reason="follow_verify_timeout_after_tap",
            failure_code=34,
            visual_candidate_id=str(visual_candidate_id or ""),
            follow_state_after=state_after,
        )
    return {
        "ok": False,
        "failure_code": 34,
        "tapped": True,
        "follow_state_before": state_before,
        "follow_state_after": state_after,
        "verify_attempts": attempts,
        "events": events,
    }


# --- Followers list engine V1 (source profile → followers list → follower profile) ---

_FOLLOWERS_HANDLE_RE = re.compile(r"^[a-zA-Z0-9._]{1,30}$")


def _visual_followers_resolve_username_in_row_band(
    d: u2.Device,
    *,
    row_top: int,
    row_bottom: int,
) -> str | None:
    """
    Best-effort handle on the followers list whose TextView vertical center falls in the row band.
    Uses device-pixel bounds (matches full-screen screenshots).
    """
    if row_bottom <= row_top:
        return None
    tol = max(10, (row_bottom - row_top) // 6)
    lo = row_top - tol
    hi = row_bottom + tol
    band_c = (row_top + row_bottom) // 2
    best: tuple[int, str] | None = None
    try:
        for el in d(className="android.widget.TextView").all():
            try:
                raw_t = (el.info.get("text") or "").strip().lstrip("@")
                if not raw_t or not _FOLLOWERS_HANDLE_RE.match(raw_t):
                    continue
                b = el.info.get("bounds") or {}
                cy = (int(b.get("top", 0)) + int(b.get("bottom", 0))) // 2
                if cy < lo or cy > hi:
                    continue
                dist = abs(cy - band_c)
                if best is None or dist < best[0]:
                    best = (dist, raw_t)
            except Exception:
                continue
    except Exception:
        return None
    return best[1] if best else None


def _visual_followers_username_band_probe(
    d: u2.Device,
    *,
    row_top: int,
    row_bottom: int,
    sample_limit: int = 8,
) -> dict[str, Any]:
    """Observability: TextViews in row band matching the followers-handle regex."""
    samples: list[str] = []
    if row_bottom <= row_top:
        return {"handle_like_textview_count": 0, "sample_texts": samples}
    tol = max(10, (row_bottom - row_top) // 6)
    lo = row_top - tol
    hi = row_bottom + tol
    band_c = (row_top + row_bottom) // 2
    scored: list[tuple[int, str]] = []
    try:
        for el in d(className="android.widget.TextView").all():
            try:
                raw_t = (el.info.get("text") or "").strip().lstrip("@")
                if not raw_t or not _FOLLOWERS_HANDLE_RE.match(raw_t):
                    continue
                b = el.info.get("bounds") or {}
                cy = (int(b.get("top", 0)) + int(b.get("bottom", 0))) // 2
                if cy < lo or cy > hi:
                    continue
                dist = abs(cy - band_c)
                scored.append((dist, raw_t))
            except Exception:
                continue
    except Exception:
        return {"handle_like_textview_count": 0, "sample_texts": [], "probe_error": True}
    scored.sort(key=lambda z: z[0])
    for _dist, txt in scored:
        if txt not in samples:
            samples.append(txt)
            if len(samples) >= sample_limit:
                break
    return {"handle_like_textview_count": len(scored), "sample_texts": samples}


_FOLLOWERS_TITLE_TEXTS = frozenset(
    {
        "Followers",
        "Abonnés",
        "Abonné(e)s",
        "Seguidores",
        "Подписчики",
    }
)
# Substrings for action_bar_title when exact locale string differs slightly.
_FOLLOWERS_TITLE_SUBSTRINGS = (
    "followers",
    "abonnés",
    "seguidores",
    "подписчик",
)
# UI / chrome strings that must not count as list usernames (relaxed detection).
_USERNAME_NOT_HANDLE_TEXTS = frozenset(
    {
        "follow",
        "following",
        "followers",
        "follow back",
        "message",
        "messages",
        "posts",
        "post",
        "edit",
        "share",
        "more",
        "about",
        "blocked",
        "requested",
        "abonnés",
        "abonné",
        "abonné(e)s",
        "suivre",
        "suivis",
        "publications",
        "publication",
        "seguidores",
        "siguiendo",
        "suggestions",
        "sort",
        "close",
        "copier",
        "copy",
    }
)


def _looks_like_instagram_username(text: str) -> bool:
    """
    Heuristic handle: 3–30 chars, [A-Za-z0-9._] only, no spaces, not common UI labels.
    """
    raw = (text or "").strip().lstrip("@")
    if not raw or " " in raw or "\n" in raw:
        return False
    if len(raw) < 3 or len(raw) > 30:
        return False
    if not re.fullmatch(r"[a-zA-Z0-9._]+", raw):
        return False
    low = raw.lower()
    if low in _USERNAME_NOT_HANDLE_TEXTS:
        return False
    if low in {x.lower() for x in _FOLLOWERS_TITLE_TEXTS}:
        return False
    for sub in _FOLLOWERS_TITLE_SUBSTRINGS:
        if low == sub:
            return False
    return True


# Official IG header block for followers (tap via center coordinates; see _tap_profile_followers_stat).
PROFILE_HEADER_FOLLOWERS_STACKED_FAMILIAR_RID = (
    "com.instagram.android:id/profile_header_followers_stacked_familiar"
)

# Until immediate post-tap screenshot/XML/hierarchy capture completes, block programmatic list scroll/swipe.
_FOLLOWERS_POST_TAP_IMMEDIATE_CAPTURE_DONE: bool = False

# Count of detect_followers_list_screen calls after followers stat tap (reset per open attempt).
_FOLLOWERS_POST_TAP_DETECT_ATTEMPT_COUNT: int = 0

# Latest followers-list hierarchy capture (post-tap debug XML); used when live U2 probes are empty.
_LAST_FOLLOWERS_DETECT_HIERARCHY_XML: str = ""
_LAST_FOLLOWERS_DETECT_HIERARCHY_XML_PATH: str = ""

# While True: block programmatic scroll/swipe (see _followers_abort_scroll_if_post_tap_lock).
POST_TAP_FOLLOWERS_DETECTION_IN_PROGRESS: bool = False

# Followers list engine session (reset each open_followers_list_from_profile).
_FOLLOWERS_LAST_OPEN_DETECTION_METHOD: str | None = None
_FOLLOWERS_VISUAL_XML_RECOVERY_ATTEMPTED: bool = False
_FOLLOWERS_VISUAL_XML_STALE_EXHAUSTED: bool = False
_FOLLOWERS_LAST_ITER_CANDIDATE_COUNT: int = 0
_FOLLOWERS_VISUAL_HAD_NONEMPTY_CANDIDATE_ROWS: bool = False

# One-shot: runner arms after legit zero-span defer so _followers_scroll_list_forward can bypass
# XML-stale exhaustion + visual_fallback zero-candidate guards exactly once (exploratory scroll).
_FOLLOWERS_VISUAL_EXPLORATORY_SCROLL_ONCE: bool = False
_FOLLOWERS_VISUAL_EXPLORATORY_SCROLL_REASON: str = ""

# Set when followers engine must exit without follow/scroll (stale XML after visual open).
_FOLLOWERS_ENGINE_STOP_REASON: str | None = None

FOLLOWERS_ENGINE_XML_STALE_EXIT_REASONS = frozenset(
    {
        "visual_open_xml_empty",
        "followers_xml_still_stale_after_force_refresh",
    }
)

# open_detection_method values that imply visual / coordinate followers list open (picker + stale-XML paths).
FOLLOWERS_ENGINE_VISUAL_OPEN_METHODS = frozenset(
    {
        "visual_followers_list",
        "followers_list_visual",
        "visual_open_followers",
        "visual_followers",
        "visual_fallback",
        "coordinate_fallback",
    }
)


def followers_bypass_xml_stale_recovery_if_visual_surface_strong(
    d: u2.Device,
    *,
    source_profile_username: str,
    det: dict[str, Any],
    phase: str,
    stop_reason: str | None,
    loop_iteration: int,
    session_visual_fallback_detail: dict[str, Any] | None = None,
    visual_xml_stale_grace_remaining: int = 0,
) -> tuple[bool, str]:
    """
    (True, reason) when the followers surface is visually / structurally strong enough to skip
    immediate exit 44 from _followers_xml_stale_engine_stop (picker may still be skipped).
    """
    _ = d
    min_conf = float(getattr(config, "FOLLOWERS_VISUAL_FALLBACK_MIN_CONFIDENCE", 0.65))

    vf_detail = det.get("visual_fallback_detail")
    if isinstance(vf_detail, dict) and bool(vf_detail.get("visual_match")):
        rows = int(vf_detail.get("visual_user_rows_detected") or 0)
        btns = int(vf_detail.get("visual_follow_button_count") or 0)
        conf = float(vf_detail.get("visual_confidence") or 0.0)
        if rows >= 2 or btns >= 1 or conf >= min_conf:
            log(
                "info",
                "followers_bypass_xml_stale_recovery_visual_surface_strong",
                reason="visual_fallback_detail",
                phase=phase,
                stop_reason=stop_reason,
                loop_iteration=loop_iteration,
                source_profile_username=source_profile_username,
                visual_user_rows_detected=rows,
                visual_follow_button_count=btns,
                visual_confidence=round(conf, 4),
            )
            return True, "det_visual_fallback_detail"

    if (
        visual_xml_stale_grace_remaining > 0
        and isinstance(session_visual_fallback_detail, dict)
        and bool(session_visual_fallback_detail.get("visual_match"))
    ):
        s_rows = int(session_visual_fallback_detail.get("visual_user_rows_detected") or 0)
        s_btns = int(session_visual_fallback_detail.get("visual_follow_button_count") or 0)
        s_conf = float(session_visual_fallback_detail.get("visual_confidence") or 0.0)
        if s_conf >= min_conf and (s_rows >= 2 or s_btns >= 1):
            log(
                "info",
                "followers_xml_stale_ignored_after_visual_match",
                phase=phase,
                stop_reason=stop_reason,
                loop_iteration=loop_iteration,
                source_profile_username=source_profile_username,
                grace_remaining=visual_xml_stale_grace_remaining,
                visual_user_rows_detected=s_rows,
                visual_follow_button_count=s_btns,
                visual_confidence=round(s_conf, 4),
            )
            return True, "session_visual_fallback_grace"

    odm = str(_FOLLOWERS_LAST_OPEN_DETECTION_METHOD or "")
    if odm in FOLLOWERS_ENGINE_VISUAL_OPEN_METHODS and _FOLLOWERS_VISUAL_HAD_NONEMPTY_CANDIDATE_ROWS:
        log(
            "info",
            "followers_bypass_xml_stale_recovery_visual_surface_strong",
            reason="visual_open_had_nonempty_candidate_rows",
            phase=phase,
            stop_reason=stop_reason,
            loop_iteration=loop_iteration,
            source_profile_username=source_profile_username,
            open_detection_method=odm,
        )
        return True, "visual_open_had_nonempty_candidate_rows"

    if odm in FOLLOWERS_ENGINE_VISUAL_OPEN_METHODS and bool(det.get("is_followers_list")):
        cc = int(det.get("candidate_username_count") or 0)
        sample = det.get("visible_usernames_sample") or []
        n_sample = len(sample) if isinstance(sample, list) else 0
        if cc >= 1 or n_sample >= 1:
            if bool(det.get("strict_list_open")) or bool(det.get("relaxed_list_open")) or cc >= 2:
                log(
                    "info",
                    "followers_bypass_xml_stale_recovery_visual_surface_strong",
                    reason="hierarchy_list_with_handles_after_visual_open",
                    phase=phase,
                    stop_reason=stop_reason,
                    loop_iteration=loop_iteration,
                    source_profile_username=source_profile_username,
                    candidate_username_count=cc,
                    visible_usernames_sample_len=n_sample,
                    strict_list_open=bool(det.get("strict_list_open")),
                    relaxed_list_open=bool(det.get("relaxed_list_open")),
                )
                return True, "hierarchy_list_with_handles_after_visual_open"

    return False, ""


def followers_engine_clear_stop_reason() -> None:
    """Clear XML-stale stop flag so the followers loop can continue in visual mode."""
    global _FOLLOWERS_ENGINE_STOP_REASON
    _FOLLOWERS_ENGINE_STOP_REASON = None


def get_followers_engine_stop_reason() -> str | None:
    return _FOLLOWERS_ENGINE_STOP_REASON


def followers_allow_visual_exploratory_scroll_once(
    *,
    reason: str,
    source_profile_username: str | None = None,
) -> bool:
    """
    Arm a single exploratory followers-list scroll that bypasses XML-stale exhaustion and the
    visual_fallback zero-candidate scroll block in _followers_scroll_list_forward.

    Idempotent: if already armed, returns False and leaves the pending permit unchanged.
    """
    global _FOLLOWERS_VISUAL_EXPLORATORY_SCROLL_ONCE
    global _FOLLOWERS_VISUAL_EXPLORATORY_SCROLL_REASON
    if _FOLLOWERS_VISUAL_EXPLORATORY_SCROLL_ONCE:
        log(
            "debug",
            "followers_visual_exploratory_scroll_permit_skipped_already_armed",
            pending_reason=str(_FOLLOWERS_VISUAL_EXPLORATORY_SCROLL_REASON or ""),
            source_profile_username=str(source_profile_username or ""),
            requested=str(reason or "")[:120],
        )
        return False
    _FOLLOWERS_VISUAL_EXPLORATORY_SCROLL_ONCE = True
    _FOLLOWERS_VISUAL_EXPLORATORY_SCROLL_REASON = str(reason or "").strip()[:120]
    log(
        "info",
        "followers_visual_exploratory_scroll_permit_armed",
        permit_reason=_FOLLOWERS_VISUAL_EXPLORATORY_SCROLL_REASON,
        source_profile_username=str(source_profile_username or ""),
    )
    return True


def followers_clear_exploratory_scroll_permit_unused() -> None:
    """Drop an armed exploratory permit (e.g. new followers loop iter without consuming it)."""
    global _FOLLOWERS_VISUAL_EXPLORATORY_SCROLL_ONCE
    global _FOLLOWERS_VISUAL_EXPLORATORY_SCROLL_REASON
    if not _FOLLOWERS_VISUAL_EXPLORATORY_SCROLL_ONCE:
        return
    _FOLLOWERS_VISUAL_EXPLORATORY_SCROLL_ONCE = False
    _FOLLOWERS_VISUAL_EXPLORATORY_SCROLL_REASON = ""


def _followers_reset_followers_list_session_state() -> None:
    global _FOLLOWERS_LAST_OPEN_DETECTION_METHOD
    global _FOLLOWERS_VISUAL_XML_RECOVERY_ATTEMPTED
    global _FOLLOWERS_VISUAL_XML_STALE_EXHAUSTED
    global _FOLLOWERS_LAST_ITER_CANDIDATE_COUNT
    global _FOLLOWERS_VISUAL_HAD_NONEMPTY_CANDIDATE_ROWS
    global _FOLLOWERS_ENGINE_STOP_REASON
    global _FOLLOWERS_VISUAL_EXPLORATORY_SCROLL_ONCE
    global _FOLLOWERS_VISUAL_EXPLORATORY_SCROLL_REASON
    _FOLLOWERS_LAST_OPEN_DETECTION_METHOD = None
    _FOLLOWERS_VISUAL_XML_RECOVERY_ATTEMPTED = False
    _FOLLOWERS_VISUAL_XML_STALE_EXHAUSTED = False
    _FOLLOWERS_LAST_ITER_CANDIDATE_COUNT = 0
    _FOLLOWERS_VISUAL_HAD_NONEMPTY_CANDIDATE_ROWS = False
    _FOLLOWERS_ENGINE_STOP_REASON = None
    _FOLLOWERS_VISUAL_EXPLORATORY_SCROLL_ONCE = False
    _FOLLOWERS_VISUAL_EXPLORATORY_SCROLL_REASON = ""


# After followers_list_open_success: XML det can still read likely_profile; avoid spurious reopen.
_FOLLOWERS_LIST_SESSION_COMMITTED_OPEN: bool = False
_FOLLOWERS_LIST_SESSION_COMMITTED_AT: float = 0.0
_FOLLOWERS_LIST_SESSION_COMMITTED_SOURCE: str = ""
_FOLLOWERS_LIST_SESSION_COMMITTED_FOR: str = ""

# Filled when compact post-follow return confirms CT followers list via visual_fallback;
# drained into ``run_visual_candidate_post_follow_phase`` return payload for runner promotion.
_POST_FOLLOW_RETURN_PENDING_VISUAL_EVIDENCE_FOR_RUNNER: dict[str, Any] = {}


def _post_follow_return_take_pending_visual_evidence_for_runner() -> dict[str, Any]:
    out = dict(_POST_FOLLOW_RETURN_PENDING_VISUAL_EVIDENCE_FOR_RUNNER)
    _POST_FOLLOW_RETURN_PENDING_VISUAL_EVIDENCE_FOR_RUNNER.clear()
    return out


def followers_session_reset_list_committed_open() -> None:
    """Clear committed-followers-list flag (start of a new followers engine run)."""
    global _FOLLOWERS_LIST_SESSION_COMMITTED_OPEN, _FOLLOWERS_LIST_SESSION_COMMITTED_AT
    global _FOLLOWERS_LIST_SESSION_COMMITTED_SOURCE, _FOLLOWERS_LIST_SESSION_COMMITTED_FOR
    _FOLLOWERS_LIST_SESSION_COMMITTED_OPEN = False
    _FOLLOWERS_LIST_SESSION_COMMITTED_AT = 0.0
    _FOLLOWERS_LIST_SESSION_COMMITTED_SOURCE = ""
    _FOLLOWERS_LIST_SESSION_COMMITTED_FOR = ""


def followers_session_mark_list_committed_open(
    source_profile_username: str,
    *,
    committed_source: str,
) -> None:
    global _FOLLOWERS_LIST_SESSION_COMMITTED_OPEN, _FOLLOWERS_LIST_SESSION_COMMITTED_AT
    global _FOLLOWERS_LIST_SESSION_COMMITTED_SOURCE, _FOLLOWERS_LIST_SESSION_COMMITTED_FOR
    key = _normalize_handle(str(source_profile_username or "").strip().lstrip("@"))
    if not key:
        return
    _FOLLOWERS_LIST_SESSION_COMMITTED_OPEN = True
    _FOLLOWERS_LIST_SESSION_COMMITTED_AT = time.perf_counter()
    _FOLLOWERS_LIST_SESSION_COMMITTED_SOURCE = str(committed_source or "")[:120]
    _FOLLOWERS_LIST_SESSION_COMMITTED_FOR = key


def followers_session_clear_list_committed_open(
    source_profile_username: str | None = None,
) -> None:
    """Clear when leaving CT followers list (e.g. follower profile) or before explicit reopen."""
    global _FOLLOWERS_LIST_SESSION_COMMITTED_OPEN, _FOLLOWERS_LIST_SESSION_COMMITTED_AT
    global _FOLLOWERS_LIST_SESSION_COMMITTED_SOURCE, _FOLLOWERS_LIST_SESSION_COMMITTED_FOR
    if source_profile_username is None:
        followers_session_reset_list_committed_open()
        return
    key = _normalize_handle(str(source_profile_username or "").strip().lstrip("@"))
    if not key or key != _FOLLOWERS_LIST_SESSION_COMMITTED_FOR:
        return
    followers_session_reset_list_committed_open()


def followers_session_list_committed_open_for(source_profile_username: str) -> bool:
    key = _normalize_handle(str(source_profile_username or "").strip().lstrip("@"))
    if not key or not _FOLLOWERS_LIST_SESSION_COMMITTED_OPEN:
        return False
    return key == _FOLLOWERS_LIST_SESSION_COMMITTED_FOR


def followers_session_committed_open_age_ms() -> float:
    if not _FOLLOWERS_LIST_SESSION_COMMITTED_OPEN or not _FOLLOWERS_LIST_SESSION_COMMITTED_AT:
        return 0.0
    return (time.perf_counter() - _FOLLOWERS_LIST_SESSION_COMMITTED_AT) * 1000.0


def followers_session_committed_meta() -> dict[str, Any]:
    return {
        "followers_list_committed_open": bool(_FOLLOWERS_LIST_SESSION_COMMITTED_OPEN),
        "followers_list_committed_at": float(_FOLLOWERS_LIST_SESSION_COMMITTED_AT),
        "followers_list_committed_source": str(_FOLLOWERS_LIST_SESSION_COMMITTED_SOURCE or ""),
        "followers_list_committed_for": str(_FOLLOWERS_LIST_SESSION_COMMITTED_FOR or ""),
    }


# Committed followers sessions that may reuse rendered-strong ``visual_fallback_detail``
# without ``visual_match`` (merge, light revalidate, runner gates).
FOLLOWERS_RENDERED_STRONG_COMMITTED_SOURCES: frozenset[str] = frozenset(
    (
        "entry_v2_rendered_strong",
        "post_follow_compact_visual_return",
        # Already-connected fast return promoted `session_vf_detail` from
        # `detect_followers_list_screen_visual_fallback` after direct Back — same
        # rendered-strong semantics as CT post-follow visual return-to-list.
        "already_connected_direct_back_visual_confirmed",
    )
)


def _followers_committed_rendered_strong_visual_ok(vf: dict[str, Any]) -> bool:
    """
    Structural visual proof aligned with ``_followers_entry_v2_transition_visual_rendered_strong_gates``
    (without requiring ``visual_match``). Used for committed-followers revalidation when
    ``followers_list_committed_source`` is in ``FOLLOWERS_RENDERED_STRONG_COMMITTED_SOURCES``.
    """
    if not isinstance(vf, dict):
        return False
    if not bool(vf.get("visual_search_area_detected")):
        return False
    sigs_raw = vf.get("visual_signals") or []
    if not any(str(x) == "search_strip" for x in sigs_raw):
        return False
    if not bool(vf.get("visual_followers_title_hint")):
        return False
    rows = int(vf.get("visual_user_rows_detected") or 0)
    fcb = int(vf.get("visual_follow_button_count") or 0)
    if fcb >= 1:
        if rows < 12:
            return False
    elif _vf_followers_rendered_strong_list_structure_strong_no_visible_follow_cta(vf):
        pass
    else:
        return False
    return True


def _followers_committed_vf_selectable_for_merge(cand: dict[str, Any]) -> bool:
    if not isinstance(cand, dict):
        return False
    if bool(cand.get("visual_match")):
        return True
    if (
        str(_FOLLOWERS_LIST_SESSION_COMMITTED_SOURCE or "")
        in FOLLOWERS_RENDERED_STRONG_COMMITTED_SOURCES
        and _followers_committed_rendered_strong_visual_ok(cand)
    ):
        return True
    return False


def followers_session_merge_det_for_committed_visual_surface(
    det: dict[str, Any],
    *,
    session_vf_detail_for_loop: dict[str, Any] | None,
    open_list_meta: dict[str, Any] | None,
) -> dict[str, Any]:
    """
    When the followers list was visually committed open, merge session / snapshot
    visual_fallback_detail so ``is_followers_list`` reflects the proven surface.
    """
    out = dict(det) if isinstance(det, dict) else {}
    vf: dict[str, Any] = {}
    if isinstance(session_vf_detail_for_loop, dict) and _followers_committed_vf_selectable_for_merge(
        session_vf_detail_for_loop
    ):
        vf = dict(session_vf_detail_for_loop)
    elif isinstance(open_list_meta, dict):
        for snap_key in ("after_tap_screen_snapshot", "last_poll_snapshot"):
            snap = open_list_meta.get(snap_key) or {}
            cand = snap.get("visual_fallback_detail") or {}
            if isinstance(cand, dict) and _followers_committed_vf_selectable_for_merge(cand):
                vf = dict(cand)
                break
    if not vf or not _followers_committed_vf_selectable_for_merge(vf):
        return out
    rows = int(vf.get("visual_user_rows_detected") or 0)
    fbc = int(vf.get("visual_follow_button_count") or 0)
    if rows >= 2 or fbc >= 1:
        if (not bool(vf.get("visual_match"))) and _followers_committed_rendered_strong_visual_ok(vf):
            try:
                log(
                    "info",
                    "followers_committed_rendered_strong_visual_merge_applied",
                    source_profile_username=str(_FOLLOWERS_LIST_SESSION_COMMITTED_FOR or "")[:120],
                    committed_source=str(_FOLLOWERS_LIST_SESSION_COMMITTED_SOURCE or ""),
                    visual_match=bool(vf.get("visual_match")),
                    visual_user_rows_detected=int(vf.get("visual_user_rows_detected") or 0),
                    visual_follow_button_count=int(vf.get("visual_follow_button_count") or 0),
                    visual_search_area_detected=bool(vf.get("visual_search_area_detected")),
                    visual_followers_title_hint=bool(vf.get("visual_followers_title_hint")),
                )
            except Exception:
                pass
        out["is_followers_list"] = True
        odm = str(out.get("open_detection_method") or vf.get("open_detection_method") or "").strip()
        if not odm or odm == "xml":
            out["open_detection_method"] = str(vf.get("open_detection_method") or "visual_fallback")
        out["visual_fallback_detail"] = dict(vf)
        sigs = list(out.get("signals") or [])
        if "committed_visual_surface_merge" not in sigs:
            sigs.append("committed_visual_surface_merge")
        out["signals"] = sigs
        if not str(out.get("current_screen_guess") or "").strip():
            out["current_screen_guess"] = "likely_followers_list_committed_visual"
    return out


def followers_committed_surface_light_revalidate(
    d: u2.Device,
    *,
    source_profile_username: str,
    expected_package: str,
    det_merged: dict[str, Any],
    committed_age_ms: float,
    open_list_meta: dict[str, Any] | None,
    session_vf_detail_for_loop: dict[str, Any] | None,
    max_committed_age_ms_for_light: float = 120_000.0,
) -> tuple[str, dict[str, Any]]:
    """
    Fast committed-surface check without ``detect_followers_list_screen``.

    Returns ``(status, meta)`` where ``status`` is:
    - ``light_ok`` — trust committed visual for this loop iteration
    - ``light_inconclusive`` — caller may run heavier revalidation
    - ``wrong_surface`` — foreground/danger rules failed (treat like lost surface)
    """
    meta: dict[str, Any] = {"path": "committed_light_revalidate"}
    exp = str(expected_package or getattr(config, "INSTAGRAM_PACKAGE", "") or "").strip()
    if not verify_app_foreground(d, exp):
        meta["reason"] = "not_foreground_or_wrong_pkg"
        return "wrong_surface", meta

    dm = det_merged if isinstance(det_merged, dict) else {}
    vf = dm.get("visual_fallback_detail")
    if not isinstance(vf, dict):
        meta["reason"] = "missing_visual_fallback_detail_dict"
        return "light_inconclusive", meta
    vf_ok = bool(vf.get("visual_match"))
    if (
        not vf_ok
        and str(_FOLLOWERS_LIST_SESSION_COMMITTED_SOURCE or "")
        in FOLLOWERS_RENDERED_STRONG_COMMITTED_SOURCES
        and _followers_committed_rendered_strong_visual_ok(vf)
    ):
        vf_ok = True
        try:
            log(
                "info",
                "committed_followers_surface_rendered_strong_visual_reused",
                source_profile_username=str(_FOLLOWERS_LIST_SESSION_COMMITTED_FOR or "")[:120],
                committed_source=str(_FOLLOWERS_LIST_SESSION_COMMITTED_SOURCE or ""),
                visual_match=bool(vf.get("visual_match")),
                visual_user_rows_detected=int(vf.get("visual_user_rows_detected") or 0),
                visual_follow_button_count=int(vf.get("visual_follow_button_count") or 0),
                visual_search_area_detected=bool(vf.get("visual_search_area_detected")),
                visual_followers_title_hint=bool(vf.get("visual_followers_title_hint")),
            )
        except Exception:
            pass
    if not vf_ok:
        meta["reason"] = "missing_merged_visual_fallback"
        return "light_inconclusive", meta
    rows = int(vf.get("visual_user_rows_detected") or 0)
    fbc = int(vf.get("visual_follow_button_count") or 0)
    if rows < 2 and fbc < 1:
        meta["reason"] = "weak_visual_row_signals"
        meta["visual_user_rows_detected"] = rows
        meta["visual_follow_button_count"] = fbc
        return "light_inconclusive", meta
    if float(committed_age_ms) > float(max_committed_age_ms_for_light):
        meta["reason"] = "committed_age_stale"
        meta["committed_age_ms"] = float(committed_age_ms)
        meta["max_committed_age_ms_for_light"] = float(max_committed_age_ms_for_light)
        return "light_inconclusive", meta

    shot = ""
    shot_src = ""
    if isinstance(open_list_meta, dict):
        _latest_inj = str(
            open_list_meta.get("latest_followers_injection_screenshot_path") or ""
        ).strip()
        if _latest_inj:
            if Path(_latest_inj).is_file():
                shot, shot_src = (
                    _latest_inj,
                    "open_list_meta.latest_followers_injection_screenshot_path",
                )
                try:
                    log(
                        "info",
                        "followers_committed_surface_revalidate_using_latest_injection_screenshot",
                        source_profile_username=str(source_profile_username or ""),
                        screenshot_path=_latest_inj,
                        selection_reason="latest_followers_injection_screenshot_path",
                        file_exists=True,
                    )
                except Exception:
                    pass
            else:
                try:
                    log(
                        "warning",
                        "followers_committed_surface_latest_injection_screenshot_missing",
                        source_profile_username=str(source_profile_username or ""),
                        screenshot_path=_latest_inj,
                        selection_reason="latest_followers_injection_screenshot_path",
                        file_exists=False,
                    )
                except Exception:
                    pass
        if not shot:
            for snap_key in ("after_tap_screen_snapshot", "last_poll_snapshot"):
                snap = open_list_meta.get(snap_key) or {}
                if not isinstance(snap, dict):
                    continue
                for sp_key in (
                    "screenshot_path_used",
                    "screenshot_path",
                    "followers_after_tap_second_pass_screenshot_path",
                    "followers_after_tap_immediate_screenshot_path",
                ):
                    sp = str(snap.get(sp_key) or "").strip()
                    if sp and Path(sp).is_file():
                        shot, shot_src = sp, f"open_list_meta.{snap_key}.{sp_key}"
                        break
                if shot:
                    break
    if not shot and isinstance(session_vf_detail_for_loop, dict):
        for sp_key in ("screenshot_path_used", "screenshot_path"):
            sp = str(session_vf_detail_for_loop.get(sp_key) or "").strip()
            if sp and Path(sp).is_file():
                shot, shot_src = sp, f"session_vf_detail.{sp_key}"
                break
    meta["screenshot_path"] = str(shot or "")[:400]
    meta["screenshot_source"] = shot_src

    if _vision_validation_enabled() and shot:
        tap_diag = {"entry_v2_source_profile_username": str(source_profile_username or "")}
        v_ok, v_dict = _vision_validation_followers_list_open_gate(
            screenshot_path=str(shot),
            det=dm,
            tap_diag=tap_diag,
            source_profile_username=str(source_profile_username or ""),
        )
        meta["vision_gate"] = v_dict if isinstance(v_dict, dict) else {"result": v_dict}
        if not v_ok:
            meta["reason"] = "vision_rejected_on_committed_shot"
            return "light_inconclusive", meta

    try:
        from vision_validation_layer import vision_detect_danger_surface

        dang = vision_detect_danger_surface({"det": dm})
        meta["xml_danger"] = dang
        if bool((dang or {}).get("danger")):
            meta["reason"] = "danger_surface"
            return "wrong_surface", meta
    except Exception as e:
        meta["danger_check_error"] = str(e)[:200]

    meta["reason"] = "light_checks_passed"
    return "light_ok", meta


def _followers_set_last_open_detection_method(method: str | None) -> None:
    global _FOLLOWERS_LAST_OPEN_DETECTION_METHOD
    _FOLLOWERS_LAST_OPEN_DETECTION_METHOD = method


def _followers_set_post_tap_detection_lock(active: bool) -> None:
    global POST_TAP_FOLLOWERS_DETECTION_IN_PROGRESS
    POST_TAP_FOLLOWERS_DETECTION_IN_PROGRESS = bool(active)


def _followers_enable_post_tap_detection_lock(source_profile_username: str) -> None:
    _followers_set_post_tap_detection_lock(True)
    log(
        "info",
        "followers_post_tap_detection_lock_enabled",
        source_profile_username=source_profile_username,
    )


def _followers_release_post_tap_detection_lock(source_profile_username: str) -> None:
    _followers_set_post_tap_detection_lock(False)
    log(
        "info",
        "followers_post_tap_detection_lock_released",
        source_profile_username=source_profile_username,
    )


def _followers_pkg_activity_for_scroll_log(d: u2.Device) -> tuple[Any, Any]:
    try:
        meta = _followers_current_pkg_activity(d)
        return meta.get("current_package"), meta.get("current_activity")
    except Exception:
        return None, None


def _followers_log_scroll_or_swipe_about_to_run(
    d: u2.Device,
    *,
    source_function: str,
    reason: str,
) -> None:
    pkg, act = _followers_pkg_activity_for_scroll_log(d)
    log(
        "info",
        "followers_scroll_or_swipe_about_to_run",
        source_function=source_function,
        reason=reason,
        post_tap_lock=POST_TAP_FOLLOWERS_DETECTION_IN_PROGRESS,
        current_activity=act,
        current_package=pkg,
    )


def _followers_abort_scroll_if_post_tap_lock(source: str) -> bool:
    """If True, caller must not scroll/swipe (post-tap followers detection still active)."""
    if POST_TAP_FOLLOWERS_DETECTION_IN_PROGRESS:
        log("warning", "followers_post_tap_scroll_prevented", source=source)
        return True
    return False


def _followers_reset_post_tap_capture_gate() -> None:
    global _FOLLOWERS_POST_TAP_IMMEDIATE_CAPTURE_DONE, _FOLLOWERS_POST_TAP_DETECT_ATTEMPT_COUNT
    _FOLLOWERS_POST_TAP_IMMEDIATE_CAPTURE_DONE = False
    _FOLLOWERS_POST_TAP_DETECT_ATTEMPT_COUNT = 0


def _followers_post_tap_capture_gate_ok() -> bool:
    return _FOLLOWERS_POST_TAP_IMMEDIATE_CAPTURE_DONE


def _followers_mark_post_tap_immediate_capture_done() -> None:
    global _FOLLOWERS_POST_TAP_IMMEDIATE_CAPTURE_DONE
    _FOLLOWERS_POST_TAP_IMMEDIATE_CAPTURE_DONE = True


def _followers_bounds_center(b: dict[str, Any]) -> tuple[int, int] | None:
    try:
        left, top, right, bottom = (
            int(b.get("left", 0)),
            int(b.get("top", 0)),
            int(b.get("right", 0)),
            int(b.get("bottom", 0)),
        )
    except Exception:
        return None
    if right <= left or bottom <= top:
        return None
    return (left + right) // 2, (top + bottom) // 2


_STAT_NUMERIC_RE = re.compile(r"^[\d\s,\.kKmM\+]+$")


def _followers_reject_posts_label(text: str) -> bool:
    s = (text or "").lower()
    return "post" in s or "publication" in s


def _followers_reject_following_column_label(text: str) -> bool:
    """Avoid tapping the 'Following' / suivis column (not Followers)."""
    s = (text or "").strip().lower()
    if not s:
        return False
    if "followers" in s and "following" not in s.replace("followers", ""):
        return False
    if s == "following" or s.startswith("following"):
        return True
    if "following" in s and "follower" not in s:
        return True
    if s in ("suivis", "abonnements") and "abonné" not in s:
        return True
    return False


def _followers_label_match(text: str) -> bool:
    """True if this TextView is a Followers column label (EN/FR), not Posts/Following."""
    s = (text or "").strip().lower()
    if not s:
        return False
    if _followers_reject_following_column_label(text):
        return False
    if _followers_reject_posts_label(text):
        return False
    if "abonnés" in s or "abonné" in s or "abonne" in s:
        return True
    if "followers" in s:
        return True
    if s == "follower":
        return True
    if "follower" in s and "following" not in s:
        return True
    return False




def _followers_harvest_blob_from_row(row: dict[str, Any]) -> str:
    parts = [
        str(row.get("raw_text") or row.get("text") or ""),
        str(row.get("content_desc") or ""),
        str(row.get("pane_title") or ""),
    ]
    return " ".join(p.strip() for p in parts if p and str(p).strip()).strip()


def _followers_harvest_classify_stat_type(blob: str) -> str | None:
    """posts | followers | following | None (fuzzy / partial)."""
    s = _follow_norm(blob)
    if not s:
        return None
    if ("publication" in s or s == "posts" or s.startswith("posts")) and "follower" not in s:
        return "posts"
    if "abonnements" in s or ("abonnement" in s and "abonné" not in s):
        return "following"
    if "suivi" in s and "abonné" not in s and "follower" not in s:
        return "following"
    if _followers_reject_following_column_label(blob):
        return "following"
    if _followers_label_match(blob):
        return "followers"
    if "follower" in s and "following" not in s:
        return "followers"
    return None




def _followers_screen_class_is_profile_like(screen_class: str) -> bool:
    s = str(screen_class or "").strip().lower()
    if not s:
        return False
    return (
        "profile" in s
        or s in ("likely_profile", "profile_header_rid", "action_bar_title")
        or "candidate_profile" in s
    )


def _followers_stats_harvest_raw_nodes_from_hierarchy_xml(
    xml_text: str,
    w: int,
    h: int,
    *,
    y_frac_lo: float = 0.045,
    y_frac_hi: float = 0.34,
) -> list[dict[str, Any]]:
    """Parse hierarchy dump; collect nodes intersecting the profile stats vertical band (incl. empty text)."""
    out: list[dict[str, Any]] = []
    t = (xml_text or "").strip()
    if not t:
        return out
    y_lo = int(h * float(y_frac_lo))
    y_hi = int(h * float(y_frac_hi))
    x_lo = int(w * 0.02)
    x_hi = int(w * 0.98)
    try:
        try:
            root = ET.fromstring(t)
        except ET.ParseError:
            root = ET.fromstring(f"<wrap>{t}</wrap>")
    except Exception:
        return out
    for el in root.iter():
        bd = _dm_parse_bounds_attr_xml(el.get("bounds"))
        if not bd:
            continue
        try:
            cx = (int(bd["left"]) + int(bd["right"])) // 2
            cy = (int(bd["top"]) + int(bd["bottom"])) // 2
        except Exception:
            continue
        if cy < y_lo or cy > y_hi or cx < x_lo or cx > x_hi:
            continue
        out.append(
            {
                "className": str(el.get("class") or "")[:200],
                "resourceId": str(el.get("resource-id") or "")[:220],
                "text": str(el.get("text") or "")[:160],
                "content_desc": str(el.get("content-desc") or "")[:320],
                "bounds": bd,
                "clickable": str(el.get("clickable") or "").lower() == "true",
            }
        )
    return out


def _followers_stats_band_write_snippet_xml(
    xml_text: str,
    out_path: Path,
    w: int,
    h: int,
) -> bool:
    """Write a small XML file with stats-band nodes only (diagnostics)."""
    nodes = _followers_stats_harvest_raw_nodes_from_hierarchy_xml(xml_text, w, h)
    try:
        _ensure_debug_dirs()
        out_path.parent.mkdir(parents=True, exist_ok=True)
        root = ET.Element("stats_band_snippet")
        root.set("screen_w", str(int(w)))
        root.set("screen_h", str(int(h)))
        root.set("node_count", str(len(nodes)))
        for n in nodes[:400]:
            ch = ET.SubElement(root, "node")
            ch.set("class", str(n.get("className") or ""))
            rid = str(n.get("resourceId") or "")
            if rid:
                ch.set("resource-id", rid)
            if str(n.get("text") or ""):
                ch.set("text", str(n.get("text") or ""))
            if str(n.get("content_desc") or ""):
                ch.set("content-desc", str(n.get("content_desc") or ""))
            b = n.get("bounds") or {}
            ch.set(
                "bounds",
                f"[{int(b.get('left',0))},{int(b.get('top',0))}][{int(b.get('right',0))},{int(b.get('bottom',0))}]",
            )
            ch.set("clickable", "true" if n.get("clickable") else "false")
        hdr = '<?xml version="1.0" encoding="utf-8"?>\n'
        out_path.write_text(
            hdr + ET.tostring(root, encoding="unicode"),
            encoding="utf-8",
        )
        return True
    except Exception:
        return False


# Stats strip (LTR): left = posts, center = followers, right = following.
# Hard taps must stay strictly left of ~45% width — wider ceilings hit Following.
_FOLLOWERS_METRIC_SCREEN_MAX_NX: float = 0.45
_FOLLOWERS_METRIC_POSTS_MAX_NX: float = 0.30
_FOLLOWERS_METRIC_WIDE_NODE_FRAC_W: float = 0.35
_FOLLOWERS_METRIC_SUB_LEFT_FRAC: float = 0.30
_FOLLOWERS_METRIC_SUB_RIGHT_FRAC: float = 0.60


def _followers_metric_max_tap_x_for_stats_strip(screen_w: int) -> int:
    """Largest integer X allowed for a stats-strip tap (strictly left of 45% screen width)."""
    sw = max(1, int(screen_w))
    return (sw * 450 - 1) // 1000


def _followers_harvest_classify_metric_screen_zone(nx: float) -> str:
    if nx < _FOLLOWERS_METRIC_POSTS_MAX_NX:
        return "posts"
    if nx > _FOLLOWERS_METRIC_SCREEN_MAX_NX:
        return "following"
    return "followers"


def _followers_metric_semantic_identity(n: dict[str, Any]) -> str:
    """
    XML-first metric column identity for profile stats strip.
    Returns followers | following | posts | unknown (geometry only for unknown).
    """
    rid = str(n.get("resourceId") or "").lower()
    cd_raw = str(n.get("content_desc") or "")
    cd = _follow_norm(cd_raw)
    tx = str(n.get("text") or "").strip()
    tx_l = tx.lower()
    if "profile_header_posts" in rid or rid.endswith("posts"):
        return "posts"
    if "profile_header_post" in rid and "follower" not in rid:
        return "posts"
    if "profile_header_following" in rid:
        return "following"
    if "followers_label" in rid or "followers_value" in rid:
        return "followers"
    if "follow_count" in rid or "follower_count" in rid:
        return "followers"
    if "profile_header_followers" in rid:
        return "followers"
    if tx and _followers_label_match(tx):
        return "followers"
    if cd:
        if _followers_reject_following_column_label(cd_raw) and not _followers_label_match(
            cd_raw
        ):
            if "follower" not in cd:
                return "following"
        if "follower" in cd or "abonné" in cd or "abonne" in cd:
            if not _followers_reject_following_column_label(cd_raw):
                return "followers"
    return "unknown"


def _followers_metric_pick_semantic_followers_tap(
    parent: dict[str, Any],
    raw_nodes: list[dict[str, Any]],
    *,
    source_profile_username: str,
) -> tuple[int, int, str, dict[str, Any], dict[str, Any]]:
    """
    Prefer followers count TextView, then label, then a left-biased point on the parent.
    Returns tap_x, tap_y, tap_source, tap_bounds, parent_bounds.
    """
    pbd = dict(parent.get("bounds") or {})
    try:
        pl = int(pbd.get("left", 0))
        pt = int(pbd.get("top", 0))
        pr = int(pbd.get("right", 0))
        pb = int(pbd.get("bottom", 0))
    except Exception:
        return 0, 0, "parent_biased", {}, pbd
    if pr <= pl or pb <= pt:
        return 0, 0, "parent_biased", {}, pbd
    nw = pr - pl
    nh = pb - pt
    p_area = max(1, nw * nh)
    rid_p = str(parent.get("resourceId") or "")
    cd_p = str(parent.get("content_desc") or "")

    def _center(bd: dict[str, Any]) -> tuple[int, int] | None:
        try:
            l, t, r, b = (
                int(bd.get("left", 0)),
                int(bd.get("top", 0)),
                int(bd.get("right", 0)),
                int(bd.get("bottom", 0)),
            )
        except Exception:
            return None
        if r <= l or b <= t:
            return None
        return (l + r) // 2, (t + b) // 2

    def _inside_parent(bd: dict[str, Any]) -> bool:
        cc = _center(bd)
        if not cc:
            return False
        mx, my = cc
        return pl <= mx <= pr and pt <= my <= pb

    value_hits: list[tuple[int, dict[str, Any]]] = []
    label_hits: list[tuple[int, dict[str, Any]]] = []
    for m in raw_nodes:
        mb = dict(m.get("bounds") or {})
        if mb == pbd:
            continue
        if not _inside_parent(mb):
            continue
        try:
            m_area = max(
                1,
                (int(mb.get("right", 0)) - int(mb.get("left", 0)))
                * (int(mb.get("bottom", 0)) - int(mb.get("top", 0))),
            )
        except Exception:
            m_area = 1
        if m_area >= int(p_area * 0.96):
            continue
        mrid = str(m.get("resourceId") or "").lower()
        mtxt = str(m.get("text") or "").strip()
        mcd = str(m.get("content_desc") or "").strip()
        _ = f"{mtxt} {mcd}".strip()
        is_val_rid = (
            "followers_value" in mrid
            or "follow_count" in mrid
            or ("follower" in mrid and "count" in mrid and "following" not in mrid)
        )
        is_lbl_rid = "followers_label" in mrid
        if is_val_rid or (
            mtxt and _STAT_NUMERIC_RE.match(mtxt) and not _followers_reject_posts_label(mtxt)
        ):
            value_hits.append((m_area, dict(mb)))
            continue
        if is_lbl_rid or (mtxt and _followers_label_match(mtxt)):
            label_hits.append((m_area, dict(mb)))

    def _emit(
        bx: dict[str, Any], src: str, tcx: int, tcy: int
    ) -> tuple[int, int, str, dict[str, Any], dict[str, Any]]:
        try:
            log(
                "info",
                "followers_entry_semantic_followers_metric_selected",
                source_profile_username=str(source_profile_username or ""),
                resource_id=str(rid_p or "")[:220],
                content_desc=str(cd_p or "")[:320],
                parent_bounds=dict(pbd),
                tap_source=str(src or ""),
                tap_x=int(tcx),
                tap_y=int(tcy),
                tap_bounds=dict(bx),
            )
        except Exception:
            pass
        return int(tcx), int(tcy), str(src), dict(bx), dict(pbd)

    if value_hits:
        value_hits.sort(key=lambda t: t[0])
        vb = value_hits[0][1]
        c = _center(vb)
        if c:
            return _emit(vb, "value_text", c[0], c[1])
    if label_hits:
        label_hits.sort(key=lambda t: t[0])
        lb = label_hits[0][1]
        c = _center(lb)
        if c:
            return _emit(lb, "label_text", c[0], c[1])
    tcx = pl + int(nw * 0.36)
    tcy = (pt + pb) // 2
    margin = max(4, nw // 25)
    tcx = max(pl + margin, min(pr - margin, tcx))
    tcy = max(pt + margin, min(pb - margin, tcy))
    fake_bd = {
        "left": max(pl, tcx - margin),
        "right": min(pr, tcx + margin),
        "top": max(pt, tcy - margin),
        "bottom": min(pb, tcy + margin),
    }
    return _emit(fake_bd, "parent_biased", tcx, tcy)


def _followers_harvest_metric_followers_sub_bounds(
    bd: dict[str, Any], *, screen_w: int
) -> tuple[dict[str, Any], bool]:
    """Wide clickables: middle 30–60% of node width, clamped into the followers screen band."""
    try:
        left = int(bd.get("left", 0))
        top = int(bd.get("top", 0))
        right = int(bd.get("right", 0))
        bottom = int(bd.get("bottom", 0))
    except Exception:
        return dict(bd), False
    sw = max(1, int(screen_w))
    nw = right - left
    if nw <= 0 or bottom <= top:
        return dict(bd), False
    if nw <= int(_FOLLOWERS_METRIC_WIDE_NODE_FRAC_W * sw):
        return {"left": left, "right": right, "top": top, "bottom": bottom}, False
    sl = left + int(_FOLLOWERS_METRIC_SUB_LEFT_FRAC * nw)
    sr = left + int(_FOLLOWERS_METRIC_SUB_RIGHT_FRAC * nw)
    sr = min(sr, _followers_metric_max_tap_x_for_stats_strip(sw))
    sl = max(sl, int(sw * 0.22))
    if sr - sl < 18:
        return {"left": left, "right": right, "top": top, "bottom": bottom}, False
    return {"left": sl, "right": sr, "top": top, "bottom": bottom}, True


def _followers_raw_xml_node_looks_like_followers_column(n: dict[str, Any]) -> bool:
    """True when hierarchy node targets the followers metric (not following/posts)."""
    rid = str(n.get("resourceId") or "").lower()
    cd = _follow_norm(str(n.get("content_desc") or ""))
    tx = str(n.get("text") or "").strip()
    if "profile_header_following" in rid and "follower" not in rid:
        return False
    if "profile_header_posts" in rid or "profile_header_post" in rid:
        return False
    if "profile_header_followers" in rid:
        return True
    if cd and ("follower" in cd or "abonné" in cd or "abonne" in cd):
        if _followers_reject_following_column_label(str(n.get("content_desc") or "")):
            return False
        return True
    if tx and _followers_label_match(tx):
        return True
    return False


def _followers_harvest_build_raw_metric_taps(
    raw_nodes: list[dict[str, Any]],
    w: int,
    h: int,
    *,
    source_profile_username: str,
    profile_verified: bool,
    profile_screen_class: str,
    profile_action_bar_title: str,
) -> list[dict[str, Any]]:
    """
    Convert raw hierarchy nodes (e.g. profile_header_followers_stacked_familiar) into tap rows.
    Gated: verified profile, profile-like screen class, action bar matches source, stats header bounds.
    """
    if not bool(profile_verified):
        return []
    if not _followers_screen_class_is_profile_like(profile_screen_class):
        return []
    abn = _normalize_handle(str(profile_action_bar_title or ""))
    srcn = _normalize_handle(str(source_profile_username or ""))
    if not abn or not srcn or abn != srcn:
        return []
    y_stat_lo, y_stat_hi = int(h * 0.055), int(h * 0.36)
    x_lo, x_hi = int(w * 0.02), int(w * 0.98)
    sw = int(max(1, w))
    out: list[dict[str, Any]] = []
    seen: set[tuple[int, int, int, int]] = set()
    for n in raw_nodes:
        if not bool(n.get("clickable")):
            continue
        if not _followers_raw_xml_node_looks_like_followers_column(n):
            continue
        bd = dict(n.get("bounds") or {})
        try:
            left = int(bd.get("left", 0))
            top = int(bd.get("top", 0))
            right = int(bd.get("right", 0))
            bottom = int(bd.get("bottom", 0))
        except Exception:
            continue
        if right <= left or bottom <= top:
            continue
        cy_full = (top + bottom) // 2
        if cy_full < y_stat_lo or cy_full > y_stat_hi:
            continue
        sem_id = _followers_metric_semantic_identity(n)
        if sem_id in ("following", "posts"):
            continue
        sub_bd, shrunk = _followers_harvest_metric_followers_sub_bounds(bd, screen_w=sw)
        try:
            sl = int(sub_bd.get("left", 0))
            sr = int(sub_bd.get("right", 0))
        except Exception:
            continue
        if sr <= sl:
            continue
        scx_geom = (sl + sr) // 2
        if scx_geom < x_lo or scx_geom > x_hi:
            continue
        nx_geom = scx_geom / float(sw)
        classified_geom = _followers_harvest_classify_metric_screen_zone(nx_geom)
        semantic_followers = bool(sem_id == "followers")
        tap_src_row = "harvest_raw_clickable_followers_metric"
        if semantic_followers:
            st_tx, st_ty, tap_src_row, tap_rect, _pbd = (
                _followers_metric_pick_semantic_followers_tap(
                    n,
                    raw_nodes,
                    source_profile_username=source_profile_username,
                )
            )
            if st_tx > 0 and st_ty > 0:
                scx = int(st_tx)
                cy_full = int(st_ty)
                if tap_rect:
                    sub_bd = dict(tap_rect)
                shrunk = False
            else:
                scx = int(scx_geom)
            classified = "followers"
            nx = float(scx) / float(sw)
        else:
            scx = int(scx_geom)
            nx = float(nx_geom)
            classified = str(classified_geom)
        try:
            log(
                "info",
                "followers_entry_metric_zone_classified",
                source_profile_username=str(source_profile_username or ""),
                bounds=dict(bd),
                screen_width=int(sw),
                center_x=int(scx),
                normalized_x=round(float(nx), 5),
                classified_zone=classified,
                semantic_metric_identity=str(sem_id or ""),
                geometry_classified_zone=str(classified_geom),
                candidate_method="harvest_raw_clickable_followers_metric",
                followers_sub_bounds_applied=bool(shrunk),
            )
        except Exception:
            pass
        if classified != "followers":
            try:
                log(
                    "warning",
                    "followers_entry_following_zone_rejected",
                    source_profile_username=str(source_profile_username or ""),
                    reason="classified_zone_not_followers",
                    classified_zone=classified,
                    semantic_metric_identity=str(sem_id or ""),
                    center_x=int(scx),
                    normalized_x=round(float(nx), 5),
                    bounds=dict(bd),
                    candidate_method="harvest_raw_clickable_followers_metric",
                )
            except Exception:
                pass
            continue
        if shrunk:
            try:
                log(
                    "info",
                    "followers_entry_sub_bounds_created",
                    source_profile_username=str(source_profile_username or ""),
                    original_bounds=dict(bd),
                    followers_sub_bounds=dict(sub_bd),
                    candidate_method="harvest_raw_clickable_followers_metric",
                )
            except Exception:
                pass
        try:
            sl = int(sub_bd.get("left", 0))
            sr = int(sub_bd.get("right", 0))
        except Exception:
            continue
        if sr <= sl:
            continue
        key = (sl, int(sub_bd.get("top", 0)), sr, int(sub_bd.get("bottom", 0)))
        if key in seen:
            continue
        seen.add(key)
        rid_s = str(n.get("resourceId") or "")[:200]
        cd_s = str(n.get("content_desc") or "")[:220]
        det = f"{rid_s}|{cd_s}"[:220]
        detail_signals = [
            "raw_clickable_followers_metric",
            "resource_id_followers",
            "content_desc_followers" if cd_s else "content_desc_empty",
            "profile_verified:true",
            "action_bar_matches_source:true",
            f"classified_zone:{classified}",
            f"followers_sub_shrink:{int(bool(shrunk))}",
            f"semantic_metric_identity:{sem_id}",
            f"semantic_followers_metric:{int(bool(semantic_followers))}",
        ]
        row: dict[str, Any] = {
            "score": 11_600,
            "cx": int(scx),
            "cy": int(cy_full),
            "tbounds": dict(sub_bd),
            "method": "harvest_raw_clickable_followers_metric",
            "tap_source": str(tap_src_row or "harvest_raw_clickable_followers_metric"),
            "detected": det,
            "detail_signals": detail_signals,
            "stat_type": "followers",
        }
        if semantic_followers:
            row["semantic_followers_metric"] = True
        out.append(row)
    return out


def _followers_entry_v2_geometry_followers_raw(w: int, h: int) -> dict[str, Any]:
    """Three-column geometry: tap center of middle (followers) column — no live UI probe."""
    x0, x1 = int(w * 0.18), int(w * 0.82)
    cw = max(24, (x1 - x0) // 3)
    tcx = x0 + cw + cw // 2
    tcy = int(h * 0.175)
    top, bot = int(h * 0.11), int(h * 0.27)
    bounds = {
        "left": max(0, tcx - cw // 2),
        "right": min(int(w) - 1, tcx + cw // 2),
        "top": top,
        "bottom": min(int(h) - 1, bot),
    }
    return {
        "score": 7750,
        "cx": int(tcx),
        "cy": int(tcy),
        "tbounds": bounds,
        "method": "geometry_followers_column_center",
        "tap_source": "geometry_stats_band_three_column",
        "detected": "geometry_followers_column_center",
        "stat_type": "followers",
    }


def followers_stats_surface_harvester_v2(
    d: u2.Device,
    w: int,
    h: int,
    *,
    source_profile_username: str = "",
    hierarchy_xml: str | None = None,
    profile_verified: bool = False,
    profile_screen_class: str = "",
    profile_action_bar_title: str = "",
) -> dict[str, Any]:
    """
    Reconstruct virtual stats blocks (posts / followers / following) from XML, content-desc,
    pane titles, and stats-band geometry — no taps, no swipes.
    """
    log(
        "info",
        "followers_stats_harvest_started",
        source_profile_username=source_profile_username or "",
        screen_w=w,
        screen_h=h,
    )
    hier = (hierarchy_xml or "").strip()
    if not hier:
        try:
            try:
                hier = str(d.dump_hierarchy(compressed=False))
            except TypeError:
                hier = str(d.dump_hierarchy())
        except Exception:
            hier = ""
    raw_band_nodes = _followers_stats_harvest_raw_nodes_from_hierarchy_xml(hier, w, h)
    try:
        log(
            "info",
            "followers_stats_harvest_raw_node_sample",
            source_profile_username=source_profile_username or "",
            sample=raw_band_nodes[:20],
            raw_node_count=len(raw_band_nodes),
        )
    except Exception:
        pass
    raw_metric_taps = _followers_harvest_build_raw_metric_taps(
        raw_band_nodes,
        int(w),
        int(h),
        source_profile_username=str(source_profile_username or ""),
        profile_verified=bool(profile_verified),
        profile_screen_class=str(profile_screen_class or ""),
        profile_action_bar_title=str(profile_action_bar_title or ""),
    )
    for rmi, rmt in enumerate(raw_metric_taps[:6]):
        try:
            b = dict(rmt.get("tbounds") or {})
            rec = {
                "stat_type": "followers",
                "text": "",
                "content_desc": str(rmt.get("detected") or "")[:240],
                "bounds": b,
                "center_x": int(rmt.get("cx") or 0),
                "center_y": int(rmt.get("cy") or 0),
                "confidence": 0.78,
                "source": "harvest_raw_clickable_followers_metric",
            }
            log(
                "info",
                "followers_stats_harvest_candidate",
                source_profile_username=source_profile_username or "",
                candidate=rec,
                raw_metric_index=rmi,
            )
        except Exception:
            pass
    band = _collect_profile_stats_band_texts(d, w, h)
    dump = _followers_collect_profile_text_dump(d, w, h)
    atoms: list[dict[str, Any]] = []

    def _emit_atom(
        *,
        stat_type: str,
        text: str,
        content_desc: str,
        bounds: dict[str, Any],
        confidence: float,
        source: str,
    ) -> dict[str, Any]:
        b = dict(bounds or {})
        c = _followers_bounds_center(b)
        cx, cy = (int(c[0]), int(c[1])) if c else (0, 0)
        rec: dict[str, Any] = {
            "stat_type": stat_type,
            "text": (text or "")[:240],
            "content_desc": (content_desc or "")[:480],
            "bounds": b,
            "center_x": cx,
            "center_y": cy,
            "confidence": round(float(confidence), 4),
            "source": source,
        }
        try:
            log(
                "info",
                "followers_stats_harvest_candidate",
                source_profile_username=source_profile_username or "",
                candidate=rec,
            )
        except Exception:
            pass
        atoms.append(rec)
        return rec

    for r in band:
        blob = _followers_harvest_blob_from_row(r)
        st = _followers_harvest_classify_stat_type(blob)
        if not st:
            continue
        conf = 0.62
        if str(r.get("resource_id") or "").lower().find("follower") >= 0:
            conf = 0.78
        if (r.get("raw_text") or "").strip():
            conf += 0.06
        if (r.get("content_desc") or "").strip() and not (r.get("raw_text") or "").strip():
            conf += 0.04
        src = "stats_band_xml" if (r.get("raw_text") or "").strip() else "stats_band_content_desc"
        _emit_atom(
            stat_type=st,
            text=str(r.get("raw_text") or r.get("text") or ""),
            content_desc=str(r.get("content_desc") or ""),
            bounds=dict(r.get("bounds") or {}),
            confidence=min(0.93, conf),
            source=src,
        )

    for r in dump:
        blob = " ".join(
            [
                str(r.get("text") or ""),
                str(r.get("content_desc") or ""),
                str(r.get("pane_title") or ""),
            ]
        ).strip()
        st = _followers_harvest_classify_stat_type(blob)
        if not st:
            continue
        conf = 0.58
        rid_l = str(r.get("resourceId") or "").lower()
        if "follower" in rid_l or "stats" in rid_l or "header" in rid_l:
            conf += 0.12
        if (r.get("text") or "").strip():
            conf += 0.06
        if (r.get("content_desc") or "").strip():
            conf += 0.05
        _emit_atom(
            stat_type=st,
            text=str(r.get("text") or ""),
            content_desc=str(r.get("content_desc") or ""),
            bounds=dict(r.get("bounds") or {}),
            confidence=min(0.91, conf),
            source=str(r.get("via") or "dump_mixed"),
        )

    fused: list[dict[str, Any]] = []
    followers_labels = [a for a in atoms if a.get("stat_type") == "followers"]
    numeric_band = [
        r
        for r in band
        if _STAT_NUMERIC_RE.match(
            (r.get("raw_text") or r.get("text") or "").strip()
        )
        and not _followers_reject_posts_label(
            r.get("raw_text") or r.get("text") or ""
        )
        and not _followers_reject_following_column_label(
            r.get("raw_text") or r.get("text") or ""
        )
    ]
    numeric_band.sort(key=lambda r: r["cx"])
    for lab in followers_labels:
        lb = lab.get("bounds") or {}
        lc = _followers_bounds_center(lb)
        if lc is None:
            continue
        lx, ly = int(lc[0]), int(lc[1])
        best: dict[str, Any] | None = None
        best_d = 10**9
        for nr in numeric_band:
            nb = nr.get("bounds") or {}
            nc = _followers_bounds_center(nb)
            if nc is None:
                continue
            nx, ny = int(nc[0]), int(nc[1])
            if ny >= ly - 4:
                continue
            if (ly - ny) > int(h * 0.16):
                continue
            dx = abs(nx - lx)
            if dx > int(w * 0.11):
                continue
            if dx < best_d:
                best_d = dx
                best = nr
        mb = _followers_merge_bounds(lb, (best or {}).get("bounds") or lb)
        mc = _followers_bounds_center(mb)
        if mc is None:
            continue
        tcx, tcy = int(mc[0]), int(mc[1])
        base_conf = float(lab.get("confidence") or 0.6)
        if best is not None:
            base_conf = min(0.94, base_conf + 0.14)
        fuse_rec = {
            "stat_type": "followers",
            "text": str(lab.get("text") or ""),
            "content_desc": str(lab.get("content_desc") or ""),
            "bounds": dict(mb),
            "center_x": tcx,
            "center_y": tcy,
            "confidence": round(base_conf, 4),
            "source": "hybrid_label_numeric_fusion",
        }
        try:
            log(
                "info",
                "followers_stats_harvest_fused_candidate",
                source_profile_username=source_profile_username or "",
                candidate=fuse_rec,
                paired_count_text=(best.get("text") if best else None),
            )
        except Exception:
            pass
        fused.append(fuse_rec)

    try:
        log(
            "info",
            "followers_stats_harvest_result",
            source_profile_username=source_profile_username or "",
            band_rows=len(band),
            dump_rows=len(dump),
            atoms=len(atoms),
            fused_followers=len(fused),
            raw_metric_taps=len(raw_metric_taps),
        )
    except Exception:
        pass
    return {
        "atoms": atoms,
        "fused_followers": fused,
        "band": band,
        "dump": dump,
        "raw_band_nodes": raw_band_nodes,
        "raw_metric_taps": raw_metric_taps,
    }


def _followers_merge_bounds(a: dict[str, Any], b: dict[str, Any]) -> dict[str, Any]:
    try:
        return {
            "left": min(int(a.get("left", 0)), int(b.get("left", 0))),
            "top": min(int(a.get("top", 0)), int(b.get("top", 0))),
            "right": max(int(a.get("right", 0)), int(b.get("right", 0))),
            "bottom": max(int(a.get("bottom", 0)), int(b.get("bottom", 0))),
        }
    except Exception:
        return dict(a or b or {})


def _followers_debug_capture(d: u2.Device, stem: str) -> dict[str, Any]:
    """Save screenshot + hierarchy for followers-list debugging."""
    _ensure_debug_dirs()
    out: dict[str, Any] = {"screenshot_path": None, "xml_path": None}
    shot = _SCREENSHOTS_DIR / f"{stem}.png"
    xml_path = _XML_DIR / f"{stem}.xml"
    try:
        screenshot(d, str(shot))
        out["screenshot_path"] = str(shot)
    except Exception as e:
        out["screenshot_error"] = str(e)
    try:
        try:
            hier = d.dump_hierarchy(compressed=False)
        except TypeError:
            hier = d.dump_hierarchy()
        xml_path.write_text(hier, encoding="utf-8")
        _bump_xml_fetch()
        out["xml_path"] = str(xml_path)
    except Exception as e:
        out["xml_error"] = str(e)
    return out


def _followers_current_pkg_activity(d: u2.Device) -> dict[str, Any]:
    meta: dict[str, Any] = {"current_package": None, "current_activity": None}
    try:
        cur = d.app_current() or {}
        meta["current_package"] = cur.get("package")
        meta["current_activity"] = cur.get("activity")
    except Exception as e:
        meta["app_current_error"] = str(e)
    return meta


def _guess_profile_screen(d: u2.Device, pkg: str, username_hint: str = "") -> str:
    if _try_profile_signals_once(d, username_hint or "", pkg):
        return "likely_profile"
    try:
        if d(resourceIdMatches=r".*:id/profile_header.*").exists(timeout=0.08):
            return "profile_header_rid"
        if d(resourceIdMatches=r".*:id/action_bar_title.*").exists(timeout=0.06):
            return "action_bar_title"
    except Exception:
        pass
    return "unknown"


def _collect_profile_stats_band_texts(d: u2.Device, w: int, h: int) -> list[dict[str, Any]]:
    """TextViews + content-desc nodes in the profile header stats row (posts / followers / following).

    Slightly taller window and contentDescription fallbacks help React Native / fragmented UI.
    """
    y_lo, y_hi = int(h * 0.06), int(h * 0.28)
    x_lo, x_hi = int(w * 0.03), int(w * 0.97)
    rows: list[dict[str, Any]] = []
    try:
        for el in _safe_ui_all(d(className="android.widget.TextView")):
            inf = _follow_safe_info(el)
            b = inf.get("bounds") or {}
            cy = _followers_bounds_center(b)
            if cy is None:
                continue
            cx, cyy = cy
            if cyy < y_lo or cyy > y_hi or cx < x_lo or cx > x_hi:
                continue
            txt = (inf.get("text") or "").strip()
            cd = (
                str(inf.get("contentDescription") or inf.get("content_desc") or "")
                .strip()
            )
            pane = str(inf.get("paneTitle") or inf.get("pane_title") or "").strip()
            display = txt or cd
            if not display:
                continue
            rows.append(
                {
                    "text": display,
                    "raw_text": txt,
                    "content_desc": cd,
                    "pane_title": pane,
                    "cx": cx,
                    "cyy": cyy,
                    "bounds": dict(b),
                    "resource_id": inf.get("resourceName"),
                }
            )
    except Exception:
        pass
    pkg = str(getattr(config, "INSTAGRAM_PACKAGE", "") or "")
    for cn in ("android.view.View", "android.widget.Button"):
        try:
            sel = d(className=cn)
            if pkg:
                sel = sel.packageName(pkg)
            for el in _safe_ui_all(sel):
                inf = _follow_safe_info(el)
                b = inf.get("bounds") or {}
                cy = _followers_bounds_center(b)
                if cy is None:
                    continue
                cx, cyy = cy
                if cyy < y_lo or cyy > y_hi or cx < x_lo or cx > x_hi:
                    continue
                txt = (inf.get("text") or "").strip()
                cd = (
                    str(inf.get("contentDescription") or inf.get("content_desc") or "")
                    .strip()
                )
                display = txt or cd
                if not display:
                    continue
                rows.append(
                    {
                        "text": display,
                        "raw_text": txt,
                        "content_desc": cd,
                        "pane_title": str(
                            inf.get("paneTitle") or inf.get("pane_title") or ""
                        ).strip(),
                        "cx": cx,
                        "cyy": cyy,
                        "bounds": dict(b),
                        "resource_id": inf.get("resourceName"),
                    }
                )
        except Exception:
            continue
    rows.sort(key=lambda r: (r["cyy"], r["cx"]))
    return rows


def _compute_followers_metric_tap_from_header_geometry(
    *,
    screen_w: int,
    screen_h: int,
    band: list[dict[str, Any]],
    source_profile_username: str = "",
) -> dict[str, Any]:
    """Stable followers-column tap from stats-band TextView geometry (not wide XML clickables).

    Returns a dict with ok, tap_x, tap_y, source_method, reason, stats_band_top, stats_band_bottom.
    """
    sw = max(1, int(screen_w))
    sh = max(1, int(screen_h))
    max_tx = _followers_metric_max_tap_x_for_stats_strip(sw)
    gap = max(8, sw // 110)

    def _geom_log_reject(reason: str, **extra: Any) -> dict[str, Any]:
        try:
            log(
                "warning",
                "followers_entry_header_geometry_tap_rejected",
                source_profile_username=str(source_profile_username or ""),
                reason=str(reason),
                screen_width=int(sw),
                expected_tab="followers",
                **{k: v for k, v in extra.items() if v is not None},
            )
        except Exception:
            pass
        return {
            "ok": False,
            "tap_x": 0,
            "tap_y": 0,
            "source_method": "",
            "reason": str(reason),
            "stats_band_top": int(extra.get("stats_band_top") or 0),
            "stats_band_bottom": int(extra.get("stats_band_bottom") or 0),
        }

    def _geom_log_ok(
        tap_x: int,
        tap_y: int,
        source_method: str,
        band_top: int,
        band_bot: int,
    ) -> dict[str, Any]:
        try:
            log(
                "info",
                "followers_entry_header_geometry_tap_computed",
                source_profile_username=str(source_profile_username or ""),
                screen_width=int(sw),
                tap_x=int(tap_x),
                tap_y=int(tap_y),
                normalized_x=round(float(tap_x) / float(sw), 5),
                source_method=str(source_method or ""),
                expected_tab="followers",
                stats_band_top=int(band_top),
                stats_band_bottom=int(band_bot),
            )
        except Exception:
            pass
        return {
            "ok": True,
            "tap_x": int(tap_x),
            "tap_y": int(tap_y),
            "source_method": str(source_method or ""),
            "reason": "",
            "stats_band_top": int(band_top),
            "stats_band_bottom": int(band_bot),
        }

    def _tap_x_passes_hard_gate(tx: int) -> bool:
        return int(tx) * 1000 < sw * 450

    nums: list[dict[str, Any]] = []
    for r in band:
        txt = (r.get("text") or "").strip()
        if not _STAT_NUMERIC_RE.match(txt):
            continue
        if _followers_reject_posts_label(txt):
            continue
        if _followers_reject_following_column_label(txt):
            continue
        b = r.get("bounds")
        if not isinstance(b, dict):
            continue
        try:
            left = int(b.get("left", 0))
            top = int(b.get("top", 0))
            right = int(b.get("right", 0))
            bottom = int(b.get("bottom", 0))
        except Exception:
            continue
        if right <= left or bottom <= top:
            continue
        cx = int(r.get("cx") or (left + right) // 2)
        cyy = int(r.get("cyy") or (top + bottom) // 2)
        nums.append(
            {
                "_left": left,
                "_right": right,
                "_top": top,
                "_bottom": bottom,
                "_cx": cx,
                "_cyy": cyy,
            }
        )

    band_top = 0
    band_bot = 0
    if nums:
        band_top = min(int(n["_top"]) for n in nums)
        band_bot = max(int(n["_bottom"]) for n in nums)

    y_tol = max(12, int(sh * 0.038))
    if nums:
        cyys = sorted(int(n["_cyy"]) for n in nums)
        med_y = cyys[len(cyys) // 2]
        strip = [n for n in nums if abs(int(n["_cyy"]) - med_y) <= y_tol]
        strip.sort(key=lambda n: int(n["_cx"]))
        if strip:
            band_top = min(int(n["_top"]) for n in strip)
            band_bot = max(int(n["_bottom"]) for n in strip)

        if len(strip) >= 3:
            cands = strip
            posts_r = int(cands[0]["_right"])
            following_l = int(cands[-1]["_left"])
            if len(cands) == 3:
                mid = cands[1]
                src = "triple_numeric_middle_chip"
            else:
                inner = cands[1:-1]
                target_x = int(sw * 0.37)
                mid = (
                    min(inner, key=lambda n: abs(int(n["_cx"]) - target_x))
                    if inner
                    else cands[1]
                )
                src = "triple_numeric_pick_nearest_expected_cx"
            mx = (int(mid["_left"]) + int(mid["_right"])) // 2
            my = (int(mid["_top"]) + int(mid["_bottom"])) // 2
            mx = min(mx, max_tx, following_l - gap)
            mx = max(mx, posts_r + gap)
            if not _tap_x_passes_hard_gate(mx):
                return _geom_log_reject(
                    "hard_gate_tap_x_not_strictly_before_45pct",
                    attempted_tap_x=int(mx),
                    attempted_normalized_x=round(float(mx) / float(sw), 5),
                    stats_band_top=band_top,
                    stats_band_bottom=band_bot,
                    source_method=str(src),
                )
            return _geom_log_ok(mx, my, src, band_top, band_bot)

        if len(strip) == 2:
            left_cell, right_cell = strip[0], strip[1]
            posts_r = int(left_cell["_right"])
            rx = (int(right_cell["_left"]) + int(right_cell["_right"])) // 2
            ry = (int(right_cell["_top"]) + int(right_cell["_bottom"])) // 2
            rx = min(rx, max_tx)
            rx = max(rx, posts_r + gap)
            if int(right_cell["_cx"]) * 1000 >= sw * 450:
                return _geom_log_reject(
                    "dual_numeric_right_cell_in_following_zone",
                    stats_band_top=band_top,
                    stats_band_bottom=band_bot,
                )
            if not _tap_x_passes_hard_gate(rx):
                return _geom_log_reject(
                    "hard_gate_tap_x_not_strictly_before_45pct",
                    attempted_tap_x=int(rx),
                    attempted_normalized_x=round(float(rx) / float(sw), 5),
                    stats_band_top=band_top,
                    stats_band_bottom=band_bot,
                    source_method="dual_numeric_right_cell",
                )
            return _geom_log_ok(rx, ry, "dual_numeric_right_cell", band_top, band_bot)

        if len(strip) == 1:
            one = strip[0]
            ox = (int(one["_left"]) + int(one["_right"])) // 2
            oy = (int(one["_top"]) + int(one["_bottom"])) // 2
            if _tap_x_passes_hard_gate(ox) and int(one["_cx"]) >= int(sw * 0.20):
                return _geom_log_ok(
                    ox, oy, "single_numeric_center", band_top, band_bot
                )

    flabs: list[dict[str, Any]] = []
    for r in band:
        disp = (r.get("raw_text") or r.get("text") or "").strip()
        if not _followers_label_match(disp):
            continue
        b = r.get("bounds")
        if not isinstance(b, dict):
            continue
        try:
            left = int(b.get("left", 0))
            top = int(b.get("top", 0))
            right = int(b.get("right", 0))
            bottom = int(b.get("bottom", 0))
        except Exception:
            continue
        if right <= left or bottom <= top:
            continue
        cx = int(r.get("cx") or (left + right) // 2)
        cyy = int(r.get("cyy") or (top + bottom) // 2)
        flabs.append(
            {
                "_left": left,
                "_right": right,
                "_top": top,
                "_bottom": bottom,
                "_cx": cx,
                "_cyy": cyy,
            }
        )

    if not flabs:
        return _geom_log_reject(
            "no_followers_geometry_from_band",
            stats_band_top=band_top,
            stats_band_bottom=band_bot,
        )

    target_x = int(sw * 0.38)
    lab = min(flabs, key=lambda z: abs(int(z["_cx"]) - target_x))
    band_top = int(lab["_top"]) if not band_top else min(band_top, int(lab["_top"]))
    band_bot = int(lab["_bottom"]) if not band_bot else max(band_bot, int(lab["_bottom"]))
    wi = int(lab["_right"]) - int(lab["_left"])
    tx = int(lab["_left"] + wi * 0.38)
    ty = (int(lab["_top"]) + int(lab["_bottom"])) // 2
    tx = min(tx, max_tx)
    tx = max(tx, int(sw * 0.24))
    if not _tap_x_passes_hard_gate(tx):
        return _geom_log_reject(
            "hard_gate_tap_x_not_strictly_before_45pct",
            attempted_tap_x=int(tx),
            attempted_normalized_x=round(float(tx) / float(sw), 5),
            stats_band_top=band_top,
            stats_band_bottom=band_bot,
            source_method="followers_label_biased_tap",
        )
    return _geom_log_ok(tx, ty, "followers_label_biased_tap", band_top, band_bot)


def _parse_profile_metric_compact_number(text: str) -> int | None:
    """Parse IG-style counts: 1,234 / 12.5K / 3M (best-effort)."""
    t = (
        (text or "")
        .strip()
        .replace(",", "")
        .replace("\u202f", "")
        .replace("\xa0", "")
        .replace(" ", "")
    )
    if not t or t in ("-", "–", "—"):
        return None
    mul = 1
    tl = t.lower().rstrip(".")
    if tl.endswith("k"):
        mul = 1000
        t = t[:-1]
    elif tl.endswith("m"):
        mul = 1_000_000
        t = t[:-1]
    elif tl.endswith("b"):
        mul = 1_000_000_000
        t = t[:-1]
    try:
        if "." in t:
            return int(float(t) * mul)
        return int(t) * mul
    except (TypeError, ValueError):
        return None


def _visual_profile_stats_numeric_row_entries(
    band: list[dict[str, Any]], *, h: int
) -> list[tuple[int, int, int]]:
    """
    From stats-band TextViews, keep numeric nodes likely on the counts row (upper part of band).
    Returns list of (cx, cyy, value) sorted left-to-right.
    """
    if not band:
        return []
    y_cut = int(h * 0.17)
    out: list[tuple[int, int, int]] = []
    for r in band:
        txt = str(r.get("text") or "").strip()
        val = _parse_profile_metric_compact_number(txt)
        if val is None:
            continue
        cyy = int(r.get("cyy") or 0)
        if cyy > y_cut:
            continue
        out.append((int(r.get("cx") or 0), cyy, val))
    out.sort(key=lambda x: (x[0], x[1]))
    return out


def visual_extract_profile_metrics(
    d: u2.Device,
    *,
    source_profile_username: str = "",
) -> dict[str, Any]:
    """
    Read posts / followers / following from the profile header stats strip (XML band).
    Never raises; on failure returns null counts and extraction_ok=False.
    """
    meta = _followers_current_pkg_activity(d)
    un_hint = _normalize_handle(source_profile_username or "")
    username_norm = un_hint
    try:
        ab = d(resourceIdMatches=r".*:id/action_bar_title.*")
        if ab.exists(timeout=0.12):
            username_norm = _normalize_handle(str(ab.get_text() or "")) or username_norm
    except Exception:
        pass

    out: dict[str, Any] = {
        "posts_count": None,
        "followers_count": None,
        "following_count": None,
        "username_norm": username_norm,
        "current_activity": meta.get("current_activity"),
        "current_package": meta.get("current_package"),
        "extraction_ok": False,
        "extraction_note": None,
    }
    try:
        w, h = d.window_size()
    except Exception:
        w, h = 1080, 1920
    try:
        band = _collect_profile_stats_band_texts(d, w, h)
        nums = _visual_profile_stats_numeric_row_entries(band, h=h)
        if len(nums) >= 3:
            out["posts_count"] = nums[0][2]
            out["followers_count"] = nums[1][2]
            out["following_count"] = nums[2][2]
            out["extraction_ok"] = True
            out["extraction_note"] = "three_column_parse"
        elif len(nums) == 2:
            out["posts_count"] = nums[0][2]
            out["followers_count"] = nums[1][2]
            out["extraction_ok"] = True
            out["extraction_note"] = "partial_two_counts"
        elif len(nums) == 1:
            out["posts_count"] = nums[0][2]
            out["extraction_ok"] = True
            out["extraction_note"] = "single_count_assumed_posts"
        else:
            out["extraction_note"] = "no_numeric_stats_in_band"
    except Exception as e:
        out["extraction_note"] = f"exception:{type(e).__name__}"
    return out


def _followers_collect_profile_text_dump(d: u2.Device, w: int, h: int) -> list[dict[str, Any]]:
    """Header / stats strip nodes: TextView + views with content-desc (RN), pane titles, RID hints."""
    y_lo, y_hi = int(h * 120 // 2400), int(h * 720 // 2400)
    out: list[dict[str, Any]] = []
    seen: set[tuple[int, int, int, int, str]] = set()

    def _push(inf: dict[str, Any], *, via: str) -> None:
        b = dict(inf.get("bounds") or {})
        cy = _followers_bounds_center(b)
        if cy is None:
            return
        _, cyy = cy
        if not (y_lo <= cyy <= y_hi):
            return
        txt = (inf.get("text") or "").strip()
        cd = (
            str(inf.get("contentDescription") or inf.get("content_desc") or "")
            .strip()
        )
        pane = str(inf.get("paneTitle") or inf.get("pane_title") or "").strip()
        if not txt and not cd and not pane:
            return
        try:
            key = (
                int(b.get("left", 0)),
                int(b.get("top", 0)),
                int(b.get("right", 0)),
                int(b.get("bottom", 0)),
                str(inf.get("className") or ""),
            )
        except Exception:
            return
        if key in seen:
            return
        seen.add(key)
        rid = str(inf.get("resourceName") or "")
        out.append(
            {
                "text": txt,
                "content_desc": cd,
                "pane_title": pane,
                "bounds": b,
                "className": str(inf.get("className") or ""),
                "resourceId": rid,
                "via": via,
            }
        )

    try:
        for el in d(className="android.widget.TextView").all():
            _push(_follow_safe_info(el), via="textview")
    except Exception:
        pass
    pkg = str(getattr(config, "INSTAGRAM_PACKAGE", "") or "")
    for cn in (
        "android.view.View",
        "android.widget.Button",
        "android.widget.ImageView",
    ):
        try:
            sel = d(className=cn)
            if pkg:
                sel = sel.packageName(pkg)
            for el in sel.all():
                _push(_follow_safe_info(el), via=f"class:{cn}")
        except Exception:
            continue
    try:
        for el in d(
            resourceIdMatches=r".*profile.*header.*|.*stats.*|.*follower.*count.*|.*followers.*"
        ).all():
            _push(_follow_safe_info(el), via="resource_id_stats_scope")
    except Exception:
        pass
    out.sort(
        key=lambda r: (
            int(r["bounds"].get("top", 0)),
            int(r["bounds"].get("left", 0)),
        )
    )
    return out


def _followers_stat_strip_y_for_text_labels(h: int) -> tuple[int, int]:
    """Vertical band where the posts/followers/following labels sit (excludes bio)."""
    return int(h * 0.13), int(h * 0.24)


def _followers_stats_dump_effectively_empty(dump: list[dict[str, Any]]) -> bool:
    """True when there is no stats strip signal yet (no text, content-desc, or pane title)."""
    if not dump:
        return True
    for r in dump:
        if str(r.get("text") or "").strip():
            return False
        if str(r.get("content_desc") or "").strip():
            return False
        if str(r.get("pane_title") or "").strip():
            return False
    return True


def _followers_profile_rescan_stats_if_empty(
    d: u2.Device, pkg_meta: dict[str, Any]
) -> dict[str, Any]:
    """
    If stats TextViews are invisible (empty dump), nudge the list with a light upward swipe
    and rescan. Logs include current package/activity.
    """
    try:
        w, h = d.window_size()
    except Exception:
        w, h = 1080, 1920
    dump = _followers_collect_profile_text_dump(d, w, h)
    vis = list(dump)
    rescan_done = False
    if _followers_stats_dump_effectively_empty(dump):
        if _followers_abort_scroll_if_post_tap_lock("_followers_profile_rescan_stats_if_empty"):
            return {
                "followers_stat_text_dump": dump,
                "profile_stats_visible": vis,
                "profile_rescan_swiped": False,
            }
        if not _followers_post_tap_capture_gate_ok():
            log(
                "info",
                "followers_profile_rescan_swipe_skipped",
                reason="post_tap_immediate_capture_not_done",
            )
            return {
                "followers_stat_text_dump": dump,
                "profile_stats_visible": vis,
                "profile_rescan_swiped": False,
            }
        log(
            "info",
            "followers_profile_rescan_after_swipe",
            profile_stats_visible=vis,
            followers_stat_text_dump=dump,
            current_activity=pkg_meta.get("current_activity"),
            current_package=pkg_meta.get("current_package"),
        )
        try:
            xmid = int(w * 0.5)
            sy, ey = int(h * 0.42), int(h * 0.36)
            _followers_log_scroll_or_swipe_about_to_run(
                d,
                source_function="_followers_profile_rescan_stats_if_empty",
                reason="light_upward_nudge_stats_strip",
            )
            d.swipe(xmid, sy, xmid, ey, 0.08)
        except Exception:
            pass
        time.sleep(0.35)
        pkg_meta.update(_followers_current_pkg_activity(d))
        dump = _followers_collect_profile_text_dump(d, w, h)
        vis = list(dump)
        rescan_done = True
        log(
            "info",
            "followers_profile_rescan_result",
            profile_stats_visible=vis,
            followers_stat_text_dump=dump,
            current_activity=pkg_meta.get("current_activity"),
            current_package=pkg_meta.get("current_package"),
        )
    return {
        "followers_stat_text_dump": dump,
        "profile_stats_visible": vis,
        "profile_rescan_swiped": rescan_done,
    }


def _followers_profile_post_failure_debug_swipe(
    d: u2.Device,
    pkg_meta: dict[str, Any],
    *,
    followers_open_failure_logged: bool = False,
) -> None:
    """
    After followers_list_open_failed was logged: optional light swipe + rescan logs (no retry tap).
    Must not run during POST_TAP_FOLLOWERS_DETECTION_IN_PROGRESS.
    """
    if not followers_open_failure_logged:
        log(
            "warning",
            "followers_profile_post_failure_debug_swipe_skipped",
            reason="followers_list_open_failed_not_logged_yet",
        )
        return
    if POST_TAP_FOLLOWERS_DETECTION_IN_PROGRESS:
        log(
            "warning",
            "followers_post_tap_scroll_prevented",
            source="_followers_profile_post_failure_debug_swipe",
        )
        return
    log("info", "followers_profile_post_failure_debug_swipe", phase="post_failure_debug")
    try:
        w, h = d.window_size()
    except Exception:
        w, h = 1080, 1920
    try:
        dump0 = _followers_collect_profile_text_dump(d, w, h)
        vis0 = list(dump0)
        log(
            "info",
            "followers_profile_rescan_after_swipe",
            profile_stats_visible=vis0,
            followers_stat_text_dump=dump0,
            current_activity=pkg_meta.get("current_activity"),
            current_package=pkg_meta.get("current_package"),
            phase="post_failure_debug_before_swipe",
        )
    except Exception:
        pass
    try:
        xmid = int(w * 0.5)
        sy, ey = int(h * 0.42), int(h * 0.36)
        _followers_log_scroll_or_swipe_about_to_run(
            d,
            source_function="_followers_profile_post_failure_debug_swipe",
            reason="post_failure_debug_profile_rescan",
        )
        d.swipe(xmid, sy, xmid, ey, 0.08)
    except Exception:
        pass
    time.sleep(0.35)
    try:
        pkg_meta.update(_followers_current_pkg_activity(d))
    except Exception:
        pass
    try:
        dump1 = _followers_collect_profile_text_dump(d, w, h)
        vis1 = list(dump1)
        log(
            "info",
            "followers_profile_rescan_result",
            profile_stats_visible=vis1,
            followers_stat_text_dump=dump1,
            current_activity=pkg_meta.get("current_activity"),
            current_package=pkg_meta.get("current_package"),
            phase="post_failure_debug_after_swipe",
        )
    except Exception:
        pass


def _tap_profile_followers_stat(
    d: u2.Device,
    *,
    pre_scan: dict[str, Any] | None = None,
) -> tuple[bool, dict[str, Any]]:
    """
    Tap the followers stat on a source profile. Returns (ok, diagnostics dict).
    Order: exact RID profile_header_followers_stacked_familiar → text followers/abonnés in stats
    zone → other resource-ids / middle column. Coordinate fallback is separate.
    """
    diag: dict[str, Any] = {
        "followers_stat_found": False,
        "followers_stat_text": None,
        "followers_stat_bounds": None,
        "tap_x": None,
        "tap_y": None,
        "tap_method": None,
        "profile_stats_visible": [],
        "stats_band_texts": [],
        "followers_stat_text_detected": None,
        "followers_stat_text_bounds": None,
        "followers_stat_tap_x": None,
        "followers_stat_tap_y": None,
        "followers_stat_tap_source": None,
        "followers_stat_text_dump": [],
        "followers_stat_coordinate_retry": False,
        "profile_rescan_swiped": False,
        "debug_before_scan_screenshot_path": None,
        "debug_before_scan_xml_path": None,
        "debug_after_fallback_screenshot_path": None,
        "debug_after_fallback_xml_path": None,
        "followers_exact_rid_used": False,
    }
    try:
        w, h = d.window_size()
    except Exception:
        w, h = 1080, 1920

    y_lo, y_hi = int(h * 0.10), int(h * 0.46)
    x_max = int(w * 0.96)
    ideal_cx = int(w * 0.60)
    ly_lo, ly_hi = _followers_stat_strip_y_for_text_labels(h)

    if pre_scan:
        diag["followers_stat_text_dump"] = list(pre_scan.get("followers_stat_text_dump") or [])
        diag["profile_stats_visible"] = list(pre_scan.get("profile_stats_visible") or [])
        diag["profile_rescan_swiped"] = bool(pre_scan.get("profile_rescan_swiped"))
        if pre_scan.get("debug_before_scan_screenshot_path"):
            diag["debug_before_scan_screenshot_path"] = pre_scan.get(
                "debug_before_scan_screenshot_path"
            )
        if pre_scan.get("debug_before_scan_xml_path"):
            diag["debug_before_scan_xml_path"] = pre_scan.get("debug_before_scan_xml_path")
    else:
        text_dump = _followers_collect_profile_text_dump(d, w, h)
        diag["followers_stat_text_dump"] = text_dump
        diag["profile_stats_visible"] = list(text_dump)

    log(
        "info",
        "followers_stat_text_dump",
        text_view_count=len(diag["followers_stat_text_dump"]),
        profile_stats_visible_sample=(diag["followers_stat_text_dump"] or [])[:25],
        profile_rescan_swiped=diag.get("profile_rescan_swiped"),
    )

    # Priority: exact Instagram RID — always use center coordinates (d.click), not UiObject.click().
    try:
        sel_exact = d(resourceId=PROFILE_HEADER_FOLLOWERS_STACKED_FAMILIAR_RID)
        if sel_exact.exists(timeout=0.38):
            for el in sel_exact.all():
                inf = _follow_safe_info(el)
                b = dict(inf.get("bounds") or {})
                try:
                    left = int(b.get("left", 0))
                    right = int(b.get("right", 0))
                    top = int(b.get("top", 0))
                    bottom = int(b.get("bottom", 0))
                except Exception:
                    continue
                if right <= left or bottom <= top:
                    continue
                cy_chk = _followers_bounds_center(b)
                if cy_chk is None:
                    continue
                _, cyy = cy_chk
                if cyy < y_lo or cyy > y_hi or left > x_max:
                    continue
                cx = (left + right) // 2
                cy = (top + bottom) // 2
                rid_seen = str(inf.get("resourceName") or PROFILE_HEADER_FOLLOWERS_STACKED_FAMILIAR_RID)
                log(
                    "info",
                    "followers_exact_rid_found",
                    resource_id=rid_seen,
                    bounds={"left": left, "right": right, "top": top, "bottom": bottom},
                    clickable=inf.get("clickable"),
                    enabled=inf.get("enabled"),
                )
                log(
                    "info",
                    "followers_exact_rid_click",
                    center_x=cx,
                    center_y=cy,
                    bounds={"left": left, "right": right, "top": top, "bottom": bottom},
                )
                try:
                    d.click(cx, cy)
                except Exception as e:
                    diag["tap_error"] = str(e)
                    return False, diag
                tbounds = dict(b)
                diag["followers_stat_found"] = True
                diag["followers_exact_rid_used"] = True
                diag["tap_method"] = "resource_id_profile_header_followers_stacked_familiar_exact"
                diag["followers_stat_tap_source"] = "exact_rid_coordinate_tap"
                diag["followers_stat_text_detected"] = "profile_header_followers_stacked_familiar"
                diag["followers_stat_text_bounds"] = tbounds
                diag["followers_stat_tap_x"] = cx
                diag["followers_stat_tap_y"] = cy
                diag["tap_x"], diag["tap_y"] = cx, cy
                diag["followers_stat_text"] = "profile_header_followers_stacked_familiar"
                diag["followers_stat_bounds"] = tbounds
                log(
                    "info",
                    "followers_stat_tap_selected",
                    followers_stat_text_detected=diag["followers_stat_text_detected"],
                    followers_stat_text_bounds=tbounds,
                    followers_stat_tap_x=cx,
                    followers_stat_tap_y=cy,
                    followers_stat_tap_source=diag["followers_stat_tap_source"],
                    tap_method=diag["tap_method"],
                )
                return True, diag
    except Exception:
        pass

    band = _collect_profile_stats_band_texts(d, w, h)
    diag["stats_band_texts"] = [(r.get("text") or "").strip() for r in band[:40]]

    numeric_row = [
        r
        for r in band
        if _STAT_NUMERIC_RE.match(
            (r.get("raw_text") or r.get("text") or "").strip()
        )
        and not _followers_reject_posts_label(
            r.get("raw_text") or r.get("text") or ""
        )
        and not _followers_reject_following_column_label(
            r.get("raw_text") or r.get("text") or ""
        )
    ]
    numeric_row.sort(key=lambda r: r["cx"])

    candidates: list[dict[str, Any]] = []

    # 0) Instagram familiar layout: clickable followers stacked container (see hierarchy XML).
    try:
        stacked = d(resourceIdMatches=r".*:id/profile_header_followers_stacked_familiar$")
        if stacked.exists(timeout=0.28):
            for el in stacked.all():
                inf = _follow_safe_info(el)
                b = inf.get("bounds") or {}
                c = _followers_bounds_center(b)
                if c is None:
                    continue
                _cx, cyy = c
                if cyy < y_lo or cyy > y_hi or int(b.get("left", 0)) > x_max:
                    continue
                rw = int(b.get("right", 0)) - int(b.get("left", 0))
                candidates.append(
                    {
                        "score": 12000 + min(rw, 500),
                        "cx": _cx,
                        "cy": cyy,
                        "rw": max(rw, 1),
                        "el": el,
                        "method": "resource_id_followers_stacked_familiar",
                        "tap_source": "parent_block",
                        "detected": "profile_header_followers_stacked_familiar",
                        "tbounds": dict(b),
                    }
                )
                break
    except Exception:
        pass

    # 1) Text: followers / follower / abonnés… — prefer label; merge with count above in same column.
    try:
        for el in d(className="android.widget.TextView").all():
            inf = _follow_safe_info(el)
            raw_txt = (inf.get("text") or "").strip()
            cd_txt = str(inf.get("contentDescription") or "").strip()
            label_txt = raw_txt or cd_txt
            if not label_txt or not _followers_label_match(label_txt):
                continue
            b = inf.get("bounds") or {}
            cy = _followers_bounds_center(b)
            if cy is None:
                continue
            _cx, cyy = cy
            if cyy < y_lo or cyy > y_hi or int(b.get("left", 0)) > x_max:
                continue
            rw = int(b.get("right", 0)) - int(b.get("left", 0))
            if rw < 8:
                continue
            low = label_txt.lower()
            if "following" in low and "follower" not in low:
                continue
            rid_l = str(inf.get("resourceName") or "")
            if (
                "profile_header_familiar_followers" not in rid_l
                and "followers_stacked" not in rid_l
            ):
                if not (ly_lo <= cyy <= ly_hi):
                    continue

            pair: dict[str, Any] | None = None
            for r in band:
                rt = (r.get("raw_text") or r.get("text") or "").strip()
                if not _STAT_NUMERIC_RE.match(rt):
                    continue
                if _followers_reject_posts_label(rt) or _followers_reject_following_column_label(rt):
                    continue
                rcx, rcyy = int(r["cx"]), int(r["cyy"])
                if abs(rcx - _cx) > int(w * 0.09):
                    continue
                if rcyy >= cyy - 4:
                    continue
                if (cyy - rcyy) > int(h * 0.14):
                    continue
                pair = r
                break

            if pair is not None:
                mb = _followers_merge_bounds(b, pair.get("bounds") or {})
                mc = _followers_bounds_center(mb)
                if mc is None:
                    continue
                tcx, tcy = mc
                bw = int(mb.get("right", 0)) - int(mb.get("left", 0))
                score = (
                    8500
                    - abs(tcx - ideal_cx)
                    + min(bw, 400)
                )
                candidates.append(
                    {
                        "score": score,
                        "cx": tcx,
                        "cy": tcy,
                        "rw": max(bw, 1),
                        "el": el,
                        "method": "text_label_with_count_block",
                        "tap_source": "parent_block",
                        "detected": f"{(pair.get('raw_text') or pair.get('text') or '').strip()}|{label_txt}",
                        "tbounds": dict(mb),
                    }
                )
            else:
                score = 6200 - abs(_cx - ideal_cx) + min(rw, 320)
                candidates.append(
                    {
                        "score": score,
                        "cx": _cx,
                        "cy": cyy,
                        "rw": rw,
                        "el": el,
                        "method": "text_followers_label",
                        "tap_source": "text_element",
                        "detected": label_txt,
                        "tbounds": dict(b),
                    }
                )
    except Exception:
        pass

    # 2) Resource-id hints (counts; stacked handled in phase 0).
    rid_patterns = (
        r".*:id/.*follower.*count.*",
        r".*:id/.*followers.*count.*",
        r".*:id/.*stacked.*follower.*",
    )
    for pat in rid_patterns:
        try:
            for el in d(resourceIdMatches=pat).all():
                inf = _follow_safe_info(el)
                b = inf.get("bounds") or {}
                cy = _followers_bounds_center(b)
                if cy is None:
                    continue
                _cx, cyy = cy
                if cyy < y_lo or cyy > y_hi or int(b.get("left", 0)) > x_max:
                    continue
                rw = int(b.get("right", 0)) - int(b.get("left", 0))
                score = 5000 + rw * 100 - abs(_cx - ideal_cx) // 2
                try:
                    det_txt = (el.get_text() or "").strip()
                except Exception:
                    det_txt = ""
                candidates.append(
                    {
                        "score": score,
                        "cx": _cx,
                        "cy": cyy,
                        "rw": max(rw, 1),
                        "el": el,
                        "method": f"resource_id:{pat}",
                        "tap_source": "text_element",
                        "detected": det_txt or pat,
                        "tbounds": dict(b),
                    }
                )
        except Exception:
            continue

    # 3) Middle numeric column when three stats visible.
    if len(numeric_row) >= 3:
        mid = numeric_row[len(numeric_row) // 2]
        b = mid.get("bounds") or {}
        c = _followers_bounds_center(b)
        if c:
            rw = int(b.get("right", 0)) - int(b.get("left", 0))
            candidates.append(
                {
                    "score": 2500 - abs(c[0] - ideal_cx),
                    "cx": c[0],
                    "cy": c[1],
                    "rw": max(rw, 1),
                    "el": None,
                    "method": "middle_stat_column",
                    "tap_source": "text_element",
                    "detected": (mid.get("text") or "").strip(),
                    "tbounds": dict(b),
                }
            )

    if not candidates:
        return False, diag

    best_c = max(candidates, key=lambda x: int(x["score"]))
    cx, cy = int(best_c["cx"]), int(best_c["cy"])
    el_pick = best_c["el"]
    method = str(best_c["method"])
    tap_src = str(best_c["tap_source"])
    detected = str(best_c["detected"])
    tbounds: dict[str, Any] = dict(best_c["tbounds"] or {})

    diag["followers_stat_found"] = True
    diag["tap_method"] = method
    diag["followers_stat_text_detected"] = detected
    diag["followers_stat_text_bounds"] = tbounds
    diag["followers_stat_tap_x"] = cx
    diag["followers_stat_tap_y"] = cy
    diag["followers_stat_tap_source"] = tap_src
    diag["tap_x"], diag["tap_y"] = cx, cy
    diag["followers_stat_text"] = detected
    diag["followers_stat_bounds"] = tbounds

    log(
        "info",
        "followers_stat_tap_selected",
        followers_stat_text_detected=detected,
        followers_stat_text_bounds=tbounds,
        followers_stat_tap_x=cx,
        followers_stat_tap_y=cy,
        followers_stat_tap_source=tap_src,
        tap_method=method,
    )

    try:
        if method == "resource_id_followers_stacked_familiar":
            d.click(cx, cy)
        elif el_pick is not None and tap_src == "parent_block":
            try:
                el_pick.click()
            except Exception:
                d.click(cx, cy)
        elif tap_src == "text_element" and el_pick is not None:
            try:
                el_pick.click()
            except Exception:
                d.click(cx, cy)
        else:
            d.click(cx, cy)
        return True, diag
    except Exception:
        try:
            d.click(cx, cy)
            diag["tap_note"] = "coordinate_after_click_failed"
            return True, diag
        except Exception as e:
            diag["tap_error"] = str(e)
            return False, diag


def _tap_followers_coord_fallback(
    d: u2.Device, diag: dict[str, Any]
) -> tuple[bool, dict[str, Any]]:
    """
    Last resort when text/RID fails: ~60% x 18.5% (1080x2400 → ~648, 444).
    """
    diag["followers_exact_rid_used"] = False
    try:
        w, h = d.window_size()
    except Exception:
        w, h = 1080, 1920
    band = _collect_profile_stats_band_texts(d, w, h)
    cx = int(w * 0.60)
    cy = int(h * 0.185)
    y_src = "ratio_w0.60_h0.185"
    diag["followers_stat_coordinate_retry"] = True
    diag["tap_method"] = "coordinate_fallback_middle_stats_column"
    diag["stats_band_center_y_source"] = y_src
    diag["tap_x"], diag["tap_y"] = cx, cy
    diag["followers_coord_fallback"] = True
    diag["followers_stat_tap_source"] = "coordinate_middle_stats_column"
    diag["followers_stat_text_detected"] = None
    diag["followers_stat_text_bounds"] = None
    diag["followers_stat_tap_x"] = cx
    diag["followers_stat_tap_y"] = cy
    diag["followers_stat_text"] = None
    diag["followers_stat_bounds"] = None
    if not diag.get("stats_band_texts"):
        diag["stats_band_texts"] = [(r.get("text") or "").strip() for r in band[:40]]
    log(
        "info",
        "followers_stat_tap_selected",
        _include_null_fields=True,
        followers_stat_text_detected=None,
        followers_stat_text_bounds=None,
        followers_stat_tap_x=cx,
        followers_stat_tap_y=cy,
        followers_stat_tap_source="coordinate_middle_stats_column",
        tap_method=diag["tap_method"],
    )
    try:
        d.click(cx, cy)
        cap_af = _followers_debug_capture(d, "followers_profile_after_fallback_tap")
        diag["debug_after_fallback_screenshot_path"] = cap_af.get("screenshot_path")
        diag["debug_after_fallback_xml_path"] = cap_af.get("xml_path")
        return True, diag
    except Exception as e:
        diag["fallback_tap_error"] = str(e)
        return False, diag


def _followers_profile_tabs_visible(d: u2.Device) -> bool:
    """
    True when typical Instagram profile tab chrome is present (grid / reels / tagged strip).
    Used to infer followers list when tabs disappear but list rows remain.
    """
    checks: list[tuple[str, Callable[[], object]]] = [
        ("resourceId:profile_tabs_container", lambda: d(resourceIdMatches=r".*:id/profile_tabs_container")),
        ("resourceId:profile_tab_layout", lambda: d(resourceIdMatches=r".*:id/profile_tab_layout")),
        ("resourceId:profile_tab_icon_view", lambda: d(resourceIdMatches=r".*:id/profile_tab_icon_view")),
        ("resourceId:media_tab", lambda: d(resourceIdMatches=r".*:id/media_tab")),
        ("descriptionContains:Grid", lambda: d(descriptionContains="Grid")),
        ("descriptionContains:Reels", lambda: d(descriptionContains="Reels")),
        ("descriptionContains:Tagged", lambda: d(descriptionContains="Tagged")),
        ("descriptionMatches:tagged", lambda: d(descriptionMatches=r"(?i).*tagged.*")),
        ("text:Posts", lambda: d(text="Posts")),
        ("textMatches:posts", lambda: d(textMatches=r"(?i).*posts.*")),
        ("resourceId:profile_tabs", lambda: d(resourceIdMatches=r".*:id/profile_tabs[^_].*")),
    ]
    for phase, fact in checks:
        el = None
        try:
            el = fact()
        except Exception as e:
            log(
                "warning",
                "followers_profile_tabs_visible_probe_failed",
                phase=phase,
                probe="selector_build",
                exception_type=type(e).__name__,
                exception_message=str(e)[:800],
            )
            continue
        try:
            if el.exists(timeout=0.06):
                return True
        except Exception as e:
            log(
                "warning",
                "followers_profile_tabs_visible_probe_failed",
                phase=phase,
                probe="exists",
                exception_type=type(e).__name__,
                exception_message=str(e)[:800],
            )
            continue
    return False


_POST_FOLLOW_PROFILE_TABS_GRID_MARGIN_PX = 12


def _followers_profile_tabs_bottom_y_px(
    d: u2.Device,
    *,
    window_h: int | None = None,
) -> tuple[int | None, str]:
    """
    Bottom edge (device Y) of the profile posts / reels / tagged tab strip, if found.
    Uses the same resource/description signals as ``_followers_profile_tabs_visible``,
    but returns geometry so callers can clamp grid scans strictly below the strip.
    """
    try:
        _, wh = d.window_size()
    except Exception:
        wh = int(window_h or 2400)
    wh = max(480, int(wh))
    y_top_min = int(wh * 0.10)
    y_bot_max = int(wh * 0.92)

    def _bounds_bottom(el: Any) -> int | None:
        try:
            b = (el.info or {}).get("bounds") or {}
            bot = int(b.get("bottom", 0))
            top = int(b.get("top", 0))
            if bot <= 0 or bot <= top:
                return None
            if top < y_top_min or bot > y_bot_max:
                return None
            return bot
        except Exception:
            return None

    def _nodes_for_selector(sel: Any) -> list[Any]:
        try:
            if not sel.exists(timeout=0.06):
                return []
        except Exception:
            return []
        try:
            if hasattr(sel, "all"):
                return list(sel.all())
        except Exception:
            pass
        return [sel]

    checks: list[tuple[str, Callable[[], Any]]] = [
        ("resourceId:profile_tabs_container", lambda: d(resourceIdMatches=r".*:id/profile_tabs_container")),
        ("resourceId:profile_tab_layout", lambda: d(resourceIdMatches=r".*:id/profile_tab_layout")),
        ("resourceId:profile_tabs", lambda: d(resourceIdMatches=r".*:id/profile_tabs[^_].*")),
        ("resourceId:media_tab", lambda: d(resourceIdMatches=r".*:id/media_tab")),
        ("resourceId:profile_tab_icon_view", lambda: d(resourceIdMatches=r".*:id/profile_tab_icon_view")),
        ("descriptionContains:Grid", lambda: d(descriptionContains="Grid")),
        ("descriptionContains:Reels", lambda: d(descriptionContains="Reels")),
        ("descriptionContains:Tagged", lambda: d(descriptionContains="Tagged")),
    ]
    best: int | None = None
    best_phase = ""
    for phase, fact in checks:
        try:
            sel = fact()
        except Exception:
            continue
        for el in _nodes_for_selector(sel):
            bb = _bounds_bottom(el)
            if bb is None:
                continue
            if best is None or bb > best:
                best = bb
                best_phase = phase
    return (best, best_phase) if best is not None else (None, "")


def _post_follow_dynamic_first_row_search_y_min_layout(
    d: u2.Device,
    ih: int,
    ui_hints: dict[str, Any],
) -> tuple[int, str, int | None, int]:
    """
    Lower Y bound (screenshot / device pixels, same space as ``ih``) for scanning the
    first post grid row. Priority: tab strip bottom (authoritative), then Suggested/Discover
    text hint band, then permissive default ratio.
    Returns ``(search_y_min_px, source, profile_tabs_bottom_y_raw_or_none, margin_px)``.
    """
    margin = int(_POST_FOLLOW_PROFILE_TABS_GRID_MARGIN_PX)
    ih = max(120, int(ih))
    tabs_bt, _phase = _followers_profile_tabs_bottom_y_px(d, window_h=ih)
    if tabs_bt is None and bool(ui_hints.get("profile_tabs_visible")):
        tabs_bt, _phase = _followers_profile_tabs_bottom_y_px(d, window_h=ih)
    if tabs_bt is not None:
        y_floor = min(max(8, int(tabs_bt) + margin), ih - 8)
        return y_floor, "profile_tabs_bottom", int(tabs_bt), margin
    overlay = bool(ui_hints.get("suggested_for_you") or ui_hints.get("discover_people"))
    if overlay:
        y_floor = max(8, min(int(ih * float(_POST_FOLLOW_LIKES_GRID_Y0_RATIO)), ih - 8))
        return y_floor, "suggested_hint_ratio", None, margin
    y_floor = max(8, min(int(ih * 0.20), ih - 8))
    return y_floor, "default_ratio", None, margin


def _followers_stacked_central_textview_run(d: u2.Device, w: int, h: int) -> int:
    """Longest run of vertically stacked TextView centers in the central list band (condition C)."""
    y_lo, y_hi = int(h * 0.28), int(h * 0.88)
    x_lo, x_hi = int(w * 0.18), int(w * 0.82)
    centers: list[int] = []
    try:
        for el in d(className="android.widget.TextView").all():
            try:
                inf = el.info
                t = (inf.get("text") or "").strip()
                if not t:
                    continue
                b = inf.get("bounds") or {}
                cx = (int(b.get("left", 0)) + int(b.get("right", 0))) // 2
                cy = (int(b.get("top", 0)) + int(b.get("bottom", 0))) // 2
                if not (y_lo <= cy <= y_hi and x_lo <= cx <= x_hi):
                    continue
                centers.append(cy)
            except Exception:
                continue
    except Exception:
        return 0
    if len(centers) < 2:
        return len(centers)
    centers.sort()
    max_run = 1
    run = 1
    for i in range(1, len(centers)):
        dy = centers[i] - centers[i - 1]
        if 6 <= dy <= 140:
            run += 1
            max_run = max(max_run, run)
        else:
            run = 1
    return max_run


def _safe_ui_all(sel: Any) -> list[Any]:
    """UiAutomator2: ``Selector.all()`` can throw when the accessibility tree is mid-refresh."""
    try:
        if sel is not None and hasattr(sel, "all"):
            return list(sel.all())
    except Exception:
        pass
    return []


_OWN_UNIFIED_FOLLOWERS_TAB_TITLE_RE = re.compile(
    r"^\d+\s+followers$",
    re.IGNORECASE,
)
_OWN_UNIFIED_FOLLOWERS_TAB_TITLE_FR_RE = re.compile(
    r"^\d+\s+abonn",
    re.IGNORECASE,
)


def _followers_store_detect_hierarchy_xml(hierarchy_xml: str, *, xml_path: str = "") -> None:
    global _LAST_FOLLOWERS_DETECT_HIERARCHY_XML, _LAST_FOLLOWERS_DETECT_HIERARCHY_XML_PATH
    _LAST_FOLLOWERS_DETECT_HIERARCHY_XML = str(hierarchy_xml or "")
    if xml_path:
        _LAST_FOLLOWERS_DETECT_HIERARCHY_XML_PATH = str(xml_path)


def followers_clear_detect_hierarchy_cache() -> None:
    """Drop cached followers-list hierarchy (pre-scroll XML must not be reused)."""
    global _LAST_FOLLOWERS_DETECT_HIERARCHY_XML, _LAST_FOLLOWERS_DETECT_HIERARCHY_XML_PATH
    _LAST_FOLLOWERS_DETECT_HIERARCHY_XML = ""
    _LAST_FOLLOWERS_DETECT_HIERARCHY_XML_PATH = ""


def followers_refresh_detect_hierarchy_cache(
    d: u2.Device,
    *,
    screen_index: int = 0,
) -> str:
    """
    Single fresh dump_hierarchy for post-scroll baseline harvest (stores cache for XML-first path).
    """
    followers_clear_detect_hierarchy_cache()
    try:
        try:
            hier = d.dump_hierarchy(compressed=False)
        except TypeError:
            hier = d.dump_hierarchy()
        hier_text = hier if isinstance(hier, str) else str(hier or "")
    except Exception:
        return ""
    if not hier_text.strip():
        return ""
    _ensure_debug_dirs()
    xml_path = _XML_DIR / f"followers_baseline_window_screen_{int(screen_index)}.xml"
    try:
        xml_path.write_text(hier_text, encoding="utf-8")
        _bump_xml_fetch()
    except Exception:
        xml_path = _XML_DIR / "followers_baseline_window_screen.xml"
        try:
            xml_path.write_text(hier_text, encoding="utf-8")
            _bump_xml_fetch()
        except Exception:
            pass
    _followers_store_detect_hierarchy_xml(hier_text, xml_path=str(xml_path))
    return hier_text.strip()


def _followers_resolve_detect_hierarchy_xml(
    d: u2.Device,
    hierarchy_xml: str | None = None,
    *,
    live_incomplete: bool = False,
) -> str:
    hier = str(hierarchy_xml or "").strip()
    if hier:
        return hier
    if str(_LAST_FOLLOWERS_DETECT_HIERARCHY_XML or "").strip():
        return str(_LAST_FOLLOWERS_DETECT_HIERARCHY_XML).strip()
    path = str(_LAST_FOLLOWERS_DETECT_HIERARCHY_XML_PATH or "").strip()
    if path:
        try:
            return Path(path).read_text(encoding="utf-8")
        except Exception:
            pass
    if live_incomplete:
        try:
            try:
                fresh = str(d.dump_hierarchy(compressed=False))
            except TypeError:
                fresh = str(d.dump_hierarchy())
            if fresh.strip():
                return fresh.strip()
        except Exception:
            pass
    return ""


def _own_unified_followers_tab_title_matches(text: str) -> bool:
    raw = str(text or "").strip()
    if not raw:
        return False
    if _OWN_UNIFIED_FOLLOWERS_TAB_TITLE_RE.match(raw):
        return True
    if _OWN_UNIFIED_FOLLOWERS_TAB_TITLE_FR_RE.match(raw):
        return True
    low = raw.lower()
    if "follower" in low and re.match(r"^\d+", raw):
        return True
    return False


def _xml_element_selected(el: ET.Element, parent_map: dict[ET.Element, ET.Element | None]) -> bool:
    cur: ET.Element | None = el
    while cur is not None:
        if str(cur.get("selected") or "").lower() == "true":
            return True
        cur = parent_map.get(cur)
    return False


def _detect_own_unified_followers_list_from_hierarchy_xml(
    hierarchy_xml: str,
    *,
    source_profile_username: str = "",
) -> dict[str, Any]:
    """
    Own-profile unified followers list (Instagram unified_follow_list_* layout).
    Does not require action bar title 'Followers' — username title + selected tab is enough.
    """
    meta: dict[str, Any] = {
        "detected": False,
        "signals": [],
        "has_tab_layout": False,
        "selected_followers_tab_text": "",
        "follow_list_username_count": 0,
        "follow_list_container_present": False,
        "recycler_present": False,
        "listview_present": False,
        "action_bar_title": "",
        "detection_source": "hierarchy_xml",
    }
    hier = str(hierarchy_xml or "").strip()
    if not hier:
        return meta
    try:
        try:
            root = ET.fromstring(hier)
        except ET.ParseError:
            root = ET.fromstring(f"<wrap>{hier}</wrap>")
    except Exception:
        return meta
    parent_map = _followers_entry_v2_xml_hierarchy_parent_map(root)
    selected_tab = ""
    for el in root.iter():
        rid = str(el.get("resource-id") or "").lower()
        cls = str(el.get("class") or "").lower()
        if "unified_follow_list_tab_layout" in rid:
            meta["has_tab_layout"] = True
        if "follow_list_container" in rid:
            meta["follow_list_container_present"] = True
        if "follow_list_username" in rid:
            meta["follow_list_username_count"] = int(meta["follow_list_username_count"]) + 1
        if "recyclerview" in cls:
            meta["recycler_present"] = True
        if cls == "android.widget.listview" or rid.endswith(":id/list"):
            meta["listview_present"] = True
        if "action_bar_title" in rid:
            t = str(el.get("text") or el.get("content-desc") or "").strip()
            if t:
                meta["action_bar_title"] = t
        text = str(el.get("text") or "").strip()
        if text and _own_unified_followers_tab_title_matches(text):
            if _xml_element_selected(el, parent_map):
                selected_tab = text
    meta["selected_followers_tab_text"] = selected_tab
    src = _normalize_handle(str(source_profile_username or ""))
    ab = _normalize_handle(str(meta.get("action_bar_title") or ""))
    title_ok = bool(not src or not ab or ab == src)
    rows_ok = int(meta["follow_list_username_count"]) >= 1
    list_chrome_ok = bool(meta["recycler_present"] or meta["listview_present"])
    tab_ok = bool(meta["has_tab_layout"] and selected_tab)
    if tab_ok and rows_ok and title_ok:
        meta["detected"] = True
        meta["signals"] = [
            "own_unified_followers_list_detected",
            "unified_follow_list_tab_layout",
            "selected_followers_tab",
            "follow_list_username",
        ]
        if meta["follow_list_container_present"]:
            meta["signals"].append("follow_list_container")
        if list_chrome_ok:
            meta["signals"].append("list_chrome_recycler_or_listview")
    return meta


def _detect_own_unified_followers_list_live(
    d: u2.Device,
    *,
    source_profile_username: str = "",
) -> dict[str, Any]:
    meta: dict[str, Any] = {
        "detected": False,
        "signals": [],
        "has_tab_layout": False,
        "selected_followers_tab_text": "",
        "follow_list_username_count": 0,
        "follow_list_container_present": False,
        "recycler_present": False,
        "listview_present": False,
        "detection_source": "live_u2",
    }
    try:
        if d(resourceIdMatches=r".*:id/unified_follow_list_tab_layout$").exists(timeout=0.12):
            meta["has_tab_layout"] = True
    except Exception:
        pass
    try:
        if d(resourceIdMatches=r".*:id/follow_list_container$").exists(timeout=0.08):
            meta["follow_list_container_present"] = True
    except Exception:
        pass
    try:
        meta["follow_list_username_count"] = len(
            _safe_ui_all(d(resourceIdMatches=r".*:id/follow_list_username$"))
        )
    except Exception:
        pass
    try:
        meta["recycler_present"] = len(_safe_ui_all(d(classNameMatches=".*RecyclerView.*"))) > 0
    except Exception:
        pass
    try:
        meta["listview_present"] = len(_safe_ui_all(d(className="android.widget.ListView"))) > 0
    except Exception:
        pass
    try:
        for el in _safe_ui_all(d(resourceIdMatches=r".*:id/title$")):
            try:
                inf = _follow_safe_info(el)
                text = str(inf.get("text") or "").strip()
                if not _own_unified_followers_tab_title_matches(text):
                    continue
                if bool(inf.get("selected")):
                    meta["selected_followers_tab_text"] = text
                    break
            except Exception:
                continue
    except Exception:
        pass
    tab_ok = bool(meta["has_tab_layout"] and meta["selected_followers_tab_text"])
    rows_ok = int(meta["follow_list_username_count"]) >= 1
    list_chrome_ok = bool(meta["recycler_present"] or meta["listview_present"])
    if tab_ok and rows_ok and list_chrome_ok:
        meta["detected"] = True
        meta["signals"] = [
            "own_unified_followers_list_detected",
            "unified_follow_list_tab_layout",
            "selected_followers_tab",
            "follow_list_username",
        ]
    return meta


def _apply_own_unified_followers_list_to_det(
    out: dict[str, Any],
    own_meta: dict[str, Any],
) -> None:
    if not bool(own_meta.get("detected")):
        out["own_unified_followers_list_detected"] = False
        return
    out["own_unified_followers_list_detected"] = True
    out["is_followers_list"] = True
    out["open_detection_method"] = "own_unified_follow_list"
    out["relaxed_list_open"] = True
    if own_meta.get("recycler_present"):
        out["recycler_present"] = True
    if own_meta.get("listview_present"):
        out["listview_present"] = True
    if int(own_meta.get("follow_list_username_count") or 0) > 0:
        out["candidate_username_count"] = max(
            int(out.get("candidate_username_count") or 0),
            int(own_meta.get("follow_list_username_count") or 0),
        )
    sig = out.get("signals")
    if not isinstance(sig, list):
        sig = []
        out["signals"] = sig
    for s in list(own_meta.get("signals") or []):
        if s not in sig:
            sig.append(s)
    if f"own_unified:{own_meta.get('detection_source')}" not in sig:
        sig.append(f"own_unified:{own_meta.get('detection_source')}")
    tab = str(own_meta.get("selected_followers_tab_text") or "").strip()
    if tab:
        out["visible_header_texts"] = list(dict.fromkeys([tab] + list(out.get("visible_header_texts") or [])))[:20]


def _harvest_own_unified_xml_first_eligible(d: u2.Device) -> bool:
    """True when own-unified followers list should harvest from cached hierarchy XML first."""
    if str(_FOLLOWERS_LAST_OPEN_DETECTION_METHOD or "").strip() == "own_unified_follow_list":
        return True
    hier = _followers_resolve_detect_hierarchy_xml(d, None, live_incomplete=False)
    return bool(hier.strip()) and "follow_list_username" in hier


def _parse_follow_list_xml_bounds(el: Any) -> dict[str, int]:
    bounds_raw = str(el.get("bounds") or "").strip()
    if not bounds_raw:
        return {}
    m = re.match(r"\[(\d+),(\d+)\]\[(\d+),(\d+)\]", bounds_raw)
    if not m:
        return {}
    return {
        "left": int(m.group(1)),
        "top": int(m.group(2)),
        "right": int(m.group(3)),
        "bottom": int(m.group(4)),
    }


def _normalize_own_unified_row_cta_xml_text(raw: str) -> tuple[str, str]:
    """Map follow_list_row_large_follow_button text to row_cta_class + display label."""
    t = str(raw or "").strip()
    if not t:
        return "unknown", ""
    low = t.lower()
    if low in ("follow", "suivre"):
        return "follow", t
    if low in ("follow back", "suivre en retour", "follow back "):
        return "follow_back", t
    if "follow back" in low or "suivre en retour" in low:
        return "follow_back", t
    if low in ("message", "envoyer un message"):
        return "message", t
    if low in ("following", "suivi(e)", "abonné"):
        return "following", t
    if low in ("requested", "demandé"):
        return "requested", t
    if low in ("contact", "contacts"):
        return "contact", t
    return "unknown", t


def _extract_own_unified_followers_usernames_from_hierarchy_xml(
    hierarchy_xml: str,
    *,
    source_profile_username: str = "",
    runtime_seen: set[str] | None = None,
) -> list[dict[str, Any]]:
    """
    Parse visible handles from own-profile unified followers list hierarchy XML.
    Per-row: username + follow_list_row_large_follow_button CTA text/bounds.
    """
    seen = runtime_seen if runtime_seen is not None else set()
    source_key = _normalize_handle(source_profile_username or "")
    hier = str(hierarchy_xml or "").strip()
    if not hier:
        return []
    try:
        try:
            root = ET.fromstring(hier)
        except ET.ParseError:
            root = ET.fromstring(f"<wrap>{hier}</wrap>")
    except Exception:
        return []

    by_user: dict[str, dict[str, Any]] = {}
    doc_order = 0
    for el in root.iter():
        rid = str(el.get("resource-id") or "")
        if "follow_list_container" not in rid:
            continue
        username_raw = ""
        username_bounds: dict[str, int] = {}
        username_rid = ""
        cta_xml_text = ""
        cta_xml_rid = ""
        cta_xml_bounds: dict[str, int] = {}
        row_bounds = _parse_follow_list_xml_bounds(el)
        for sub in el.iter():
            sr = str(sub.get("resource-id") or "")
            if "follow_list_username" in sr:
                cand = str(sub.get("text") or "").strip().lstrip("@")
                if cand and _FOLLOWERS_HANDLE_RE.match(cand):
                    username_raw = cand
                    username_bounds = _parse_follow_list_xml_bounds(sub)
                    username_rid = sr
            elif "follow_list_row_large_follow_button" in sr:
                cta_xml_text = str(sub.get("text") or "").strip()
                cta_xml_rid = sr
                cta_xml_bounds = _parse_follow_list_xml_bounds(sub)
        if not username_raw:
            continue
        key = _normalize_handle(username_raw)
        if not key or key == source_key or key in by_user:
            continue
        bounds = username_bounds if username_bounds else row_bounds
        c = _followers_bounds_center(bounds) if bounds else None
        row_y = int(c[1]) if c else doc_order * 100
        cta_cls, cta_disp = _normalize_own_unified_row_cta_xml_text(cta_xml_text)
        by_user[key] = {
            "username": username_raw,
            "bounds": bounds,
            "row_bounds": row_bounds,
            "row_center": [int(c[0]) if c else 0, row_y],
            "already_seen_runtime": key in seen,
            "resource_id": username_rid,
            "extraction_source": "own_unified_follow_list_username_xml",
            "row_cta_xml_text": cta_xml_text,
            "row_cta_xml_resource_id": cta_xml_rid,
            "row_cta_xml_bounds": cta_xml_bounds,
            "row_cta_xml_class": cta_cls,
        }
        doc_order += 1

    rows = sorted(by_user.values(), key=lambda r: (r["row_center"][1], r["username"]))
    for r in rows:
        log(
            "info",
            "followers_candidate_seen",
            username=r["username"],
            source_profile_username=source_profile_username,
            already_seen_runtime=bool(r["already_seen_runtime"]),
            resource_id=r.get("resource_id"),
            extraction_source="own_unified_follow_list_username_xml",
            row_cta_xml_text=str(r.get("row_cta_xml_text") or "")[:80],
            row_cta_xml_class=str(r.get("row_cta_xml_class") or "")[:40],
        )
    return rows


def harvest_follow_list_row_cta_from_hierarchy_xml(
    hierarchy_xml: str,
    *,
    source_profile_username: str = "",
) -> list[dict[str, Any]]:
    """
    Follow-flow only: visible followers list rows with username + CTA from XML.
    Does not replace ``_extract_own_unified_followers_usernames_from_hierarchy_xml`` (Welcome/DM).
    """
    from visual_row_mapping import normalize_own_unified_row_cta_xml_text

    source_key = _normalize_handle(source_profile_username or "")
    hier = str(hierarchy_xml or "").strip()
    if not hier:
        return []
    try:
        try:
            root = ET.fromstring(hier)
        except ET.ParseError:
            root = ET.fromstring(f"<wrap>{hier}</wrap>")
    except Exception:
        return []

    by_user: dict[str, dict[str, Any]] = {}

    def _bounds_from_elem(el: Any) -> dict[str, int]:
        bd = _dm_parse_bounds_attr_xml(str(el.get("bounds") or ""))
        return dict(bd) if bd else {}

    for el in root.iter():
        rid = str(el.get("resource-id") or "")
        if "follow_list_container" not in rid:
            continue
        username_raw = ""
        username_bounds: dict[str, int] = {}
        cta_xml_text = ""
        cta_xml_bounds: dict[str, int] = {}
        row_bounds = _bounds_from_elem(el)
        for sub in el.iter():
            sr = str(sub.get("resource-id") or "")
            if "follow_list_username" in sr:
                cand = str(sub.get("text") or "").strip().lstrip("@")
                if cand and _FOLLOWERS_HANDLE_RE.match(cand):
                    username_raw = cand
                    username_bounds = _bounds_from_elem(sub)
            elif "follow_list_row_large_follow_button" in sr:
                cta_xml_text = str(sub.get("text") or "").strip()
                cta_xml_bounds = _bounds_from_elem(sub)
        if not username_raw:
            continue
        key = _normalize_handle(username_raw)
        if not key or key == source_key or key in by_user:
            continue
        bounds = username_bounds if username_bounds else row_bounds
        cta_cls, cta_disp = normalize_own_unified_row_cta_xml_text(cta_xml_text)
        band_top = bounds.get("top", row_bounds.get("top", 0))
        band_bot = bounds.get("bottom", row_bounds.get("bottom", 0))
        if cta_xml_bounds:
            band_top = min(int(band_top), int(cta_xml_bounds.get("top", band_top)))
            band_bot = max(int(band_bot), int(cta_xml_bounds.get("bottom", band_bot)))
        row_band = {
            "left": int(bounds.get("left", 0)),
            "top": int(band_top),
            "right": int(bounds.get("right", 0)),
            "bottom": int(band_bot),
        }
        by_user[key] = {
            "username": username_raw,
            "bounds": bounds,
            "row_bounds": row_band,
            "row_cta_xml_text": cta_xml_text,
            "row_cta_xml_bounds": cta_xml_bounds,
            "row_cta_xml_class": cta_cls,
            "row_cta_xml_display": cta_disp,
        }

    if not by_user:
        cta_nodes: list[tuple[int, int, int, str]] = []
        user_nodes: list[tuple[str, dict[str, int]]] = []
        for el in root.iter():
            sr = str(el.get("resource-id") or "")
            bd = _bounds_from_elem(el)
            if not bd:
                continue
            cy = (int(bd["top"]) + int(bd["bottom"])) // 2
            if "follow_list_row_large_follow_button" in sr:
                cta_nodes.append((cy, int(bd["top"]), int(bd["bottom"]), str(el.get("text") or "").strip()))
            elif "follow_list_username" in sr:
                cand = str(el.get("text") or "").strip().lstrip("@")
                if cand and _FOLLOWERS_HANDLE_RE.match(cand):
                    user_nodes.append((cand, bd))
        for username_raw, ub in user_nodes:
            key = _normalize_handle(username_raw)
            if not key or key == source_key or key in by_user:
                continue
            ucy = (int(ub["top"]) + int(ub["bottom"])) // 2
            best_cta: tuple[int, int, int, str] | None = None
            best_dy = 10**9
            for ccy, ct, cb, ctxt in cta_nodes:
                if ccy < int(ub["top"]) - 80 or ccy > int(ub["bottom"]) + 80:
                    continue
                dy = abs(ccy - ucy)
                if dy < best_dy:
                    best_dy = dy
                    best_cta = (ccy, ct, cb, ctxt)
            cta_xml_text = best_cta[3] if best_cta else ""
            cta_xml_bounds = (
                {"top": best_cta[1], "bottom": best_cta[2], "left": ub.get("left", 0), "right": ub.get("right", 0)}
                if best_cta
                else {}
            )
            cta_cls, cta_disp = normalize_own_unified_row_cta_xml_text(cta_xml_text)
            band_bot = max(int(ub["bottom"]), int(cta_xml_bounds.get("bottom", ub["bottom"])))
            band_top = min(int(ub["top"]), int(cta_xml_bounds.get("top", ub["top"])))
            by_user[key] = {
                "username": username_raw,
                "bounds": dict(ub),
                "row_bounds": {
                    "left": int(ub.get("left", 0)),
                    "top": int(band_top),
                    "right": int(ub.get("right", 0)),
                    "bottom": int(band_bot),
                },
                "row_cta_xml_text": cta_xml_text,
                "row_cta_xml_bounds": cta_xml_bounds,
                "row_cta_xml_class": cta_cls,
                "row_cta_xml_display": cta_disp,
            }

    return sorted(by_user.values(), key=lambda r: int((r.get("row_bounds") or {}).get("top", 0)))


def harvest_follow_list_row_cta_for_follow_flow(
    d: u2.Device,
    *,
    source_profile_username: str = "",
) -> list[dict[str, Any]]:
    """
    Follow engine only: read cached followers-list hierarchy (one live dump if cache lacks CTA nodes).
    """
    from visual_row_mapping import is_row_cta_xml_reject_class

    hier = _followers_resolve_detect_hierarchy_xml(d, None, live_incomplete=False)
    hierarchy_source = "cached"
    if not hier or "follow_list_row_large_follow_button" not in hier:
        try:
            try:
                live = d.dump_hierarchy(compressed=False)
            except TypeError:
                live = d.dump_hierarchy()
            live_text = live if isinstance(live, str) else str(live or "")
        except Exception:
            live_text = ""
        if live_text.strip():
            hier = live_text.strip()
            hierarchy_source = "live_dump_follow_cta_gate"
    rows: list[dict[str, Any]] = []
    if hier and "follow_list_username" in hier:
        rows = harvest_follow_list_row_cta_from_hierarchy_xml(
            hier,
            source_profile_username=source_profile_username,
        )
    reject_count = sum(
        1 for r in rows if is_row_cta_xml_reject_class(str(r.get("row_cta_xml_class") or ""))
    )
    try:
        log(
            "info",
            "followers_xml_cta_harvest_done",
            rows_count=len(rows),
            reject_count=int(reject_count),
            source_profile_username=str(source_profile_username or "")[:120],
            hierarchy_source=str(hierarchy_source),
            hierarchy_len=len(hier or ""),
        )
    except Exception:
        pass
    return rows


def detect_followers_list_screen(
    d: u2.Device,
    *,
    source_profile_username: str = "",
    hierarchy_xml: str | None = None,
) -> dict[str, Any]:
    """
    Heuristic followers list: strict title + list chrome, OR relaxed list/content signals
    (RecyclerView / scrollable / usernames / stacked rows) without requiring Followers title.
    """
    try:
        from followers_inter_candidate_perf import inter_candidate_count_detect_followers_list

        inter_candidate_count_detect_followers_list()
    except Exception:
        pass
    pkg = str(getattr(config, "INSTAGRAM_PACKAGE", "") or "com.instagram.android")
    cur_pkg: str | None = None
    cur_act: str | None = None
    try:
        cur = d.app_current() or {}
        cur_pkg = cur.get("package")
        cur_act = cur.get("activity")
    except Exception as e:
        log(
            "warning",
            "followers_list_detect_probe_failed",
            phase="app_current",
            exception_type=type(e).__name__,
            exception_message=str(e)[:800],
            source_profile_username=str(source_profile_username or "")[:160],
        )

    out: dict[str, Any] = {
        "is_followers_list": False,
        "title_match": False,
        "action_bar_title": "",
        "recycler_present": False,
        "listview_present": False,
        "scrollable_present": False,
        "scrollable_count": 0,
        "profile_tabs_absent": False,
        "visible_usernames_sample": [],
        "signals": [],
        "visible_header_texts": [],
        "candidate_username_count": 0,
        "stacked_central_textview_run": 0,
        "relaxed_rules_matched": [],
        "strict_list_open": False,
        "relaxed_list_open": False,
        "own_unified_followers_list_detected": False,
        "current_package": cur_pkg,
        "current_activity": cur_act,
        "current_screen_guess": "unknown",
    }
    def _probe_fail(phase: str, exc: BaseException) -> None:
        log(
            "warning",
            "followers_list_detect_probe_failed",
            phase=phase,
            exception_type=type(exc).__name__,
            exception_message=str(exc)[:800],
            source_profile_username=str(source_profile_username or "")[:160],
        )

    try:
        try:
            w, h = d.window_size()
        except Exception as e:
            _probe_fail("window_size", e)
            w, h = 1080, 1920

        try:
            out["current_screen_guess"] = _guess_profile_screen(d, pkg, source_profile_username)
        except Exception as e:
            _probe_fail("guess_profile_screen", e)

        try:
            ab = d(resourceIdMatches=r".*:id/action_bar_title.*")
            if ab.exists(timeout=0.12):
                try:
                    out["action_bar_title"] = str(ab.get_text() or "").strip()
                except Exception as e:
                    _probe_fail("action_bar_get_text", e)
        except Exception as e:
            _probe_fail("action_bar_title_probe", e)
        if not str(out.get("action_bar_title") or "").strip():
            try:
                ab_large = d(resourceIdMatches=r".*:id/action_bar_large_title_auto_size$")
                if ab_large.exists(timeout=0.12):
                    try:
                        large_title = str(ab_large.get_text() or "").strip()
                        if large_title:
                            out["action_bar_title"] = large_title
                            out["signals"].append("action_bar_large_title_auto_size")
                            log(
                                "info",
                                "followers_entry_profile_action_bar_large_title_resolved",
                                title=large_title[:120],
                            )
                    except Exception as e:
                        _probe_fail("action_bar_large_title_get_text", e)
            except Exception as e:
                _probe_fail("action_bar_large_title_probe", e)

        # Toolbar / top strip texts for diagnostics
        try:
            y_hdr = int(h * 0.14)
            hdr_texts: list[str] = []
            for el in _safe_ui_all(d(className="android.widget.TextView")):
                try:
                    inf = el.info
                    b = inf.get("bounds") or {}
                    if int(b.get("bottom", 0)) > y_hdr:
                        continue
                    t = (inf.get("text") or "").strip()
                    if t and t not in hdr_texts:
                        hdr_texts.append(t)
                except Exception:
                    continue
            out["visible_header_texts"] = hdr_texts[:20]
        except Exception as e:
            _probe_fail("visible_header_texts", e)

        title_ok = False
        for t in _FOLLOWERS_TITLE_TEXTS:
            try:
                if d(text=t).exists(timeout=0.06):
                    title_ok = True
                    out["signals"].append(f"title_text:{t}")
                    break
            except Exception as e:
                _probe_fail(f"followers_title_exists:{t}", e)
                continue
        if not title_ok and out["action_bar_title"]:
            ab_l = out["action_bar_title"].strip().lower()
            for cand in _FOLLOWERS_TITLE_TEXTS:
                if ab_l == cand.lower():
                    title_ok = True
                    out["signals"].append("title_action_bar")
                    break
            if not title_ok:
                if any(sub in ab_l for sub in _FOLLOWERS_TITLE_SUBSTRINGS):
                    title_ok = True
                    out["signals"].append("title_action_bar_substring")
        out["title_match"] = title_ok

        try:
            rvs = _safe_ui_all(d(classNameMatches=".*RecyclerView.*"))
            out["recycler_present"] = len(rvs) > 0
            if out["recycler_present"]:
                out["signals"].append(f"recyclerview_count:{len(rvs)}")
        except Exception as e:
            _probe_fail("recyclerview_probe", e)

        try:
            lvs = _safe_ui_all(d(className="android.widget.ListView"))
            out["listview_present"] = len(lvs) > 0
            if out["listview_present"]:
                out["signals"].append(f"listview_count:{len(lvs)}")
        except Exception as e:
            _probe_fail("listview_probe", e)

        try:
            sc = _safe_ui_all(d(scrollable=True))
            out["scrollable_count"] = len(sc)
            out["scrollable_present"] = len(sc) > 0
            if out["scrollable_present"]:
                out["signals"].append(f"scrollable_count:{len(sc)}")
        except Exception as e:
            _probe_fail("scrollable_probe", e)

        list_chrome = bool(
            out["recycler_present"] or out["listview_present"] or out["scrollable_present"]
        )

        try:
            out["profile_tabs_absent"] = not _followers_profile_tabs_visible(d)
        except Exception as e:
            _probe_fail("profile_tabs_visible", e)
            out["profile_tabs_absent"] = False

        sample: list[str] = []
        handle_keys: set[str] = set()
        try:
            y_min = int(h * 0.08)
            src_key = _normalize_handle(source_profile_username or "")
            for el in _safe_ui_all(d(className="android.widget.TextView")):
                try:
                    inf = el.info
                    raw_t = (inf.get("text") or "").strip().lstrip("@")
                    if not _looks_like_instagram_username(raw_t):
                        continue
                    b = inf.get("bounds") or {}
                    cy = (int(b.get("top", 0)) + int(b.get("bottom", 0))) // 2
                    if cy < y_min or cy > int(h * 0.96):
                        continue
                    hk = _normalize_handle(raw_t)
                    if hk == src_key:
                        continue
                    handle_keys.add(hk)
                    if len(sample) < 12:
                        sample.append(raw_t)
                except Exception:
                    continue
        except Exception as e:
            _probe_fail("visible_username_handles_sample", e)
        out["visible_usernames_sample"] = sample
        out["candidate_username_count"] = len(handle_keys)

        stacked_run = 0
        try:
            stacked_run = _followers_stacked_central_textview_run(d, w, h)
        except Exception as e:
            _probe_fail("stacked_central_textview_run", e)
            stacked_run = 0
        out["stacked_central_textview_run"] = stacked_run

        # --- Relaxed OR conditions (no Followers title required) ---
        cond_a = list_chrome and out["candidate_username_count"] >= 3
        cond_b = len(sample) >= 2
        cond_c = bool(out["scrollable_present"] and stacked_run >= 5)
        ab_norm = _normalize_handle(out["action_bar_title"] or "")
        src_norm = _normalize_handle(source_profile_username or "")
        cond_d = bool(
            src_norm
            and ab_norm == src_norm
            and out["scrollable_present"]
            and (out["candidate_username_count"] >= 1 or len(sample) >= 1)
        )
        handles_visible_ok = bool(
            out["candidate_username_count"] >= 1 or len(sample) >= 1
        )
        cond_e = bool(
            out["profile_tabs_absent"]
            and list_chrome
            and handles_visible_ok
        )

        relaxed_reasons: list[str] = []
        if cond_a:
            relaxed_reasons.append("A_recycler_or_scrollable_and_3plus_handles")
            log(
                "info",
                "followers_list_detect_recycler_match",
                action_bar_title=out["action_bar_title"],
                recycler_present=out["recycler_present"],
                listview_present=out.get("listview_present"),
                scrollable_present=out["scrollable_present"],
                scrollable_count=out["scrollable_count"],
                candidate_username_count=out["candidate_username_count"],
                visible_usernames_sample=out["visible_usernames_sample"],
                visible_header_texts=out["visible_header_texts"],
                current_activity=out["current_activity"],
                current_package=out["current_package"],
                current_screen_guess=out["current_screen_guess"],
            )
        if cond_b:
            relaxed_reasons.append("B_multi_plausible_username_sample")
            log(
                "info",
                "followers_list_detect_username_match",
                action_bar_title=out["action_bar_title"],
                recycler_present=out["recycler_present"],
                listview_present=out.get("listview_present"),
                scrollable_present=out["scrollable_present"],
                scrollable_count=out["scrollable_count"],
                candidate_username_count=out["candidate_username_count"],
                visible_usernames_sample=out["visible_usernames_sample"],
                visible_header_texts=out["visible_header_texts"],
                current_activity=out["current_activity"],
                current_package=out["current_package"],
                current_screen_guess=out["current_screen_guess"],
            )
        if cond_c:
            relaxed_reasons.append("C_scrollable_and_stacked_central_textviews")
            log(
                "info",
                "followers_list_detect_scrollable_match",
                action_bar_title=out["action_bar_title"],
                recycler_present=out["recycler_present"],
                listview_present=out.get("listview_present"),
                scrollable_present=out["scrollable_present"],
                scrollable_count=out["scrollable_count"],
                stacked_central_textview_run=stacked_run,
                candidate_username_count=out["candidate_username_count"],
                visible_usernames_sample=out["visible_usernames_sample"],
                visible_header_texts=out["visible_header_texts"],
                current_activity=out["current_activity"],
                current_package=out["current_package"],
                current_screen_guess=out["current_screen_guess"],
            )
        if cond_d:
            relaxed_reasons.append("D_action_bar_is_source_profile_with_list")
            log(
                "info",
                "followers_list_detect_relaxed_match",
                reason="D_title_equals_source_profile",
                action_bar_title=out["action_bar_title"],
                source_profile_username=source_profile_username,
                recycler_present=out["recycler_present"],
                listview_present=out.get("listview_present"),
                scrollable_present=out["scrollable_present"],
                scrollable_count=out["scrollable_count"],
                candidate_username_count=out["candidate_username_count"],
                visible_usernames_sample=out["visible_usernames_sample"],
                visible_header_texts=out["visible_header_texts"],
                current_activity=out["current_activity"],
                current_package=out["current_package"],
                current_screen_guess=out["current_screen_guess"],
            )
        if cond_e:
            relaxed_reasons.append(
                "E_profile_tabs_absent_with_list_chrome_and_plausible_handles"
            )
            log(
                "info",
                "followers_list_detect_profile_tabs_absent_match",
                profile_tabs_absent=out["profile_tabs_absent"],
                action_bar_title=out["action_bar_title"],
                source_profile_username=source_profile_username,
                recycler_present=out["recycler_present"],
                listview_present=out.get("listview_present"),
                scrollable_present=out["scrollable_present"],
                scrollable_count=out["scrollable_count"],
                candidate_username_count=out["candidate_username_count"],
                visible_usernames_sample=out["visible_usernames_sample"],
                visible_header_texts=out["visible_header_texts"],
                current_activity=out["current_activity"],
                current_package=out["current_package"],
                current_screen_guess=out["current_screen_guess"],
            )

        relaxed_hit = cond_a or cond_b or cond_c or cond_d or cond_e
        out["relaxed_rules_matched"] = relaxed_reasons
        out["relaxed_list_open"] = relaxed_hit

        strict_hit = bool(title_ok and list_chrome)
        out["strict_list_open"] = strict_hit

        live_incomplete = bool(
            not list_chrome
            or int(out.get("candidate_username_count") or 0) == 0
        )
        hier_for_own = _followers_resolve_detect_hierarchy_xml(
            d,
            hierarchy_xml,
            live_incomplete=live_incomplete,
        )
        own_meta: dict[str, Any] = {"detected": False}
        if hier_for_own:
            own_meta = _detect_own_unified_followers_list_from_hierarchy_xml(
                hier_for_own,
                source_profile_username=source_profile_username,
            )
            if not bool(own_meta.get("detected")):
                own_live = _detect_own_unified_followers_list_live(
                    d,
                    source_profile_username=source_profile_username,
                )
                if bool(own_live.get("detected")):
                    own_meta = own_live
        else:
            own_live = _detect_own_unified_followers_list_live(
                d,
                source_profile_username=source_profile_username,
            )
            if bool(own_live.get("detected")):
                own_meta = own_live

        out["is_followers_list"] = bool(relaxed_hit or strict_hit)
        if out["is_followers_list"]:
            out["open_detection_method"] = "xml"
            if relaxed_hit:
                out["signals"].append(f"relaxed:{','.join(relaxed_reasons)}")
            if strict_hit:
                out["signals"].append("strict:title_and_list_chrome")
        else:
            out["open_detection_method"] = None

        if bool(own_meta.get("detected")):
            _apply_own_unified_followers_list_to_det(out, own_meta)
            try:
                log(
                    "info",
                    "followers_list_own_unified_detected",
                    source_profile_username=source_profile_username or "",
                    detection_source=str(own_meta.get("detection_source") or ""),
                    selected_followers_tab_text=str(
                        own_meta.get("selected_followers_tab_text") or ""
                    )[:80],
                    follow_list_username_count=int(
                        own_meta.get("follow_list_username_count") or 0
                    ),
                    has_tab_layout=bool(own_meta.get("has_tab_layout")),
                )
            except Exception:
                pass

        try:
            log(
                "info",
                "followers_list_detect_debug",
                is_followers_list=out["is_followers_list"],
                title_match=out["title_match"],
                strict_list_open=out["strict_list_open"],
                relaxed_list_open=out["relaxed_list_open"],
                relaxed_rules_matched=out["relaxed_rules_matched"],
                own_unified_followers_list_detected=bool(
                    out.get("own_unified_followers_list_detected")
                ),
                open_detection_method=out.get("open_detection_method"),
                action_bar_title=out["action_bar_title"],
                recycler_present=out["recycler_present"],
                listview_present=out["listview_present"],
                scrollable_present=out["scrollable_present"],
                scrollable_count=out["scrollable_count"],
                candidate_username_count=out["candidate_username_count"],
                visible_usernames_sample=out["visible_usernames_sample"],
                visible_header_texts=out["visible_header_texts"],
                stacked_central_textview_run=out["stacked_central_textview_run"],
                profile_tabs_absent=out.get("profile_tabs_absent"),
                current_activity=out["current_activity"],
                current_package=out["current_package"],
                current_screen_guess=out["current_screen_guess"],
            )
        except Exception as e:
            _probe_fail("followers_list_detect_debug_log", e)
        return out
    except Exception as _fatal_det:
        _probe_fail("detect_followers_list_screen_fatal", _fatal_det)
        sig = out.get("signals")
        if not isinstance(sig, list):
            out["signals"] = ["detect_followers_list_aborted_safe"]
        else:
            sig.append("detect_followers_list_aborted_safe")
        out["is_followers_list"] = False
        out["strict_list_open"] = False
        out["relaxed_list_open"] = False
        out["relaxed_rules_matched"] = []
        out["open_detection_method"] = None
        return out


def _ig_follow_button_blue_pixel(r: int, g: int, b: int) -> bool:
    """Heuristic: Instagram Follow pill blues (no OCR)."""
    if b < 105:
        return False
    if r < 120 and b > r + 40 and b >= g - 20:
        return True
    if r < 160 and b > r + 35 and b > g + 8:
        return True
    return False


def _visual_downscale_rgb(im: Any, max_w: int = 400) -> Any:
    from PIL import Image

    w, h = im.size
    if w <= max_w:
        return im.convert("RGB")
    nh = max(1, int(h * max_w / w))
    return im.convert("RGB").resize((max_w, nh), Image.Resampling.BILINEAR)


def _visual_count_right_column_blue_bands(im_rgb: Any) -> int:
    """Repeated blue regions on the right edge (Follow buttons column)."""
    w, h = im_rgb.size
    x0 = int(w * 0.70)
    x1 = w - 1
    y0 = int(h * 0.085)
    y1 = int(h * 0.90)
    if x1 <= x0 or y1 <= y0:
        return 0
    roi = im_rgb.crop((x0, y0, x1 + 1, y1 + 1))
    wroi, hroi = roi.size
    flat = list(roi.getdata())
    row_scores: list[float] = []
    for yy in range(hroi):
        blue_n = 0
        off = yy * wroi
        for xx in range(wroi):
            r, g, b = flat[off + xx]
            if _ig_follow_button_blue_pixel(int(r), int(g), int(b)):
                blue_n += 1
        row_scores.append(blue_n / max(wroi, 1))
    smoothed: list[float] = []
    for i in range(len(row_scores)):
        a = row_scores[max(0, i - 1)] + row_scores[i] + row_scores[min(len(row_scores) - 1, i + 1)]
        smoothed.append(a / 3.0)
    thr = 0.028
    bands = 0
    i = 0
    while i < len(smoothed):
        if smoothed[i] >= thr:
            start = i
            while i < len(smoothed) and smoothed[i] >= thr * 0.55:
                i += 1
            height = i - start
            if 2 <= height <= max(90, hroi // 6):
                bands += 1
        else:
            i += 1
    return bands


def _visual_detect_search_strip(im_rgb: Any) -> bool:
    w, h = im_rgb.size
    x0, x1 = int(w * 0.08), int(w * 0.92)
    y0, y1 = int(h * 0.045), int(h * 0.135)
    roi = im_rgb.crop((x0, y0, x1 + 1, y1 + 1))
    flat_bright = 0
    n = 0
    for r, g, b in roi.getdata():
        n += 1
        lum = (int(r) + int(g) + int(b)) / 3
        spread = max(int(r), int(g), int(b)) - min(int(r), int(g), int(b))
        if lum > 200 and spread < 45:
            flat_bright += 1
    return n > 0 and (flat_bright / n) > 0.16


def _visual_count_left_column_row_bands(im_rgb: Any) -> int:
    """Avatar / row structure: elevated luminance variance in left strip by band."""
    w, h = im_rgb.size
    x0, x1 = int(w * 0.03), int(w * 0.24)
    y0, y1 = int(h * 0.12), int(h * 0.88)
    roi = im_rgb.crop((x0, y0, x1 + 1, y1 + 1))
    wroi, hroi = roi.size
    px = list(roi.getdata())
    band_h = max(12, hroi // 22)
    bands = 0
    yy = 0
    while yy + band_h <= hroi:
        lums: list[float] = []
        for row in range(yy, yy + band_h):
            off = row * wroi
            for xx in range(wroi):
                r, g, b = px[off + xx]
                lums.append((int(r) + int(g) + int(b)) / 3)
        if lums:
            mu = sum(lums) / len(lums)
            var = sum((x - mu) ** 2 for x in lums) / len(lums)
            if var > 380:
                bands += 1
        yy += band_h
    return bands


def _visual_header_dark_text_hint(im_rgb: Any) -> bool:
    w, h = im_rgb.size
    x0, x1 = int(w * 0.10), int(w * 0.90)
    y0, y1 = int(h * 0.055), int(h * 0.12)
    roi = im_rgb.crop((x0, y0, x1 + 1, y1 + 1))
    dark = 0
    px = list(roi.getdata())
    n = len(px)
    for r, g, b in px:
        if (int(r) + int(g) + int(b)) / 3 < 100:
            dark += 1
    return n > 0 and (dark / n) > 0.010


def _visual_bottom_strip_tabs_heuristic(im_rgb: Any, follow_bands: int) -> bool:
    """
    True when bottom strip looks unlike a 3-icon profile tab bar (very rough).
    """
    if follow_bands >= 4:
        return True
    w, h = im_rgb.size
    x0, x1 = int(w * 0.06), int(w * 0.94)
    y0, y1 = int(h * 0.78), int(h * 0.97)
    roi = im_rgb.crop((x0, y0, x1 + 1, y1 + 1))
    lums = [(int(r) + int(g) + int(b)) / 3 for r, g, b in roi.getdata()]
    if not lums:
        return False
    mu = sum(lums) / len(lums)
    var = sum((x - mu) ** 2 for x in lums) / len(lums)
    return var < 2200 or mu > 245


def _visual_collect_follow_row_y_spans(im_rgb: Any) -> list[tuple[int, int, float]]:
    """Vertical spans in image Y where right-column blue (Follow) density peaks."""
    w, h = im_rgb.size
    x0 = int(w * 0.68)
    x1 = w - 1
    # Include rows just below header/search; avoid missing the first Follow pill.
    y0 = int(h * 0.085)
    y1 = int(h * 0.90)
    if x1 <= x0 or y1 <= y0:
        return []
    roi = im_rgb.crop((x0, y0, x1 + 1, y1 + 1))
    wroi, hroi = roi.size
    flat = list(roi.getdata())
    row_scores: list[float] = []
    for yy in range(hroi):
        blue_n = 0
        off = yy * wroi
        for xx in range(wroi):
            r, g, b = flat[off + xx]
            if _ig_follow_button_blue_pixel(int(r), int(g), int(b)):
                blue_n += 1
        row_scores.append(blue_n / max(wroi, 1))
    smoothed: list[float] = []
    for i in range(len(row_scores)):
        a = row_scores[max(0, i - 1)] + row_scores[i] + row_scores[min(len(row_scores) - 1, i + 1)]
        smoothed.append(a / 3.0)
    thr = 0.028
    spans: list[tuple[int, int, float]] = []
    i = 0
    while i < len(smoothed):
        if smoothed[i] >= thr:
            start = i
            peak = smoothed[i]
            while i < len(smoothed) and smoothed[i] >= thr * 0.55:
                peak = max(peak, smoothed[i])
                i += 1
            height = i - start
            if 2 <= height <= max(100, hroi // 5):
                yt = y0 + start
                yb = y0 + i - 1
                spans.append((yt, yb, float(peak)))
        else:
            i += 1
    return spans


def _visual_tight_blue_bounds(
    im_rgb: Any,
    *,
    left: int,
    top: int,
    right: int,
    bottom: int,
) -> dict[str, int] | None:
    if right <= left or bottom <= top:
        return None
    crop = im_rgb.crop((left, top, right + 1, bottom + 1))
    cw, ch = crop.size
    flat = list(crop.getdata())
    minx, miny, maxx, maxy = 10**9, 10**9, -1, -1
    for yy in range(ch):
        off = yy * cw
        for xx in range(cw):
            r, g, b = flat[off + xx]
            if _ig_follow_button_blue_pixel(int(r), int(g), int(b)):
                if xx < minx:
                    minx = xx
                if yy < miny:
                    miny = yy
                if xx > maxx:
                    maxx = xx
                if yy > maxy:
                    maxy = yy
    if maxx < 0:
        return None
    return {
        "left": left + minx,
        "top": top + miny,
        "right": left + maxx + 1,
        "bottom": top + maxy + 1,
    }


def _visual_row_left_content_variance(
    im_rgb: Any, row_top: int, row_bottom: int
) -> float:
    w, h = im_rgb.size
    xl, xr = int(w * 0.03), int(w * 0.24)
    yt = max(0, row_top)
    yb = min(h - 1, row_bottom)
    if yb <= yt or xr <= xl:
        return 0.0
    roi = im_rgb.crop((xl, yt, xr + 1, yb + 1))
    lums: list[float] = []
    for r, g, b in roi.getdata():
        lums.append((int(r) + int(g) + int(b)) / 3)
    if not lums:
        return 0.0
    mu = sum(lums) / len(lums)
    return sum((x - mu) ** 2 for x in lums) / len(lums)


def _scale_bounds_to_original(
    bd: dict[str, int], *, aw: int, ah: int, orig_w: int, orig_h: int
) -> dict[str, int]:
    sx = orig_w / max(aw, 1)
    sy = orig_h / max(ah, 1)
    return {
        "left": int(bd["left"] * sx),
        "top": int(bd["top"] * sy),
        "right": int(bd["right"] * sx),
        "bottom": int(bd["bottom"] * sy),
    }


def followers_visual_candidate_diagnostic(
    d: u2.Device,
    *,
    screenshot_path: str | None = None,
    source_profile_username: str | None = None,
) -> dict[str, Any]:
    """
    Read-only: infer follower list row layout (avatar / text / Follow) from screenshot pixels.
    No UiAutomator queries beyond optional path; no tap, scroll, or follow.
    """
    out: dict[str, Any] = {
        "visual_candidate_rows": [],
        "visual_candidate_count": 0,
        "visual_follow_button_count": 0,
        "visual_confidence": 0.0,
        "screenshot_path": "",
        "source_profile_username": source_profile_username or "",
        "diagnostic_error": None,
    }
    path = screenshot_path
    if not path:
        out["diagnostic_error"] = "no_screenshot_path"
        return out
    out["screenshot_path"] = path
    try:
        from PIL import Image

        im_orig = Image.open(path)
        orig_w, orig_h = im_orig.size
        im_rgb = _visual_downscale_rgb(im_orig, max_w=480)
    except Exception as e:
        out["diagnostic_error"] = f"pil_failed:{e}"
        return out

    aw, ah = im_rgb.size
    log(
        "info",
        "followers_visual_candidate_diagnostic_started",
        screenshot_path=path,
        source_profile_username=source_profile_username,
        analysis_size=(aw, ah),
        original_size=(orig_w, orig_h),
    )

    spans = _visual_collect_follow_row_y_spans(im_rgb)
    out["visual_follow_button_count"] = len(spans)
    rows_out: list[dict[str, Any]] = []
    confidences: list[float] = []

    w, h = aw, ah
    for idx, (yt, yb, peak) in enumerate(spans):
        pad = max(4, (yb - yt + 1) // 3)
        row_top = max(int(h * 0.10), yt - pad)
        row_bottom = min(int(h * 0.93), yb + pad)
        approx_row_bounds = {
            "left": int(w * 0.02),
            "top": row_top,
            "right": int(w * 0.98),
            "bottom": row_bottom,
        }
        approx_avatar_bounds = {
            "left": int(w * 0.03),
            "top": row_top,
            "right": int(w * 0.20),
            "bottom": row_bottom,
        }
        approx_text_area_bounds = {
            "left": int(w * 0.20),
            "top": row_top,
            "right": int(w * 0.66),
            "bottom": row_bottom,
        }
        fb_left, fb_right = int(w * 0.66), w - 2
        tight = _visual_tight_blue_bounds(
            im_rgb,
            left=fb_left,
            top=yt,
            right=fb_right,
            bottom=yb,
        )
        if tight is None:
            approx_follow_button_bounds = {
                "left": fb_left,
                "top": yt,
                "right": fb_right,
                "bottom": yb,
            }
            fb_score = peak
        else:
            approx_follow_button_bounds = tight
            fb_score = peak + 0.04

        lvar = _visual_row_left_content_variance(im_rgb, row_top, row_bottom)
        row_conf = float(
            min(
                0.98,
                0.22 + min(0.45, fb_score * 10.0) + min(0.28, (lvar / 5000.0) ** 0.5 * 0.28),
            )
        )
        confidences.append(row_conf)

        row_analysis = {
            "row_index": idx,
            "approx_row_bounds": _scale_bounds_to_original(
                approx_row_bounds, aw=aw, ah=ah, orig_w=orig_w, orig_h=orig_h
            ),
            "approx_avatar_bounds": _scale_bounds_to_original(
                approx_avatar_bounds, aw=aw, ah=ah, orig_w=orig_w, orig_h=orig_h
            ),
            "approx_text_area_bounds": _scale_bounds_to_original(
                approx_text_area_bounds, aw=aw, ah=ah, orig_w=orig_w, orig_h=orig_h
            ),
            "approx_follow_button_bounds": _scale_bounds_to_original(
                approx_follow_button_bounds, aw=aw, ah=ah, orig_w=orig_w, orig_h=orig_h
            ),
            "confidence": round(row_conf, 4),
        }
        rows_out.append(row_analysis)
        log(
            "info",
            "followers_visual_candidate_row_detected",
            screenshot_path=path,
            source_profile_username=source_profile_username,
            row_index=idx,
            confidence=row_analysis["confidence"],
            approx_follow_button_bounds=row_analysis["approx_follow_button_bounds"],
            approx_row_bounds=row_analysis["approx_row_bounds"],
        )

    out["visual_candidate_rows"] = rows_out
    out["visual_candidate_count"] = len(rows_out)
    out["visual_confidence"] = float(
        sum(confidences) / len(confidences) if confidences else 0.0
    )

    sample_rows = rows_out[:12]
    log(
        "info",
        "followers_visual_candidate_diagnostic_done",
        screenshot_path=path,
        source_profile_username=source_profile_username,
        visual_candidate_count=out["visual_candidate_count"],
        visual_follow_button_count=out["visual_follow_button_count"],
        visual_confidence=round(out["visual_confidence"], 4),
        sample_rows=sample_rows,
    )

    if out["visual_candidate_count"] > 0:
        log(
            "info",
            "followers_visual_candidate_strategy_possible",
            screenshot_path=path,
            source_profile_username=source_profile_username,
            visual_candidate_count=out["visual_candidate_count"],
            visual_confidence=round(out["visual_confidence"], 4),
        )
    else:
        log(
            "info",
            "followers_visual_candidate_strategy_not_ready",
            screenshot_path=path,
            source_profile_username=source_profile_username,
            visual_follow_button_count=out["visual_follow_button_count"],
            diagnostic_error=out.get("diagnostic_error"),
        )

    return out


def _followers_visual_picker_scroll_down_once_for_candidates(d: u2.Device) -> None:
    """Small vertical swipe to reveal more follower rows (no RecyclerView-specific API)."""
    try:
        w, h = d.window_size()
        x = int(w // 2)
        d.swipe(x, int(h * 0.62), x, int(h * 0.42), 0.1)
    except Exception:
        pass
    time.sleep(0.38)


def visual_extract_followers_candidates_from_screenshot(
    d: u2.Device,
    *,
    screenshot_path: str | None = None,
    source_profile_username: str | None = None,
    runtime_seen: set[str] | None = None,
    action_account_username: str | None = None,
    phase: str | None = None,
    open_list_meta: dict[str, Any] | None = None,
    visual_loop_state: dict[str, Any] | None = None,
    list_committed_open: bool = False,
    committed_age_ms: float | None = None,
    follow_xml_cta_rows: list[dict[str, Any]] | None = None,
) -> dict[str, Any]:
    """
    Build structured visual follower-row candidates from an on-disk screenshot (PIL pixels only).
    No taps / scroll / follow. Uses ``d`` only to map row bands to list handles via UiAutomator.
    ``runtime_seen`` is reserved for future username-based filtering (no OCR in V1).

    Rows matching ``VISUAL_FOLLOWERS_ACTION_ACCOUNT_USERNAME`` / ``action_account_username`` are dropped
    (logged-out worker account showing as first row on someone else's followers list).
    """
    _ = runtime_seen
    dry_run = bool(getattr(config, "VISUAL_FOLLOWERS_PICKER_DRY_RUN", True))
    max_pick = int(getattr(config, "VISUAL_FOLLOWERS_MAX_CANDIDATES_PER_SCREEN", 5) or 5)
    max_pick = max(1, min(max_pick, 50))

    out: dict[str, Any] = {
        "candidates": [],
        "candidate_count": 0,
        "mean_confidence": 0.0,
        "screenshot_path": str(screenshot_path or ""),
        "source_profile_username": source_profile_username or "",
        "sample_candidates": [],
        "picker_error": None,
        "internal_gate_skipped": False,
        "internal_gate_ms": 0.0,
        "picker_core_ms": 0.0,
    }
    path = screenshot_path
    if not path:
        out["picker_error"] = "no_screenshot_path"
        log(
            "info",
            "visual_followers_candidate_picker_empty",
            screenshot_path="",
            source_profile_username=source_profile_username,
            candidate_count=0,
            sample_candidates=[],
            confidence=0.0,
            dry_run=dry_run,
            visual_only=True,
            reason="no_screenshot_path",
        )
        return out

    work_path = str(path)
    scroll_executed = 0
    max_scrolls = 2
    vision_required = bool(_vision_validation_enabled())
    out["picker_scroll_rounds"] = 0
    _stall_key = f"{work_path}|{str(source_profile_username or '')}"

    try:
        from PIL import Image

        im_orig = Image.open(work_path)
        orig_w, orig_h = im_orig.size
        im_rgb = _visual_downscale_rgb(im_orig, max_w=480)
    except Exception as e:
        out["picker_error"] = f"pil_failed:{e}"
        log(
            "info",
            "visual_followers_candidate_picker_empty",
            screenshot_path=str(work_path),
            source_profile_username=source_profile_username,
            candidate_count=0,
            sample_candidates=[],
            confidence=0.0,
            dry_run=dry_run,
            visual_only=True,
            reason=out["picker_error"],
            empty_reason=out["picker_error"],
            spans_count=0,
            candidates_before_cta_filter=0,
            candidates_after_cta_filter=0,
        )
        _followers_visual_picker_terminal_reset(_stall_key)
        return out

    aw, ah = im_rgb.size
    internal_gate_skipped = False
    t_internal_gate = time.perf_counter()
    if vision_required:
        skip_internal_gate = False
        skip_internal_meta: dict[str, Any] = {}
        try:
            from followers_injection_evidence import (
                should_skip_picker_internal_vision_gate,
            )

            skip_internal_gate, skip_internal_meta = should_skip_picker_internal_vision_gate(
                open_list_meta,
                visual_loop_state,
                source_profile_username=str(source_profile_username or ""),
                screenshot_path=str(work_path),
                picker_phase=str(phase or ""),
                list_committed_open=bool(list_committed_open),
                committed_age_ms=committed_age_ms,
            )
        except Exception:
            skip_internal_gate = False
            skip_internal_meta = {}
        if skip_internal_gate:
            internal_gate_skipped = True
            out["internal_gate_skipped"] = True
            out["internal_gate_ms"] = round(
                (time.perf_counter() - t_internal_gate) * 1000.0, 2
            )
            try:
                log(
                    "info",
                    "followers_picker_internal_gate_skipped_committed_evidence_fresh",
                    source_profile_username=str(source_profile_username or "")[:120],
                    screenshot_path=str(work_path)[:400],
                    evidence_age_ms=float(skip_internal_meta.get("evidence_age_ms") or 0.0),
                    committed_age_ms=float(skip_internal_meta.get("committed_age_ms") or 0.0),
                    reason=str(
                        skip_internal_meta.get("reason")
                        or "same_fresh_committed_evidence_already_revalidated"
                    ),
                )
            except Exception:
                pass
        elif not _vision_validation_visual_followers_candidate_gate(
            screenshot_path=str(work_path),
            d=d,
            source_profile_username=source_profile_username,
        ):
            out["internal_gate_ms"] = round(
                (time.perf_counter() - t_internal_gate) * 1000.0, 2
            )
            out["picker_error"] = (
                "vision_validation_rejected"
                if scroll_executed == 0
                else "vision_validation_rejected_after_scroll_retry"
            )
            log(
                "info",
                "visual_followers_candidate_picker_empty",
                screenshot_path=str(work_path),
                source_profile_username=source_profile_username,
                candidate_count=0,
                sample_candidates=[],
                confidence=0.0,
                dry_run=dry_run,
                visual_only=True,
                reason=out["picker_error"],
                empty_reason=out["picker_error"],
                spans_count=0,
                candidates_before_cta_filter=0,
                candidates_after_cta_filter=0,
            )
            _followers_visual_picker_terminal_reset(_stall_key)
            return out
        else:
            out["internal_gate_ms"] = round(
                (time.perf_counter() - t_internal_gate) * 1000.0, 2
            )
    t_picker_core = time.perf_counter()
    try:
        log(
            "info",
            "visual_followers_candidate_picker_after_vision_gate",
            screenshot_path=str(work_path),
            source_profile_username=source_profile_username,
            vision_required=vision_required,
            vision_candidate_surface_allowed=True,
            dry_run=dry_run,
            visual_only=True,
        )
    except Exception:
        pass

    if scroll_executed == 0:
        _prev_inc = int(_FOLLOWERS_VISUAL_PICKER_INCOMPLETE_STARTS.get(_stall_key, 0))
        _next_inc = _prev_inc + 1
        if _next_inc > 3:
            try:
                log(
                    "warning",
                    "followers_candidate_picker_stalled",
                    repeat_count=_prev_inc,
                    screenshot_path=str(work_path),
                    source_profile_username=source_profile_username,
                )
            except Exception:
                pass
            _followers_visual_picker_terminal_reset(_stall_key)
            out["picker_error"] = "picker_stalled_repeated_picker_started"
            out["candidate_count"] = 0
            try:
                log(
                    "info",
                    "visual_followers_candidate_picker_empty",
                    screenshot_path=str(work_path),
                    source_profile_username=source_profile_username,
                    candidate_count=0,
                    sample_candidates=[],
                    confidence=0.0,
                    dry_run=dry_run,
                    visual_only=True,
                    reason=out["picker_error"],
                    empty_reason=out["picker_error"],
                    spans_count=0,
                    candidates_before_cta_filter=0,
                    candidates_after_cta_filter=0,
                )
            except Exception:
                pass
            out["picker_core_ms"] = round((time.perf_counter() - t_picker_core) * 1000.0, 2)
            return out
        _FOLLOWERS_VISUAL_PICKER_INCOMPLETE_STARTS[_stall_key] = _next_inc

        log(
            "info",
            "visual_followers_candidate_picker_started",
            screenshot_path=str(work_path),
            source_profile_username=source_profile_username,
            dry_run=dry_run,
            visual_only=True,
            max_candidates=max_pick,
            analysis_size=(aw, ah),
            original_size=(orig_w, orig_h),
        )

    spans = _visual_collect_follow_row_y_spans(im_rgb)
    try:
        log(
            "info",
            "visual_followers_candidate_picker_spans_detected",
            screenshot_path=str(work_path),
            source_profile_username=source_profile_username,
            spans_count=len(spans),
            dry_run=dry_run,
            visual_only=True,
        )
    except Exception:
        pass
    try:
        log(
            "info",
            "visual_followers_candidate_picker_before_cta_classification",
            screenshot_path=str(work_path),
            source_profile_username=source_profile_username,
            spans_count=len(spans),
            dry_run=dry_run,
            visual_only=True,
        )
    except Exception:
        pass

    w, h = aw, ah
    built: list[dict[str, Any]] = []
    confidences: list[float] = []
    cta_followable_row_count = 0
    src_key = (source_profile_username or "").strip().lstrip("@").lower()[:40]
    action_raw = (
        (action_account_username or "").strip()
        or str(getattr(config, "VISUAL_FOLLOWERS_ACTION_ACCOUNT_USERNAME", "") or "").strip()
    )
    action_norm = _normalize_handle(action_raw) if action_raw else ""

    from visual_row_mapping import _vr_log_row_cta as _vr_log_row_cta_fn
    from visual_row_mapping import visual_followers_row_cta_classify as _vr_row_cta_classify

    for idx, (yt, yb, peak) in enumerate(spans):
        pad = max(4, (yb - yt + 1) // 3)
        row_top = max(int(h * 0.052), yt - pad)
        row_bottom = min(int(h * 0.93), yb + pad)
        approx_row_bounds = {
            "left": int(w * 0.02),
            "top": row_top,
            "right": int(w * 0.98),
            "bottom": row_bottom,
        }
        approx_avatar_bounds = {
            "left": int(w * 0.03),
            "top": row_top,
            "right": int(w * 0.20),
            "bottom": row_bottom,
        }
        approx_username_text_zone = {
            "left": int(w * 0.20),
            "top": row_top,
            "right": int(w * 0.66),
            "bottom": row_bottom,
        }
        fb_left, fb_right = int(w * 0.66), w - 2
        tight = _visual_tight_blue_bounds(
            im_rgb,
            left=fb_left,
            top=yt,
            right=fb_right,
            bottom=yb,
        )
        if tight is None:
            approx_follow_button_bounds = {
                "left": fb_left,
                "top": yt,
                "right": fb_right,
                "bottom": yb,
            }
            fb_score = peak
        else:
            approx_follow_button_bounds = tight
            fb_score = peak + 0.04

        lvar = _visual_row_left_content_variance(im_rgb, row_top, row_bottom)
        row_conf = float(
            min(
                0.98,
                0.22 + min(0.45, fb_score * 10.0) + min(0.28, (lvar / 5000.0) ** 0.5 * 0.28),
            )
        )

        row_o = _scale_bounds_to_original(
            approx_row_bounds, aw=aw, ah=ah, orig_w=orig_w, orig_h=orig_h
        )
        cy = (int(row_o["top"]) + int(row_o["bottom"])) // 2
        top_o = int(row_o["top"])
        bot_o = int(row_o["bottom"])

        cta_row = _vr_row_cta_classify(
            im_rgb,
            fb_left=fb_left,
            fb_top=yt,
            fb_right=fb_right,
            fb_bottom=yb,
            tight_bounds=tight,
        )
        if bool(cta_row.get("cta_followable")):
            cta_followable_row_count += 1
        digest_pre = hashlib.sha1(
            f"{src_key}|{idx}|{row_o['left']}|{row_o['top']}|{row_o['right']}|{row_o['bottom']}".encode()
        ).hexdigest()[:12]
        visual_candidate_id_pre = f"vfp_{idx}_{digest_pre}"
        _vr_log_row_cta_fn(
            event="followers_row_cta_classified",
            row_index=idx,
            visual_candidate_id=visual_candidate_id_pre,
            span_index=idx,
            cta=cta_row,
            screenshot_path=str(path),
            source_profile_username=str(source_profile_username or ""),
            extra={"selection_method": "visual_screenshot"},
        )
        if not bool(cta_row.get("cta_followable")):
            _vr_log_row_cta_fn(
                event="followers_row_cta_rejected",
                row_index=idx,
                visual_candidate_id=visual_candidate_id_pre,
                span_index=idx,
                cta=cta_row,
                screenshot_path=str(path),
                source_profile_username=str(source_profile_username or ""),
                extra={
                    "cta_reject_reason": str(cta_row.get("cta_class") or "unknown"),
                    "selection_method": "visual_screenshot",
                },
            )
            if str(cta_row.get("cta_class") or "") in (
                "message",
                "contact",
                "following",
                "requested",
                "connected_gray",
                "inactive",
            ) or (
                str(cta_row.get("cta_class") or "") == "unknown"
                and float(cta_row.get("frac_blue_full") or 0.0) < 0.045
            ):
                log(
                    "info",
                    "followers_visual_candidate_rejected_already_connected",
                    row_index=idx,
                    visual_candidate_id=visual_candidate_id_pre,
                    cta_class=str(cta_row.get("cta_class") or ""),
                    cta_text=str(cta_row.get("cta_text") or ""),
                    reason="row_cta_non_follow_or_connected",
                    span_index=idx,
                    screenshot_path=str(work_path),
                    source_profile_username=str(source_profile_username or ""),
                )
            continue
        _vr_log_row_cta_fn(
            event="followers_row_cta_allowed",
            row_index=idx,
            visual_candidate_id=visual_candidate_id_pre,
            span_index=idx,
            cta=cta_row,
            screenshot_path=str(path),
            source_profile_username=str(source_profile_username or ""),
            extra={"selection_method": "visual_screenshot"},
        )

        _xml_match_for_cand: dict[str, Any] | None = None
        if follow_xml_cta_rows:
            from visual_row_mapping import (
                attach_follow_xml_cta_fields_to_candidate,
                follow_xml_cta_gate_for_visual_band,
            )

            _xml_reject, _xml_match_for_cand, _xml_overlap = follow_xml_cta_gate_for_visual_band(
                row_top=top_o,
                row_bottom=bot_o,
                xml_cta_rows=list(follow_xml_cta_rows),
                source_profile_username=str(source_profile_username or ""),
                visual_candidate_id=visual_candidate_id_pre,
                span_index=idx,
                resolved_username="",
            )
            if _xml_reject:
                continue

        if cy < int(orig_h * 0.065) or cy > int(orig_h * 0.92):
            log(
                "info",
                "visual_followers_candidate_skipped",
                screenshot_path=str(path),
                source_profile_username=source_profile_username,
                span_index=idx,
                skip_reason="row_center_outside_list_safe_band",
                top=top_o,
                bottom=bot_o,
                row_center_y=cy,
                confidence=round(row_conf, 4),
                dry_run=dry_run,
                visual_only=True,
            )
            continue

        resolved_u = _visual_followers_resolve_username_in_row_band(
            d, row_top=top_o, row_bottom=bot_o
        )
        if not resolved_u:
            try:
                _utz_o = _scale_bounds_to_original(
                    approx_username_text_zone,
                    aw=aw,
                    ah=ah,
                    orig_w=orig_w,
                    orig_h=orig_h,
                )
                _band_probe = _visual_followers_username_band_probe(
                    d, row_top=top_o, row_bottom=bot_o
                )
                log(
                    "info",
                    "followers_visual_candidate_username_hint_missing_preopen",
                    source_profile_username=str(source_profile_username or ""),
                    visual_candidate_id=visual_candidate_id_pre,
                    span_index=idx,
                    row_band_top=top_o,
                    row_band_bottom=bot_o,
                    approx_row_bounds=row_o,
                    approx_username_text_zone=_utz_o,
                    screenshot_path=str(path),
                    handle_like_textview_count=int(
                        _band_probe.get("handle_like_textview_count") or 0
                    ),
                    sample_handle_like_texts=_band_probe.get("sample_texts") or [],
                )
            except Exception:
                pass
        if (
            action_norm
            and resolved_u
            and _normalize_handle(resolved_u) == action_norm
        ):
            log(
                "info",
                "visual_followers_candidate_skipped",
                screenshot_path=str(path),
                source_profile_username=source_profile_username,
                span_index=idx,
                skip_reason="source_account_self",
                skipped_username=resolved_u,
                action_account_username=action_raw,
                top=top_o,
                bottom=bot_o,
                confidence=round(row_conf, 4),
                dry_run=dry_run,
                visual_only=True,
            )
            continue

        av_o = _scale_bounds_to_original(
            approx_avatar_bounds, aw=aw, ah=ah, orig_w=orig_w, orig_h=orig_h
        )
        tz_o = _scale_bounds_to_original(
            approx_username_text_zone, aw=aw, ah=ah, orig_w=orig_w, orig_h=orig_h
        )
        fb_o = _scale_bounds_to_original(
            approx_follow_button_bounds, aw=aw, ah=ah, orig_w=orig_w, orig_h=orig_h
        )

        visual_candidate_id = visual_candidate_id_pre

        cand = {
            "visual_candidate_id": visual_candidate_id,
            "row_index": len(built),
            "span_index": idx,
            "approx_row_bounds": row_o,
            "approx_follow_button_bounds": fb_o,
            "approx_avatar_bounds": av_o,
            "approx_username_text_zone": tz_o,
            "confidence": round(row_conf, 4),
            "source_profile_username": source_profile_username or "",
            "selection_method": "visual_screenshot",
            "resolved_username_hint": resolved_u or "",
            "row_cta_class": str(cta_row.get("cta_class") or ""),
            "row_cta_text": str(cta_row.get("cta_text") or ""),
            "row_cta_blue_frac": max(
                float(cta_row.get("frac_blue_tight") or 0.0),
                float(cta_row.get("frac_blue_full") or 0.0),
            ),
        }
        if _xml_match_for_cand is not None:
            from visual_row_mapping import attach_follow_xml_cta_fields_to_candidate

            attach_follow_xml_cta_fields_to_candidate(cand, _xml_match_for_cand)
        cand.update(_compute_visual_candidate_tap_points_from_bounds(row_o, av_o, tz_o, fb_o))
        built.append(cand)
        confidences.append(row_conf)
        log(
            "info",
            "followers_visual_candidate_selected",
            screenshot_path=str(path),
            source_profile_username=source_profile_username,
            visual_candidate_id=visual_candidate_id,
            row_index=cand["row_index"],
            span_index=idx,
            row_cta_class=cand.get("row_cta_class"),
            row_cta_text=cand.get("row_cta_text"),
            row_cta_blue_frac=cand.get("row_cta_blue_frac"),
            confidence=cand["confidence"],
        )
        log(
            "info",
            "visual_followers_candidate_detected",
            screenshot_path=str(path),
            source_profile_username=source_profile_username,
            visual_candidate_id=visual_candidate_id,
            row_index=cand["row_index"],
            span_index=idx,
            top=top_o,
            bottom=bot_o,
            confidence=cand["confidence"],
            approx_row_bounds=row_o,
            dry_run=dry_run,
            visual_only=True,
        )
        if len(built) >= max_pick:
            break

    try:
        log(
            "info",
            "visual_followers_candidate_picker_after_cta_classification",
            screenshot_path=str(work_path),
            source_profile_username=source_profile_username,
            spans_count=len(spans),
            cta_followable_rows=cta_followable_row_count,
            visual_candidates_after_row_filters=len(built),
            dry_run=dry_run,
            visual_only=True,
        )
    except Exception:
        pass

    try:
        # Priority among already-safe followable rows: visual top-to-bottom only.
        # row_cta_blue_frac / confidence remain validation signals upstream, not pick order.
        built.sort(
            key=lambda c: (
                int((c.get("approx_row_bounds") or {}).get("top") or 10**9),
                int(c["span_index"])
                if c.get("span_index") is not None
                else 10**9,
            )
        )
        for _ri, _c in enumerate(built):
            _c["row_index"] = int(_ri)

        try:
            log(
                "info",
                "followers_visual_candidate_ordering_applied",
                ordering_policy="top_to_bottom_safe_followable",
                candidate_count=len(built),
                ordered_candidate_ids=[
                    str(c.get("visual_candidate_id") or "") for c in built
                ],
                ordered_span_indices=[
                    int(c["span_index"])
                    if c.get("span_index") is not None
                    else -1
                    for c in built
                ],
                ordered_top_values=[
                    int((c.get("approx_row_bounds") or {}).get("top") or -1) for c in built
                ],
                screenshot_path=str(work_path),
                source_profile_username=str(source_profile_username or ""),
                dry_run=bool(dry_run),
                visual_only=True,
            )
        except Exception:
            pass

        out["candidates"] = built
        out["candidate_count"] = len(built)
        out["mean_confidence"] = float(
            sum(confidences) / len(confidences) if confidences else 0.0
        )
        out["sample_candidates"] = built[:5]

        if out["candidate_count"] == 0:
            if spans:
                log(
                    "warning",
                    "followers_visual_no_followable_candidate_found",
                    screenshot_path=str(path),
                    source_profile_username=source_profile_username,
                    span_count=len(spans),
                    dry_run=dry_run,
                    visual_only=True,
                    reason="no_row_passed_follow_cta_gate",
                )
            empty_reason = "no_rows_after_filter" if spans else "no_blue_follow_spans"
            out["empty_reason"] = empty_reason
            out["reason"] = empty_reason
            log(
                "info",
                "visual_followers_candidate_picker_empty",
                screenshot_path=str(path),
                source_profile_username=source_profile_username,
                candidate_count=0,
                sample_candidates=[],
                confidence=0.0,
                dry_run=dry_run,
                visual_only=True,
                reason=empty_reason,
                empty_reason=empty_reason,
                spans_count=len(spans),
                candidates_before_cta_filter=len(spans),
                candidates_after_cta_filter=cta_followable_row_count,
            )
        else:
            log(
                "info",
                "visual_followers_candidate_picker_done",
                screenshot_path=str(path),
                source_profile_username=source_profile_username,
                candidate_count=out["candidate_count"],
                sample_candidates=out["sample_candidates"],
                confidence=round(out["mean_confidence"], 4),
                dry_run=dry_run,
                visual_only=True,
            )
        out["internal_gate_skipped"] = bool(internal_gate_skipped)
        out["picker_core_ms"] = round((time.perf_counter() - t_picker_core) * 1000.0, 2)
        _followers_visual_picker_terminal_reset(_stall_key)
        return out
    except Exception as e:
        try:
            log(
                "error",
                "visual_followers_candidate_picker_failed",
                exception_type=type(e).__name__,
                exception_message=str(e)[:800],
                screenshot_path=str(work_path),
                source_profile_username=source_profile_username,
                phase=str(phase or ""),
                candidate_count_so_far=len(built),
                spans_count=len(spans),
                dry_run=dry_run,
                visual_only=True,
            )
        except Exception:
            pass
        out["picker_error"] = f"unexpected:{type(e).__name__}"
        out["candidates"] = list(built)
        out["candidate_count"] = len(built)
        out["mean_confidence"] = float(
            sum(confidences) / len(confidences) if confidences else 0.0
        )
        out["sample_candidates"] = built[:5]
        out["internal_gate_skipped"] = bool(internal_gate_skipped)
        out["picker_core_ms"] = round((time.perf_counter() - t_picker_core) * 1000.0, 2)
        _followers_visual_picker_terminal_reset(_stall_key)
        return out


def _compute_visual_candidate_tap_points_from_bounds(
    row_o: dict[str, Any],
    av_o: dict[str, Any],
    tz_o: dict[str, Any],
    fb_o: dict[str, Any],
) -> dict[str, int]:
    """
    Multiple tap targets on a followers-list row (original pixel space).
    All points stay left of the Follow pill column.
    """
    def _ig(d: dict[str, Any], k: str) -> int:
        try:
            return int(d.get(k) or 0)
        except (TypeError, ValueError):
            return 0

    rl, rt, rr, rb = (
        _ig(row_o, "left"),
        _ig(row_o, "top"),
        _ig(row_o, "right"),
        _ig(row_o, "bottom"),
    )
    al, at, ar, ab = (
        _ig(av_o, "left"),
        _ig(av_o, "top"),
        _ig(av_o, "right"),
        _ig(av_o, "bottom"),
    )
    tl, tt, tr, tb = (
        _ig(tz_o, "left"),
        _ig(tz_o, "top"),
        _ig(tz_o, "right"),
        _ig(tz_o, "bottom"),
    )
    fl = _ig(fb_o, "left")
    fw = max(_ig(fb_o, "right") - fl, 1)

    row_w = max(rr - rl, 1)
    margin = max(12, int(row_w * 0.02))
    # Horizontal guard: stay clearly left of Follow column
    x_max = fl - margin - max(4, fw // 16) if fl > rl + margin else rr - margin

    avatar_tap_x = max(al + 4, min((al + ar) // 2, x_max))
    avatar_tap_y = (at + ab) // 2

    safe_left_tap_x = max(
        al + max(6, (ar - al) // 12),
        min(al + (ar - al) // 5, x_max),
    )
    safe_left_tap_y = avatar_tap_y

    r_eff = min(tr, x_max) if tr > tl else x_max
    if fl > 0:
        r_eff = min(r_eff, fl - margin)
    if r_eff <= tl + 6:
        username_area_tap_x = max(tl + 8, min((tl + max(tl, fl - margin)) // 2, x_max))
    else:
        username_area_tap_x = max(tl + 6, min((tl + r_eff) // 2, x_max))
    username_area_tap_y = (tt + tb) // 2

    left_band_right = max(rl + margin * 2, fl - margin)
    row_center_left_tap_x = max(
        rl + margin,
        min((rl + left_band_right) // 2, x_max),
    )
    row_center_left_tap_y = (rt + rb) // 2

    return {
        "avatar_tap_x": int(avatar_tap_x),
        "avatar_tap_y": int(avatar_tap_y),
        "username_area_tap_x": int(username_area_tap_x),
        "username_area_tap_y": int(username_area_tap_y),
        "row_center_left_tap_x": int(row_center_left_tap_x),
        "row_center_left_tap_y": int(row_center_left_tap_y),
        "safe_left_tap_x": int(safe_left_tap_x),
        "safe_left_tap_y": int(safe_left_tap_y),
    }


def _visual_open_strategy_taps_from_candidate(
    candidate: dict[str, Any],
) -> list[tuple[str, int, int]]:
    """Ordered tap strategies for visual follower rows; dedupes identical coordinates."""
    out: list[tuple[str, int, int]] = []
    seen: set[tuple[int, int]] = set()

    def _add(name: str, x: Any, y: Any) -> None:
        try:
            xi, yi = int(x), int(y)
        except (TypeError, ValueError):
            return
        if xi <= 0 or yi <= 0:
            return
        sig = (xi, yi)
        if sig in seen:
            return
        seen.add(sig)
        out.append((name, xi, yi))

    rc = candidate.get("row_center") or [0, 0]
    if isinstance(rc, (list, tuple)) and len(rc) >= 2:
        _add("row_center", rc[0], rc[1])

    _add("username_area", candidate.get("username_area_tap_x"), candidate.get("username_area_tap_y"))
    _add("avatar_area", candidate.get("avatar_tap_x"), candidate.get("avatar_tap_y"))
    _add("row_center_left", candidate.get("row_center_left_tap_x"), candidate.get("row_center_left_tap_y"))
    _add("safe_left", candidate.get("safe_left_tap_x"), candidate.get("safe_left_tap_y"))

    return out


def _wait_visual_follower_open_transition(
    d: u2.Device,
    *,
    pkg: str,
    source_profile_username: str,
    timeout_s: float = 2.65,
) -> bool:
    """
    After tapping a followers row, wait until navigation suggests we left the CT title
    or landed on a profile-like surface (never blocks indefinitely).
    """
    from navigation_engine import NavigationEngineState, observe_instagram_state

    deadline = time.monotonic() + float(timeout_s)
    src_n = _normalize_handle(source_profile_username or "")
    poll = float(getattr(config, "PROFILE_VERIFY_POLL_S", 0.12) or 0.12)

    while time.monotonic() < deadline:
        try:
            ab = read_current_profile_username_for_follow_gate(d)
            ab_n = _normalize_handle(ab or "")
            if src_n and ab_n and ab_n != src_n:
                return True
        except Exception:
            pass

        try:
            nav = observe_instagram_state(
                d,
                expected_package=pkg,
                last_known_state=NavigationEngineState.FOLLOWERS_LIST.value,
                context={
                    "phase": "visual_follower_open_transition",
                    "source_profile_username": source_profile_username,
                    "disable_followers_visual_fallback": True,
                    "expected_state": "PROFILE",
                },
            )
            st = str(nav.get("state") or "")
            cf = float(nav.get("confidence") or 0.0)
            if st in (
                NavigationEngineState.PROFILE.value,
                NavigationEngineState.CANDIDATE_PROFILE.value,
                NavigationEngineState.PRIVATE_PROFILE.value,
            ) and cf >= 0.42:
                if (
                    _visual_raw_follow_invite_visible_quick(d)
                    or _follow_ui_state_snapshot(d) == "follow"
                ):
                    return True
        except Exception:
            pass

        try:
            det = detect_followers_list_screen(
                d, source_profile_username=source_profile_username
            )
            if not bool(det.get("is_followers_list")):
                guess = str(det.get("current_screen_guess") or "").lower()
                if "profile" in guess or guess == "likely_profile":
                    return True
        except Exception:
            pass

        time.sleep(poll)

    return False


def _visual_follower_username_zone_tap_xy(
    candidate: dict[str, Any],
) -> tuple[int, int, str | None]:
    """
    Pick a tap point in the username / handle column, left of the Follow pill. Returns (x,y) or failure reason.
    """
    min_conf = float(getattr(config, "FOLLOWERS_VISUAL_FALLBACK_MIN_CONFIDENCE", 0.65))
    if float(candidate.get("confidence") or 0) < min_conf:
        return 0, 0, "confidence_below_threshold"
    tz = candidate.get("approx_username_text_zone") or {}
    fb = candidate.get("approx_follow_button_bounds") or {}
    l, t, r, b = tz.get("left"), tz.get("top"), tz.get("right"), tz.get("bottom")
    if l is None or t is None or r is None or b is None:
        row = candidate.get("approx_row_bounds") or {}
        l, t, r, b = row.get("left"), row.get("top"), row.get("right"), row.get("bottom")
        if l is None or t is None or r is None or b is None:
            return 0, 0, "missing_bounds"
    l, t, r, b = int(l), int(t), int(r), int(b)
    if r <= l + 4 or b <= t + 4:
        return 0, 0, "invalid_bounds"
    fbl = fb.get("left")
    r_eff = r
    if fbl is not None:
        r_eff = min(r, int(fbl) - 12)
    if r_eff <= l + 4:
        return 0, 0, "tap_zone_collides_with_follow"
    cx = (l + r_eff) // 2
    cy = (t + b) // 2
    return cx, cy, None


def open_visual_follower_candidate_from_screenshot(
    d: u2.Device,
    candidate: dict[str, Any],
    *,
    source_profile_username: str | None = None,
) -> dict[str, Any]:
    """
    Tap the username / row zone (never the Follow pill), then verify Instagram profile chrome.
    Does not follow, DM, or scroll.
    """
    global _VISUAL_TARGET_PROFILE_LOCK_ACTIVE, _VISUAL_TARGET_PROFILE_CONTEXT
    if _VISUAL_TARGET_PROFILE_LOCK_ACTIVE:
        meta_blk = _followers_current_pkg_activity(d)
        pin = _VISUAL_TARGET_PROFILE_CONTEXT or {}
        exp_fp_blk = str(
            pin.get("profile_visual_fingerprint")
            or pin.get("profile_fingerprint")
            or ""
        )
        log(
            "info",
            "visual_target_profile_lock_mismatch_abort",
            action="open_follower_candidate_blocked_active_target_lock",
            expected_profile_fingerprint=exp_fp_blk,
            current_profile_fingerprint="",
            confidence=0.0,
            same_profile=False,
            current_activity=meta_blk.get("current_activity"),
            current_package=meta_blk.get("current_package"),
            source_profile_username=source_profile_username or "",
        )
        return {
            "visual_candidate_id": str(candidate.get("visual_candidate_id") or ""),
            "row_index": candidate.get("row_index"),
            "tap_x": None,
            "tap_y": None,
            "approx_row_bounds": dict(candidate.get("approx_row_bounds") or {}),
            "approx_username_text_zone": dict(
                candidate.get("approx_username_text_zone") or {}
            ),
            "source_profile_username": source_profile_username or "",
            "current_activity": meta_blk.get("current_activity"),
            "current_package": meta_blk.get("current_package"),
            "profile_detected": False,
            "failure_reason": "visual_target_profile_lock_active",
            "ok": False,
        }

    pkg = str(getattr(config, "INSTAGRAM_PACKAGE", "") or "")
    row_b = dict(candidate.get("approx_row_bounds") or {})
    tz_b = dict(candidate.get("approx_username_text_zone") or {})
    fb_b = dict(candidate.get("approx_follow_button_bounds") or {})
    vid = str(candidate.get("visual_candidate_id") or "")
    ridx = candidate.get("row_index")

    def _payload(
        *,
        tap_x: int | None,
        tap_y: int | None,
        profile_detected: bool,
        failure_reason: str | None,
        cur_pkg: str | None = None,
        cur_act: str | None = None,
    ) -> dict[str, Any]:
        return {
            "visual_candidate_id": vid,
            "row_index": ridx,
            "tap_x": tap_x,
            "tap_y": tap_y,
            "approx_row_bounds": row_b,
            "approx_username_text_zone": tz_b,
            "source_profile_username": source_profile_username or "",
            "current_activity": cur_act,
            "current_package": cur_pkg,
            "profile_detected": profile_detected,
            "failure_reason": failure_reason,
        }

    cx, cy, pre_fail = _visual_follower_username_zone_tap_xy(candidate)
    if pre_fail:
        log(
            "error",
            "visual_follower_candidate_open_failed",
            **_payload(
                tap_x=None,
                tap_y=None,
                profile_detected=False,
                failure_reason=pre_fail,
            ),
        )
        return {
            **_payload(
                tap_x=None,
                tap_y=None,
                profile_detected=False,
                failure_reason=pre_fail,
            ),
            "ok": False,
        }

    try:
        w, h = d.window_size()
        cx = max(2, min(int(w) - 3, cx))
        cy = max(2, min(int(h) - 3, cy))
    except Exception:
        pass

    log(
        "info",
        "visual_follower_candidate_open_started",
        **_payload(
            tap_x=cx,
            tap_y=cy,
            profile_detected=False,
            failure_reason=None,
        ),
    )

    tap_inside_follow = False
    if fb_b:
        try:
            fl, ft, frb, fbot = (
                int(fb_b["left"]),
                int(fb_b["top"]),
                int(fb_b["right"]),
                int(fb_b["bottom"]),
            )
            tap_inside_follow = fl <= cx < frb and ft <= cy < fbot
        except (KeyError, TypeError, ValueError):
            tap_inside_follow = False

    log(
        "info",
        "visual_follower_candidate_open_target_zone_verified",
        visual_candidate_id=vid,
        tap_x=cx,
        tap_y=cy,
        approx_username_text_zone=tz_b,
        approx_follow_button_bounds=fb_b,
        tap_inside_follow_button=tap_inside_follow,
    )

    if tap_inside_follow:
        meta = _followers_current_pkg_activity(d)
        fr_guard = "tap_would_hit_follow_button_after_clamp"
        log(
            "error",
            "visual_follower_candidate_open_failed",
            **_payload(
                tap_x=cx,
                tap_y=cy,
                profile_detected=False,
                failure_reason=fr_guard,
                cur_pkg=meta.get("current_package"),
                cur_act=meta.get("current_activity"),
            ),
        )
        return {
            **_payload(
                tap_x=cx,
                tap_y=cy,
                profile_detected=False,
                failure_reason=fr_guard,
                cur_pkg=meta.get("current_package"),
                cur_act=meta.get("current_activity"),
            ),
            "ok": False,
        }

    try:
        d.click(cx, cy)
    except Exception as e:
        fr = f"tap_failed:{e}"
        meta = _followers_current_pkg_activity(d)
        log(
            "error",
            "visual_follower_candidate_open_failed",
            **_payload(
                tap_x=cx,
                tap_y=cy,
                profile_detected=False,
                failure_reason=fr,
                cur_pkg=meta.get("current_package"),
                cur_act=meta.get("current_activity"),
            ),
        )
        return {
            **_payload(
                tap_x=cx,
                tap_y=cy,
                profile_detected=False,
                failure_reason=fr,
                cur_pkg=meta.get("current_package"),
                cur_act=meta.get("current_activity"),
            ),
            "ok": False,
        }

    log(
        "info",
        "visual_follower_candidate_open_tap_sent",
        **_payload(
            tap_x=cx,
            tap_y=cy,
            profile_detected=False,
            failure_reason=None,
        ),
    )

    time.sleep(1.5)
    try:
        try:
            d.dump_hierarchy(compressed=False)
        except TypeError:
            d.dump_hierarchy()
    except Exception:
        pass

    meta = _followers_current_pkg_activity(d)
    cur_pkg = meta.get("current_package")
    cur_act = meta.get("current_activity")
    signal = _try_profile_signals_once(d, "", pkg)
    guess = _guess_profile_screen(d, pkg, "")
    profile_detected = bool(
        signal
        or guess in ("likely_profile", "profile_header_rid", "action_bar_title")
    )
    fr: str | None = None if profile_detected else "profile_not_verified"

    if profile_detected:
        log(
            "info",
            "visual_follower_candidate_open_success",
            **_payload(
                tap_x=cx,
                tap_y=cy,
                profile_detected=True,
                failure_reason=None,
                cur_pkg=cur_pkg,
                cur_act=cur_act,
            ),
            profile_signal=signal,
            screen_guess=guess,
        )
        tgt_ctx = visual_capture_profile_context(
            d, source_profile_username=source_profile_username
        )
        tgt_fp = str(
            tgt_ctx.get("profile_visual_fingerprint")
            or tgt_ctx.get("profile_fingerprint")
            or ""
        )
        if tgt_ctx.get("ok") and tgt_fp:
            _VISUAL_TARGET_PROFILE_CONTEXT = tgt_ctx
            _VISUAL_TARGET_PROFILE_LOCK_ACTIVE = True
            log(
                "info",
                "visual_target_profile_lock_enabled",
                expected_profile_fingerprint=tgt_fp,
                current_activity=cur_act,
                current_package=cur_pkg,
                source_profile_username=source_profile_username or "",
                action="after_follower_candidate_open_success",
            )
        else:
            _VISUAL_TARGET_PROFILE_CONTEXT = None
            _VISUAL_TARGET_PROFILE_LOCK_ACTIVE = False
            log(
                "warning",
                "visual_target_profile_lock_enable_failed",
                expected_profile_fingerprint="",
                capture_ok=bool(tgt_ctx.get("ok")),
                failure_reason=str(tgt_ctx.get("failure_reason") or ""),
                current_activity=cur_act,
                current_package=cur_pkg,
                source_profile_username=source_profile_username or "",
                action="after_follower_candidate_open_success",
            )
        return {
            **_payload(
                tap_x=cx,
                tap_y=cy,
                profile_detected=True,
                failure_reason=None,
                cur_pkg=cur_pkg,
                cur_act=cur_act,
            ),
            "ok": True,
            "profile_signal": signal,
            "screen_guess": guess,
            "target_profile_context": tgt_ctx,
        }

    log(
        "error",
        "visual_follower_candidate_open_failed",
        **_payload(
            tap_x=cx,
            tap_y=cy,
            profile_detected=False,
            failure_reason=fr,
            cur_pkg=cur_pkg,
            cur_act=cur_act,
        ),
        profile_signal=signal,
        screen_guess=guess,
    )
    return {
        **_payload(
            tap_x=cx,
            tap_y=cy,
            profile_detected=False,
            failure_reason=fr,
            cur_pkg=cur_pkg,
            cur_act=cur_act,
        ),
        "ok": False,
        "profile_signal": signal,
        "screen_guess": guess,
    }


# --- Visual post grid + like dry-run (screenshot heuristics; like tap never sent when VISUAL_POST_LIKE_DRY_RUN) ---
_VISUAL_POST_LIKE_TAPS_RECORDED: int = 0

# Session: after a follower candidate profile opens successfully, pin that profile until flow end.
_VISUAL_TARGET_PROFILE_LOCK_ACTIVE: bool = False
_VISUAL_TARGET_PROFILE_CONTEXT: dict[str, Any] | None = None


def visual_target_profile_lock_clear() -> None:
    global _VISUAL_TARGET_PROFILE_LOCK_ACTIVE, _VISUAL_TARGET_PROFILE_CONTEXT
    _VISUAL_TARGET_PROFILE_LOCK_ACTIVE = False
    _VISUAL_TARGET_PROFILE_CONTEXT = None


def runner_invalidate_visual_followers_session_after_safe_stop(
    d: u2.Device | None,
    *,
    source_profile_username: str = "",
) -> None:
    """
    After a terminal post-follow safe stop (force_stop / home): clear in-memory followers
    visual state so the runner cannot reuse a stale screenshot or row CTA selection.
    """
    un = str(source_profile_username or "").strip()
    try:
        _followers_release_post_tap_detection_lock(un)
    except Exception:
        try:
            _followers_set_post_tap_detection_lock(False)
        except Exception:
            pass
    try:
        _followers_reset_post_tap_capture_gate()
    except Exception:
        pass
    try:
        visual_target_profile_lock_clear()
    except Exception:
        pass
    try:
        _followers_reset_followers_list_session_state()
    except Exception:
        pass
    try:
        _followers_set_post_tap_detection_lock(False)
    except Exception:
        pass
    if d is not None:
        try:
            d.app_current()
        except Exception:
            pass


def visual_target_profile_lock_verify(
    d: u2.Device,
    *,
    source_profile_username: str | None,
    action: str,
) -> dict[str, Any]:
    """
    If a target profile lock is active, ensure the current screen still matches the
    captured follower profile before post open / real like / real follow / mute dry-run.
    """
    global _VISUAL_TARGET_PROFILE_LOCK_ACTIVE, _VISUAL_TARGET_PROFILE_CONTEXT
    meta = _followers_current_pkg_activity(d)
    if not _VISUAL_TARGET_PROFILE_LOCK_ACTIVE:
        return {
            "ok": True,
            "skipped": True,
            "target_profile_lock_mismatch": False,
        }
    ctx = _VISUAL_TARGET_PROFILE_CONTEXT
    if not isinstance(ctx, dict):
        log(
            "info",
            "visual_target_profile_lock_mismatch_abort",
            action=action,
            expected_profile_fingerprint="",
            current_profile_fingerprint="",
            current_context_failure_reason="invalid_target_context_object",
            current_context_screenshot_path="",
            confidence=0.0,
            same_profile=False,
            current_activity=meta.get("current_activity"),
            current_package=meta.get("current_package"),
            source_profile_username=source_profile_username or "",
        )
        return {
            "ok": False,
            "skipped": False,
            "target_profile_lock_mismatch": True,
        }
    exp_fp = str(
        ctx.get("profile_visual_fingerprint") or ctx.get("profile_fingerprint") or ""
    )
    if ctx.get("ok") is False or not exp_fp:
        log(
            "info",
            "visual_target_profile_lock_mismatch_abort",
            action=action,
            expected_profile_fingerprint=exp_fp,
            current_profile_fingerprint="",
            current_context_failure_reason=str(ctx.get("failure_reason") or "target_baseline_invalid"),
            current_context_screenshot_path=str(
                ctx.get("screenshot_path") or ctx.get("profile_screenshot_path") or ""
            ),
            confidence=0.0,
            same_profile=False,
            current_activity=meta.get("current_activity"),
            current_package=meta.get("current_package"),
            source_profile_username=source_profile_username or "",
        )
        return {
            "ok": False,
            "skipped": False,
            "target_profile_lock_mismatch": True,
        }

    log(
        "info",
        "visual_target_profile_lock_verify_started",
        expected_profile_fingerprint=exp_fp,
        current_profile_fingerprint="",
        confidence=0.0,
        same_profile=False,
        current_activity=meta.get("current_activity"),
        current_package=meta.get("current_package"),
        source_profile_username=source_profile_username or "",
        action=action,
    )

    cur_cap = visual_capture_profile_context(
        d, source_profile_username=source_profile_username
    )
    cur_fp_live = str(
        cur_cap.get("profile_visual_fingerprint")
        or cur_cap.get("profile_fingerprint")
        or ""
    )
    if cur_cap.get("ok") is False or not cur_fp_live:
        time.sleep(0.35)
        cur_cap = visual_capture_profile_context(
            d, source_profile_username=source_profile_username
        )
        cur_fp_live = str(
            cur_cap.get("profile_visual_fingerprint")
            or cur_cap.get("profile_fingerprint")
            or ""
        )

    hdr_h = int(cur_cap.get("header_hash") or cur_cap.get("ahash_64") or 0)
    av_h = int(cur_cap.get("avatar_hash") or cur_cap.get("avatar_ahash_64") or 0)
    shot_ctx = str(
        cur_cap.get("screenshot_path") or cur_cap.get("profile_screenshot_path") or ""
    )
    cur_fp_log = str(
        cur_cap.get("profile_visual_fingerprint")
        or cur_cap.get("profile_fingerprint")
        or ""
    )
    log(
        "info",
        "visual_target_profile_lock_current_context_captured",
        ok=bool(cur_cap.get("ok")),
        failure_reason=str(cur_cap.get("failure_reason") or ""),
        screenshot_path=shot_ctx,
        current_profile_fingerprint=cur_fp_log,
        header_hash=hdr_h,
        avatar_hash=av_h,
        username_norm=str(cur_cap.get("username_norm") or ""),
        current_activity=cur_cap.get("current_activity"),
        current_package=cur_cap.get("current_package"),
        action=action,
        source_profile_username=source_profile_username or "",
    )
    if cur_cap.get("ok") is False or not cur_fp_log:
        log(
            "warning",
            "visual_target_profile_lock_current_context_empty",
            failure_reason=str(cur_cap.get("failure_reason") or "empty_profile_fingerprint"),
            screenshot_path=shot_ctx,
            action=action,
            current_activity=meta.get("current_activity"),
            current_package=meta.get("current_package"),
        )

    min_c = float(
        getattr(config, "VISUAL_PROFILE_CONTEXT_MIN_MATCH_CONFIDENCE", 0.72) or 0.72
    )
    ver = visual_verify_same_profile_context(
        d,
        expected_context=ctx,
        source_profile_username=source_profile_username,
        current_capture=cur_cap,
    )
    cur_fp = str(
        ver.get("current_profile_fingerprint")
        or cur_fp_log
        or ""
    )
    exp_fp_v = str(ver.get("expected_profile_fingerprint") or exp_fp)
    conf = float(ver.get("confidence") or 0.0)
    same_p = bool(ver.get("same_profile"))
    bad = (not same_p) or conf < min_c
    ctx_fail = str(
        ver.get("current_capture_failure_reason")
        or cur_cap.get("failure_reason")
        or ""
    )
    ctx_shot = str(
        ver.get("current_capture_screenshot_path")
        or shot_ctx
        or ""
    )

    payload = {
        "expected_profile_fingerprint": exp_fp_v,
        "current_profile_fingerprint": cur_fp,
        "current_context_failure_reason": ctx_fail,
        "current_context_screenshot_path": ctx_shot,
        "confidence": round(conf, 4),
        "same_profile": same_p,
        "current_activity": meta.get("current_activity"),
        "current_package": meta.get("current_package"),
        "source_profile_username": source_profile_username or "",
        "action": action,
    }
    if bad:
        log("info", "visual_target_profile_lock_mismatch_abort", **payload)
        return {
            "ok": False,
            "skipped": False,
            "target_profile_lock_mismatch": True,
            **payload,
            "verify": ver,
        }
    log("info", "visual_target_profile_lock_verify_success", **payload)
    return {
        "ok": True,
        "skipped": False,
        "target_profile_lock_mismatch": False,
        **payload,
        "verify": ver,
    }


def _visual_image_cell_luma_variance(
    im: Any, x0: int, y0: int, cw: int, ch: int
) -> float:
    W, H = im.size
    x1 = min(W - 1, x0 + cw)
    y1 = min(H - 1, y0 + ch)
    if x1 <= x0 + 4 or y1 <= y0 + 4:
        return 0.0
    roi = im.crop((x0, y0, x1 + 1, y1 + 1))
    lums = [(int(r) + int(g) + int(b)) / 3.0 for r, g, b in roi.getdata()]
    if not lums:
        return 0.0
    mu = sum(lums) / len(lums)
    return sum((x - mu) ** 2 for x in lums) / len(lums)


def _visual_xy_image_to_device(
    ix: int, iy: int, iw: int, ih: int, ww: int, wh: int
) -> tuple[int, int]:
    if iw <= 0 or ih <= 0:
        return max(1, ix), max(1, iy)
    return max(1, int(ix * ww / iw)), max(1, int(iy * wh / ih))


def _visual_profile_grid_cells_mostly_blank(
    im: Any, iw: int, ih: int, *, var_thr: float = 88.0, min_blank_cells: int = 5
) -> tuple[bool, float]:
    """True when most 3×3-style grid slots under the profile tabs look blank (empty-state)."""
    grid_y0 = int(ih * 0.33)
    grid_y1 = int(ih * 0.92)
    cols = 3
    cell_w = max(24, iw // cols)
    cell_h = cell_w
    blank = 0
    total = 0
    for col, row in ((0, 0), (1, 0), (2, 0), (0, 1), (1, 1), (2, 1)):
        x0 = col * cell_w
        y0 = grid_y0 + row * cell_h
        if y0 + cell_h > grid_y1 or x0 + cell_w > iw:
            continue
        total += 1
        v = _visual_image_cell_luma_variance(im, x0, y0, cell_w, cell_h)
        if v < var_thr:
            blank += 1
    if total == 0:
        return False, 0.0
    if blank >= min_blank_cells:
        ratio = blank / total
        conf = float(min(0.82, 0.48 + ratio * 0.28))
        return True, conf
    return False, 0.0


def _visual_profile_lower_grid_mostly_blank(
    im: Any,
    iw: int,
    ih: int,
    *,
    var_thr: float = 96.0,
    min_blank_cells: int = 4,
    grid_y0_ratio: float = 0.58,
    grid_y1_ratio: float = 0.94,
) -> tuple[bool, float]:
    """
    Sample cells only below the header / stats / 'Suggested for you' strip (≈ lower half).
    Empty-state profiles show a flat 'No posts yet' region here; suggestion cards sit higher.
    """
    grid_y0 = int(ih * grid_y0_ratio)
    grid_y1 = int(ih * grid_y1_ratio)
    cols = 3
    cell_w = max(24, iw // cols)
    cell_h = cell_w
    blank = 0
    total = 0
    for col, row in ((0, 0), (1, 0), (2, 0), (0, 1), (1, 1), (2, 1)):
        x0 = col * cell_w
        y0 = grid_y0 + row * cell_h
        if y0 + cell_h > grid_y1 or x0 + cell_w > iw:
            continue
        total += 1
        v = _visual_image_cell_luma_variance(im, x0, y0, cell_w, cell_h)
        if v < var_thr:
            blank += 1
    if total == 0:
        return False, 0.0
    if blank >= min_blank_cells:
        ratio = blank / total
        conf = float(min(0.8, 0.44 + ratio * 0.28))
        return True, conf
    return False, 0.0


_POST_FOLLOW_LIKES_GRID_Y0_RATIO = 0.52
_POST_FOLLOW_LIKES_GRID_Y1_RATIO = 0.92
_POST_FOLLOW_LIKES_GRID_VAR_THR = 120.0
_POST_FOLLOW_LIKES_GRID_PARTIAL_VAR_THR = 80.0
_POST_FOLLOW_LIKES_GRID_UPPER_Y0_RATIO = 0.33
_POST_FOLLOW_LIKES_GRID_UPPER_Y1_RATIO = 0.52
_POST_FOLLOW_LIKES_GRID_DEEP_Y0_RATIO = 0.62
_POST_FOLLOW_LIKES_GRID_DEEP_Y1_RATIO = 0.92


def _post_follow_likes_grid_ui_surface_hints(d: u2.Device) -> dict[str, Any]:
    """Overlay + profile tab chrome for post-follow grid classification."""
    overlay = _post_follow_overlay_ui_hints(d)
    tabs_visible = False
    try:
        tabs_visible = bool(_followers_profile_tabs_visible(d))
    except Exception:
        tabs_visible = False
    return {
        "suggested_for_you": bool(overlay.get("suggested_for_you")),
        "discover_people": bool(overlay.get("discover_people")),
        "profile_tabs_visible": tabs_visible,
    }


def _visual_profile_post_grid_band_probe(
    im: Any,
    iw: int,
    ih: int,
    *,
    grid_y0_ratio: float = _POST_FOLLOW_LIKES_GRID_Y0_RATIO,
    grid_y1_ratio: float = _POST_FOLLOW_LIKES_GRID_Y1_RATIO,
    upper_y0_ratio: float = _POST_FOLLOW_LIKES_GRID_UPPER_Y0_RATIO,
    upper_y1_ratio: float = _POST_FOLLOW_LIKES_GRID_UPPER_Y1_RATIO,
    deep_y0_ratio: float = _POST_FOLLOW_LIKES_GRID_DEEP_Y0_RATIO,
    deep_y1_ratio: float = _POST_FOLLOW_LIKES_GRID_DEEP_Y1_RATIO,
    var_thr: float = _POST_FOLLOW_LIKES_GRID_VAR_THR,
    partial_var_thr: float = _POST_FOLLOW_LIKES_GRID_PARTIAL_VAR_THR,
    surface_hints: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Probe lower (post-grid) and upper-mid bands; classify visible / partial / not_visible."""
    cols = 3
    cell_w = max(24, iw // cols)
    cell_h = cell_w
    order = ((0, 0), (1, 0), (2, 0), (0, 1), (1, 1), (2, 1))

    def _band_stats(y0_ratio: float, y1_ratio: float) -> dict[str, Any]:
        y0 = int(ih * y0_ratio)
        y1 = int(ih * y1_ratio)
        max_v = 0.0
        solid = 0
        partial_cells = 0
        for col, row in order:
            x0 = col * cell_w
            cy0 = y0 + row * cell_h
            if cy0 + cell_h > y1 or x0 + cell_w > iw:
                continue
            v = _visual_image_cell_luma_variance(im, x0, cy0, cell_w, cell_h)
            max_v = max(max_v, float(v))
            if v >= var_thr:
                solid += 1
            elif v >= partial_var_thr:
                partial_cells += 1
        return {
            "max_variance": max_v,
            "solid_cell_count": solid,
            "partial_cell_count": partial_cells,
        }

    lower = _band_stats(grid_y0_ratio, grid_y1_ratio)
    upper = _band_stats(upper_y0_ratio, upper_y1_ratio)
    deep = _band_stats(deep_y0_ratio, deep_y1_ratio)
    lower_blank, lower_blank_conf = _visual_profile_lower_grid_mostly_blank(
        im,
        iw,
        ih,
        grid_y0_ratio=grid_y0_ratio,
        grid_y1_ratio=grid_y1_ratio,
        var_thr=partial_var_thr,
        min_blank_cells=4,
    )

    hints = surface_hints if isinstance(surface_hints, dict) else {}
    suggested = bool(hints.get("suggested_for_you"))
    discover = bool(hints.get("discover_people"))
    tabs_visible = bool(hints.get("profile_tabs_visible"))
    lower_solid = int(lower.get("solid_cell_count") or 0)
    deep_solid = int(deep.get("solid_cell_count") or 0)
    upper_solid = int(upper.get("solid_cell_count") or 0)
    overlay_blocks_visible = bool(suggested or discover)

    raw_visible = lower_solid >= 1
    grid_confirmed = bool(
        tabs_visible
        and deep_solid >= 1
        and (not overlay_blocks_visible or deep_solid >= 2)
    )

    if raw_visible and grid_confirmed and not overlay_blocks_visible:
        state = "visible"
    elif overlay_blocks_visible:
        if deep_solid >= 1 or lower_solid >= 1 or upper_solid >= 1:
            state = "partial"
        else:
            state = "not_visible"
    elif raw_visible and tabs_visible and deep_solid >= 1:
        state = "visible"
    elif raw_visible:
        state = "partial"
    elif bool(lower_blank) and float(upper.get("max_variance") or 0.0) >= var_thr:
        state = "partial"
    elif (
        float(lower.get("max_variance") or 0.0) >= partial_var_thr
        or int(lower.get("partial_cell_count") or 0) >= 1
        or float(upper.get("max_variance") or 0.0) >= var_thr
    ):
        state = "partial"
    else:
        state = "not_visible"

    return {
        "grid_state": state,
        "lower_max_variance": round(float(lower.get("max_variance") or 0.0), 2),
        "lower_solid_cell_count": lower_solid,
        "lower_partial_cell_count": int(lower.get("partial_cell_count") or 0),
        "lower_mostly_blank": bool(lower_blank),
        "lower_blank_confidence": round(float(lower_blank_conf), 4),
        "upper_max_variance": round(float(upper.get("max_variance") or 0.0), 2),
        "upper_solid_cell_count": upper_solid,
        "deep_lower_max_variance": round(float(deep.get("max_variance") or 0.0), 2),
        "deep_lower_solid_cell_count": deep_solid,
        "suggested_for_you": suggested,
        "discover_people": discover,
        "profile_tabs_visible": tabs_visible,
        "overlay_blocks_visible": overlay_blocks_visible,
        "grid_y0_ratio": grid_y0_ratio,
        "grid_y1_ratio": grid_y1_ratio,
        "deep_y0_ratio": deep_y0_ratio,
        "deep_y1_ratio": deep_y1_ratio,
    }


def _dynamic_first_post_grid_row_from_image(
    im: Any,
    iw: int,
    ih: int,
    *,
    var_thr: float = _POST_FOLLOW_LIKES_GRID_VAR_THR,
    search_y_min_ratio: float = 0.20,
    search_y_max_ratio: float = 0.62,
    search_y_min_px: int | None = None,
) -> dict[str, Any]:
    """
    Scan below the tab band for the topmost Y band that looks like a real 3-wide post row
    (variance in image cells). Used to avoid a fixed grid_y0_ratio missing the physical first row.
    When ``search_y_min_px`` is set (e.g. tab strip bottom + margin), it overrides the ratio floor.
    """
    if ih < 120 or iw < 120:
        return {"ok": False}
    cols = 3
    cell_w = max(24, iw // cols)
    cell_h = cell_w
    if search_y_min_px is not None:
        y_lo = max(8, int(search_y_min_px))
    else:
        y_lo = max(8, int(ih * float(search_y_min_ratio)))
    y_hi_ratio = int(ih * float(search_y_max_ratio))
    y_hi = min(ih - 2 * cell_h - 12, y_hi_ratio)
    if search_y_min_px is not None:
        y_hi = min(ih - 2 * cell_h - 12, max(y_hi, y_lo + cell_h + 8))
    step = max(4, cell_h // 5)
    if y_hi <= y_lo + step:
        return {"ok": False}

    ranked: list[tuple[int, int]] = []
    gy = y_lo
    while gy <= y_hi:
        solids = 0
        for col in (0, 1, 2):
            x0 = col * cell_w
            if x0 + cell_w > iw:
                continue
            try:
                v = _visual_image_cell_luma_variance(im, x0, gy, cell_w, cell_h)
            except Exception:
                v = 0.0
            if float(v) >= float(var_thr):
                solids += 1
        if solids >= 1:
            ranked.append((solids, gy))
        gy += step
    if not ranked:
        return {"ok": False}
    ranked.sort(key=lambda t: (-t[0], t[1]))
    best_solid, gy_best = ranked[0]
    return {
        "ok": True,
        "first_row_top": int(gy_best),
        "first_row_bottom": int(gy_best + cell_h),
        "solid_count": int(best_solid),
        "cell_h": int(cell_h),
    }


def _single_post_sparse_grid_has_post_tile_proof(probe: dict[str, Any]) -> bool:
    """True when probe shows a real first-row post tile under profile tabs."""
    if bool(probe.get("dynamic_first_row_probe_ok")):
        dyn_sc = int(probe.get("dynamic_first_row_solid_count") or 0)
        if 1 <= dyn_sc <= 3:
            return True
    lower_solid = int(probe.get("lower_solid_cell_count") or 0)
    upper_solid = int(probe.get("upper_solid_cell_count") or 0)
    if lower_solid >= 1 and (lower_solid + upper_solid) <= 3:
        return True
    return False


def _single_post_candidate_proven_below_profile_tabs(
    probe: dict[str, Any],
) -> tuple[bool, str]:
    """
    True when dynamic first-row scan is anchored on tab-strip bottom and the row top
    sits strictly below tabs + margin (never Suggested / highlights above tabs).
    """
    if not bool(probe.get("profile_tabs_visible")):
        return False, "profile_tabs_not_visible"
    tabs_bt = probe.get("profile_tabs_bottom_y_px")
    if tabs_bt is None:
        return False, "profile_tabs_bottom_unknown"
    try:
        tabs_bt_i = int(tabs_bt)
    except (TypeError, ValueError):
        return False, "profile_tabs_bottom_invalid"
    margin = int(
        probe.get("profile_tabs_grid_margin_px") or _POST_FOLLOW_PROFILE_TABS_GRID_MARGIN_PX
    )
    if str(probe.get("dynamic_first_row_search_y_min_source") or "").strip() != (
        "profile_tabs_bottom"
    ):
        return False, "dynamic_first_row_search_y_min_not_profile_tabs_bottom"
    if not bool(probe.get("dynamic_first_row_probe_ok")):
        return False, "dynamic_first_row_probe_not_ok"
    row_top = probe.get("dynamic_first_row_top")
    if row_top is None:
        return False, "dynamic_first_row_top_missing"
    try:
        row_top_i = int(row_top)
    except (TypeError, ValueError):
        return False, "dynamic_first_row_top_invalid"
    y_floor = tabs_bt_i + margin
    if row_top_i < y_floor - 2:
        return False, "candidate_above_profile_tabs"
    dyn_sc = int(probe.get("dynamic_first_row_solid_count") or 0)
    if not (1 <= dyn_sc <= 3):
        return False, "dynamic_first_row_solid_count_out_of_range"
    return True, ""


def _post_follow_merge_tabs_layout_into_probe(
    probe: dict[str, Any],
    *,
    search_y_min_px: int,
    search_y_min_src: str,
    profile_tabs_bottom_y_px: int | None,
    tabs_margin_px: int,
    ui_hints: dict[str, Any],
) -> None:
    probe["profile_tabs_bottom_y_px"] = profile_tabs_bottom_y_px
    probe["dynamic_first_row_search_y_min_px"] = int(search_y_min_px)
    probe["dynamic_first_row_search_y_min_source"] = str(search_y_min_src or "")
    probe["profile_tabs_grid_margin_px"] = int(tabs_margin_px)
    below_ok, below_reason = _single_post_candidate_proven_below_profile_tabs(probe)
    probe["candidate_below_profile_tabs"] = bool(below_ok)
    probe["single_post_below_tabs_detail"] = str(below_reason or "")[:120]
    _ov = bool(
        ui_hints.get("suggested_for_you") or ui_hints.get("discover_people")
    )
    probe["suggested_for_you_above_tabs"] = bool(
        _ov and profile_tabs_bottom_y_px is not None and not below_ok
    )


def _log_single_post_sparse_grid_rejected(
    probe: dict[str, Any],
    reject_reason: str,
    **extra: Any,
) -> None:
    below_ok, below_detail = _single_post_candidate_proven_below_profile_tabs(probe)
    try:
        log(
            "info",
            "post_follow_post_likes_single_post_sparse_grid_rejected",
            reject_reason=str(reject_reason or "")[:160],
            suggested_for_you=probe.get("suggested_for_you"),
            discover_people=probe.get("discover_people"),
            suggested_for_you_above_tabs=probe.get("suggested_for_you_above_tabs"),
            profile_tabs_visible=probe.get("profile_tabs_visible"),
            profile_tabs_bottom_y_px=probe.get("profile_tabs_bottom_y_px"),
            dynamic_first_row_search_y_min_px=probe.get("dynamic_first_row_search_y_min_px"),
            dynamic_first_row_search_y_min_source=probe.get(
                "dynamic_first_row_search_y_min_source"
            ),
            dynamic_first_row_solid_count=probe.get("dynamic_first_row_solid_count"),
            dynamic_first_row_top=probe.get("dynamic_first_row_top"),
            dynamic_first_row_probe_ok=probe.get("dynamic_first_row_probe_ok"),
            candidate_below_profile_tabs=bool(below_ok),
            single_post_below_tabs_detail=str(below_detail or "")[:120],
            lower_mostly_blank=probe.get("lower_mostly_blank"),
            lower_solid_cell_count=probe.get("lower_solid_cell_count"),
            **extra,
        )
    except Exception:
        pass


def _single_post_sparse_grid_accept_log_fields(probe: dict[str, Any]) -> dict[str, Any]:
    below_ok, _ = _single_post_candidate_proven_below_profile_tabs(probe)
    return {
        "suggested_for_you": probe.get("suggested_for_you"),
        "discover_people": probe.get("discover_people"),
        "suggested_for_you_above_tabs": probe.get("suggested_for_you_above_tabs"),
        "profile_tabs_visible": probe.get("profile_tabs_visible"),
        "profile_tabs_bottom_y_px": probe.get("profile_tabs_bottom_y_px"),
        "dynamic_first_row_search_y_min_px": probe.get("dynamic_first_row_search_y_min_px"),
        "dynamic_first_row_search_y_min_source": probe.get(
            "dynamic_first_row_search_y_min_source"
        ),
        "dynamic_first_row_solid_count": probe.get("dynamic_first_row_solid_count"),
        "dynamic_first_row_top": probe.get("dynamic_first_row_top"),
        "dynamic_first_row_probe_ok": probe.get("dynamic_first_row_probe_ok"),
        "candidate_below_profile_tabs": bool(below_ok),
        "profile_tabs_grid_margin_px": probe.get("profile_tabs_grid_margin_px"),
    }


def _single_post_sparse_grid_acceptable_for_post_follow(
    probe: dict[str, Any],
    *,
    log_reject: bool = True,
) -> bool:
    """
    Very sparse profile grids (1–3 posts on one row, mostly blank lower band).
    Does not require deep_lower_solid_cell_count (no second row on true 1-post profiles).

    When Suggested for you is visible above tabs, accept only if dynamic first-row proof
    shows the candidate row strictly below profile_tabs_bottom_y_px + margin.
    """
    if str(probe.get("grid_state") or "").strip().lower() != "partial":
        if log_reject:
            _log_single_post_sparse_grid_rejected(probe, "grid_state_not_partial")
        return False
    if not bool(probe.get("profile_tabs_visible")):
        if log_reject:
            _log_single_post_sparse_grid_rejected(probe, "profile_tabs_not_visible")
        return False

    suggested = bool(probe.get("suggested_for_you"))
    discover = bool(probe.get("discover_people"))
    overlay = bool(suggested or discover)
    below_tabs, below_reason = _single_post_candidate_proven_below_profile_tabs(probe)

    if overlay and below_tabs:
        if not _single_post_sparse_grid_has_post_tile_proof(probe):
            if log_reject:
                _log_single_post_sparse_grid_rejected(
                    probe,
                    "no_post_tile_proof_below_tabs",
                    single_post_below_tabs_detail=below_reason,
                )
            return False
        return True

    if overlay and not below_tabs:
        if log_reject:
            _log_single_post_sparse_grid_rejected(
                probe,
                (
                    "suggested_for_you_candidate_not_proven_below_tabs"
                    if suggested
                    else "discover_people_candidate_not_proven_below_tabs"
                ),
                single_post_below_tabs_detail=below_reason,
            )
        return False

    if bool(probe.get("overlay_blocks_visible")):
        if log_reject:
            _log_single_post_sparse_grid_rejected(probe, "overlay_blocks_visible")
        return False
    if not bool(probe.get("lower_mostly_blank")):
        if log_reject:
            _log_single_post_sparse_grid_rejected(probe, "lower_band_not_mostly_blank")
        return False
    if not _single_post_sparse_grid_has_post_tile_proof(probe):
        if log_reject:
            _log_single_post_sparse_grid_rejected(probe, "no_post_tile_proof")
        return False
    dyn_sc = int(probe.get("dynamic_first_row_solid_count") or 0)
    if bool(probe.get("dynamic_first_row_probe_ok")) and 1 <= dyn_sc <= 3:
        return True
    lower_solid = int(probe.get("lower_solid_cell_count") or 0)
    upper_solid = int(probe.get("upper_solid_cell_count") or 0)
    deep_solid = int(probe.get("deep_lower_solid_cell_count") or 0)
    total_solids = lower_solid + upper_solid + deep_solid
    if not (1 <= total_solids <= 6):
        if log_reject:
            _log_single_post_sparse_grid_rejected(
                probe,
                "total_solid_cell_count_out_of_range",
                total_solid_cell_count=total_solids,
            )
        return False
    return True


def _post_follow_sparse_post_scroll_grid_acceptable(
    probe: dict[str, Any],
    *,
    scroll_used: bool,
) -> bool:
    """
    After profile scroll only: partial grid with real tiles below tabs may open even if
    suggested_for_you XML hint remains true (lolie/emistyle class of false negatives).
    """
    if not scroll_used:
        return False
    if str(probe.get("grid_state") or "").strip().lower() != "partial":
        return False
    if not bool(probe.get("profile_tabs_visible")):
        return False
    if int(probe.get("lower_solid_cell_count") or 0) < 3:
        return False
    if not bool(probe.get("dynamic_first_row_probe_ok")):
        return False
    if not _single_post_sparse_grid_has_post_tile_proof(probe):
        return False
    below_ok, _ = _single_post_candidate_proven_below_profile_tabs(probe)
    return bool(below_ok)


def _sparse_post_grid_partial_acceptable_for_post_follow(
    probe: dict[str, Any],
    *,
    scroll_used: bool = False,
) -> bool:
    """Single-row / sparse grids: accept partial band state only under strict anti-Suggested guards."""
    if scroll_used and _post_follow_sparse_post_scroll_grid_acceptable(
        probe, scroll_used=True
    ):
        return True
    if str(probe.get("grid_state") or "").strip().lower() != "partial":
        return False
    if not bool(probe.get("profile_tabs_visible")):
        return False
    if _single_post_sparse_grid_acceptable_for_post_follow(probe, log_reject=False):
        return True
    if bool(probe.get("suggested_for_you")) or bool(probe.get("discover_people")):
        _log_single_post_sparse_grid_rejected(
            probe,
            "suggested_for_you_candidate_not_proven_below_tabs",
        )
        return False
    if bool(probe.get("overlay_blocks_visible")):
        return False
    solids = (
        int(probe.get("upper_solid_cell_count") or 0)
        + int(probe.get("lower_solid_cell_count") or 0)
        + int(probe.get("deep_lower_solid_cell_count") or 0)
    )
    return solids >= 1


def _post_follow_merge_grid_probe_meta(
    out: dict[str, Any], probe: dict[str, Any]
) -> None:
    out["dynamic_first_row_probe_ok"] = bool(probe.get("dynamic_first_row_probe_ok"))
    out["dynamic_first_row_top"] = probe.get("dynamic_first_row_top")
    out["dynamic_first_row_bottom"] = probe.get("dynamic_first_row_bottom")
    out["dynamic_first_row_solid_count"] = probe.get("dynamic_first_row_solid_count")
    out["dynamic_first_row_cell_h"] = probe.get("dynamic_first_row_cell_h")
    out["grid_probe_screenshot_path"] = probe.get("screenshot_path")
    out["grid_probe_source"] = "post_follow_likes_grid_probe_same_capture"


def _post_follow_likes_profile_scroll_swipe(
    d: u2.Device,
    *,
    scroll_profile: str,
    ww: int,
    wh: int,
) -> dict[str, Any]:
    """Bounded vertical swipe on profile to reveal post grid (finger up = content down)."""
    sp = str(scroll_profile or "micro").strip().lower()
    xmid = int(ww * 0.5)
    if sp == "long":
        y_start = int(wh * 0.72)
        y_end = int(wh * 0.38)
        duration_s = 0.14
    else:
        y_start = int(wh * 0.58)
        y_end = int(wh * 0.48)
        duration_s = 0.11
    y_start = max(int(wh * 0.22), min(int(wh * 0.88), y_start))
    y_end = max(int(wh * 0.12), min(y_start - 8, y_end))
    try:
        _followers_log_scroll_or_swipe_about_to_run(
            d,
            source_function="_post_follow_likes_profile_scroll_swipe",
            reason=f"post_follow_likes_grid_{sp}",
        )
        d.swipe(xmid, y_start, xmid, y_end, duration_s)
        swipe_ok = True
    except Exception as e:
        return {
            "swipe_ok": False,
            "scroll_profile": sp,
            "y_start": y_start,
            "y_end": y_end,
            "duration_s": duration_s,
            "error": str(e),
        }
    return {
        "swipe_ok": True,
        "scroll_profile": sp,
        "y_start": y_start,
        "y_end": y_end,
        "duration_s": duration_s,
        "error": None,
    }


def _post_follow_likes_profile_still_on_candidate(
    d: u2.Device,
    *,
    follower_username: str,
    pkg: str,
) -> tuple[bool, str]:
    """Light guard: still on a profile surface and action bar matches follower when known."""
    fu = str(follower_username or "").strip().lstrip("@")
    try:
        prof = bool(
            _try_profile_signals_once(d, "", pkg)
            or _guess_profile_screen(d, pkg, "")
            in ("likely_profile", "profile_header_rid", "action_bar_title")
        )
    except Exception:
        prof = False
    if not prof:
        return False, "not_profile_surface"
    if not fu:
        return True, ""
    try:
        ab = str(read_current_profile_username_for_follow_gate(d) or "").strip().lstrip("@")
    except Exception:
        ab = ""
    if ab and _normalize_handle(ab) == _normalize_handle(fu):
        return True, ""
    if ab:
        return False, "action_bar_mismatch"
    return True, ""


def _likes_perf_elapsed_ms(phase_t0: float | None) -> float | None:
    if phase_t0 is None:
        return None
    return round((time.perf_counter() - float(phase_t0)) * 1000.0, 2)


def _likes_perf_subdict(val: Any) -> dict[str, Any]:
    return val if isinstance(val, dict) else {}


def _log_post_follow_post_likes_perf_summary(
    *,
    phase_outcome: str,
    visual_candidate_id: str,
    source_profile_username: str,
    follower_username: str,
    likes_phase_perf_t0: float,
    likes_phase_total_ms: float,
    likes_perf_grid: dict[str, Any] | None,
    likes_perf_post_open: dict[str, Any] | None,
    likes_perf_like: dict[str, Any] | None,
    already_liked_decision_ms: float | None,
    like_verify_total_ms: float | None,
    verify_attempts_count: int | None,
    verification_method: str | None,
    verify_success: bool | None,
    like_verify_failure_reason: str | None,
    return_to_profile_total_ms: float | None,
    return_success: bool | None,
    grid_readiness_mode: str | None,
    final_grid_state: str | None,
    final_suggested_for_you: Any,
    final_profile_tabs_visible: Any,
    failure_reason: str | None,
) -> None:
    """Single grep-friendly JSON-shaped log line for post-follow likes phase perf."""
    g = _likes_perf_subdict(likes_perf_grid)
    init_p = _likes_perf_subdict(g.get("initial_probe_ms"))
    scroll_cycles = [
        c for c in (g.get("scroll_cycles") or []) if isinstance(c, dict)
    ]
    sc1 = scroll_cycles[0] if len(scroll_cycles) > 0 else {}
    sc2 = scroll_cycles[1] if len(scroll_cycles) > 1 else {}
    po = _likes_perf_subdict(likes_perf_post_open)
    lk = _likes_perf_subdict(likes_perf_like)
    try:
        log(
            "info",
            "post_follow_post_likes_perf_summary_emit_started",
            visual_candidate_id=str(visual_candidate_id or ""),
            source_profile_username=str(source_profile_username or ""),
            follower_username=str(follower_username or ""),
            phase_outcome=str(phase_outcome or ""),
        )
    except Exception:
        pass
    try:
        # Second positional arg to log() is the event name — do not pass event= again.
        log(
            "info",
            "post_follow_post_likes_perf_summary",
            phase_outcome=str(phase_outcome or ""),
            visual_candidate_id=str(visual_candidate_id or ""),
            source_profile_username=str(source_profile_username or ""),
            follower_username=str(follower_username or ""),
            likes_phase_total_ms=round(float(likes_phase_total_ms), 2),
            initial_grid_probe_ms=init_p.get("initial_probe_total_ms"),
            budget_snapshot_ms=g.get("budget_snapshot_ms"),
            grid_prepare_total_ms=g.get("grid_prepare_total_ms"),
            scroll_attempts_used=len(scroll_cycles),
            scroll_cycle_1_total_ms=sc1.get("scroll_cycle_wall_ms"),
            scroll_cycle_2_total_ms=sc2.get("scroll_cycle_wall_ms"),
            post_open_total_ms=po.get("post_open_total_ms"),
            opened_on_first_tap=po.get("opened_on_first_tap"),
            retry_used=po.get("retry_used"),
            retry_total_ms=po.get("retry_total_ms"),
            like_target_detection_ms=lk.get("like_target_detection_ms"),
            like_verify_total_ms=like_verify_total_ms,
            verify_attempts_count=verify_attempts_count,
            verification_method=verification_method,
            verify_success=verify_success,
            like_verify_failure_reason=like_verify_failure_reason,
            return_to_profile_total_ms=return_to_profile_total_ms,
            return_success=return_success,
            already_liked_decision_ms=already_liked_decision_ms,
            post_open_context_guard_ms=lk.get("post_open_context_guard_ms"),
            still_profile_grid_probe_ms=lk.get("still_profile_grid_probe_ms"),
            grid_readiness_mode=grid_readiness_mode,
            final_grid_state=final_grid_state,
            final_suggested_for_you=final_suggested_for_you,
            final_profile_tabs_visible=final_profile_tabs_visible,
            failure_reason=failure_reason,
            like_tap_dispatch_ms=lk.get("like_tap_dispatch_ms"),
            like_tap_sent=lk.get("like_tap_sent"),
            already_liked=lk.get("already_liked"),
            perf_t0_monotonic=float(likes_phase_perf_t0),
            elapsed_from_phase_start_ms=_likes_perf_elapsed_ms(likes_phase_perf_t0),
        )
    except Exception as e:
        try:
            log(
                "warning",
                "post_follow_post_likes_perf_summary_emit_failed",
                visual_candidate_id=str(visual_candidate_id or ""),
                source_profile_username=str(source_profile_username or ""),
                follower_username=str(follower_username or ""),
                phase_outcome=str(phase_outcome or ""),
                error=str(e)[:240],
            )
        except Exception:
            pass
        return
    try:
        log(
            "info",
            "post_follow_post_likes_perf_summary_emit_done",
            visual_candidate_id=str(visual_candidate_id or ""),
            source_profile_username=str(source_profile_username or ""),
            follower_username=str(follower_username or ""),
            phase_outcome=str(phase_outcome or ""),
            likes_phase_total_ms=round(float(likes_phase_total_ms), 2),
        )
    except Exception:
        pass


def ensure_post_grid_visible_for_post_follow_likes(
    d: u2.Device,
    *,
    source_profile_username: str | None = None,
    follower_username: str | None = None,
    visual_candidate_id: str | None = None,
    budget_s: float | None = None,
    likes_perf_phase_t0: float | None = None,
    likes_perf_follow_state_after: str | None = None,
) -> dict[str, Any]:
    """
    Before post-follow open: probe lower post grid band, scroll profile if needed (max 2 swipes).
    """
    t0 = time.perf_counter()
    pkg = str(getattr(config, "INSTAGRAM_PACKAGE", "") or "")
    src = str(source_profile_username or "").strip()
    cand = str(follower_username or "").strip().lstrip("@")
    vcid = str(visual_candidate_id or "").strip()
    budget = max(2.5, float(budget_s or 8.0))
    timings: dict[str, float] = {}
    scroll_profiles_used: list[str] = []
    screenshot_paths: list[str] = []
    scroll_perf_cycles: list[dict[str, Any]] = []
    budget_snapshot_total_ms: float | None = None

    def _probe_once() -> tuple[dict[str, Any], str | None, dict[str, float]]:
        pperf: dict[str, float] = {}
        t_probe0 = time.perf_counter()
        _ensure_debug_dirs()
        shot = str(
            _SCREENSHOTS_DIR
            / f"post_follow_likes_grid_probe_{int(time.time() * 1000)}.png"
        )
        t_cap0 = time.perf_counter()
        try:
            screenshot(d, shot)
        except Exception as e:
            pperf["initial_probe_total_ms"] = round(
                (time.perf_counter() - t_probe0) * 1000.0, 2
            )
            return {}, f"screenshot_failed:{e}", pperf
        pperf["initial_probe_screenshot_capture_ms"] = round(
            (time.perf_counter() - t_cap0) * 1000.0, 2
        )
        screenshot_paths.append(shot)
        t_pil0 = time.perf_counter()
        try:
            from PIL import Image

            im = Image.open(shot).convert("RGB")
        except Exception as e:
            pperf["initial_probe_total_ms"] = round(
                (time.perf_counter() - t_probe0) * 1000.0, 2
            )
            return {}, f"pil_failed:{e}", pperf
        pperf["initial_probe_pil_decode_ms"] = round(
            (time.perf_counter() - t_pil0) * 1000.0, 2
        )
        iw, ih = im.size
        t_ui0 = time.perf_counter()
        ui_hints = _post_follow_likes_grid_ui_surface_hints(d)
        pperf["initial_probe_ui_hints_ms"] = round(
            (time.perf_counter() - t_ui0) * 1000.0, 2
        )
        t_band0 = time.perf_counter()
        probe = _visual_profile_post_grid_band_probe(
            im, iw, ih, surface_hints=ui_hints
        )
        pperf["initial_probe_image_band_probe_ms"] = round(
            (time.perf_counter() - t_band0) * 1000.0, 2
        )
        probe["screenshot_path"] = shot
        probe["image_w"] = iw
        probe["image_h"] = ih
        t_layout0 = time.perf_counter()
        (
            search_y_min_px,
            search_y_min_src,
            profile_tabs_bottom_y_px,
            tabs_margin_px,
        ) = _post_follow_dynamic_first_row_search_y_min_layout(d, ih, ui_hints)
        pperf["initial_probe_tabs_bottom_layout_ms"] = round(
            (time.perf_counter() - t_layout0) * 1000.0, 2
        )
        _ov_block = bool(
            ui_hints.get("suggested_for_you") or ui_hints.get("discover_people")
        )
        t_dyn0 = time.perf_counter()
        dyn = _dynamic_first_post_grid_row_from_image(
            im,
            iw,
            ih,
            var_thr=_POST_FOLLOW_LIKES_GRID_VAR_THR,
            search_y_min_px=int(search_y_min_px),
        )
        pperf["initial_probe_dynamic_first_row_ms"] = round(
            (time.perf_counter() - t_dyn0) * 1000.0, 2
        )
        pperf["initial_probe_image_analysis_ms"] = round(
            pperf.get("initial_probe_image_band_probe_ms", 0.0)
            + pperf.get("initial_probe_dynamic_first_row_ms", 0.0),
            2,
        )
        if bool(dyn.get("ok")):
            probe["dynamic_first_row_probe_ok"] = True
            probe["dynamic_first_row_top"] = dyn.get("first_row_top")
            probe["dynamic_first_row_bottom"] = dyn.get("first_row_bottom")
            probe["dynamic_first_row_solid_count"] = dyn.get("solid_count")
            probe["dynamic_first_row_cell_h"] = dyn.get("cell_h")
            try:
                _ymin_ratio = round(float(search_y_min_px) / float(ih), 5)
                log(
                    "info",
                    "post_follow_post_likes_dynamic_grid_first_row_resolved",
                    visual_candidate_id=vcid,
                    source_profile_username=src,
                    follower_username=cand,
                    first_row_top=dyn.get("first_row_top"),
                    first_row_bottom=dyn.get("first_row_bottom"),
                    grid_probe_source="post_follow_likes_grid_probe_same_capture",
                    screenshot_path=shot,
                    solid_count=dyn.get("solid_count"),
                    cell_h=dyn.get("cell_h"),
                    overlay_blocks_post_grid_top_hint=_ov_block,
                    dynamic_first_row_search_y_min_ratio=_ymin_ratio,
                    profile_tabs_bottom_y_px=profile_tabs_bottom_y_px,
                    dynamic_first_row_search_y_min_px=int(search_y_min_px),
                    dynamic_first_row_search_y_min_source=str(search_y_min_src),
                    profile_tabs_grid_margin_px=int(tabs_margin_px),
                    candidate_row_above_profile_tabs_blocked=False,
                )
            except Exception:
                pass
        else:
            probe["dynamic_first_row_probe_ok"] = False
            probe["dynamic_first_row_top"] = None
            probe["dynamic_first_row_bottom"] = None
            probe["dynamic_first_row_solid_count"] = None
            probe["dynamic_first_row_cell_h"] = None
        _post_follow_merge_tabs_layout_into_probe(
            probe,
            search_y_min_px=int(search_y_min_px),
            search_y_min_src=str(search_y_min_src),
            profile_tabs_bottom_y_px=profile_tabs_bottom_y_px,
            tabs_margin_px=int(tabs_margin_px),
            ui_hints=ui_hints,
        )
        pperf["initial_probe_total_ms"] = round(
            (time.perf_counter() - t_probe0) * 1000.0, 2
        )
        return probe, None, pperf

    def _log_checked(probe: dict[str, Any], *, phase: str) -> None:
        st = str(probe.get("grid_state") or "")
        log(
            "info",
            "post_follow_post_likes_grid_visibility_checked",
            visual_candidate_id=vcid,
            source_profile_username=src,
            follower_username=cand,
            phase=phase,
            grid_state=st,
            lower_max_variance=probe.get("lower_max_variance"),
            lower_solid_cell_count=probe.get("lower_solid_cell_count"),
            lower_partial_cell_count=probe.get("lower_partial_cell_count"),
            lower_mostly_blank=probe.get("lower_mostly_blank"),
            upper_max_variance=probe.get("upper_max_variance"),
            deep_lower_solid_cell_count=probe.get("deep_lower_solid_cell_count"),
            suggested_for_you=probe.get("suggested_for_you"),
            profile_tabs_visible=probe.get("profile_tabs_visible"),
            screenshot_path=probe.get("screenshot_path"),
        )
        if st == "partial":
            log(
                "info",
                "post_follow_post_likes_grid_partial_visible",
                visual_candidate_id=vcid,
                source_profile_username=src,
                follower_username=cand,
                phase=phase,
                lower_max_variance=probe.get("lower_max_variance"),
                upper_max_variance=probe.get("upper_max_variance"),
                screenshot_path=probe.get("screenshot_path"),
            )
        elif st == "not_visible":
            log(
                "info",
                "post_follow_post_likes_grid_not_visible",
                visual_candidate_id=vcid,
                source_profile_username=src,
                follower_username=cand,
                phase=phase,
                lower_max_variance=probe.get("lower_max_variance"),
                screenshot_path=probe.get("screenshot_path"),
            )

    out: dict[str, Any] = {
        "ok": False,
        "grid_state_before": "",
        "grid_state_after": "",
        "scroll_used": False,
        "scroll_profile": None,
        "scroll_profiles_used": [],
        "attempts": 0,
        "failure_reason": None,
        "partial_sparse_grid_accepted": False,
        "sparse_grid_accepted": False,
        "screenshot_paths": screenshot_paths,
        "timings_ms": timings,
    }

    if (time.perf_counter() - t0) > budget:
        out["failure_reason"] = "grid_prep_budget_exceeded"
        timings["grid_prep_total_ms"] = round((time.perf_counter() - t0) * 1000, 2)
        out["timings_ms"] = timings
        out["likes_perf_grid"] = {
            "initial_probe_ms": {},
            "scroll_cycles": list(scroll_perf_cycles),
        }
        return out

    if likes_perf_phase_t0 is not None:
        try:
            log(
                "info",
                "post_follow_post_likes_perf_phase_entered",
                visual_candidate_id=vcid,
                source_profile_username=src,
                follower_username=cand,
                perf_t0_monotonic=float(likes_perf_phase_t0),
                follow_state_after=str(likes_perf_follow_state_after or ""),
                elapsed_to_first_grid_probe_ms=_likes_perf_elapsed_ms(
                    likes_perf_phase_t0
                ),
            )
        except Exception:
            pass

    probe0, perr, p0perf = _probe_once()
    if perr:
        out["failure_reason"] = perr
        timings["grid_prep_total_ms"] = round((time.perf_counter() - t0) * 1000, 2)
        out["timings_ms"] = timings
        out["likes_perf_grid"] = {
            "initial_probe_ms": dict(p0perf),
            "scroll_cycles": list(scroll_perf_cycles),
        }
        return out

    probe_last: dict[str, Any] = probe0
    state = str(probe0.get("grid_state") or "not_visible")
    out["grid_state_before"] = state
    _log_checked(probe0, phase="initial")
    try:
        log(
            "info",
            "post_follow_post_likes_perf_initial_grid_probe_done",
            visual_candidate_id=vcid,
            source_profile_username=src,
            follower_username=cand,
            elapsed_from_phase_start_ms=_likes_perf_elapsed_ms(likes_perf_phase_t0),
            initial_probe_total_ms=p0perf.get("initial_probe_total_ms"),
            initial_probe_screenshot_capture_ms=p0perf.get(
                "initial_probe_screenshot_capture_ms"
            ),
            initial_probe_pil_decode_ms=p0perf.get("initial_probe_pil_decode_ms"),
            initial_probe_ui_hints_ms=p0perf.get("initial_probe_ui_hints_ms"),
            initial_probe_image_band_probe_ms=p0perf.get(
                "initial_probe_image_band_probe_ms"
            ),
            initial_probe_tabs_bottom_layout_ms=p0perf.get(
                "initial_probe_tabs_bottom_layout_ms"
            ),
            initial_probe_dynamic_first_row_ms=p0perf.get(
                "initial_probe_dynamic_first_row_ms"
            ),
            initial_probe_image_analysis_ms=p0perf.get(
                "initial_probe_image_analysis_ms"
            ),
            grid_state=probe0.get("grid_state"),
            suggested_for_you=probe0.get("suggested_for_you"),
            profile_tabs_visible=probe0.get("profile_tabs_visible"),
            lower_solid_cell_count=probe0.get("lower_solid_cell_count"),
            deep_lower_solid_cell_count=probe0.get("deep_lower_solid_cell_count"),
        )
    except Exception:
        pass

    if state != "visible" and _sparse_post_grid_partial_acceptable_for_post_follow(
        probe0
    ):
        out["ok"] = True
        out["grid_state_after"] = str(probe0.get("grid_state") or "partial")
        out["failure_reason"] = None
        out["partial_sparse_grid_accepted"] = True
        out["sparse_grid_accepted"] = True
        _single_sparse0 = _single_post_sparse_grid_acceptable_for_post_follow(probe0)
        _post_follow_merge_grid_probe_meta(out, probe0)
        try:
            if _single_sparse0:
                log(
                    "info",
                    "post_follow_post_likes_single_post_sparse_grid_accepted",
                    visual_candidate_id=vcid,
                    source_profile_username=src,
                    follower_username=cand,
                    acceptance_phase="initial",
                    grid_state_after=str(probe0.get("grid_state") or ""),
                    lower_solid_cell_count=probe0.get("lower_solid_cell_count"),
                    upper_solid_cell_count=probe0.get("upper_solid_cell_count"),
                    deep_lower_solid_cell_count=probe0.get(
                        "deep_lower_solid_cell_count"
                    ),
                    lower_mostly_blank=probe0.get("lower_mostly_blank"),
                    screenshot_path=probe0.get("screenshot_path"),
                    **_single_post_sparse_grid_accept_log_fields(probe0),
                )
            else:
                log(
                    "info",
                    "post_follow_post_likes_sparse_grid_accepted",
                    visual_candidate_id=vcid,
                    source_profile_username=src,
                    follower_username=cand,
                    acceptance_phase="initial",
                    partial_sparse_grid_accepted=True,
                    grid_state_after=str(probe0.get("grid_state") or ""),
                    lower_solid_cell_count=probe0.get("lower_solid_cell_count"),
                    upper_solid_cell_count=probe0.get("upper_solid_cell_count"),
                    deep_lower_solid_cell_count=probe0.get(
                        "deep_lower_solid_cell_count"
                    ),
                    profile_tabs_visible=probe0.get("profile_tabs_visible"),
                    screenshot_path=probe0.get("screenshot_path"),
                )
        except Exception:
            pass
        timings["grid_prep_total_ms"] = round((time.perf_counter() - t0) * 1000, 2)
        out["timings_ms"] = timings
        out["screenshot_paths"] = screenshot_paths
        try:
            log(
                "info",
                "post_follow_post_likes_perf_grid_ready",
                visual_candidate_id=vcid,
                source_profile_username=src,
                follower_username=cand,
                readiness_mode="sparse_accepted",
                total_grid_prepare_ms=timings.get("grid_prep_total_ms"),
                scroll_attempts_used=0,
                final_grid_state=str(probe0.get("grid_state") or ""),
                final_suggested_for_you=probe0.get("suggested_for_you"),
                final_profile_tabs_visible=probe0.get("profile_tabs_visible"),
                elapsed_from_phase_start_ms=_likes_perf_elapsed_ms(
                    likes_perf_phase_t0
                ),
            )
        except Exception:
            pass
        out["likes_perf_grid"] = {
            "initial_probe_ms": dict(p0perf),
            "scroll_cycles": list(scroll_perf_cycles),
            "grid_prepare_total_ms": timings.get("grid_prep_total_ms"),
        }
        return out

    if state == "visible":
        out["ok"] = True
        out["grid_state_after"] = "visible"
        log(
            "info",
            "post_follow_post_likes_grid_visible_confirmed",
            visual_candidate_id=vcid,
            source_profile_username=src,
            follower_username=cand,
            phase="initial",
            scroll_used=False,
            screenshot_path=probe0.get("screenshot_path"),
        )
        timings["grid_prep_total_ms"] = round((time.perf_counter() - t0) * 1000, 2)
        out["timings_ms"] = timings
        out["screenshot_paths"] = screenshot_paths
        _post_follow_merge_grid_probe_meta(out, probe0)
        try:
            log(
                "info",
                "post_follow_post_likes_perf_grid_ready",
                visual_candidate_id=vcid,
                source_profile_username=src,
                follower_username=cand,
                readiness_mode="visible_confirmed",
                total_grid_prepare_ms=timings.get("grid_prep_total_ms"),
                scroll_attempts_used=0,
                final_grid_state="visible",
                final_suggested_for_you=probe0.get("suggested_for_you"),
                final_profile_tabs_visible=probe0.get("profile_tabs_visible"),
                elapsed_from_phase_start_ms=_likes_perf_elapsed_ms(
                    likes_perf_phase_t0
                ),
            )
        except Exception:
            pass
        out["likes_perf_grid"] = {
            "initial_probe_ms": dict(p0perf),
            "scroll_cycles": list(scroll_perf_cycles),
            "grid_prepare_total_ms": timings.get("grid_prep_total_ms"),
        }
        return out

    try:
        ww, wh = d.window_size()
    except Exception:
        ww, wh = 1080, 2400

    t_budget_snap = time.perf_counter()
    elapsed_after_initial_probe_s = float(time.perf_counter() - t0)
    remaining_after_initial_probe_s = float(budget) - elapsed_after_initial_probe_s
    reserve_second_pass_s = float(
        getattr(config, "POST_FOLLOW_LIKES_GRID_SECOND_PASS_RESERVE_S", 5.5) or 5.5
    )
    reserve_second_pass_s = max(4.0, min(reserve_second_pass_s, 12.0))
    suggested_overlay = bool(probe0.get("suggested_for_you"))
    promote_long_first = (
        state == "partial"
        and suggested_overlay
        and remaining_after_initial_probe_s < reserve_second_pass_s
    )
    try:
        log(
            "info",
            "post_follow_post_likes_grid_budget_snapshot",
            visual_candidate_id=vcid,
            source_profile_username=src,
            follower_username=cand,
            budget_s_received=round(float(budget), 4),
            elapsed_inside_grid_prepare_after_initial_probe_s=round(
                elapsed_after_initial_probe_s, 4
            ),
            remaining_grid_budget_after_initial_probe_s=round(
                remaining_after_initial_probe_s, 4
            ),
            second_pass_reserve_s=round(reserve_second_pass_s, 4),
            suggested_for_you=suggested_overlay,
            grid_state_before=state,
            promote_long_first_on_partial=bool(promote_long_first),
        )
    except Exception:
        pass
    budget_snapshot_total_ms = round(
        (time.perf_counter() - t_budget_snap) * 1000.0, 2
    )
    try:
        log(
            "info",
            "post_follow_post_likes_perf_budget_snapshot_done",
            visual_candidate_id=vcid,
            source_profile_username=src,
            follower_username=cand,
            elapsed_from_phase_start_ms=_likes_perf_elapsed_ms(likes_perf_phase_t0),
            budget_snapshot_total_ms=budget_snapshot_total_ms,
            budget_s_received=round(float(budget), 4),
            remaining_grid_budget_after_initial_probe_s=round(
                remaining_after_initial_probe_s, 4
            ),
            promote_long_first_on_partial=bool(promote_long_first),
        )
    except Exception:
        pass
    if promote_long_first:
        try:
            log(
                "info",
                "post_follow_post_likes_scroll_strategy_promoted_to_long_due_to_budget",
                visual_candidate_id=vcid,
                source_profile_username=src,
                follower_username=cand,
                budget_s_received=round(float(budget), 4),
                elapsed_inside_grid_prepare_s=round(
                    elapsed_after_initial_probe_s, 4
                ),
                remaining_grid_budget_before_scroll=round(
                    remaining_after_initial_probe_s, 4
                ),
                suggested_for_you=bool(suggested_overlay),
                grid_state_before=state,
                chosen_scroll_profile="long",
                decision_reason=(
                    "partial_plus_suggested_overlay_and_remaining_budget_below_"
                    "second_pass_reserve_promote_long_first"
                ),
            )
        except Exception:
            pass

    attempts = 0
    state_after = state
    while attempts < 2 and (time.perf_counter() - t0) <= budget:
        t_cycle_wall_0 = time.perf_counter()
        sp = "micro" if state_after in ("partial", "visible") else "long"
        if attempts == 1 and state_after == "partial":
            sp = "long"
        if attempts == 0 and promote_long_first and state_after == "partial":
            sp = "long"
        grid_state_before_this_attempt = str(state_after)
        log(
            "info",
            "post_follow_post_likes_profile_scroll_started",
            visual_candidate_id=vcid,
            source_profile_username=src,
            follower_username=cand,
            scroll_profile=sp,
            attempt=attempts + 1,
            grid_state_before=state_after,
        )
        t_sw = time.perf_counter()
        sw = _post_follow_likes_profile_scroll_swipe(
            d, scroll_profile=sp, ww=ww, wh=wh
        )
        timings[f"profile_scroll_{attempts + 1}_ms"] = round(
            (time.perf_counter() - t_sw) * 1000, 2
        )
        attempts += 1
        out["scroll_used"] = True
        scroll_profiles_used.append(str(sw.get("scroll_profile") or sp))
        out["scroll_profile"] = scroll_profiles_used[-1]
        out["scroll_profiles_used"] = list(scroll_profiles_used)
        out["attempts"] = attempts

        if not sw.get("swipe_ok"):
            out["failure_reason"] = f"profile_scroll_failed:{sw.get('error')}"
            break

        log(
            "info",
            "post_follow_post_likes_profile_scroll_used",
            visual_candidate_id=vcid,
            source_profile_username=src,
            follower_username=cand,
            scroll_profile=sp,
            attempt=attempts,
            y_start=sw.get("y_start"),
            y_end=sw.get("y_end"),
            duration_s=sw.get("duration_s"),
            grid_state_before=state_after,
        )
        t_post_scroll0 = time.perf_counter()
        time.sleep(0.42)

        on_prof, why = _post_follow_likes_profile_still_on_candidate(
            d, follower_username=cand, pkg=pkg
        )
        if not on_prof:
            out["failure_reason"] = f"profile_lost_after_scroll:{why}"
            break

        probe1, perr1, p1perf = _probe_once()
        if perr1:
            out["failure_reason"] = perr1
            break
        probe_last = probe1
        state_after = str(probe1.get("grid_state") or "not_visible")
        _log_checked(probe1, phase=f"after_scroll_{attempts}")
        post_scroll_wait_and_reprobe_ms = round(
            (time.perf_counter() - t_post_scroll0) * 1000.0, 2
        )
        _dur_s = sw.get("duration_s")
        try:
            gesture_duration_ms = (
                round(float(_dur_s) * 1000.0, 2)
                if _dur_s is not None
                else None
            )
        except (TypeError, ValueError):
            gesture_duration_ms = None
        _scroll_cycle_rec: dict[str, Any] = {
            "attempt": int(attempts),
            "scroll_profile": str(sp),
            "grid_state_before": grid_state_before_this_attempt,
            "gesture_duration_ms": gesture_duration_ms,
            "profile_scroll_wall_ms": timings.get(f"profile_scroll_{attempts}_ms"),
            "post_scroll_wait_and_reprobe_ms": post_scroll_wait_and_reprobe_ms,
            "reprobe_probe_total_ms": p1perf.get("initial_probe_total_ms"),
            "scroll_cycle_wall_ms": round(
                (time.perf_counter() - t_cycle_wall_0) * 1000.0, 2
            ),
            "elapsed_from_phase_start_ms": _likes_perf_elapsed_ms(likes_perf_phase_t0),
            "resulting_grid_state": state_after,
            "suggested_for_you_after": probe1.get("suggested_for_you"),
            "profile_tabs_visible_after": probe1.get("profile_tabs_visible"),
        }
        scroll_perf_cycles.append(dict(_scroll_cycle_rec))
        try:
            log(
                "info",
                "post_follow_post_likes_perf_scroll_cycle_done",
                visual_candidate_id=vcid,
                source_profile_username=src,
                follower_username=cand,
                **_scroll_cycle_rec,
            )
        except Exception:
            pass

        if (
            state_after != "visible"
            and _post_follow_sparse_post_scroll_grid_acceptable(
                probe1, scroll_used=True
            )
        ):
            out["ok"] = True
            out["grid_state_after"] = str(probe1.get("grid_state") or "partial")
            out["failure_reason"] = None
            out["partial_sparse_grid_accepted"] = True
            out["sparse_grid_accepted"] = True
            out["sparse_post_scroll_accepted"] = True
            _post_follow_merge_grid_probe_meta(out, probe1)
            try:
                log(
                    "info",
                    "post_follow_post_grid_sparse_post_scroll_accepted",
                    visual_candidate_id=vcid,
                    source_profile_username=src,
                    follower_username=cand,
                    acceptance_phase=f"after_scroll_{attempts}",
                    lower_solid_cell_count=probe1.get("lower_solid_cell_count"),
                    dynamic_first_row_top=probe1.get("dynamic_first_row_top"),
                    profile_tabs_bottom_y_px=probe1.get("profile_tabs_bottom_y_px"),
                    suggested_for_you=probe1.get("suggested_for_you"),
                    screenshot_path=probe1.get("screenshot_path"),
                    **_single_post_sparse_grid_accept_log_fields(probe1),
                )
            except Exception:
                pass
            timings["grid_prep_total_ms"] = round((time.perf_counter() - t0) * 1000, 2)
            out["timings_ms"] = timings
            out["screenshot_paths"] = screenshot_paths
            try:
                log(
                    "info",
                    "post_follow_post_likes_perf_grid_ready",
                    visual_candidate_id=vcid,
                    source_profile_username=src,
                    follower_username=cand,
                    readiness_mode="sparse_post_scroll_accepted",
                    total_grid_prepare_ms=timings.get("grid_prep_total_ms"),
                    scroll_attempts_used=int(attempts),
                    final_grid_state=str(probe1.get("grid_state") or "partial"),
                    final_suggested_for_you=probe1.get("suggested_for_you"),
                    final_profile_tabs_visible=probe1.get("profile_tabs_visible"),
                    elapsed_from_phase_start_ms=_likes_perf_elapsed_ms(
                        likes_perf_phase_t0
                    ),
                )
            except Exception:
                pass
            out["likes_perf_grid"] = {
                "initial_probe_ms": dict(p0perf),
                "scroll_cycles": list(scroll_perf_cycles),
                "grid_prepare_total_ms": timings.get("grid_prep_total_ms"),
                "budget_snapshot_ms": budget_snapshot_total_ms,
            }
            return out

        if state_after == "visible":
            out["ok"] = True
            out["grid_state_after"] = "visible"
            log(
                "info",
                "post_follow_post_likes_grid_visible_confirmed",
                visual_candidate_id=vcid,
                source_profile_username=src,
                follower_username=cand,
                phase=f"after_scroll_{attempts}",
                scroll_used=True,
                scroll_profile=sp,
                attempt=attempts,
                screenshot_path=probe1.get("screenshot_path"),
            )
            timings["grid_prep_total_ms"] = round((time.perf_counter() - t0) * 1000, 2)
            out["timings_ms"] = timings
            out["screenshot_paths"] = screenshot_paths
            _post_follow_merge_grid_probe_meta(out, probe1)
            try:
                log(
                    "info",
                    "post_follow_post_likes_perf_grid_ready",
                    visual_candidate_id=vcid,
                    source_profile_username=src,
                    follower_username=cand,
                    readiness_mode="visible_confirmed",
                    total_grid_prepare_ms=timings.get("grid_prep_total_ms"),
                    scroll_attempts_used=int(attempts),
                    final_grid_state="visible",
                    final_suggested_for_you=probe1.get("suggested_for_you"),
                    final_profile_tabs_visible=probe1.get("profile_tabs_visible"),
                    elapsed_from_phase_start_ms=_likes_perf_elapsed_ms(
                        likes_perf_phase_t0
                    ),
                )
            except Exception:
                pass
            out["likes_perf_grid"] = {
                "initial_probe_ms": dict(p0perf),
                "scroll_cycles": list(scroll_perf_cycles),
                "grid_prepare_total_ms": timings.get("grid_prep_total_ms"),
                "budget_snapshot_ms": budget_snapshot_total_ms,
            }
            return out

    out["grid_state_after"] = state_after
    timings["grid_prep_total_ms"] = round((time.perf_counter() - t0) * 1000, 2)
    out["timings_ms"] = timings
    out["screenshot_paths"] = screenshot_paths
    _likes_perf_grid_common: dict[str, Any] = {
        "initial_probe_ms": dict(p0perf) if p0perf else {},
        "scroll_cycles": list(scroll_perf_cycles),
        "grid_prepare_total_ms": timings.get("grid_prep_total_ms"),
        "budget_snapshot_ms": budget_snapshot_total_ms,
        "final_suggested_for_you": probe_last.get("suggested_for_you"),
        "final_profile_tabs_visible": probe_last.get("profile_tabs_visible"),
    }
    if not out.get("ok") and _sparse_post_grid_partial_acceptable_for_post_follow(
        probe_last,
        scroll_used=bool(out.get("scroll_used")),
    ):
        out["ok"] = True
        out["failure_reason"] = None
        out["partial_sparse_grid_accepted"] = True
        out["sparse_grid_accepted"] = True
        _post_scroll_sparse = _post_follow_sparse_post_scroll_grid_acceptable(
            probe_last, scroll_used=bool(out.get("scroll_used"))
        )
        if _post_scroll_sparse:
            out["sparse_post_scroll_accepted"] = True
        _single_sparse = _single_post_sparse_grid_acceptable_for_post_follow(probe_last)
        _post_follow_merge_grid_probe_meta(out, probe_last)
        try:
            if _post_scroll_sparse:
                log(
                    "info",
                    "post_follow_post_grid_sparse_post_scroll_accepted",
                    visual_candidate_id=vcid,
                    source_profile_username=src,
                    follower_username=cand,
                    acceptance_phase="after_scroll_final",
                    lower_solid_cell_count=probe_last.get("lower_solid_cell_count"),
                    dynamic_first_row_top=probe_last.get("dynamic_first_row_top"),
                    profile_tabs_bottom_y_px=probe_last.get("profile_tabs_bottom_y_px"),
                    suggested_for_you=probe_last.get("suggested_for_you"),
                    screenshot_path=probe_last.get("screenshot_path"),
                    **_single_post_sparse_grid_accept_log_fields(probe_last),
                )
            elif _single_sparse:
                log(
                    "info",
                    "post_follow_post_likes_single_post_sparse_grid_accepted",
                    visual_candidate_id=vcid,
                    source_profile_username=src,
                    follower_username=cand,
                    acceptance_phase="after_scroll",
                    grid_state_after=str(probe_last.get("grid_state") or ""),
                    lower_solid_cell_count=probe_last.get("lower_solid_cell_count"),
                    upper_solid_cell_count=probe_last.get("upper_solid_cell_count"),
                    deep_lower_solid_cell_count=probe_last.get(
                        "deep_lower_solid_cell_count"
                    ),
                    lower_mostly_blank=probe_last.get("lower_mostly_blank"),
                    screenshot_path=probe_last.get("screenshot_path"),
                    **_single_post_sparse_grid_accept_log_fields(probe_last),
                )
            else:
                log(
                    "info",
                    "post_follow_post_likes_sparse_grid_accepted",
                    visual_candidate_id=vcid,
                    source_profile_username=src,
                    follower_username=cand,
                    partial_sparse_grid_accepted=True,
                    grid_state_after=str(probe_last.get("grid_state") or ""),
                    lower_solid_cell_count=probe_last.get("lower_solid_cell_count"),
                    upper_solid_cell_count=probe_last.get("upper_solid_cell_count"),
                    deep_lower_solid_cell_count=probe_last.get(
                        "deep_lower_solid_cell_count"
                    ),
                    profile_tabs_visible=probe_last.get("profile_tabs_visible"),
                    screenshot_path=probe_last.get("screenshot_path"),
                )
        except Exception:
            pass
        try:
            log(
                "info",
                "post_follow_post_likes_perf_grid_ready",
                visual_candidate_id=vcid,
                source_profile_username=src,
                follower_username=cand,
                readiness_mode=(
                    "sparse_post_scroll_accepted"
                    if _post_scroll_sparse
                    else "sparse_accepted"
                ),
                total_grid_prepare_ms=timings.get("grid_prep_total_ms"),
                scroll_attempts_used=int(attempts),
                final_grid_state=str(probe_last.get("grid_state") or ""),
                final_suggested_for_you=probe_last.get("suggested_for_you"),
                final_profile_tabs_visible=probe_last.get("profile_tabs_visible"),
                elapsed_from_phase_start_ms=_likes_perf_elapsed_ms(
                    likes_perf_phase_t0
                ),
            )
        except Exception:
            pass
        out["likes_perf_grid"] = dict(_likes_perf_grid_common)
    elif not out.get("ok"):
        if not out.get("failure_reason"):
            out["failure_reason"] = "post_grid_not_visible_before_open"
        log(
            "warning",
            "post_follow_post_likes_grid_still_not_visible",
            visual_candidate_id=vcid,
            source_profile_username=src,
            follower_username=cand,
            grid_state_before=out.get("grid_state_before"),
            grid_state_after=state_after,
            scroll_used=bool(out.get("scroll_used")),
            scroll_profiles_used=scroll_profiles_used,
            attempts=attempts,
            screenshot_path=screenshot_paths[-1] if screenshot_paths else None,
        )
        try:
            log(
                "warning",
                "post_follow_post_likes_perf_grid_prepare_failed",
                visual_candidate_id=vcid,
                source_profile_username=src,
                follower_username=cand,
                total_grid_prepare_ms=timings.get("grid_prep_total_ms"),
                scroll_attempts_used=int(attempts),
                last_grid_state=str(state_after or ""),
                last_suggested_for_you=probe_last.get("suggested_for_you"),
                last_profile_tabs_visible=probe_last.get("profile_tabs_visible"),
                failure_reason=str(out.get("failure_reason") or ""),
                elapsed_from_phase_start_ms=_likes_perf_elapsed_ms(
                    likes_perf_phase_t0
                ),
            )
        except Exception:
            pass
        out["likes_perf_grid"] = dict(_likes_perf_grid_common)
    else:
        out["likes_perf_grid"] = dict(_likes_perf_grid_common)
    return out


def visual_profile_has_no_posts(
    d: u2.Device,
    *,
    source_profile_username: str | None = None,
) -> dict[str, Any]:
    """
    Detect Instagram profile empty grid ("No posts yet" / localized / visual blank grid).
    """
    meta = _followers_current_pkg_activity(d)
    base_out = {
        "no_posts_detected": False,
        "detection_method": "none",
        "confidence": 0.0,
        "current_activity": meta.get("current_activity"),
        "current_package": meta.get("current_package"),
        "source_profile_username": source_profile_username or "",
    }

    ui_needles = (
        "No Posts Yet",
        "No posts yet",
        "No posts",
        "No Posts",
        "Aucune publication",
        "Aucune photo",
        "Pas encore de publication",
        "Pas encore de photo",
        "Sin publicaciones",
        "Sin publicaciones aún",
        "Keine Beiträge",
        "Keine Beiträge vorhanden",
        "Nessun post",
        "Nessuna pubblicazione",
        "Sem publicações",
        "Sem publicações ainda",
        "投稿なし",
        "投稿がありません",
    )

    for needle in ui_needles:
        try:
            if d(textContains=needle).exists(timeout=0.1):
                out = dict(base_out)
                out["no_posts_detected"] = True
                out["detection_method"] = f"ui_textContains:{needle[:48]}"
                out["confidence"] = 0.91
                return out
        except Exception:
            continue

    for needle in (
        "No posts yet",
        "No Posts Yet",
        "Aucune publication",
        "Pas encore de publication",
    ):
        try:
            if d(descriptionContains=needle).exists(timeout=0.09):
                out = dict(base_out)
                out["no_posts_detected"] = True
                out["detection_method"] = f"ui_descriptionContains:{needle[:48]}"
                out["confidence"] = 0.89
                return out
        except Exception:
            continue

    hier = ""
    try:
        hier = str(d.dump_hierarchy(compressed=False))
    except Exception:
        try:
            hier = str(d.dump_hierarchy())
        except Exception:
            hier = ""
    hier_l = hier.lower()
    hier_markers = (
        "no posts yet",
        "no posts",
        "aucune publication",
        "pas encore de publication",
        "pas encore de photo",
        "sin publicaciones",
        "keine beiträge",
        "nessun post",
        "sem publicações",
        "投稿がありません",
        "投稿なし",
    )
    for mk in hier_markers:
        if mk in hier_l:
            out = dict(base_out)
            out["no_posts_detected"] = True
            out["detection_method"] = f"hierarchy:{mk[:40]}"
            out["confidence"] = 0.76
            return out

    _hier_zero_posts = (
        (r"\b0\s+posts\b", "hierarchy_regex:0_posts_en"),
        (r"\b0\s+post\b", "hierarchy_regex:0_post_en"),
        (r"\b0\s+publications?\b", "hierarchy_regex:0_publications_fr"),
        (r"\b0\s+publicación(?:es)?\b", "hierarchy_regex:0_publicaciones_es"),
        (r"\b0\s+beiträge\b", "hierarchy_regex:0_beitraege_de"),
        (r"\b0\s+pubblicazioni\b", "hierarchy_regex:0_pubblicazioni_it"),
    )
    for pat, method in _hier_zero_posts:
        try:
            if re.search(pat, hier, re.I):
                out = dict(base_out)
                out["no_posts_detected"] = True
                out["detection_method"] = method
                out["confidence"] = 0.83
                return out
        except Exception:
            continue

    suggested_strip = any(
        mk in hier_l
        for mk in (
            "suggested for you",
            "suggested accounts",
            "suggestions pour vous",
            "comptes suggérés",
            "sugerencias para ti",
            "vorschläge für dich",
        )
    )

    try:
        _ensure_debug_dirs()
        shot = str(
            _SCREENSHOTS_DIR
            / f"visual_profile_no_posts_{int(time.time() * 1000)}.png"
        )
        screenshot(d, shot)
        from PIL import Image

        im = Image.open(shot).convert("RGB")
        iw, ih = im.size
        empty_guess, conf_v = _visual_profile_grid_cells_mostly_blank(im, iw, ih)
        if empty_guess:
            out = dict(base_out)
            out["no_posts_detected"] = True
            out["detection_method"] = "visual_blank_grid"
            out["confidence"] = conf_v
            return out
        empty_lower, conf_lo = _visual_profile_lower_grid_mostly_blank(im, iw, ih)
        if empty_lower and suggested_strip:
            out = dict(base_out)
            out["no_posts_detected"] = True
            out["detection_method"] = "visual_lower_grid_blank_with_suggested_strip"
            out["confidence"] = conf_lo
            return out
    except Exception:
        pass

    return base_out


def visual_detect_private_profile(
    d: u2.Device,
    *,
    source_profile_username: str | None = None,
) -> dict[str, Any]:
    """
    Detect Instagram private-account profile chrome (lock message / localized strings).
    Does not tap. Distinct from empty public grid (Suggested / No posts yet).
    """
    meta = _followers_current_pkg_activity(d)
    pkg_s = str(meta.get("current_package") or "")
    act_s = str(meta.get("current_activity") or "")
    src = source_profile_username or ""
    base_out: dict[str, Any] = {
        "private_profile_detected": False,
        "detection_method": "none",
        "confidence": 0.0,
        "current_activity": act_s,
        "current_package": pkg_s,
        "source_profile_username": src,
    }
    log(
        "info",
        "visual_private_profile_detect_started",
        source_profile_username=src,
        current_activity=act_s,
        current_package=pkg_s,
    )
    try:
        from followers_inter_candidate_perf import (
            inter_candidate_on_private_profile_detect_started,
        )

        inter_candidate_on_private_profile_detect_started()
    except Exception:
        pass

    def _private_detect_done() -> None:
        try:
            from followers_inter_candidate_perf import (
                inter_candidate_on_private_profile_detect_finished,
            )

            inter_candidate_on_private_profile_detect_finished()
        except Exception:
            pass

    ui_rows: list[tuple[str, str, float]] = [
        ("ui_textContains_this_account_private_en", "This account is private", 0.93),
        (
            "ui_textContains_follow_to_see_en",
            "Follow this account to see their photos and videos",
            0.91,
        ),
        ("ui_textContains_ce_compte_prive_fr", "Ce compte est privé", 0.91),
        ("ui_textContains_compte_prive_fr", "Compte privé", 0.84),
        ("ui_textContains_suivez_compte_fr", "Suivez ce compte pour voir", 0.87),
        (
            "ui_textContains_abonnez_compte_fr",
            "Abonnez-vous à ce compte pour voir",
            0.87,
        ),
        ("ui_textContains_cuenta_privada_es", "Esta cuenta es privada", 0.89),
        ("ui_textContains_konto_privat_de", "Dieses Konto ist privat", 0.89),
    ]
    for method, needle, conf in ui_rows:
        try:
            if d(textContains=needle).exists(timeout=0.15):
                out = dict(base_out)
                out["private_profile_detected"] = True
                out["detection_method"] = method
                out["confidence"] = float(conf)
                log(
                    "info",
                    "visual_private_profile_detected",
                    detection_method=out["detection_method"],
                    confidence=out["confidence"],
                    current_activity=out["current_activity"],
                    current_package=out["current_package"],
                    source_profile_username=src,
                )
                _private_detect_done()
                return out
        except Exception:
            continue

    for nd, method_suffix in (
        ("This account is private", "this_account_private"),
        ("Ce compte est privé", "ce_compte_prive"),
        ("Compte privé", "compte_prive"),
    ):
        try:
            if d(descriptionContains=nd).exists(timeout=0.12):
                out = dict(base_out)
                out["private_profile_detected"] = True
                out["detection_method"] = f"ui_descriptionContains:{method_suffix}"
                out["confidence"] = 0.85
                log(
                    "info",
                    "visual_private_profile_detected",
                    detection_method=out["detection_method"],
                    confidence=out["confidence"],
                    current_activity=out["current_activity"],
                    current_package=out["current_package"],
                    source_profile_username=src,
                )
                _private_detect_done()
                return out
        except Exception:
            continue

    hier = ""
    try:
        hier = str(d.dump_hierarchy(compressed=False))
    except Exception:
        try:
            hier = str(d.dump_hierarchy())
        except Exception:
            hier = ""
    hl = hier.lower()
    hier_markers: tuple[tuple[str, str], ...] = (
        ("this account is private", "hierarchy:this_account_private"),
        (
            "follow this account to see their photos",
            "hierarchy:follow_to_see_photos",
        ),
        ("ce compte est privé", "hierarchy:ce_compte_prive"),
        ("compte privé", "hierarchy:compte_prive"),
        ("suivez ce compte pour voir", "hierarchy:suivez_compte"),
        ("esta cuenta es privada", "hierarchy:cuenta_privada"),
        ("dieses konto ist privat", "hierarchy:konto_privat"),
    )
    for substr, method in hier_markers:
        if substr in hl:
            out = dict(base_out)
            out["private_profile_detected"] = True
            out["detection_method"] = method
            out["confidence"] = 0.79
            log(
                "info",
                "visual_private_profile_detected",
                detection_method=out["detection_method"],
                confidence=out["confidence"],
                current_activity=out["current_activity"],
                current_package=out["current_package"],
                source_profile_username=src,
            )
            _private_detect_done()
            return out

    log(
        "info",
        "visual_private_profile_not_detected",
        source_profile_username=src,
        current_activity=act_s,
        current_package=pkg_s,
    )
    _private_detect_done()
    return base_out


_VISUAL_POST_OPEN_SELECTION_MAX_VARIANCE = "max_variance"
_VISUAL_POST_OPEN_SELECTION_FIRST_ROW_LTR = (
    "first_row_left_to_right_recent_priority"
)
_VISUAL_GRID_CELL_TAP_FRAC_X = 0.42
_VISUAL_GRID_CELL_TAP_FRAC_Y = 0.52
_VISUAL_RECENT_POST_OPEN_PRE_TAP_SETTLE_S = 0.25
_VISUAL_GRID_CELL_RETRY_TAP_FRAC_X = 0.50
_VISUAL_GRID_CELL_RETRY_TAP_FRAC_Y = 0.55
_VISUAL_POST_VIEWER_OPEN_POLL_INITIAL_S = 0.38
_VISUAL_POST_VIEWER_OPEN_POLL_INTERVAL_S = 0.18
_VISUAL_POST_VIEWER_OPEN_POLL_MAX_S = 1.35
_VISUAL_POST_VIEWER_OPEN_POLL_RETRY_MAX_S = 1.45
_POST_FOLLOW_OPEN_LIKE_PROOF_TTL_MS = 20_000.0
_post_follow_open_like_proof_stash: dict[str, Any] | None = None
_TRUSTED_POST_FOLLOW_OPEN_NOT_LIKED_RID_SUFFIX = ":not_liked"
_TRUSTED_POST_FOLLOW_OPEN_NOT_LIKED_EXACT_SIGNALS = frozenset(
    {
        "ui_description_exact_like",
        "ui_text_exact_like",
        "ui_description_fr_jaime",
        "ui_description_es_like",
        "ui_description_de_like",
    }
)
_VISUAL_RETURN_PROFILE_POLL_INITIAL_S = 0.15
_VISUAL_RETURN_PROFILE_POLL_INTERVAL_S = 0.18
_VISUAL_RETURN_PROFILE_POLL_MAX_S = 1.0


def _visual_profile_detected_after_back(
    d: u2.Device,
    *,
    pkg: str,
) -> bool:
    return bool(
        _try_profile_signals_once(d, "", pkg)
        or _guess_profile_screen(d, pkg, "")
        in ("likely_profile", "profile_header_rid", "action_bar_title")
    )


def _visual_wait_profile_after_back(
    d: u2.Device,
    *,
    pkg: str,
    initial_delay_s: float = _VISUAL_RETURN_PROFILE_POLL_INITIAL_S,
    poll_interval_s: float = _VISUAL_RETURN_PROFILE_POLL_INTERVAL_S,
    max_wait_s: float = _VISUAL_RETURN_PROFILE_POLL_MAX_S,
) -> dict[str, Any]:
    """Poll profile chrome after Back instead of a fixed post-back sleep."""
    t0 = time.perf_counter()
    poll_count = 0
    if initial_delay_s > 0:
        time.sleep(float(initial_delay_s))
    profile_detected = False
    while True:
        poll_count += 1
        profile_detected = _visual_profile_detected_after_back(d, pkg=pkg)
        elapsed_s = time.perf_counter() - t0
        if profile_detected:
            return {
                "profile_detected": True,
                "return_profile_poll_count": int(poll_count),
                "return_profile_fast_confirmed": bool(
                    poll_count <= 2 and elapsed_s < 0.55
                ),
                "return_profile_poll_wait_ms": round(elapsed_s * 1000.0, 2),
            }
        if elapsed_s >= float(max_wait_s):
            break
        time.sleep(min(float(poll_interval_s), float(max_wait_s) - elapsed_s))
    elapsed_s = time.perf_counter() - t0
    return {
        "profile_detected": False,
        "return_profile_poll_count": int(poll_count),
        "return_profile_fast_confirmed": False,
        "return_profile_poll_wait_ms": round(elapsed_s * 1000.0, 2),
    }


def _visual_wait_post_viewer_opened_after_tap(
    d: u2.Device,
    *,
    pkg: str,
    expected_follower_username: str,
    act_before: Any,
    poll_label: str = "first_tap",
) -> dict[str, Any]:
    """Adaptive poll for post viewer after grid tap (replaces fixed 1.6s sleep)."""
    t0 = time.perf_counter()
    initial_s = float(_VISUAL_POST_VIEWER_OPEN_POLL_INITIAL_S)
    interval_s = float(_VISUAL_POST_VIEWER_OPEN_POLL_INTERVAL_S)
    max_s = float(_VISUAL_POST_VIEWER_OPEN_POLL_MAX_S)
    if str(poll_label or "").strip() == "retry_tap":
        max_s = float(_VISUAL_POST_VIEWER_OPEN_POLL_RETRY_MAX_S)

    poll_sleep_s = 0.0
    if initial_s > 0:
        time.sleep(initial_s)
        poll_sleep_s += initial_s

    poll_count = 0
    last_detect_ms = 0.0
    det: dict[str, Any] = {}
    while True:
        poll_count += 1
        t_detect0 = time.perf_counter()
        det = _visual_detect_post_viewer_opened_after_tap(
            d,
            pkg=pkg,
            expected_follower_username=expected_follower_username,
            act_before=act_before,
        )
        last_detect_ms = (time.perf_counter() - t_detect0) * 1000.0
        if bool(det.get("post_detected")):
            elapsed_s = time.perf_counter() - t0
            detect_path = str(det.get("viewer_detect_path") or "")
            return {
                **det,
                "poll_count": int(poll_count),
                "viewer_open_poll_wait_ms": round(elapsed_s * 1000.0, 2),
                "viewer_open_poll_sleep_ms": round(poll_sleep_s * 1000.0, 2),
                "viewer_open_detect_call_ms": round(last_detect_ms, 2),
                "viewer_detect_like_unlike_ms": det.get("viewer_detect_like_unlike_ms"),
                "viewer_detect_action_bar_ms": det.get("viewer_detect_action_bar_ms"),
                "viewer_detect_header_ms": det.get("viewer_detect_header_ms"),
                "viewer_detect_profile_still_ms": det.get(
                    "viewer_detect_profile_still_ms"
                ),
                "viewer_detect_broad_chrome_ms": det.get("viewer_detect_broad_chrome_ms"),
                "viewer_detect_hierarchy_ms": det.get("viewer_detect_hierarchy_ms"),
                "viewer_detect_total_ms": det.get("viewer_detect_total_ms"),
                "viewer_detect_path": detect_path,
                "viewer_detect_exact_desc_ms": det.get("viewer_detect_exact_desc_ms"),
                "viewer_detect_exact_desc_signal": det.get(
                    "viewer_detect_exact_desc_signal"
                ),
                "viewer_detect_exact_desc_guard_result": det.get(
                    "viewer_detect_exact_desc_guard_result"
                ),
                "viewer_open_fast_path": bool(
                    detect_path
                    in (
                        "phase_a_like_unlike_fast",
                        "phase_a2_exact_like_desc_fast",
                    )
                    or (
                        poll_count == 1
                        and elapsed_s < initial_s + interval_s + 0.08
                    )
                ),
                "viewer_open_poll_label": str(poll_label or ""),
            }
        elapsed_s = time.perf_counter() - t0
        if elapsed_s >= max_s:
            break
        sleep_s = min(interval_s, max(0.0, max_s - elapsed_s))
        if sleep_s > 0:
            time.sleep(sleep_s)
            poll_sleep_s += sleep_s

    elapsed_s = time.perf_counter() - t0
    return {
        **det,
        "poll_count": int(poll_count),
        "viewer_open_poll_wait_ms": round(elapsed_s * 1000.0, 2),
        "viewer_open_poll_sleep_ms": round(poll_sleep_s * 1000.0, 2),
        "viewer_open_detect_call_ms": round(last_detect_ms, 2),
        "viewer_open_fast_path": False,
        "viewer_open_poll_label": str(poll_label or ""),
    }


def _already_liked_precheck_trusted_not_liked(
    precheck: dict[str, Any] | None,
) -> bool:
    if not isinstance(precheck, dict):
        return False
    if bool(precheck.get("already_liked")):
        return False
    state = str(precheck.get("semantic_like_state") or "")
    reason = str(precheck.get("already_liked_decision_reason") or "")
    if state == "like":
        return True
    return reason in (
        "semantic_like_confirmed_not_liked",
        "hierarchy_like_confirmed_not_liked",
    )


def _already_liked_precheck_requires_recheck(
    precheck: dict[str, Any] | None,
) -> tuple[bool, str]:
    if not isinstance(precheck, dict):
        return True, "no_precheck_supplied"
    if bool(precheck.get("already_liked")):
        return False, "precheck_already_liked_confirmed"
    if _already_liked_precheck_trusted_not_liked(precheck):
        return False, "precheck_trusted_not_liked"
    state = str(precheck.get("semantic_like_state") or "")
    if state == "unknown":
        return True, "precheck_unknown_requires_heart_bounds_recheck"
    return True, str(precheck.get("already_liked_decision_reason") or "precheck_inconclusive")


def _visual_grid_cell_tap_xy_device(
    x0: int,
    y0: int,
    cell_w: int,
    cell_h: int,
    *,
    iw: int,
    ih: int,
    ww: int,
    wh: int,
    offset_ix: int = 0,
    offset_iy: int = 0,
    tap_frac_x: float = _VISUAL_GRID_CELL_TAP_FRAC_X,
    tap_frac_y: float = _VISUAL_GRID_CELL_TAP_FRAC_Y,
) -> tuple[int, int]:
    """Inset tap inside grid cell (avoids Reel corner icon and cell edges)."""
    cx_img = x0 + int(cell_w * float(tap_frac_x)) + int(offset_ix)
    cy_img = y0 + int(cell_h * float(tap_frac_y)) + int(offset_iy)
    cx_img = max(x0 + 8, min(x0 + cell_w - 8, cx_img))
    cy_img = max(y0 + 8, min(y0 + cell_h - 8, cy_img))
    tap_x, tap_y = _visual_xy_image_to_device(cx_img, cy_img, iw, ih, ww, wh)
    return max(2, min(ww - 3, tap_x)), max(2, min(wh - 3, tap_y))


def _visual_select_profile_grid_cell(
    im: Any,
    *,
    iw: int,
    ih: int,
    grid_y0: int,
    grid_y1: int,
    selection_policy: str,
    var_thr: float = 120.0,
) -> tuple[tuple[int, int, int, int, float] | None, list[dict[str, Any]]]:
    cols = 3
    cell_w = max(24, iw // cols)
    cell_h = cell_w
    if selection_policy == _VISUAL_POST_OPEN_SELECTION_FIRST_ROW_LTR:
        scan_order = [(0, 0), (1, 0), (2, 0)]
    else:
        scan_order = [(0, 0), (1, 0), (2, 0), (0, 1), (1, 1), (2, 1)]

    ordered_candidates: list[dict[str, Any]] = []
    chosen: tuple[int, int, int, int, float] | None = None
    for col, row in scan_order:
        x0 = col * cell_w
        y0 = grid_y0 + row * cell_h
        if y0 + cell_h > grid_y1 or x0 + cell_w > iw:
            ordered_candidates.append(
                {
                    "col": col,
                    "row": row,
                    "eligible": False,
                    "variance": 0.0,
                    "reason": "out_of_grid_band",
                }
            )
            continue
        v = _visual_image_cell_luma_variance(im, x0, y0, cell_w, cell_h)
        eligible = bool(v >= var_thr)
        ordered_candidates.append(
            {
                "col": col,
                "row": row,
                "eligible": eligible,
                "variance": round(float(v), 2),
            }
        )
        if not eligible:
            continue
        if selection_policy == _VISUAL_POST_OPEN_SELECTION_FIRST_ROW_LTR:
            chosen = (col, row, x0, y0, v)
            break
        if chosen is None or v > chosen[4]:
            chosen = (col, row, x0, y0, v)
    return chosen, ordered_candidates


def _visual_detect_post_viewer_stage_ms(t0: float) -> float:
    return round((time.perf_counter() - t0) * 1000.0, 2)


