def _post_follow_return_ct_sample_visible_texts(
    d: u2.Device, *, max_items: int = 28, max_len: int = 72
) -> list[str]:
    out: list[str] = []
    try:
        for el in d(className="android.widget.TextView").all():
            try:
                t = (el.info.get("text") or "").strip()
                if len(t) > 1:
                    out.append(t[:max_len])
                if len(out) >= max_items:
                    break
            except Exception:
                continue
    except Exception:
        return out
    return out


def _post_follow_return_ct_drift_surface_reasons(
    *,
    nav: dict[str, Any],
    last_det: dict[str, Any],
    ok_list_confirmed: bool,
    texts_sample: list[str],
) -> list[str]:
    """Return human-readable drift reasons; empty means no dangerous surface for this guard."""
    from navigation_engine import NavigationEngineState

    if ok_list_confirmed:
        return []

    reasons: list[str] = []
    st = str(nav.get("state") or "")
    cf = float(nav.get("confidence") or 0.0)
    guess_blob = " ".join(
        [
            str(last_det.get("current_screen_guess") or ""),
            str(nav.get("xml_guess") or ""),
        ]
    ).lower()
    texts_blob = " ".join(texts_sample).lower()

    if st == NavigationEngineState.SEARCH.value:
        reasons.append("navigation_search")
    if st == NavigationEngineState.SEARCH_RESULTS.value:
        reasons.append("navigation_search_results")
    if st == NavigationEngineState.UNKNOWN.value and cf < 0.35:
        reasons.append("navigation_unknown_low_confidence")

    for frag in _POST_FOLLOW_DRIFT_GUESS_SUBSTR:
        if frag in guess_blob:
            reasons.append(f"current_screen_guess_or_xml:{frag}")
            break
    for frag in _POST_FOLLOW_DRIFT_TEXT_SUBSTR:
        if frag in texts_blob:
            reasons.append(f"visible_text:{frag}")
            break

    return reasons


def _post_follow_compact_foreign_profile_visual_followers_list_check(
    d: u2.Device,
    *,
    src: str,
    cand: str,
    det_xml: dict[str, Any],
) -> tuple[bool, str, dict[str, Any]]:
    """
    After a compact ``back`` from a foreign candidate profile, XML ``detect_followers_list_screen``
    may false-negative a CT followers list (especially scrolled / zero-CTA layouts). Use the same
    screenshot-based visual_fallback path as elsewhere, plus rendered-strong structural OK from
    ``_followers_committed_rendered_strong_visual_ok`` (without requiring
    ``followers_session_list_committed_open_for``, which is cleared when opening a candidate
    profile), then CT surface hints from the last XML det (action bar / headers).
    """
    vf: dict[str, Any] = {}
    try:
        vf = detect_followers_list_screen_visual_fallback(
            d, source_profile_username=src or None, screenshot_path=None
        )
    except Exception as e:
        vf = {"visual_error": f"visual_fallback_exception:{type(e).__name__}:{e}"}
    if not isinstance(vf, dict):
        vf = {}

    validation_reason = ""
    vf_ok = False
    if bool(vf.get("visual_match")):
        vf_ok = True
        validation_reason = "visual_match"
    elif _followers_committed_rendered_strong_visual_ok(vf):
        vf_ok = True
        validation_reason = "post_follow_compact_rendered_strong_visual_ok"

    if not vf_ok:
        err = str(vf.get("visual_error") or "").strip()
        return False, (err or "no_visual_followers_signals"), vf

    det_l = det_xml if isinstance(det_xml, dict) else {}
    src_n = _normalize_handle(src)
    cand_n = _normalize_handle(cand or "")
    ab_raw = str(det_l.get("action_bar_title") or "").strip()
    ab = _normalize_handle(ab_raw)
    if cand_n and ab and ab == cand_n:
        return False, "ct_check_failed_action_bar_still_followed_candidate", vf
    if src_n and ab and ab == src_n:
        return True, f"{validation_reason}+ct_action_bar_title", vf
    for t in (det_l.get("visible_header_texts") or [])[:30]:
        if _normalize_handle(str(t)) == src_n:
            return True, f"{validation_reason}+ct_header_text", vf
    if bool(det_l.get("title_match")):
        return True, f"{validation_reason}+xml_title_match", vf
    try:
        if src_n and bool(verify_profile(d, src)):
            return True, f"{validation_reason}+verify_profile_ct_anchor", vf
    except Exception:
        pass
    return False, "ct_check_failed_no_ct_marker_after_visual_ok", vf


def post_follow_controlled_return_to_followers_list(
    d: u2.Device,
    *,
    pkg: str,
    source_profile_username: str,
    follower_username: str,
    visual_candidate_id: str,
    det: dict[str, Any] | None,
    max_rounds: int = 4,
    compact_after_follow_verified_mute: bool = False,
    compact_reason: str | None = None,
) -> tuple[bool, str, str | None]:
    """
    Return to the CT followers list after follow / mute.

    Safety: no taps on feed/media/stories, comment threads, or message composers; no swipes
    or exploratory navigation while recovery is uncertain. Drift surfaces get at most one
    controlled ``back`` plus re-observe before abort.

    When ``compact_after_follow_verified_mute`` is True (follow vérifié + candidat visuel),
    the return uses a **strict** path: observe → liste CT confirmée, sinon **un** ``back``
    sûr → ré-observation → liste (sans hierarchy refresh / reopen profile dans la boucle
    compact principale). Un profil PROFILE « étranger » (handle barre ≠ source) tente
    d’abord ce **seul** ``back``; si la liste CT n’est toujours pas confirmée, on logue
    ``post_follow_return_ct_fast_abort_after_foreign_profile`` puis un **fallback**
    ``return_to_followers_list`` (multi-back / reopen depuis le profil CT) avant d’échouer.
    Entre l’échec XML après ce ``back`` et ce fast-abort, une **confirmation visuelle**
    (``detect_followers_list_screen_visual_fallback`` + option rendered-strong committed + marqueurs CT)
    peut reconnaître la liste Followers déjà ouverte et éviter le fallback.
    """
    from navigation_engine import NavigationEngineState, observe_instagram_state

    _POST_FOLLOW_RETURN_PENDING_VISUAL_EVIDENCE_FOR_RUNNER.clear()

    pkg = pkg or str(getattr(config, "INSTAGRAM_PACKAGE", "") or "")
    vcid = str(visual_candidate_id or "").strip()
    src = str(source_profile_username or "").strip()
    cand = str(follower_username or "").strip()
    compact = bool(compact_after_follow_verified_mute)
    eff_max_rounds = 1 if compact else max(1, int(max_rounds))
    drift_max = int(
        getattr(config, "POST_FOLLOW_RETURN_CT_DRIFT_ABORT_STREAK", 4) or 4
    )
    if compact:
        drift_max = 1
    drift_streak = 0
    budget_s = float(
        getattr(config, "POST_FOLLOW_RETURN_CT_ROUND_BUDGET_S", 10.0) or 10.0
    )
    budget_s = max(8.0, min(12.0, budget_s))
    if compact:
        budget_s = min(budget_s, 5.0)
    allow_reopen = bool(
        getattr(config, "POST_FOLLOW_RETURN_CT_ALLOW_HIERARCHY_PROFILE_REOPEN", False)
    )
    if compact:
        allow_reopen = False
    back_max = max(
        0,
        int(getattr(config, "POST_FOLLOW_RETURN_CT_BACK_MAX_RETRIES", 1) or 1),
    )

    def _list_confirmed() -> tuple[bool, dict[str, Any]]:
        try:
            det_l = detect_followers_list_screen(
                d, source_profile_username=src
            )
        except Exception:
            det_l = {}
        is_list = bool(det_l.get("is_followers_list"))
        try:
            ct_ok = verify_followers_list_surface_is_ct_account(
                d,
                source_profile_username=src,
                follower_candidate_username=cand or None,
                det=det_l,
            )
        except Exception:
            ct_ok = is_list
        return bool(is_list and ct_ok), det_l

    def _over_budget(round_t0: float) -> bool:
        return (time.monotonic() - round_t0) >= budget_s

    def _landing_ok(nav2: dict[str, Any]) -> bool:
        ok_l, _d = _list_confirmed()
        if ok_l:
            return True
        st2 = str(nav2.get("state") or "")
        if st2 in (
            NavigationEngineState.CANDIDATE_PROFILE.value,
            NavigationEngineState.PRIVATE_PROFILE.value,
            NavigationEngineState.MUTE_SHEET.value,
            NavigationEngineState.FOLLOWERS_LIST.value,
        ):
            return True
        if st2 == NavigationEngineState.PROFILE.value:
            try:
                return bool(verify_profile(d, src))
            except Exception:
                return False
        return False

    ok0, det0 = _list_confirmed()
    if ok0:
        log(
            "info",
            "post_follow_return_ct_visual_confirmed",
            visual_candidate_id=vcid,
            source_profile_username=src,
            attempt=0,
            note="already_on_confirmed_followers_list",
            action_bar_title=str(det0.get("action_bar_title") or "")[:120],
        )
        return True, "already_on_followers_list", None

    last_det: dict[str, Any] = dict(det) if isinstance(det, dict) else {}
    how_last = ""

    if compact:
        req_mr = max(1, int(max_rounds))
        if req_mr > 1 or eff_max_rounds != 1:
            log(
                "warning",
                "post_follow_return_ct_compact_contract_violation",
                visual_candidate_id=vcid,
                source_profile_username=src,
                requested_max_rounds=req_mr,
                effective_max_rounds=int(eff_max_rounds),
                compact_reason=str(compact_reason or ""),
            )
            return (
                False,
                "compact_abort_contract_violation",
                "post_follow_return_ct_compact_contract_violation",
            )

        round_t0 = time.monotonic()
        log(
            "info",
            "post_follow_return_ct_compact_mode_enabled",
            visual_candidate_id=vcid,
            source_profile_username=src,
            compact_reason=str(compact_reason or ""),
            round_budget_s=round(budget_s, 2),
            effective_max_rounds=1,
        )
        round_idx = 1
        log(
            "info",
            "post_follow_return_ct_attempt",
            visual_candidate_id=vcid,
            source_profile_username=src,
            attempt=round_idx,
            max_rounds=1,
            round_budget_s=round(budget_s, 2),
            compact_after_follow_verified_mute=True,
        )
        try:
            last_det = detect_followers_list_screen(d, source_profile_username=src)
        except Exception:
            last_det = {}
        nav_ctx: dict[str, Any] = {
            "phase": "post_follow_return_compact",
            "visual_candidate_id": vcid,
            "source_profile_username": src,
            "det": last_det,
            "disable_followers_visual_fallback": False,
        }
        try:
            nav = observe_instagram_state(
                d,
                expected_package=pkg,
                last_known_state=NavigationEngineState.CANDIDATE_PROFILE.value,
                context=nav_ctx,
            )
        except Exception as e:
            nav = {"state": "UNKNOWN", "confidence": 0.0, "reason": str(e)}
        log(
            "info",
            "post_follow_return_ct_state_observed",
            visual_candidate_id=vcid,
            source_profile_username=src,
            attempt=round_idx,
            observe_sequence="initial",
            navigation_state=str(nav.get("state") or ""),
            navigation_confidence=float(nav.get("confidence") or 0.0),
            navigation_reason=str(nav.get("reason") or ""),
            xml_guess=str(nav.get("xml_guess") or ""),
        )

        ok_list_now, det_now = _list_confirmed()
        if ok_list_now:
            log(
                "info",
                "post_follow_return_ct_visual_confirmed",
                visual_candidate_id=vcid,
                source_profile_username=src,
                attempt=round_idx,
                how="compact_initial_list_confirmed",
                action_bar_title=str(det_now.get("action_bar_title") or "")[:120],
            )
            return True, "compact_initial_list_confirmed", None

        st_nav = str(nav.get("state") or "")
        cf_nav = float(nav.get("confidence") or 0.0)
        ab_raw = str(last_det.get("action_bar_title") or "").strip()
        ab_n = _normalize_handle(ab_raw) if ab_raw else ""
        src_n = _normalize_handle(src)
        foreign_profile = (
            st_nav == NavigationEngineState.PROFILE.value
            and bool(ab_n)
            and ab_n != src_n
            and not ok_list_now
        )
        if foreign_profile:
            log(
                "warning",
                "post_follow_return_ct_profile_not_source_detected",
                visual_candidate_id=vcid,
                source_profile_username=src,
                action_bar_title=ab_raw[:120],
                navigation_state=st_nav,
                navigation_confidence=cf_nav,
                xml_guess=str(nav.get("xml_guess") or ""),
            )
            if verify_app_foreground(d, pkg):
                try:
                    d.press("back")
                    time.sleep(0.42)
                except Exception:
                    pass
                try:
                    last_det = detect_followers_list_screen(
                        d, source_profile_username=src
                    )
                except Exception:
                    last_det = {}
                ab_post_raw = str(last_det.get("action_bar_title") or "").strip()
                ab_post_n = _normalize_handle(ab_post_raw) if ab_post_raw else ""
                cand_n_post = _normalize_handle(cand or "")
                ct_action_bar_fast_path = (
                    bool(src_n)
                    and bool(ab_post_n)
                    and ab_post_n == src_n
                    and (not cand_n_post or ab_post_n != cand_n_post)
                )
                det_fb: dict[str, Any] = (
                    last_det if isinstance(last_det, dict) else {}
                )
                ok_fb = False
                if ct_action_bar_fast_path:
                    try:
                        log(
                            "info",
                            "post_follow_return_ct_compact_foreign_profile_ct_action_bar_fast_path",
                            visual_candidate_id=vcid,
                            source_profile_username=src,
                            follower_username=cand or None,
                            action_bar_title=ab_post_raw[:120],
                            skipped_xml_reconfirm=True,
                        )
                    except Exception:
                        pass
                else:
                    ok_fb, det_fb = _list_confirmed()
                if ok_fb:
                    log(
                        "info",
                        "post_follow_return_ct_visual_confirmed",
                        visual_candidate_id=vcid,
                        source_profile_username=src,
                        attempt=round_idx,
                        how="foreign_profile_one_safe_back_then_list",
                        action_bar_title=str(
                            det_fb.get("action_bar_title") or ""
                        )[:120],
                    )
                    return True, "foreign_profile_one_safe_back_then_list", None
                try:
                    log(
                        "info",
                        "post_follow_return_ct_compact_foreign_profile_visual_list_check_started",
                        visual_candidate_id=vcid,
                        source_profile_username=src,
                        follower_username=cand or None,
                        action_bar_title=str(det_fb.get("action_bar_title") or "")[:120],
                    )
                except Exception:
                    pass
                vis_ok, vis_reason, vf_vis = (
                    _post_follow_compact_foreign_profile_visual_followers_list_check(
                        d,
                        src=src,
                        cand=cand,
                        det_xml=det_fb,
                    )
                )
                if vis_ok:
                    try:
                        log(
                            "info",
                            "post_follow_return_ct_compact_foreign_profile_visual_list_confirmed",
                            visual_candidate_id=vcid,
                            source_profile_username=src,
                            follower_username=cand or None,
                            screenshot_path=str(
                                vf_vis.get("screenshot_path_used") or ""
                            ),
                            visual_match=bool(vf_vis.get("visual_match")),
                            visual_confidence=float(
                                vf_vis.get("visual_confidence") or 0.0
                            ),
                            visual_user_rows_detected=int(
                                vf_vis.get("visual_user_rows_detected") or 0
                            ),
                            visual_follow_button_count=int(
                                vf_vis.get("visual_follow_button_count") or 0
                            ),
                            validation_reason=str(vis_reason or ""),
                        )
                    except Exception:
                        pass
                    log(
                        "info",
                        "post_follow_return_ct_visual_confirmed",
                        visual_candidate_id=vcid,
                        source_profile_username=src,
                        attempt=round_idx,
                        how="compact_foreign_profile_back_visual_followers_list_confirmed",
                        action_bar_title=str(det_fb.get("action_bar_title") or "")[:120],
                    )
                    _POST_FOLLOW_RETURN_PENDING_VISUAL_EVIDENCE_FOR_RUNNER.clear()
                    if isinstance(vf_vis, dict) and vf_vis:
                        _lst_shot = str(
                            vf_vis.get("screenshot_path_used")
                            or vf_vis.get("screenshot_path")
                            or ""
                        ).strip()
                        if _lst_shot:
                            _POST_FOLLOW_RETURN_PENDING_VISUAL_EVIDENCE_FOR_RUNNER[
                                "return_list_screenshot_path"
                            ] = _lst_shot
                            _POST_FOLLOW_RETURN_PENDING_VISUAL_EVIDENCE_FOR_RUNNER[
                                "return_visual_fallback_detail"
                            ] = dict(vf_vis)
                    return (
                        True,
                        "compact_foreign_profile_back_visual_followers_list_confirmed",
                        None,
                    )
                try:
                    log(
                        "info",
                        "post_follow_return_ct_compact_foreign_profile_visual_list_rejected",
                        visual_candidate_id=vcid,
                        source_profile_username=src,
                        follower_username=cand or None,
                        screenshot_path=str(
                            vf_vis.get("screenshot_path_used") or ""
                        ),
                        visual_match=bool(vf_vis.get("visual_match")),
                        visual_confidence=float(
                            vf_vis.get("visual_confidence") or 0.0
                        ),
                        visual_user_rows_detected=int(
                            vf_vis.get("visual_user_rows_detected") or 0
                        ),
                        visual_follow_button_count=int(
                            vf_vis.get("visual_follow_button_count") or 0
                        ),
                        validation_reason=str(vis_reason or ""),
                    )
                except Exception:
                    pass
            log(
                "warning",
                "post_follow_return_ct_fast_abort_after_foreign_profile",
                visual_candidate_id=vcid,
                source_profile_username=src,
                follower_username=cand or None,
                attempt=round_idx,
                action_bar_title=ab_raw[:120],
                navigation_state=st_nav,
                xml_guess=str(nav.get("xml_guess") or ""),
                compact_recovery_fallback=True,
            )
            log(
                "warning",
                "post_follow_return_ct_compact_foreign_profile_fallback_started",
                visual_candidate_id=vcid,
                source_profile_username=src,
                follower_username=cand or None,
                original_failure_reason="post_follow_return_ct_fast_abort_after_foreign_profile",
            )
            fb_ok = False
            fb_how = ""
            try:
                fb_ok, fb_how = return_to_followers_list(d, src, pkg)
            except Exception as e:
                fb_how = f"exception:{type(e).__name__}"
            ok_fin, det_fin = _list_confirmed()
            _fb_repoll_max = 3
            _fb_repoll_sleep_s = min(0.35, max(0.2, 0.28))
            if (
                fb_ok
                and not ok_fin
                and str(fb_how or "") == "reopen_from_source_profile"
            ):
                try:
                    log(
                        "info",
                        "post_follow_return_ct_fallback_list_confirm_repoll_started",
                        visual_candidate_id=vcid,
                        source_profile_username=src,
                        follower_username=cand or None,
                        fallback_method=str(fb_how or ""),
                        max_attempts=int(_fb_repoll_max),
                        sleep_s=round(float(_fb_repoll_sleep_s), 3),
                    )
                except Exception:
                    pass
                for _rep_i in range(1, _fb_repoll_max + 1):
                    try:
                        time.sleep(_fb_repoll_sleep_s)
                    except Exception:
                        pass
                    ok_fin, det_fin = _list_confirmed()
                    try:
                        log(
                            "info",
                            "post_follow_return_ct_fallback_list_confirm_repoll_attempt",
                            visual_candidate_id=vcid,
                            source_profile_username=src,
                            follower_username=cand or None,
                            fallback_method=str(fb_how or ""),
                            attempt=int(_rep_i),
                            max_attempts=int(_fb_repoll_max),
                            confirmed=bool(ok_fin),
                            is_followers_list=bool(det_fin.get("is_followers_list")),
                            action_bar_title=str(det_fin.get("action_bar_title") or "")[:120],
                        )
                    except Exception:
                        pass
                    if ok_fin:
                        try:
                            log(
                                "info",
                                "post_follow_return_ct_fallback_list_confirm_repoll_success",
                                visual_candidate_id=vcid,
                                source_profile_username=src,
                                follower_username=cand or None,
                                fallback_method=str(fb_how or ""),
                                attempt=int(_rep_i),
                                max_attempts=int(_fb_repoll_max),
                                is_followers_list=bool(det_fin.get("is_followers_list")),
                                action_bar_title=str(det_fin.get("action_bar_title") or "")[:120],
                            )
                        except Exception:
                            pass
                        break
                if not ok_fin:
                    try:
                        log(
                            "warning",
                            "post_follow_return_ct_fallback_list_confirm_repoll_exhausted",
                            visual_candidate_id=vcid,
                            source_profile_username=src,
                            follower_username=cand or None,
                            fallback_method=str(fb_how or ""),
                            max_attempts=int(_fb_repoll_max),
                            confirmed=False,
                            is_followers_list=bool(det_fin.get("is_followers_list")),
                            action_bar_title=str(det_fin.get("action_bar_title") or "")[:120],
                        )
                    except Exception:
                        pass
            if fb_ok and ok_fin:
                log(
                    "info",
                    "post_follow_return_ct_compact_foreign_profile_fallback_success",
                    visual_candidate_id=vcid,
                    source_profile_username=src,
                    follower_username=cand or None,
                    original_failure_reason="post_follow_return_ct_fast_abort_after_foreign_profile",
                    fallback_method=str(fb_how or "return_to_followers_list"),
                    action_bar_title=str(det_fin.get("action_bar_title") or "")[:120],
                )
                return True, "compact_foreign_profile_fallback_then_list", None
            log(
                "warning",
                "post_follow_return_ct_compact_foreign_profile_fallback_failed",
                visual_candidate_id=vcid,
                source_profile_username=src,
                follower_username=cand or None,
                original_failure_reason="post_follow_return_ct_fast_abort_after_foreign_profile",
                fallback_method=str(fb_how or ""),
                return_to_followers_list_ok=bool(fb_ok),
                list_confirmed_after=bool(ok_fin),
            )
            return (
                False,
                "fast_abort_foreign_profile_after_post_follow",
                "post_follow_return_ct_fast_abort_after_foreign_profile",
            )

        if _over_budget(round_t0):
            log(
                "warning",
                "post_follow_return_ct_compact_abort_no_list_confirmed",
                visual_candidate_id=vcid,
                source_profile_username=src,
                phase="before_compact_safe_back",
                budget_s=budget_s,
            )
            return (
                False,
                "compact_abort_no_list_confirmed",
                "post_follow_return_ct_compact_abort_no_list_confirmed",
            )

        log(
            "info",
            "post_follow_return_ct_compact_safe_back_only",
            visual_candidate_id=vcid,
            source_profile_username=src,
            attempt=round_idx,
        )
        if not verify_app_foreground(d, pkg):
            log(
                "warning",
                "post_follow_return_ct_compact_abort_no_list_confirmed",
                visual_candidate_id=vcid,
                source_profile_username=src,
                attempt=round_idx,
                skip_reason="not_instagram_foreground_safe",
            )
            return (
                False,
                "compact_abort_no_list_confirmed",
                "post_follow_return_ct_compact_abort_no_list_confirmed",
            )
        try:
            d.press("back")
            time.sleep(0.38)
        except Exception as e:
            log(
                "warning",
                "post_follow_return_ct_compact_abort_no_list_confirmed",
                visual_candidate_id=vcid,
                source_profile_username=src,
                attempt=round_idx,
                back_error=str(e),
            )
            return (
                False,
                "compact_abort_no_list_confirmed",
                "post_follow_return_ct_compact_abort_no_list_confirmed",
            )

        try:
            last_det = detect_followers_list_screen(d, source_profile_username=src)
        except Exception:
            last_det = {}
        nav_ctx2 = dict(nav_ctx)
        nav_ctx2["det"] = last_det
        try:
            nav2 = observe_instagram_state(
                d,
                expected_package=pkg,
                last_known_state=NavigationEngineState.CANDIDATE_PROFILE.value,
                context=nav_ctx2,
            )
        except Exception as e2:
            nav2 = {"state": "UNKNOWN", "confidence": 0.0, "reason": str(e2)}
        log(
            "info",
            "post_follow_return_ct_state_observed",
            visual_candidate_id=vcid,
            source_profile_username=src,
            attempt=round_idx,
            observe_sequence="after_safe_back",
            navigation_state=str(nav2.get("state") or ""),
            navigation_confidence=float(nav2.get("confidence") or 0.0),
            navigation_reason=str(nav2.get("reason") or ""),
            xml_guess=str(nav2.get("xml_guess") or ""),
        )

        ok_after, det_after = _list_confirmed()
        if ok_after:
            log(
                "info",
                "post_follow_return_ct_visual_confirmed",
                visual_candidate_id=vcid,
                source_profile_username=src,
                attempt=round_idx,
                how="compact_safe_back_then_list",
                action_bar_title=str(det_after.get("action_bar_title") or "")[:120],
            )
            return True, "compact_safe_back_then_list", None

        log(
            "warning",
            "post_follow_return_ct_compact_abort_no_list_confirmed",
            visual_candidate_id=vcid,
            source_profile_username=src,
            attempt=round_idx,
            navigation_state_after=str(nav2.get("state") or ""),
        )
        return (
            False,
            "compact_abort_no_list_confirmed",
            "post_follow_return_ct_compact_abort_no_list_confirmed",
        )

    for round_idx in range(1, eff_max_rounds + 1):
        round_t0 = time.monotonic()
        log(
            "info",
            "post_follow_return_ct_attempt",
            visual_candidate_id=vcid,
            source_profile_username=src,
            attempt=round_idx,
            max_rounds=int(eff_max_rounds),
            round_budget_s=round(budget_s, 2),
            compact_after_follow_verified_mute=compact,
        )
        try:
            last_det = detect_followers_list_screen(d, source_profile_username=src)
        except Exception:
            last_det = {}

        nav_ctx: dict[str, Any] = {
            "phase": "post_follow_return",
            "visual_candidate_id": vcid,
            "source_profile_username": src,
            "det": last_det,
            "disable_followers_visual_fallback": False,
        }
        try:
            nav = observe_instagram_state(
                d,
                expected_package=pkg,
                last_known_state=NavigationEngineState.CANDIDATE_PROFILE.value,
                context=nav_ctx,
            )
        except Exception as e:
            nav = {"state": "UNKNOWN", "confidence": 0.0, "reason": str(e)}
        log(
            "info",
            "post_follow_return_ct_state_observed",
            visual_candidate_id=vcid,
            source_profile_username=src,
            attempt=round_idx,
            navigation_state=str(nav.get("state") or ""),
            navigation_confidence=float(nav.get("confidence") or 0.0),
            navigation_reason=str(nav.get("reason") or ""),
            xml_guess=str(nav.get("xml_guess") or ""),
        )

        ok_list_now, det_now = _list_confirmed()
        if ok_list_now:
            drift_streak = 0
            log(
                "info",
                "post_follow_return_ct_visual_confirmed",
                visual_candidate_id=vcid,
                source_profile_username=src,
                attempt=round_idx,
                how="confirmed_list_after_observe",
                action_bar_title=str(det_now.get("action_bar_title") or "")[:120],
            )
            return True, "confirmed_list_after_observe", None

        st_nav = str(nav.get("state") or "")
        cf_nav = float(nav.get("confidence") or 0.0)

        vis_sample = _post_follow_return_ct_sample_visible_texts(d)
        drift_reasons = _post_follow_return_ct_drift_surface_reasons(
            nav=nav,
            last_det=last_det,
            ok_list_confirmed=False,
            texts_sample=vis_sample,
        )

        if drift_reasons:
            log(
                "warning",
                "post_follow_return_ct_drift_surface_detected",
                visual_candidate_id=vcid,
                source_profile_username=src,
                attempt=round_idx,
                navigation_state=st_nav,
                navigation_confidence=cf_nav,
                xml_guess=str(nav.get("xml_guess") or ""),
                current_screen_guess=str(last_det.get("current_screen_guess") or ""),
                action_bar_title=str(last_det.get("action_bar_title") or "")[:120],
                visible_texts_sample=vis_sample[:16],
                drift_reasons=drift_reasons,
            )
            allow_back = verify_app_foreground(d, pkg)
            if allow_back:
                log(
                    "info",
                    "post_follow_return_ct_safe_back_started",
                    visual_candidate_id=vcid,
                    source_profile_username=src,
                    attempt=round_idx,
                    max_presses=1,
                )
                back_ok = False
                back_err = ""
                try:
                    d.press("back")
                    time.sleep(0.42)
                    back_ok = True
                except Exception as e:
                    back_err = str(e)
                try:
                    last_det = detect_followers_list_screen(
                        d, source_profile_username=src
                    )
                except Exception:
                    last_det = {}
                nav_ctx2 = dict(nav_ctx)
                nav_ctx2["det"] = last_det
                try:
                    nav2 = observe_instagram_state(
                        d,
                        expected_package=pkg,
                        last_known_state=NavigationEngineState.CANDIDATE_PROFILE.value,
                        context=nav_ctx2,
                    )
                except Exception as e2:
                    nav2 = {"state": "UNKNOWN", "confidence": 0.0, "reason": str(e2)}
                ok_after, det_after = _list_confirmed()
                landed = ok_after or _landing_ok(nav2)
                log(
                    "info",
                    "post_follow_return_ct_safe_back_result",
                    visual_candidate_id=vcid,
                    source_profile_username=src,
                    attempt=round_idx,
                    back_sent=bool(back_ok),
                    back_error=back_err or None,
                    list_confirmed_after=bool(ok_after),
                    navigation_state_after=str(nav2.get("state") or ""),
                    landed_acceptable=bool(landed),
                )
                if ok_after:
                    log(
                        "info",
                        "post_follow_return_ct_visual_confirmed",
                        visual_candidate_id=vcid,
                        source_profile_username=src,
                        attempt=round_idx,
                        how="safe_back_then_list",
                        action_bar_title=str(det_after.get("action_bar_title") or "")[:120],
                    )
                    return True, "safe_back_then_list", None
                if landed:
                    drift_streak = 0
                    continue
            else:
                log(
                    "info",
                    "post_follow_return_ct_safe_back_result",
                    visual_candidate_id=vcid,
                    source_profile_username=src,
                    attempt=round_idx,
                    back_sent=False,
                    skipped_reason="not_instagram_foreground_safe",
                )
            log(
                "warning",
                "post_follow_return_ct_aborted_to_prevent_drift",
                visual_candidate_id=vcid,
                source_profile_username=src,
                attempt=round_idx,
                mode="drift_surface",
                navigation_state=st_nav,
                drift_reasons=drift_reasons,
            )
            return (
                False,
                "aborted_drift_prevention",
                "post_follow_return_ct_aborted_to_prevent_drift",
            )

        bad_drift = (
            (st_nav == NavigationEngineState.UNKNOWN.value and cf_nav < 0.42)
            or st_nav
            in (
                NavigationEngineState.LAUNCHER_WRONG_SURFACE.value,
                NavigationEngineState.INSTAGRAM_CLOSED.value,
                NavigationEngineState.SEARCH.value,
                NavigationEngineState.SEARCH_RESULTS.value,
            )
        )
        if bad_drift:
            drift_streak += 1
        else:
            drift_streak = 0
        if drift_streak >= max(1, drift_max):
            log(
                "warning",
                "post_follow_return_ct_aborted_to_prevent_drift",
                visual_candidate_id=vcid,
                source_profile_username=src,
                attempt=round_idx,
                drift_streak=drift_streak,
                drift_max=drift_max,
                navigation_state=st_nav,
                navigation_confidence=cf_nav,
                mode="streak_guard",
            )
            return (
                False,
                "aborted_drift_prevention",
                "post_follow_return_ct_aborted_to_prevent_drift",
            )

        if _over_budget(round_t0):
            log(
                "warning",
                "post_follow_return_ct_round_budget_exceeded",
                visual_candidate_id=vcid,
                source_profile_username=src,
                attempt=round_idx,
                budget_s=budget_s,
            )
            return (
                False,
                "round_budget_exceeded",
                "post_follow_return_ct_round_budget_exceeded",
            )

        if bool(last_det.get("is_followers_list")):
            try:
                ct_only = verify_followers_list_surface_is_ct_account(
                    d,
                    source_profile_username=src,
                    follower_candidate_username=cand or None,
                )
            except Exception:
                ct_only = False
            if not ct_only:
                log(
                    "info",
                    "post_follow_return_ct_recovery_attempt",
                    visual_candidate_id=vcid,
                    source_profile_username=src,
                    attempt=round_idx,
                    kind="wrong_profile_followers_surface",
                )
            else:
                log(
                    "info",
                    "post_follow_return_ct_visual_confirmed",
                    visual_candidate_id=vcid,
                    source_profile_username=src,
                    attempt=round_idx,
                    how="detect_without_back",
                    action_bar_title=str(last_det.get("action_bar_title") or "")[:120],
                )
                return True, "detect_without_back", None

        if _post_follow_overlay_ui_hints(d).get("likely_mute_toggle_sheet"):
            if _over_budget(round_t0):
                log(
                    "warning",
                    "post_follow_return_ct_round_budget_exceeded",
                    visual_candidate_id=vcid,
                    source_profile_username=src,
                    attempt=round_idx,
                    budget_s=budget_s,
                    phase="before_mute_sheet_dismiss",
                )
                return (
                    False,
                    "round_budget_exceeded",
                    "post_follow_return_ct_round_budget_exceeded",
                )
            try:
                if d(text="Posts").exists(timeout=0.07) and d(text="Stories").exists(
                    timeout=0.05
                ):
                    d.press("back")
                    time.sleep(0.42)
                    log(
                        "info",
                        "post_follow_return_ct_recovery_attempt",
                        visual_candidate_id=vcid,
                        source_profile_username=src,
                        attempt=round_idx,
                        kind="dismiss_mute_sheet_back",
                    )
            except Exception:
                pass

        if _over_budget(round_t0):
            log(
                "warning",
                "post_follow_return_ct_round_budget_exceeded",
                visual_candidate_id=vcid,
                source_profile_username=src,
                attempt=round_idx,
                budget_s=budget_s,
                phase="before_return_to_followers_list",
            )
            return (
                False,
                "round_budget_exceeded",
                "post_follow_return_ct_round_budget_exceeded",
            )

        try:
            ok_r, how_last = return_to_followers_list(
                d,
                src,
                pkg,
                max_retries=back_max,
            )
        except Exception as e:
            ok_r, how_last = False, f"exception:{e}"

        ok1, det1 = _list_confirmed()
        if ok_r and ok1:
            log(
                "info",
                "post_follow_return_ct_visual_confirmed",
                visual_candidate_id=vcid,
                source_profile_username=src,
                attempt=round_idx,
                how=str(how_last or ""),
                action_bar_title=str(det1.get("action_bar_title") or "")[:120],
            )
            return True, str(how_last or "back"), None
        if ok1:
            log(
                "info",
                "post_follow_return_ct_visual_confirmed",
                visual_candidate_id=vcid,
                source_profile_username=src,
                attempt=round_idx,
                how=str(how_last or "ambiguous_nav"),
            )
            return True, str(how_last or "back"), None

        if allow_reopen and not _over_budget(round_t0):
            log(
                "info",
                "post_follow_return_ct_recovery_attempt",
                visual_candidate_id=vcid,
                source_profile_username=src,
                attempt=round_idx,
                kind="hierarchy_refresh_and_reopen_list",
                return_ok=bool(ok_r),
                how=str(how_last or ""),
            )
            try:
                followers_force_hierarchy_refresh(d, src or None)
            except Exception:
                pass
            time.sleep(0.2)
            try:
                if verify_profile(d, src):
                    ok_re, _meta = open_followers_list_from_profile(
                        d, src, pkg, profile_verified=True
                    )
                    if ok_re:
                        ok2, det2 = _list_confirmed()
                        if ok2:
                            log(
                                "info",
                                "post_follow_return_ct_visual_confirmed",
                                visual_candidate_id=vcid,
                                source_profile_username=src,
                                attempt=round_idx,
                                how="reopen_from_source_profile",
                            )
                            return True, "reopen_from_source_profile", None
            except Exception:
                pass

    fail_reason = "post_follow_return_recovery_exhausted"
    try:
        nav_final = observe_instagram_state(
            d,
            expected_package=pkg,
            last_known_state=NavigationEngineState.CANDIDATE_PROFILE.value,
            context={
                "phase": "post_follow_return_classify",
                "visual_candidate_id": vcid,
                "source_profile_username": src,
                "det": last_det,
                "disable_followers_visual_fallback": False,
            },
        )
        st = str(nav_final.get("state") or "")
        cf = float(nav_final.get("confidence") or 0.0)
        if st == NavigationEngineState.UNKNOWN.value and cf < 0.42:
            fail_reason = "post_follow_return_lost_state"
        is_list = bool(last_det.get("is_followers_list"))
        if is_list:
            try:
                ct_bad = not verify_followers_list_surface_is_ct_account(
                    d,
                    source_profile_username=src,
                    follower_candidate_username=cand or None,
                )
            except Exception:
                ct_bad = True
            if ct_bad:
                fail_reason = "post_follow_return_wrong_profile"
        elif st != NavigationEngineState.FOLLOWERS_LIST.value:
            fail_reason = "post_follow_return_followers_not_confirmed"
        if not str(how_last or "").strip() and not is_list:
            fail_reason = "post_follow_return_back_stack_failed"
    except Exception:
        pass

    return False, str(how_last or "failed"), fail_reason


# --- Mute Engine V2: bounded, non-recovery mute after verified follow (best-effort) ---

# Nominal post-follow window (observe + overlay + fingerprint); Following CTA search needs extra time.
_MUTE_ENGINE_V2_BUDGET_S = 4.0
MIN_FOLLOWING_CTA_SEARCH_BUDGET_S = 1.5
# Reserved tail for mute toggle sheet: label wait + tap + short verify per axis (Posts + Stories).
MIN_MUTE_TOGGLE_STAGE_BUDGET_S = 2.0
_MUTE_ENGINE_V2_EFFECTIVE_TOTAL_S = (
    _MUTE_ENGINE_V2_BUDGET_S
    + MIN_FOLLOWING_CTA_SEARCH_BUDGET_S
    + MIN_MUTE_TOGGLE_STAGE_BUDGET_S
)

# Mute v2: post-tap settle before Switch.checked polling; verify window (replaces old 0.55s hard cap).
_MUTE_V2_TOGGLE_POST_TAP_SETTLE_S = 0.12
_MUTE_V2_TOGGLE_VERIFY_MIN_S = 0.35
_MUTE_V2_TOGGLE_VERIFY_MAX_S = 1.4

_MUTE_V2_REJECT_SUBSTR: tuple[str, ...] = (
    "contact",
    "message",
    "suggested",
    "invite",
    "follow back",
    "add friend",
    "composer",
    "direct",
    "thread",
)

_MUTE_V2_FOLLOWING_STATE_LABELS: tuple[str, ...] = (
    "Following",
    "Requested",
    "Suivi(e)",
    "Suivi",
    "Abonné(e)",
    "Abonné",
    "Siguiendo",
    "Gefolgt",
    "Demandé",
    "Demande envoyée",
)


def _mute_engine_v2_remaining_s(t0: float) -> float:
    return max(0.0, _MUTE_ENGINE_V2_EFFECTIVE_TOTAL_S - (time.perf_counter() - t0))


def _mute_engine_v2_map_toggle_rsn(rsn: str) -> str:
    r = str(rsn or "").strip()
    if r == "budget":
        return "budget"
    if r == "toggle_label_not_found":
        return "label_missing"
    if r.startswith("tap_failed"):
        return "tap_failed"
    if r in ("", "skipped"):
        return "skipped"
    return r or "unknown"


def _mute_engine_v2_classify_both_toggles_failure(
    *,
    want_posts: bool,
    want_stories: bool,
    posts_ok: bool,
    stories_ok: bool,
    tapped_p: bool,
    tapped_s: bool,
    already_p: bool,
    already_s: bool,
    rsn_p: str,
    rsn_s: str,
) -> tuple[str, str]:
    """
    Returns (abort_reason, failure_reason) for mute_engine_v2 when both axes were required
    and the combined outcome is failure (no partial success path).
    """
    mp = _mute_engine_v2_map_toggle_rsn(rsn_p)
    ms = _mute_engine_v2_map_toggle_rsn(rsn_s)
    if mp == "budget" or ms == "budget":
        return "mute_toggle_budget_starved", "mute_toggle_budget_starved"
    if mp == "label_missing" or ms == "label_missing":
        return "mute_toggle_label_missing", "mute_toggle_label_missing"
    vfail_p = bool(want_posts and tapped_p and not already_p and not posts_ok)
    vfail_s = bool(want_stories and tapped_s and not already_s and not stories_ok)
    if vfail_p or vfail_s:
        return "mute_toggle_verify_failed", "mute_toggle_verify_failed"
    if mp == "tap_failed" or ms == "tap_failed":
        return "mute_toggle_tap_failed", "mute_toggle_tap_failed"
    return "mute_toggle_failed", "mute_toggle_failed"


def _mute_engine_v2_classify_single_toggle_failure(
    *,
    want_posts: bool,
    want_stories: bool,
    posts_ok: bool,
    stories_ok: bool,
    tapped_p: bool,
    tapped_s: bool,
    already_p: bool,
    already_s: bool,
    rsn_p: str,
    rsn_s: str,
) -> tuple[str, str]:
    if want_posts and not want_stories:
        m = _mute_engine_v2_map_toggle_rsn(rsn_p)
        vfail = bool(tapped_p and not already_p and not posts_ok)
    elif want_stories and not want_posts:
        m = _mute_engine_v2_map_toggle_rsn(rsn_s)
        vfail = bool(tapped_s and not already_s and not stories_ok)
    else:
        return "mute_toggle_failed", "mute_toggle_failed"
    if m == "budget":
        return "mute_toggle_budget_starved", "mute_toggle_budget_starved"
    if m == "label_missing":
        return "mute_toggle_label_missing", "mute_toggle_label_missing"
    if vfail:
        return "mute_toggle_verify_failed", "mute_toggle_verify_failed"
    if m == "tap_failed":
        return "mute_toggle_tap_failed", "mute_toggle_tap_failed"
    return "mute_toggle_failed", "mute_toggle_failed"


def _mute_engine_v2_text_rejected(txt: str) -> bool:
    t = (txt or "").strip().lower()
    if not t:
        return True
    for sub in _MUTE_V2_REJECT_SUBSTR:
        if sub in t:
            return True
    if t in ("follow", "suivre", "seguir", "folgen", "abonar", "folgen"):
        return True
    return False


def _mute_engine_v2_following_header_text_ok(txt: str) -> bool:
    """True for profile header states: Following / Requested / localized, not Follow / Contact."""
    t = (txt or "").strip()
    if not t:
        return False
    low = t.lower()
    if "contact" in low or ("message" in low and "requested" not in low):
        return False
    if "follow back" in low or low in ("follow", "follow "):
        return False
    if low.startswith("follow ") and not low.startswith("following"):
        return False
    if _mute_engine_v2_text_rejected(t):
        return False
    for lab in _MUTE_V2_FOLLOWING_STATE_LABELS:
        ll = lab.lower()
        if low == ll or low.startswith(ll) or low.startswith(ll + " "):
            return True
    return False


def _mute_engine_v2_pick_following_cta(
    d: u2.Device,
    *,
    ww: int,
    wh: int,
    t0: float,
    visual_candidate_id: str = "",
    source_profile_username: str = "",
) -> tuple[Any | None, str]:
    rem = _mute_engine_v2_remaining_s(t0)
    vcid = str(visual_candidate_id or "").strip()
    src = str(source_profile_username or "").strip()
    base_log: dict[str, Any] = {
        "visual_candidate_id": vcid,
        "source_profile_username": src,
        "window_w": int(ww),
        "window_h": int(wh),
        "budget_remaining_s": round(float(rem), 4),
    }
    if rem <= 0.1:
        try:
            log(
                "warning",
                "mute_engine_v2_following_button_search_budget_starved",
                **base_log,
            )
        except Exception:
            pass
    log("info", "mute_engine_v2_following_button_search_started", **base_log)
    ex_to = max(0.05, min(0.14, rem * 0.32))
    y_header_max = int(wh * 0.52)
    y_header_min = int(wh * 0.07)

    def _element_passes(el: Any, *, pick_reason: str) -> tuple[Any | None, str]:
        try:
            raw_txt = str(el.info.get("text") or "").strip()
            cd = str(el.info.get("contentDescription") or "").strip()
            rid = str(el.info.get("resourceName") or el.info.get("resourceId") or "")
            b = el.info.get("bounds") or {}
        except Exception:
            return None, ""
        merged = raw_txt or cd
        rl = rid.lower()
        if "contact" in rl or "message" in rl or "invite" in rl:
            log(
                "info",
                "mute_engine_v2_following_button_rejected",
                **base_log,
                reason="resource_id_blocked",
                candidate_text=merged[:120],
                resource_id=rid[:160],
                pick_reason=pick_reason,
            )
            return None, ""
        if not _mute_engine_v2_following_header_text_ok(merged):
            log(
                "info",
                "mute_engine_v2_following_button_rejected",
                **base_log,
                reason="not_following_state_label",
                candidate_text=merged[:120],
                content_desc=cd[:120],
                pick_reason=pick_reason,
            )
            return None, ""
        try:
            cy = (int(b.get("top", 0)) + int(b.get("bottom", 0))) // 2
            rx = int(b.get("right", 0))
        except Exception:
            return None, ""
        if cy < y_header_min or cy > y_header_max:
            log(
                "info",
                "mute_engine_v2_following_button_rejected",
                **base_log,
                reason="y_outside_header_cta_band",
                cy=int(cy),
                pick_reason=pick_reason,
            )
            return None, ""
        if rx < int(ww * 0.16):
            log(
                "info",
                "mute_engine_v2_following_button_rejected",
                **base_log,
                reason="too_far_left",
                pick_reason=pick_reason,
            )
            return None, ""
        log(
            "info",
            "mute_engine_v2_following_button_candidate",
            **base_log,
            pick_reason=pick_reason,
            candidate_text=merged[:120],
            bounds={
                "left": b.get("left"),
                "top": b.get("top"),
                "right": b.get("right"),
                "bottom": b.get("bottom"),
            },
        )
        return el, pick_reason

    for lab in _MUTE_V2_FOLLOWING_STATE_LABELS:
        if _mute_engine_v2_remaining_s(t0) < 0.05:
            break
        try:
            el = d(text=lab)
            if not el.exists(timeout=ex_to):
                continue
            try:
                raw_txt = str(el.info.get("text") or "").strip()
            except Exception:
                raw_txt = lab
            if raw_txt != lab and _normalize_handle(raw_txt) != _normalize_handle(lab):
                if not _mute_engine_v2_following_header_text_ok(raw_txt):
                    log(
                        "info",
                        "mute_engine_v2_following_button_rejected",
                        **base_log,
                        reason="exact_label_text_mismatch",
                        candidate_text=raw_txt[:120],
                        expected_label=lab,
                        pick_reason=f"text_exact:{lab}",
                    )
                    continue
            if _mute_engine_v2_text_rejected(raw_txt):
                continue
            picked, pr = _element_passes(el, pick_reason=f"text_exact:{lab}")
            if picked is not None:
                return picked, pr
        except Exception:
            continue

    for probe_name, factory in (
        ("textStartsWith_Following", lambda: d(textStartsWith="Following")),
        ("textContains_Following", lambda: d(textContains="Following")),
    ):
        if _mute_engine_v2_remaining_s(t0) < 0.06:
            break
        try:
            sel = factory()
            if not sel.exists(timeout=ex_to):
                continue
            for el in sel.all()[:12]:
                picked, pr = _element_passes(el, pick_reason=probe_name)
                if picked is not None:
                    return picked, pr
        except Exception:
            continue

    try:
        sel = d(descriptionContains="Following")
        if sel.exists(timeout=max(0.05, ex_to * 0.9)):
            for el in sel.all()[:8]:
                picked, pr = _element_passes(el, pick_reason="descriptionContains:Following")
                if picked is not None:
                    return picked, pr
    except Exception:
        pass

    try:
        for el in d(classNameMatches=r".*(Button|TextView)", clickable=True).all()[:55]:
            try:
                raw_txt = str(el.info.get("text") or "").strip()
                cd = str(el.info.get("contentDescription") or "").strip()
                merged = raw_txt or cd
            except Exception:
                continue
            if not merged or not _mute_engine_v2_following_header_text_ok(merged):
                continue
            picked, pr = _element_passes(el, pick_reason="clickable_header_band_scan")
            if picked is not None:
                return picked, pr
    except Exception:
        pass

    log(
        "warning",
        "mute_engine_v2_following_button_rejected",
        **base_log,
        reason="exhausted_search_no_cta",
    )
    return None, ""


_MUTE_V2_DANGEROUS_SCREEN_GUESS_FRAGMENTS: tuple[str, ...] = (
    "story",
    "reel",
    "comment",
    "composer",
    "direct",
    "feed",
    "explore",
    "inbox",
)


def _mute_engine_v2_build_lightweight_profile_det(
    d: u2.Device,
    *,
    det_hint: dict[str, Any] | None,
    pkg: str,
) -> dict[str, Any]:
    """Minimal ``det`` for mute V2 when follow state + title already prove target profile (skips heavy XML)."""
    out: dict[str, Any] = {
        "is_followers_list": False,
        "strict_list_open": False,
        "relaxed_list_open": False,
        "action_bar_title": "",
        "current_screen_guess": "likely_profile",
        "profile_tabs_absent": False,
        "candidate_username_count": 0,
        "visible_header_texts": [],
        "current_package": None,
        "current_activity": None,
        "current_package_expected": str(pkg or "").strip(),
    }
    hint = det_hint if isinstance(det_hint, dict) else {}
    ab = str(hint.get("action_bar_title") or "").strip()
    try:
        cur = d.app_current() or {}
        out["current_package"] = cur.get("package")
        out["current_activity"] = cur.get("activity")
    except Exception:
        pass
    try:
        ab_el = d(resourceIdMatches=r".*:id/action_bar_title.*")
        if ab_el.exists(timeout=0.11):
            live = str(ab_el.get_text() or "").strip()
            if live:
                ab = live
    except Exception:
        pass
    out["action_bar_title"] = ab
    cg = str(hint.get("current_screen_guess") or "").strip()
    if cg:
        out["current_screen_guess"] = cg
    return out


def _mute_engine_v2_following_label_visible_quick(
    d: u2.Device, *, timeout_s: float
) -> bool:
    wt = max(0.04, min(0.09, float(timeout_s)))
    for lab in _MUTE_V2_FOLLOWING_STATE_LABELS:
        try:
            if d(text=lab).exists(timeout=wt):
                return True
        except Exception:
            continue
    return False


def _mute_engine_v2_keyboard_focus_edit_text(d: u2.Device, *, timeout_s: float) -> bool:
    try:
        wt = max(0.03, min(0.07, float(timeout_s)))
        ed = d(className="android.widget.EditText", focused=True)
        return bool(ed.exists(timeout=wt))
    except Exception:
        return False


def _mute_engine_v2_truly_dangerous_surface(
    d: u2.Device,
    *,
    pkg: str,
    nav: dict[str, Any],
    det: dict[str, Any],
    fp: dict[str, Any] | None,
    overlay: dict[str, Any],
    remaining_s: float,
) -> tuple[bool, str]:
    """
    Surfaces that must block mute regardless of inline "Suggested for you" on profile.
    """
    from navigation_engine import NavigationEngineState

    if bool(overlay.get("likely_mute_toggle_sheet")):
        return False, ""

    rem = max(0.06, float(remaining_s))
    st = str(nav.get("state") or "")

    exp = str(pkg or "").strip()
    try:
        cur = d.app_current() or {}
        fg = str(cur.get("package") or "")
    except Exception:
        fg = ""
    if exp and fg and fg != exp:
        return True, "wrong_foreground_package"

    if st in (
        NavigationEngineState.LAUNCHER_WRONG_SURFACE.value,
        NavigationEngineState.INSTAGRAM_CLOSED.value,
    ):
        return True, f"bad_nav_state:{st}"

    guess = str(det.get("current_screen_guess") or "").lower()
    if guess:
        for frag in _MUTE_V2_DANGEROUS_SCREEN_GUESS_FRAGMENTS:
            if frag in guess:
                return True, f"screen_guess_drift:{frag}"

    if _mute_engine_v2_keyboard_focus_edit_text(d, timeout_s=min(0.07, rem * 0.12)):
        return True, "keyboard_focus_edittext"

    sc = str((fp or {}).get("screen_class") or "").strip().lower()
    if sc in ("search_like", "followers_list", "followers_list_strong"):
        return True, f"fingerprint_screen_class:{sc}"

    return False, ""


def _mute_engine_v2_resolve_effective_candidate_username(
    *,
    follower_username: str,
    action_bar_title: str,
    source_profile_username: str,
    det_hint: dict[str, Any] | None,
    visual_candidate_id: str,
) -> tuple[str, str]:
    """
    Handle for the opened profile row. ``follower_username`` may be empty in visual mode;
    fall back to action bar / hint / id-shaped handles.
    """
    fu = str(follower_username or "").strip()
    if fu:
        return fu, "follower_username"
    ab = str(action_bar_title or "").strip()
    src = str(source_profile_username or "").strip()
    if ab and src and _normalize_handle(ab) != _normalize_handle(src):
        return ab, "action_bar_title_fallback"
    if ab and not src:
        return ab, "action_bar_title_fallback"
    hint = det_hint if isinstance(det_hint, dict) else {}
    for key in (
        "follower_username",
        "candidate_username",
        "visual_candidate_username",
        "target_username",
        "opened_profile_username",
        "profile_username",
    ):
        v = str(hint.get(key) or "").strip()
        if v and (not src or _normalize_handle(v) != _normalize_handle(src)):
            return v, f"det_hint:{key}"
    vcid = str(visual_candidate_id or "").strip()
    if vcid and re.match(r"^[A-Za-z0-9._]{1,30}$", vcid):
        if not src or _normalize_handle(vcid) != _normalize_handle(src):
            return vcid, "visual_candidate_id"
    return "", "unresolved"


def _mute_engine_v2_surface_unstable(
    d: u2.Device,
    *,
    nav: dict[str, Any],
    overlay: dict[str, Any],
    det: dict[str, Any],
    fp: dict[str, Any] | None,
    follower_username: str,
    follow_state_after: str,
    pkg: str,
    budget_remaining_s: float,
    visual_candidate_id: str = "",
    source_profile_username: str = "",
    det_hint: dict[str, Any] | None = None,
    follow_header_snapshot: str = "",
) -> tuple[bool, str]:
    from navigation_engine import NavigationEngineState

    st = str(nav.get("state") or "")
    allowed = frozenset(
        {
            NavigationEngineState.PROFILE.value,
            NavigationEngineState.CANDIDATE_PROFILE.value,
            NavigationEngineState.PRIVATE_PROFILE.value,
        }
    )
    if st not in allowed:
        return True, f"navigation_not_profile:{st}"
    ab = str(det.get("action_bar_title") or "").strip()
    if not ab:
        return True, "empty_action_bar_title"

    rem_b = max(0.08, float(budget_remaining_s))
    dangerous, dwhy = _mute_engine_v2_truly_dangerous_surface(
        d,
        pkg=pkg,
        nav=nav,
        det=det,
        fp=fp,
        overlay=overlay,
        remaining_s=rem_b,
    )

    ov_sug = bool(overlay.get("suggested_for_you"))
    ov_dis = bool(overlay.get("discover_people"))
    if ov_sug or ov_dis:
        ovt = (
            "both"
            if (ov_sug and ov_dis)
            else ("suggested_for_you" if ov_sug else "discover_people")
        )
        fu_raw = str(follower_username or "").strip()
        src_stripped = str(source_profile_username or "").strip()
        eff, res_src = _mute_engine_v2_resolve_effective_candidate_username(
            follower_username=fu_raw,
            action_bar_title=ab,
            source_profile_username=src_stripped,
            det_hint=det_hint,
            visual_candidate_id=str(visual_candidate_id or ""),
        )
        log(
            "info",
            "mute_engine_v2_effective_candidate_handle_resolved",
            follower_username=fu_raw,
            action_bar_title=ab[:120],
            source_profile_username=src_stripped[:120],
            effective_candidate_username=str(eff or "")[:120],
            resolution_source=res_src,
            visual_candidate_id=str(visual_candidate_id or ""),
        )

        fs_low = str(follow_state_after or "").strip().lower()
        fhs = str(follow_header_snapshot or "").strip().lower()
        fs_from_state = fs_low in ("following", "requested")
        fs_from_header = fhs in ("following", "requested")
        fs_vis = (
            fs_from_state
            or fs_from_header
            or _mute_engine_v2_following_label_visible_quick(
                d, timeout_s=min(0.11, rem_b * 0.28)
            )
        )

        src_norm = _normalize_handle(src_stripped) if src_stripped else ""
        ab_norm = _normalize_handle(ab)
        on_candidate_not_owner = bool(ab) and (not src_norm or ab_norm != src_norm)

        title_ok_explicit = bool(fu_raw) and bool(ab) and (
            _normalize_handle(fu_raw) == ab_norm
        )
        profile_overlay_safe = (
            st in allowed
            and not dangerous
            and fs_vis
            and on_candidate_not_owner
            and (not bool(fu_raw) or title_ok_explicit)
        )

        gate_title_source = ""
        if profile_overlay_safe:
            if bool(fu_raw) and title_ok_explicit:
                gate_title_source = "follower_username_match"
            else:
                gate_title_source = "action_bar_title_fallback"

        base_common: dict[str, Any] = {
            "overlay_type": ovt,
            "action_bar_title": ab[:120],
            "navigation_state": st,
            "following_visible": bool(fs_vis),
            "dangerous_surface": bool(dangerous),
            "dangerous_reason": dwhy or "",
            "visual_candidate_id": str(visual_candidate_id or ""),
            "source_profile_username": src_stripped[:120],
            "follower_username": fu_raw,
            "effective_candidate_username": str(eff or "")[:120],
            "effective_resolution_source": res_src,
        }
        log("info", "mute_engine_v2_overlay_surface_detected", **base_common)

        if dangerous:
            log(
                "warning",
                "mute_engine_v2_overlay_surface_rejected",
                **base_common,
                allow_mute=False,
                safe_profile_overlay_surface=False,
                rejection_reason="dangerous_context",
            )
            return True, dwhy if dwhy else "dangerous_context"

        if profile_overlay_safe:
            log(
                "info",
                "mute_engine_v2_overlay_surface_allowed",
                **base_common,
                allow_mute=True,
                safe_profile_overlay_surface=True,
                profile_gate_title_ok=True,
                profile_gate_title_source=gate_title_source,
            )
        else:
            log(
                "warning",
                "mute_engine_v2_overlay_surface_rejected",
                **base_common,
                allow_mute=False,
                safe_profile_overlay_surface=False,
                rejection_reason="overlay_suggestion_profile_gate_failed",
                profile_gate_title_ok=bool(title_ok_explicit),
                profile_gate_following_visible=bool(fs_vis),
                profile_gate_on_candidate_not_owner=bool(on_candidate_not_owner),
                profile_gate_follow_header_snapshot=fhs[:32],
            )
            return True, "overlay_suggestion_surface"
    elif dangerous:
        return True, dwhy if dwhy else "dangerous_context"

    if overlay.get("notification_prompt") or overlay.get("turn_on_notifications"):
        return True, "overlay_system_prompt"
    if overlay.get("likely_mute_toggle_sheet"):
        try:
            p0 = bool(d(text="Posts").exists(timeout=0.04)) or bool(
                d(text="Publications").exists(timeout=0.04)
            )
            s0 = bool(d(text="Stories").exists(timeout=0.04))
        except Exception:
            p0 = s0 = False
        if not (p0 and s0):
            return True, "mute_sheet_partial_or_unknown"

    return False, ""


def _mute_engine_v2_tap_toggle_short(
    d: u2.Device, labels: tuple[str, ...], ww: int, t0: float
) -> tuple[bool, bool, str]:
    """Returns (tapped_or_already_on, is_already_on, reason)."""
    rem = _mute_engine_v2_remaining_s(t0)
    if rem < 0.08:
        return False, False, "budget"
    wt = max(0.05, min(0.22, rem * 0.35))
    el: Any | None = None
    for lab in labels:
        try:
            cand = d(text=lab)
            if cand.wait(timeout=wt):
                el = cand
                break
        except Exception:
            continue
    if el is None:
        return False, False, "toggle_label_not_found"
    chk = _visual_switch_checked_near_row(d, el)
    if chk is True:
        return True, True, ""
    try:
        b = el.info.get("bounds") or {}
        cy = (int(b["top"]) + int(b["bottom"])) // 2
        tap_x = min(ww - 6, max(int(ww * 0.88), int(b.get("right", 0)) + 72))
        d.click(int(tap_x), int(cy))
    except Exception as e:
        return False, False, f"tap_failed:{e}"
    return True, False, ""


def run_mute_engine_v2(
    d: u2.Device,
    *,
    pkg: str,
    source_profile_username: str,
    visual_candidate_id: str,
    follower_username: str,
    follow_state_after: str,
    det_hint: dict[str, Any] | None,
) -> dict[str, Any]:
    """
    Short, non-exploratory mute after verified follow. No return_to_followers_list,
    no hierarchy refresh, no profile reopen, no scroll/swipe recovery.
    """
    from navigation_engine import NavigationEngineState, observe_instagram_state

    t_all = time.perf_counter()
    timings: dict[str, float] = {}
    vcid = str(visual_candidate_id or "").strip()
    src = str(source_profile_username or "").strip()
    pkg = str(pkg or getattr(config, "INSTAGRAM_PACKAGE", "") or "")
    fs_after = str(follow_state_after or "").strip()
    raw_inv = False
    try:
        raw_inv = bool(_visual_raw_follow_invite_visible_quick(d))
    except Exception:
        raw_inv = False

    log(
        "info",
        "mute_engine_v2_started",
        visual_candidate_id=vcid,
        source_profile_username=src,
        follower_username=str(follower_username or "").strip(),
        follow_state_after=fs_after,
        budget_s=_MUTE_ENGINE_V2_BUDGET_S,
        effective_total_budget_s=_MUTE_ENGINE_V2_EFFECTIVE_TOTAL_S,
        following_cta_reserved_budget_s=MIN_FOLLOWING_CTA_SEARCH_BUDGET_S,
    )

    def _abort(reason: str, *, fr: str | None = None, **log_extra: Any) -> dict[str, Any]:
        timings["mute_total_ms"] = round((time.perf_counter() - t_all) * 1000, 2)
        _log_payload: dict[str, Any] = {
            "visual_candidate_id": vcid,
            "source_profile_username": src,
            "reason": reason,
            "failure_reason": fr or reason,
            "timings_ms": dict(timings),
        }
        if log_extra:
            _log_payload.update({k: v for k, v in log_extra.items() if v is not None})
        log(
            "warning",
            "mute_engine_v2_safe_abort",
            **_log_payload,
        )
        _out: dict[str, Any] = {
            "ok": False,
            "partial": False,
            "skipped": False,
            "failure_reason": fr or reason,
            "outcome": "safe_abort",
            "abort_reason": reason,
            "mute_engine_v2": True,
            "timings_ms": dict(timings),
        }
        if log_extra:
            _out["mute_v2_abort_detail"] = {
                k: v for k, v in log_extra.items() if v is not None and not str(k).startswith("_")
            }
        return _out

    if _mute_engine_v2_remaining_s(t_all) < 0.25:
        return _abort("mute_budget_exceeded", fr="mute_budget_exceeded")

    t_obs = time.perf_counter()
    light_profile_det = False
    det: dict[str, Any] = {}
    fu2 = str(follower_username or "").strip()
    fs_low = str(follow_state_after or "").strip().lower()
    if fs_low in ("following", "requested") and fu2:
        try:
            det_try = _mute_engine_v2_build_lightweight_profile_det(
                d, det_hint=det_hint, pkg=pkg
            )
            ab_try = str(det_try.get("action_bar_title") or "").strip()
            if ab_try and _normalize_handle(ab_try) == _normalize_handle(fu2):
                det = det_try
                light_profile_det = True
        except Exception:
            pass
    if not light_profile_det:
        try:
            det = detect_followers_list_screen(d, source_profile_username=src)
        except Exception:
            det = {}
    timings["mute_engine_v2_screen_det_ms"] = round(
        (time.perf_counter() - t_obs) * 1000, 2
    )
    if isinstance(det_hint, dict) and det_hint:
        if not str(det.get("action_bar_title") or "").strip():
            abh = str(det_hint.get("action_bar_title") or "").strip()
            if abh:
                det = {**det, "action_bar_title": abh}
        if not str(det.get("current_screen_guess") or "").strip():
            cg = str(det_hint.get("current_screen_guess") or "").strip()
            if cg:
                det = {**det, "current_screen_guess": cg}

    ab_live = str(det.get("action_bar_title") or "").strip()
    eff_early, res_early = _mute_engine_v2_resolve_effective_candidate_username(
        follower_username=fu2,
        action_bar_title=ab_live,
        source_profile_username=src,
        det_hint=det_hint if isinstance(det_hint, dict) else None,
        visual_candidate_id=vcid,
    )
    trusted_eff_fp = False
    if str(res_early or "") == "follower_username" and str(eff_early or "").strip():
        trusted_eff_fp = True
    elif (
        str(res_early or "") == "action_bar_title_fallback"
        and str(eff_early or "").strip()
        and ab_live
        and src
        and _normalize_handle(ab_live) != _normalize_handle(src)
    ):
        trusted_eff_fp = True

    try:
        log(
            "info",
            "mute_engine_v2_early_effective_candidate_handle_resolved",
            visual_candidate_id=vcid,
            follower_username=fu2[:120] if fu2 else "",
            action_bar_title=ab_live[:120],
            effective_candidate_username=str(eff_early or "")[:120],
            resolution_source=str(res_early or ""),
            trusted_for_fast_path=bool(trusted_eff_fp),
            source_profile_username=src[:120] if src else "",
        )
    except Exception:
        pass

    handle_fp_match = (
        fu2 if fu2 else (str(eff_early or "").strip() if trusted_eff_fp else "")
    ).strip()
    if (
        not light_profile_det
        and fs_low in ("following", "requested")
        and handle_fp_match
        and trusted_eff_fp
    ):
        try:
            det_try2 = _mute_engine_v2_build_lightweight_profile_det(
                d, det_hint=det_hint, pkg=pkg
            )
            ab_try2 = str(det_try2.get("action_bar_title") or "").strip()
            if ab_try2 and _normalize_handle(ab_try2) == _normalize_handle(handle_fp_match):
                det = det_try2
                light_profile_det = True
                if isinstance(det_hint, dict) and det_hint:
                    if not str(det.get("action_bar_title") or "").strip():
                        abh2 = str(det_hint.get("action_bar_title") or "").strip()
                        if abh2:
                            det = {**det, "action_bar_title": abh2}
                    if not str(det.get("current_screen_guess") or "").strip():
                        cg2 = str(det_hint.get("current_screen_guess") or "").strip()
                        if cg2:
                            det = {**det, "current_screen_guess": cg2}
        except Exception:
            pass

    ab_live = str(det.get("action_bar_title") or "").strip()

    nav_ctx: dict[str, Any] = {
        "phase": "mute_engine_v2",
        "visual_candidate_id": vcid,
        "source_profile_username": src,
        "det": det,
        "disable_followers_visual_fallback": True,
    }
    mute_preflight_fast = False
    src_norm = _normalize_handle(src) if src else ""
    ab_norm = _normalize_handle(ab_live) if ab_live else ""
    on_candidate_not_owner = bool(ab_live) and (not src_norm or ab_norm != src_norm)
    try:
        following_chip = _mute_engine_v2_following_label_visible_quick(d, timeout_s=0.16)
    except Exception:
        following_chip = False
    if (
        fs_low in ("following", "requested")
        and following_chip
        and ab_live
        and on_candidate_not_owner
    ):
        mute_preflight_fast = True

    t_nav = time.perf_counter()
    if mute_preflight_fast:
        nav = {
            "state": NavigationEngineState.PROFILE.value,
            "confidence": 0.86,
            "reason": "mute_v2_preflight_profile_following_visible_short_circuit",
            "signals": {"mute_v2_fast_observe": True},
            "xml_guess": str(det.get("current_screen_guess") or ""),
            "visual_guess": "",
            "foreground_package": pkg,
        }
        try:
            log(
                "info",
                "mute_engine_v2_observe_short_circuited",
                visual_candidate_id=vcid,
                source_profile_username=src,
                navigation_state=str(nav.get("state") or ""),
                light_profile_det=bool(light_profile_det),
                action_bar_title=ab_live[:120],
                follow_state_after=fs_low,
                note="skip_observe_instagram_state_following_label_visible",
            )
        except Exception:
            pass
    else:
        try:
            nav = observe_instagram_state(
                d,
                expected_package=pkg,
                last_known_state=NavigationEngineState.CANDIDATE_PROFILE.value,
                context=nav_ctx,
            )
        except Exception as e:
            nav = {"state": "UNKNOWN", "confidence": 0.0, "reason": str(e)}
    timings["observe_nav_ms"] = round((time.perf_counter() - t_nav) * 1000, 2)

    nav_st = str(nav.get("state") or "")
    safe_fp_fast = (
        bool(mute_preflight_fast)
        and bool(light_profile_det)
        and nav_st == NavigationEngineState.PROFILE.value
        and fs_low in ("following", "requested")
        and bool(handle_fp_match)
        and bool(ab_live)
        and _normalize_handle(handle_fp_match) == _normalize_handle(ab_live)
    )

    t_ov = time.perf_counter()
    overlay = _post_follow_overlay_ui_hints(d)
    if safe_fp_fast:
        fp = _post_follow_screen_fingerprint_mute_v2_fast(
            d,
            nav_state=nav_st,
            det=det,
            action_bar_title=ab_live,
            follow_header_state=fs_low,
        )
        try:
            log(
                "info",
                "mute_engine_v2_fast_fingerprint_used",
                visual_candidate_id=vcid,
                source_profile_username=src,
                action_bar_title=ab_live[:120],
                follower_username=fu2[:120] if fu2 else "",
                effective_candidate_username=handle_fp_match[:120] if handle_fp_match else "",
                follow_state_after=fs_low,
                reason="post_follow_verified_safe_context",
            )
        except Exception:
            pass
    else:
        fp = _post_follow_screen_fingerprint(
            d, nav_state=nav_st, det=det
        )
        try:
            log(
                "info",
                "mute_engine_v2_full_fingerprint_used",
                visual_candidate_id=vcid,
                source_profile_username=src,
                navigation_state=nav_st,
                mute_preflight_fast=bool(mute_preflight_fast),
                light_profile_det=bool(light_profile_det),
                follow_state_after=fs_low,
            )
        except Exception:
            pass
    timings["mute_engine_v2_overlay_fp_ms"] = round(
        (time.perf_counter() - t_ov) * 1000, 2
    )
    fhs = ""
    if safe_fp_fast:
        fhs = fs_low
    else:
        try:
            fhs = str(_follow_ui_state_snapshot(d) or "").strip()
        except Exception:
            fhs = ""
    ui_snapshot = {
        "action_bar_title": str(det.get("action_bar_title") or "")[:120],
        "visible_header_texts": list((det.get("visible_header_texts") or [])[:14]),
        "raw_follow_invite_visible": raw_inv,
        "follow_header_snapshot": fhs,
        "fingerprint_id": fp.get("fingerprint_id"),
        "screen_class": fp.get("screen_class"),
        "light_profile_det": light_profile_det,
    }
    log(
        "info",
        "mute_engine_v2_state_observed",
        visual_candidate_id=vcid,
        source_profile_username=src,
        navigation_state=str(nav.get("state") or ""),
        navigation_confidence=float(nav.get("confidence") or 0.0),
        xml_guess=str(nav.get("xml_guess") or det.get("current_screen_guess") or ""),
        **ui_snapshot,
    )
    timings["observe_state_ms"] = round((time.perf_counter() - t_obs) * 1000, 2)

    if not _vision_validation_mute_engine_surface(
        screenshot_path="",
        det=det,
        nav=nav,
        overlay=overlay,
        fp=fp if isinstance(fp, dict) else {},
        follow_header_snapshot=fhs,
        follow_state_after=fs_after,
        visual_candidate_id=vcid,
        source_profile_username=src,
    ):
        return _abort(
            "vision_validation_mute_surface_rejected",
            fr="vision_validation_mute_surface_rejected",
        )

    bad, why = _mute_engine_v2_surface_unstable(
        d,
        nav=nav,
        overlay=overlay,
        det=det,
        fp=fp if isinstance(fp, dict) else None,
        follower_username=follower_username,
        follow_state_after=follow_state_after,
        pkg=pkg,
        budget_remaining_s=_mute_engine_v2_remaining_s(t_all),
        visual_candidate_id=vcid,
        source_profile_username=src,
        det_hint=det_hint if isinstance(det_hint, dict) else None,
        follow_header_snapshot=fhs,
    )
    if bad:
        return _abort("unstable_post_follow_surface", fr=why)

    try:
        ww, wh = d.window_size()
    except Exception:
        ww, wh = 1080, 2400

    skip_following = False
    try:
        if overlay.get("likely_mute_toggle_sheet"):
            p0 = bool(d(text="Posts").exists(timeout=0.06)) or bool(
                d(text="Publications").exists(timeout=0.05)
            )
            s0 = bool(d(text="Stories").exists(timeout=0.06))
            if p0 and s0:
                skip_following = True
                log(
                    "info",
                    "mute_engine_v2_sheet_detected",
                    visual_candidate_id=vcid,
                    source_profile_username=src,
                    phase="precheck",
                    posts_visible=True,
                    stories_visible=True,
                    note="sheet_already_visible_skip_following_tap",
                )
    except Exception:
        pass

    t_follow = time.perf_counter()
    following_method = ""
    if not skip_following:
        _eff_total = float(_MUTE_ENGINE_V2_EFFECTIVE_TOTAL_S)
        _obs_cap = max(0.0, _eff_total - float(MIN_FOLLOWING_CTA_SEARCH_BUDGET_S))
        _rem_cta = _mute_engine_v2_remaining_s(t_all)
        try:
            log(
                "info",
                "mute_engine_v2_budget_allocated",
                visual_candidate_id=vcid,
                source_profile_username=src,
                total_budget_s=round(_eff_total, 4),
                observe_budget_s=round(_obs_cap, 4),
                following_cta_reserved_budget_s=float(MIN_FOLLOWING_CTA_SEARCH_BUDGET_S),
                toggle_stage_reserved_budget_s=float(MIN_MUTE_TOGGLE_STAGE_BUDGET_S),
                budget_remaining_before_cta_s=round(float(_rem_cta), 4),
                mute_preflight_fast_observe=bool(mute_preflight_fast),
            )
        except Exception:
            pass
        btn, following_method = _mute_engine_v2_pick_following_cta(
            d,
            ww=ww,
            wh=wh,
            t0=t_all,
            visual_candidate_id=vcid,
            source_profile_username=src,
        )
        if btn is None:
            log(
                "warning",
                "mute_engine_v2_following_button_missing",
                visual_candidate_id=vcid,
                source_profile_username=src,
                navigation_state=str(nav.get("state") or ""),
                action_bar_title=str(det.get("action_bar_title") or "")[:120],
                budget_remaining_s=round(float(_mute_engine_v2_remaining_s(t_all)), 4),
            )
            _rem_post = _mute_engine_v2_remaining_s(t_all)
            if _rem_post <= 0.1:
                return _abort(
                    "following_button_search_budget_exhausted",
                    fr="following_button_search_budget_exhausted",
                )
            return _abort("following_button_not_found", fr="following_button_not_found")
        log(
            "info",
            "mute_engine_v2_following_button_detected",
            visual_candidate_id=vcid,
            source_profile_username=src,
            method=following_method,
        )
        try:
            btn.click()
        except Exception as e:
            return _abort("following_click_failed", fr=str(e))
        time.sleep(min(0.38, max(0.12, _mute_engine_v2_remaining_s(t_all) * 0.25)))

    timings["following_detect_ms"] = round((time.perf_counter() - t_follow) * 1000, 2)

    if _mute_engine_v2_remaining_s(t_all) < 0.2:
        return _abort("mute_budget_exceeded", fr="mute_budget_exceeded")

    t_sheet = time.perf_counter()
    if not skip_following:
        mute_el, mute_lab = _visual_find_mute_row_first_sheet(d)
        if mute_el is None:
            return _abort("mute_row_not_found", fr="mute_row_not_found")
        try:
            mute_el.click()
        except Exception as e:
            return _abort("mute_row_click_failed", fr=str(e))
        time.sleep(min(0.42, max(0.12, _mute_engine_v2_remaining_s(t_all) * 0.28)))

    posts_v = bool(d(text="Posts").exists(timeout=min(0.35, _mute_engine_v2_remaining_s(t_all) * 0.45)))
    if not posts_v:
        posts_v = bool(
            d(text="Publications").exists(
                timeout=min(0.22, max(0.05, _mute_engine_v2_remaining_s(t_all) * 0.35))
            )
        )
    stories_v = bool(
        d(text="Stories").exists(
            timeout=min(0.35, max(0.05, _mute_engine_v2_remaining_s(t_all) * 0.45))
        )
    )
    timings["mute_sheet_open_ms"] = round((time.perf_counter() - t_sheet) * 1000, 2)

    if not posts_v or not stories_v:
        return _abort("posts_or_stories_labels_missing", fr="posts_or_stories_labels_missing")

    log(
        "info",
        "mute_engine_v2_sheet_detected",
        visual_candidate_id=vcid,
        source_profile_username=src,
        posts_visible=posts_v,
        stories_visible=stories_v,
    )

    _rem_toggle_stage = _mute_engine_v2_remaining_s(t_all)
    timings["toggle_stage_remaining_budget_s"] = round(_rem_toggle_stage, 4)
    timings["toggle_stage_required_budget_s"] = float(MIN_MUTE_TOGGLE_STAGE_BUDGET_S)
    _req_toggle_floor = float(MIN_MUTE_TOGGLE_STAGE_BUDGET_S) * 0.92
    if _rem_toggle_stage < _req_toggle_floor:
        return _abort(
            "mute_toggle_budget_starved",
            fr="mute_toggle_budget_starved",
            remaining_budget_s=round(_rem_toggle_stage, 4),
            required_toggle_budget_s=round(_req_toggle_floor, 4),
            phase="post_sheet_pre_toggle",
        )
    try:
        log(
            "info",
            "mute_engine_v2_toggle_stage_entered",
            visual_candidate_id=vcid,
            source_profile_username=src,
            remaining_budget_s=round(_rem_toggle_stage, 4),
            required_toggle_budget_s=float(MIN_MUTE_TOGGLE_STAGE_BUDGET_S),
        )
    except Exception:
        pass

    want_posts = bool(getattr(config, "VISUAL_MUTE_POSTS_AFTER_FOLLOW", True))
    want_stories = bool(getattr(config, "VISUAL_MUTE_STORIES_AFTER_FOLLOW", True))
    posts_labels = ("Posts", "Publications")
    stories_labels = ("Stories", "Historias", "Storie")

    posts_ok = not want_posts
    stories_ok = not want_stories
    posts_tapped = False
    stories_tapped = False
    tapped_p = False
    already_p = False
    rsn_p = "skipped"
    tapped_s = False
    already_s = False
    rsn_s = "skipped"

    if want_posts:
        try:
            log(
                "info",
                "mute_engine_v2_posts_toggle_started",
                visual_candidate_id=vcid,
                source_profile_username=src,
                remaining_budget_s=round(_mute_engine_v2_remaining_s(t_all), 4),
            )
        except Exception:
            pass
        t_tp = time.perf_counter()
        tapped_p, already_p, rsn_p = _mute_engine_v2_tap_toggle_short(
            d, posts_labels, ww, t_all
        )
        posts_tapped = bool(tapped_p and not already_p)
        if already_p:
            posts_ok = True
        elif tapped_p:
            _settle = min(
                float(_MUTE_V2_TOGGLE_POST_TAP_SETTLE_S),
                max(0.0, _mute_engine_v2_remaining_s(t_all) - 0.06),
            )
            if _settle >= 0.02:
                time.sleep(_settle)
            _rem_v = _mute_engine_v2_remaining_s(t_all)
            vto = min(
                float(_MUTE_V2_TOGGLE_VERIFY_MAX_S),
                max(
                    float(_MUTE_V2_TOGGLE_VERIFY_MIN_S),
                    min(_rem_v * 0.48, float(_MUTE_V2_TOGGLE_VERIFY_MAX_S)),
                ),
            )
            posts_ok, _posts_vmeta = _visual_verify_toggle_on_for_labels_detailed(
                d, posts_labels, timeout_s=vto
            )
            if not posts_ok:
                try:
                    log(
                        "warning",
                        "mute_engine_v2_toggle_verify_diag",
                        axis="posts",
                        visual_candidate_id=vcid,
                        source_profile_username=src,
                        verify_timeout_s=_posts_vmeta.get("verify_timeout_s"),
                        verify_ok=bool(_posts_vmeta.get("verify_ok")),
                        probe_cycles=_posts_vmeta.get("probe_cycles"),
                        inner_probes=_posts_vmeta.get("inner_probes"),
                        last_label=_posts_vmeta.get("last_label"),
                        last_checked_signal=_posts_vmeta.get("last_checked_signal"),
                        last_switches_in_band=_posts_vmeta.get("last_switches_in_band"),
                        last_nearest_dy=_posts_vmeta.get("last_nearest_dy"),
                        checked_raw_on_nearest=_posts_vmeta.get("checked_raw_on_nearest"),
                        post_tap_settle_s=round(_settle, 4),
                        matched_toggle_class=_posts_vmeta.get("matched_toggle_class"),
                        matched_toggle_resource_id=_posts_vmeta.get("matched_toggle_resource_id"),
                        matched_toggle_checked=_posts_vmeta.get("matched_toggle_checked"),
                    )
                except Exception:
                    pass
                try:
                    _mute_engine_v2_toggle_live_candidates_diag(
                        d,
                        axis="posts",
                        vmeta=_posts_vmeta,
                        labels_tuple=posts_labels,
                        visual_candidate_id=vcid,
                        source_profile_username=src,
                    )
                except Exception:
                    pass
                try:
                    if _mute_engine_v2_toggle_verify_xml_fallback_maybe(
                        d,
                        axis="posts",
                        vmeta=_posts_vmeta,
                        visual_candidate_id=vcid,
                        source_profile_username=src,
                    ):
                        posts_ok = True
                except Exception:
                    pass
                _mute_engine_v2_toggle_verify_structure_diag(
                    d,
                    axis="posts",
                    labels_tuple=posts_labels,
                    vmeta=_posts_vmeta,
                    visual_candidate_id=vcid,
                    source_profile_username=src,
                )
        timings["toggle_posts_ms"] = round((time.perf_counter() - t_tp) * 1000, 2)
        try:
            log(
                "info",
                "mute_engine_v2_posts_toggle_completed",
                visual_candidate_id=vcid,
                source_profile_username=src,
                posts_ok=bool(posts_ok),
                posts_toggle_raw_reason=rsn_p,
                posts_toggle_reason=_mute_engine_v2_map_toggle_rsn(rsn_p),
                posts_tap_attempted=bool(posts_tapped),
                remaining_budget_s=round(_mute_engine_v2_remaining_s(t_all), 4),
            )
        except Exception:
            pass
        if posts_ok:
            log(
                "info",
                "mute_engine_v2_posts_toggle_detected",
                visual_candidate_id=vcid,
                source_profile_username=src,
                posts_verified=True,
            )

    if want_stories:
        try:
            log(
                "info",
                "mute_engine_v2_stories_toggle_started",
                visual_candidate_id=vcid,
                source_profile_username=src,
                remaining_budget_s=round(_mute_engine_v2_remaining_s(t_all), 4),
            )
        except Exception:
            pass
        t_ts = time.perf_counter()
        tapped_s, already_s, rsn_s = _mute_engine_v2_tap_toggle_short(
            d, stories_labels, ww, t_all
        )
        stories_tapped = bool(tapped_s and not already_s)
        if already_s:
            stories_ok = True
        elif tapped_s:
            _settle_s = min(
                float(_MUTE_V2_TOGGLE_POST_TAP_SETTLE_S),
                max(0.0, _mute_engine_v2_remaining_s(t_all) - 0.06),
            )
            if _settle_s >= 0.02:
                time.sleep(_settle_s)
            _rem_vs = _mute_engine_v2_remaining_s(t_all)
            vto_s = min(
                float(_MUTE_V2_TOGGLE_VERIFY_MAX_S),
                max(
                    float(_MUTE_V2_TOGGLE_VERIFY_MIN_S),
                    min(_rem_vs * 0.48, float(_MUTE_V2_TOGGLE_VERIFY_MAX_S)),
                ),
            )
            stories_ok, _stories_vmeta = _visual_verify_toggle_on_for_labels_detailed(
                d, stories_labels, timeout_s=vto_s
            )
            if not stories_ok:
                try:
                    log(
                        "warning",
                        "mute_engine_v2_toggle_verify_diag",
                        axis="stories",
                        visual_candidate_id=vcid,
                        source_profile_username=src,
                        verify_timeout_s=_stories_vmeta.get("verify_timeout_s"),
                        verify_ok=bool(_stories_vmeta.get("verify_ok")),
                        probe_cycles=_stories_vmeta.get("probe_cycles"),
                        inner_probes=_stories_vmeta.get("inner_probes"),
                        last_label=_stories_vmeta.get("last_label"),
                        last_checked_signal=_stories_vmeta.get("last_checked_signal"),
                        last_switches_in_band=_stories_vmeta.get("last_switches_in_band"),
                        last_nearest_dy=_stories_vmeta.get("last_nearest_dy"),
                        checked_raw_on_nearest=_stories_vmeta.get("checked_raw_on_nearest"),
                        post_tap_settle_s=round(_settle_s, 4),
                        matched_toggle_class=_stories_vmeta.get("matched_toggle_class"),
                        matched_toggle_resource_id=_stories_vmeta.get("matched_toggle_resource_id"),
                        matched_toggle_checked=_stories_vmeta.get("matched_toggle_checked"),
                    )
                except Exception:
                    pass
                try:
                    _mute_engine_v2_toggle_live_candidates_diag(
                        d,
                        axis="stories",
                        vmeta=_stories_vmeta,
                        labels_tuple=stories_labels,
                        visual_candidate_id=vcid,
                        source_profile_username=src,
                    )
                except Exception:
                    pass
                try:
                    if _mute_engine_v2_toggle_verify_xml_fallback_maybe(
                        d,
                        axis="stories",
                        vmeta=_stories_vmeta,
                        visual_candidate_id=vcid,
                        source_profile_username=src,
                    ):
                        stories_ok = True
                except Exception:
                    pass
                _mute_engine_v2_toggle_verify_structure_diag(
                    d,
                    axis="stories",
                    labels_tuple=stories_labels,
                    vmeta=_stories_vmeta,
                    visual_candidate_id=vcid,
                    source_profile_username=src,
                )
        timings["toggle_stories_ms"] = round((time.perf_counter() - t_ts) * 1000, 2)
        try:
            log(
                "info",
                "mute_engine_v2_stories_toggle_completed",
                visual_candidate_id=vcid,
                source_profile_username=src,
                stories_ok=bool(stories_ok),
                stories_toggle_raw_reason=rsn_s,
                stories_toggle_reason=_mute_engine_v2_map_toggle_rsn(rsn_s),
                stories_tap_attempted=bool(stories_tapped),
                remaining_budget_s=round(_mute_engine_v2_remaining_s(t_all), 4),
            )
        except Exception:
            pass
        if stories_ok:
            log(
                "info",
                "mute_engine_v2_stories_toggle_detected",
                visual_candidate_id=vcid,
                source_profile_username=src,
                stories_verified=True,
            )

    timings["mute_total_ms"] = round((time.perf_counter() - t_all) * 1000, 2)

    if want_posts and want_stories:
        if posts_ok and stories_ok:
            log(
                "info",
                "mute_engine_v2_success",
                visual_candidate_id=vcid,
                source_profile_username=src,
                timings_ms=dict(timings),
            )
            return {
                "ok": True,
                "partial": False,
                "skipped": False,
                "failure_reason": None,
                "outcome": "success",
                "abort_reason": None,
                "mute_engine_v2": True,
                "posts_verified": True,
                "stories_verified": True,
                "posts_tapped": posts_tapped,
                "stories_tapped": stories_tapped,
                "mute_row_label": "",
                "timings_ms": dict(timings),
            }
        if posts_ok or stories_ok:
            log(
                "warning",
                "mute_engine_v2_partial_success",
                visual_candidate_id=vcid,
                source_profile_username=src,
                posts_verified=bool(posts_ok),
                stories_verified=bool(stories_ok),
                timings_ms=dict(timings),
            )
            return {
                "ok": True,
                "partial": True,
                "skipped": False,
                "failure_reason": "mute_partial_one_toggle",
                "outcome": "partial_success",
                "abort_reason": None,
                "mute_engine_v2": True,
                "posts_verified": bool(posts_ok),
                "stories_verified": bool(stories_ok),
                "posts_tapped": posts_tapped,
                "stories_tapped": stories_tapped,
                "timings_ms": dict(timings),
            }
        _ab_reason, _fail_reason = _mute_engine_v2_classify_both_toggles_failure(
            want_posts=want_posts,
            want_stories=want_stories,
            posts_ok=posts_ok,
            stories_ok=stories_ok,
            tapped_p=tapped_p,
            tapped_s=tapped_s,
            already_p=already_p,
            already_s=already_s,
            rsn_p=rsn_p,
            rsn_s=rsn_s,
        )
        return _abort(
            _ab_reason,
            fr=_fail_reason,
            posts_verified=False,
            stories_verified=False,
            posts_toggle_reason=_mute_engine_v2_map_toggle_rsn(rsn_p),
            stories_toggle_reason=_mute_engine_v2_map_toggle_rsn(rsn_s),
            posts_toggle_raw_reason=rsn_p,
            stories_toggle_raw_reason=rsn_s,
            posts_tap_attempted=bool(posts_tapped),
            stories_tap_attempted=bool(stories_tapped),
        )

    # only one of want_posts / want_stories
    if (want_posts and posts_ok) or (want_stories and stories_ok):
        log(
            "info",
            "mute_engine_v2_success",
            visual_candidate_id=vcid,
            source_profile_username=src,
            timings_ms=dict(timings),
        )
        return {
            "ok": True,
            "partial": False,
            "skipped": False,
            "failure_reason": None,
            "outcome": "success",
            "abort_reason": None,
            "mute_engine_v2": True,
            "posts_verified": bool(posts_ok),
            "stories_verified": bool(stories_ok),
            "posts_tapped": posts_tapped,
            "stories_tapped": stories_tapped,
            "timings_ms": dict(timings),
        }
    _ab2, _fr2 = _mute_engine_v2_classify_single_toggle_failure(
        want_posts=want_posts,
        want_stories=want_stories,
        posts_ok=posts_ok,
        stories_ok=stories_ok,
        tapped_p=tapped_p,
        tapped_s=tapped_s,
        already_p=already_p,
        already_s=already_s,
        rsn_p=rsn_p,
        rsn_s=rsn_s,
    )
    return _abort(
        _ab2,
        fr=_fr2,
        posts_verified=bool(posts_ok),
        stories_verified=bool(stories_ok),
        posts_toggle_reason=_mute_engine_v2_map_toggle_rsn(rsn_p),
        stories_toggle_reason=_mute_engine_v2_map_toggle_rsn(rsn_s),
        posts_toggle_raw_reason=rsn_p,
        stories_toggle_raw_reason=rsn_s,
        posts_tap_attempted=bool(posts_tapped),
        stories_tap_attempted=bool(stories_tapped),
    )


def _post_follow_post_likes_count_from_range(spec: str) -> int:
    """Parse likes count range (e.g. '1-1', '2-3') and return one random target in band."""
    raw = str(spec or "1-1").strip()
    lo, hi = 1, 1
    if "-" in raw:
        parts = raw.split("-", 1)
        try:
            lo = max(0, int(parts[0].strip()))
            hi = max(lo, int(parts[1].strip()))
        except (TypeError, ValueError):
            lo, hi = 1, 1
    else:
        try:
            lo = hi = max(0, int(raw))
        except (TypeError, ValueError):
            lo = hi = 1
    if hi <= lo:
        return lo
    return int(random.randint(lo, hi))


def _post_follow_post_likes_out_template() -> dict[str, Any]:
    return {
        "ok": False,
        "skipped": True,
        "skipped_reason": None,
        "phase_outcome": "skipped",
        "target_count": 0,
        "attempted_count": 0,
        "liked_count": 0,
        "skipped_already_liked_count": 0,
        "failed_navigation_count": 0,
        "post_like_mode": "profile_grid_single_v1",
        "timings_ms": {},
        "per_post": [],
    }


def run_post_follow_post_likes_phase(
    d: u2.Device,
    *,
    pkg: str,
    source_profile_username: str,
    follower_username: str,
    visual_candidate_id: str,
    follow_success_verified: bool,
    follow_state_after: str,
    skipped_tap: bool,
    session_likes_used: int = 0,
) -> dict[str, Any]:
    """
    Post-follow: like recent post(s) on the open candidate profile (V1: single post).
    Best-effort; does not return to followers list (caller runs return CT next).
    """
    from navigation_engine import NavigationEngineState, observe_instagram_state

    t_all = time.perf_counter()
    timings: dict[str, float] = {}
    pkg = str(pkg or getattr(config, "INSTAGRAM_PACKAGE", "") or "")
    src = str(source_profile_username or "").strip()
    cand = str(follower_username or "").strip().lstrip("@")
    vcid = str(visual_candidate_id or "").strip()
    fs_after = str(follow_state_after or "").strip()
    follow_priv = bool(getattr(config, "FOLLOW_PRIVATE_ACCOUNTS", False))
    pending_rq = fs_after == "requested"

    out = _post_follow_post_likes_out_template()
    out["post_like_mode"] = "profile_grid_single_v1"
    _likes_perf_ctx: dict[str, Any] = {
        "phase_t0": time.perf_counter(),
        "summary_emitted": False,
        "grid": {},
        "grid_readiness_mode": None,
        "final_grid_state": None,
        "final_suggested_for_you": None,
        "final_profile_tabs_visible": None,
        "post_open": {},
        "like": {},
        "already_liked_decision_ms": None,
        "like_verify_ms": None,
        "verify_attempts_count": None,
        "verification_method": None,
        "verify_success": None,
        "like_verify_failure_reason": None,
        "return_to_profile_ms": None,
        "return_success": None,
        "failure_reason": None,
    }

    def _likes_cfg_effective() -> dict[str, Any]:
        return {
            "post_follow_enabled": bool(
                getattr(config, "POST_FOLLOW_POST_LIKES_ENABLED", False)
            ),
            "real_visual_like_enabled": bool(
                getattr(config, "ENABLE_REAL_VISUAL_POST_LIKE", False)
            ),
            "percentage": int(getattr(config, "POST_FOLLOW_POST_LIKES_PERCENTAGE", 100) or 100),
            "count_range": str(
                getattr(config, "POST_FOLLOW_POST_LIKES_COUNT_RANGE", "1-1") or "1-1"
            ),
            "total_likes_limit": int(
                getattr(config, "POST_FOLLOW_TOTAL_LIKES_LIMIT", 150) or 150
            ),
            "session_likes_used": max(0, int(session_likes_used or 0)),
            "budget_s": float(getattr(config, "POST_FOLLOW_POST_LIKES_BUDGET_S", 10.0) or 10.0),
        }

    def _log_likes_early_exit(skipped_reason: str, **extra: Any) -> None:
        cfg = _likes_cfg_effective()
        try:
            log(
                "info",
                "post_follow_post_likes_phase_skipped",
                visual_candidate_id=vcid,
                source_profile_username=src,
                follower_username=cand,
                skipped_reason=str(skipped_reason or ""),
                POST_FOLLOW_POST_LIKES_ENABLED_effective=cfg["post_follow_enabled"],
                ENABLE_REAL_VISUAL_POST_LIKE_effective=cfg["real_visual_like_enabled"],
                POST_FOLLOW_POST_LIKES_PERCENTAGE_effective=cfg["percentage"],
                POST_FOLLOW_TOTAL_LIKES_LIMIT_effective=cfg["total_likes_limit"],
                session_likes_used=cfg["session_likes_used"],
                **extra,
            )
        except Exception:
            pass

    def _finish(
        *,
        phase_outcome: str,
        skipped_reason: str | None = None,
        skipped: bool = True,
        ok: bool = False,
        log_early_exit: bool = False,
        **counts: Any,
    ) -> dict[str, Any]:
        _clear_post_follow_open_like_proof_stash()
        if log_early_exit and skipped_reason:
            _log_likes_early_exit(skipped_reason)
        timings["likes_total_ms"] = round((time.perf_counter() - t_all) * 1000, 2)
        out["timings_ms"] = dict(timings)
        out["phase_outcome"] = phase_outcome
        out["skipped"] = skipped
        out["skipped_reason"] = skipped_reason
        out["ok"] = ok
        for k, v in counts.items():
            if k in out:
                out[k] = v
        if not bool(_likes_perf_ctx.get("summary_emitted")):
            pt0 = _likes_perf_ctx.get("phase_t0")
            if not isinstance(pt0, (int, float)):
                pt0 = t_all
            try:
                g = _likes_perf_ctx.get("grid")
                g_dict = g if isinstance(g, dict) else {}
                _log_post_follow_post_likes_perf_summary(
                    phase_outcome=str(phase_outcome or ""),
                    visual_candidate_id=vcid,
                    source_profile_username=src,
                    follower_username=cand,
                    likes_phase_perf_t0=float(pt0),
                    likes_phase_total_ms=round(
                        (time.perf_counter() - float(pt0)) * 1000.0, 2
                    ),
                    likes_perf_grid=g_dict if g_dict else None,
                    likes_perf_post_open=_likes_perf_ctx.get("post_open") or None,
                    likes_perf_like=_likes_perf_ctx.get("like") or None,
                    already_liked_decision_ms=_likes_perf_ctx.get(
                        "already_liked_decision_ms"
                    ),
                    like_verify_total_ms=_likes_perf_ctx.get("like_verify_ms"),
                    verify_attempts_count=_likes_perf_ctx.get("verify_attempts_count"),
                    verification_method=_likes_perf_ctx.get("verification_method"),
                    verify_success=_likes_perf_ctx.get("verify_success"),
                    like_verify_failure_reason=_likes_perf_ctx.get(
                        "like_verify_failure_reason"
                    ),
                    return_to_profile_total_ms=_likes_perf_ctx.get(
                        "return_to_profile_ms"
                    ),
                    return_success=_likes_perf_ctx.get("return_success"),
                    grid_readiness_mode=_likes_perf_ctx.get("grid_readiness_mode"),
                    final_grid_state=_likes_perf_ctx.get("final_grid_state"),
                    final_suggested_for_you=_likes_perf_ctx.get(
                        "final_suggested_for_you"
                    ),
                    final_profile_tabs_visible=_likes_perf_ctx.get(
                        "final_profile_tabs_visible"
                    ),
                    failure_reason=_likes_perf_ctx.get("failure_reason")
                    or (skipped_reason if phase_outcome != "success" else None),
                )
                _likes_perf_ctx["summary_emitted"] = True
            except Exception as e:
                try:
                    log(
                        "warning",
                        "post_follow_post_likes_perf_summary_emit_failed",
                        visual_candidate_id=vcid,
                        source_profile_username=src,
                        follower_username=cand,
                        phase_outcome=str(phase_outcome or ""),
                        error=str(e)[:240],
                    )
                except Exception:
                    pass
        return out

    log(
        "info",
        "post_follow_post_likes_phase_started",
        visual_candidate_id=vcid,
        source_profile_username=src,
        follower_username=cand,
        follow_success_verified=bool(follow_success_verified),
        follow_state_after=fs_after,
    )
    _cfg_snap = _likes_cfg_effective()
    try:
        log(
            "info",
            "post_follow_post_likes_config_snapshot",
            visual_candidate_id=vcid,
            source_profile_username=src,
            follower_username=cand,
            post_follow_enabled=_cfg_snap["post_follow_enabled"],
            real_visual_like_enabled=_cfg_snap["real_visual_like_enabled"],
            percentage=_cfg_snap["percentage"],
            count_range=_cfg_snap["count_range"],
            total_likes_limit=_cfg_snap["total_likes_limit"],
            session_likes_used=_cfg_snap["session_likes_used"],
            budget_s=round(float(_cfg_snap["budget_s"]), 3),
        )
    except Exception:
        pass

    if not cand:
        _log_likes_early_exit("unresolved_follower_username")
        return _finish(phase_outcome="skipped", skipped_reason="unresolved_follower_username")

    if not follow_success_verified:
        return _finish(
            phase_outcome="skipped",
            skipped_reason="follow_not_verified",
            log_early_exit=True,
        )

    if skipped_tap:
        return _finish(
            phase_outcome="skipped",
            skipped_reason="skipped_tap_already_connected",
            log_early_exit=True,
        )

    if pending_rq and follow_priv:
        return _finish(
            phase_outcome="skipped",
            skipped_reason="private_follow_request_pending",
            log_early_exit=True,
        )

    if not _cfg_snap["post_follow_enabled"]:
        return _finish(
            phase_outcome="skipped",
            skipped_reason="likes_disabled_by_config",
            log_early_exit=True,
        )

    if not _cfg_snap["real_visual_like_enabled"]:
        return _finish(
            phase_outcome="skipped",
            skipped_reason="real_post_like_disabled_by_config",
            log_early_exit=True,
        )

    pct = int(_cfg_snap["percentage"])
    pct = max(0, min(100, pct))
    if pct < 100 and random.randint(1, 100) > pct:
        return _finish(
            phase_outcome="skipped",
            skipped_reason="likes_percentage_roll_skip",
            log_early_exit=True,
        )

    total_lim = int(_cfg_snap["total_likes_limit"])
    used = int(_cfg_snap["session_likes_used"])
    if total_lim > 0 and used >= total_lim:
        _log_likes_early_exit(
            "likes_skipped_session_quota",
            note="session_quota_before_target_count",
        )
        log(
            "info",
            "post_follow_post_likes_session_quota_reached",
            visual_candidate_id=vcid,
            source_profile_username=src,
            session_likes_used=used,
            session_likes_limit=total_lim,
        )
        return _finish(
            phase_outcome="skipped",
            skipped_reason="likes_skipped_session_quota",
        )

    budget_s = float(_cfg_snap["budget_s"])
    budget_s = max(3.0, min(budget_s, 30.0))

    target_count = _post_follow_post_likes_count_from_range(str(_cfg_snap["count_range"]))
    if total_lim > 0:
        target_count = min(target_count, max(0, total_lim - used))
    if target_count <= 0:
        _log_likes_early_exit(
            "likes_skipped_session_quota",
            note="no_remaining_like_slots_for_target",
            target_count=target_count,
        )
        log(
            "info",
            "post_follow_post_likes_session_quota_reached",
            visual_candidate_id=vcid,
            source_profile_username=src,
            session_likes_used=used,
            session_likes_limit=total_lim,
            note="no_remaining_like_slots_for_target",
        )
        return _finish(
            phase_outcome="skipped",
            skipped_reason="likes_skipped_session_quota",
        )

    log(
        "info",
        "post_follow_post_likes_target_count_decided",
        visual_candidate_id=vcid,
        source_profile_username=src,
        follower_username=cand,
        target_count=target_count,
        session_likes_used=used,
        session_likes_limit=total_lim,
    )
    out["target_count"] = target_count

    t_prof = time.perf_counter()
    ab = ""
    try:
        ab = str(read_current_profile_username_for_follow_gate(d) or "").strip().lstrip("@")
    except Exception:
        ab = ""
    nav_prof: dict[str, Any] = {}
    try:
        nav_prof = observe_instagram_state(
            d,
            expected_package=pkg,
            last_known_state=NavigationEngineState.CANDIDATE_PROFILE.value,
            context={
                "phase": "post_follow_post_likes_profile_guard",
                "visual_candidate_id": vcid,
                "source_profile_username": src,
                "disable_followers_visual_fallback": True,
                "expected_state": "CANDIDATE_PROFILE",
            },
        )
    except Exception as e:
        nav_prof = {"state": "UNKNOWN", "confidence": 0.0, "reason": str(e)}
    timings["profile_guard_ms"] = round((time.perf_counter() - t_prof) * 1000, 2)
    st_prof = str(nav_prof.get("state") or "")
    prof_like = st_prof in (
        NavigationEngineState.PROFILE.value,
        NavigationEngineState.CANDIDATE_PROFILE.value,
        NavigationEngineState.PRIVATE_PROFILE.value,
    )
    ab_match = bool(ab) and _normalize_handle(ab) == _normalize_handle(cand)
    if not prof_like and not ab_match:
        log(
            "warning",
            "post_follow_post_likes_phase_skipped",
            visual_candidate_id=vcid,
            source_profile_username=src,
            reason="profile_not_confirmed",
            navigation_state=st_prof,
            action_bar_title=ab,
        )
        return _finish(
            phase_outcome="skipped",
            skipped_reason="profile_not_confirmed_before_likes",
        )

    per_post: list[dict[str, Any]] = []
    liked_count = 0
    skipped_already = 0
    failed_nav = 0
    attempted_count = 0

    for post_idx in range(target_count):
        if (time.perf_counter() - t_all) > budget_s:
            break
        attempted_count += 1
        post_rec: dict[str, Any] = {"index": post_idx, "outcome": "pending"}
        profile_baseline: dict[str, Any] | None = None
        _likes_perf_ctx["post_open"] = {}
        _likes_perf_ctx["like"] = {}
        _likes_perf_ctx["already_liked_decision_ms"] = None
        _likes_perf_ctx["like_verify_ms"] = None
        _likes_perf_ctx["verify_attempts_count"] = None
        _likes_perf_ctx["verification_method"] = None
        _likes_perf_ctx["verify_success"] = None
        _likes_perf_ctx["like_verify_failure_reason"] = None
        _likes_perf_ctx["return_to_profile_ms"] = None
        _likes_perf_ctx["return_success"] = None

        log(
            "info",
            "post_follow_post_like_open_started",
            visual_candidate_id=vcid,
            source_profile_username=src,
            follower_username=cand,
            post_index=post_idx,
        )
        t_grid = time.perf_counter()
        grid_rem_s = max(1.5, budget_s - (time.perf_counter() - t_all))
        grid_out = ensure_post_grid_visible_for_post_follow_likes(
            d,
            source_profile_username=src,
            follower_username=cand,
            visual_candidate_id=vcid,
            budget_s=grid_rem_s,
            likes_perf_phase_t0=_likes_perf_ctx.get("phase_t0"),
            likes_perf_follow_state_after=fs_after,
        )
        timings[f"grid_prep_{post_idx}_ms"] = round(
            (time.perf_counter() - t_grid) * 1000, 2
        )

        if not grid_out.get("ok"):
            failed_nav += 1
            _likes_perf_ctx["grid"] = dict(grid_out.get("likes_perf_grid") or {})
            _likes_perf_ctx["failure_reason"] = str(
                grid_out.get("failure_reason") or "post_grid_not_visible_before_open"
            )
            _likes_perf_ctx["grid_readiness_mode"] = None
            _likes_perf_ctx["final_grid_state"] = grid_out.get("grid_state_after")
            post_rec["outcome"] = "grid_not_visible"
            fr_grid = str(
                grid_out.get("failure_reason") or "post_grid_not_visible_before_open"
            )
            if fr_grid != "post_grid_not_visible_before_open":
                fr_grid = "post_grid_not_visible_before_open"
            post_rec["failure_reason"] = fr_grid
            per_post.append(post_rec)
            log(
                "warning",
                "post_follow_post_likes_open_skipped_grid_not_visible",
                visual_candidate_id=vcid,
                source_profile_username=src,
                follower_username=cand,
                failure_reason=fr_grid,
                grid_state_before=grid_out.get("grid_state_before"),
                grid_state_after=grid_out.get("grid_state_after"),
                scroll_used=grid_out.get("scroll_used"),
                scroll_profile=grid_out.get("scroll_profile"),
                attempts=grid_out.get("attempts"),
            )
            log(
                "warning",
                "post_follow_post_like_open_failed",
                visual_candidate_id=vcid,
                source_profile_username=src,
                follower_username=cand,
                failure_reason=fr_grid,
            )
            return _finish(
                phase_outcome="failed_safe_continue",
                skipped_reason="likes_failed_open_post_safe_continue",
                skipped=False,
                ok=False,
                attempted_count=attempted_count,
                liked_count=liked_count,
                skipped_already_liked_count=skipped_already,
                failed_navigation_count=failed_nav,
                per_post=per_post,
            )

        _likes_perf_ctx["grid"] = dict(grid_out.get("likes_perf_grid") or {})
        _glc = _likes_perf_ctx["grid"]
        _likes_perf_ctx["final_grid_state"] = grid_out.get("grid_state_after")
        _likes_perf_ctx["final_suggested_for_you"] = _glc.get("final_suggested_for_you")
        _likes_perf_ctx["final_profile_tabs_visible"] = _glc.get(
            "final_profile_tabs_visible"
        )
        if grid_out.get("partial_sparse_grid_accepted"):
            _likes_perf_ctx["grid_readiness_mode"] = "sparse_accepted"
        else:
            _likes_perf_ctx["grid_readiness_mode"] = "visible_confirmed"
        _likes_perf_ctx["failure_reason"] = None

        if bool(getattr(config, "ENABLE_VISUAL_PROFILE_CONTEXT_LOCK", False)):
            t_ctx = time.perf_counter()
            profile_baseline = visual_capture_profile_context(
                d, source_profile_username=src
            )
            timings[f"context_baseline_{post_idx}_ms"] = round(
                (time.perf_counter() - t_ctx) * 1000, 2
            )
            if isinstance(profile_baseline, dict) and cand:
                ab_ctx = str(
                    profile_baseline.get("header_username_detected") or ""
                ).strip().lstrip("@")
                if not ab_ctx or _normalize_handle(ab_ctx) != _normalize_handle(cand):
                    profile_baseline = {
                        **dict(profile_baseline),
                        "header_username_detected": cand,
                        "username_norm": _normalize_handle(cand),
                    }
            try:
                log(
                    "info",
                    "post_follow_post_likes_context_baseline_prepared",
                    visual_candidate_id=vcid,
                    source_profile_username=src,
                    follower_username=cand,
                    baseline_ok=bool((profile_baseline or {}).get("ok")),
                    profile_fingerprint=str(
                        (profile_baseline or {}).get("profile_fingerprint") or ""
                    )[:64],
                    header_username_detected=str(
                        (profile_baseline or {}).get("header_username_detected") or ""
                    )[:120],
                )
            except Exception:
                pass

        t_open = time.perf_counter()
        dr_top = grid_out.get("dynamic_first_row_top")
        dr_bottom = grid_out.get("dynamic_first_row_bottom")
        gps = grid_out.get("grid_probe_source")
        gpss = grid_out.get("grid_probe_screenshot_path")
        open_out = visual_open_recent_post_from_profile(
            d,
            source_profile_username=src,
            expected_follower_username=cand,
            grid_y0_ratio=_POST_FOLLOW_LIKES_GRID_Y0_RATIO,
            grid_y1_ratio=_POST_FOLLOW_LIKES_GRID_Y1_RATIO,
            selection_policy=_VISUAL_POST_OPEN_SELECTION_FIRST_ROW_LTR,
            dynamic_grid_first_row_top_px=(
                int(dr_top) if isinstance(dr_top, (int, float)) else None
            ),
            dynamic_grid_first_row_bottom_px=(
                int(dr_bottom) if isinstance(dr_bottom, (int, float)) else None
            ),
            grid_probe_source=str(gps).strip() if gps else None,
            grid_probe_screenshot_path=str(gpss).strip() if gpss else None,
            likes_perf_phase_t0=_likes_perf_ctx.get("phase_t0"),
            post_follow_stash_open_like_proof=True,
        )
        timings[f"open_post_{post_idx}_ms"] = round(
            (time.perf_counter() - t_open) * 1000, 2
        )
        _likes_perf_ctx["post_open"] = dict(open_out.get("likes_perf_post_open") or {})
        try:
            _pod = dict(_likes_perf_ctx["post_open"])
            log(
                "info",
                "post_follow_post_likes_perf_post_open_done",
                visual_candidate_id=vcid,
                source_profile_username=src,
                follower_username=cand,
                elapsed_from_phase_start_ms=_likes_perf_elapsed_ms(
                    _likes_perf_ctx.get("phase_t0")
                ),
                **_pod,
            )
        except Exception:
            pass

        if open_out.get("no_posts_profile"):
            post_rec["outcome"] = "no_posts"
            per_post.append(post_rec)
            _likes_perf_ctx["failure_reason"] = "likes_skipped_no_posts"
            log(
                "info",
                "post_follow_post_likes_phase_skipped",
                visual_candidate_id=vcid,
                source_profile_username=src,
                reason="likes_skipped_no_posts",
            )
            return _finish(
                phase_outcome="skipped",
                skipped_reason="likes_skipped_no_posts",
                skipped=True,
                ok=True,
                attempted_count=attempted_count,
                liked_count=0,
                skipped_already_liked_count=0,
                failed_navigation_count=failed_nav,
                per_post=per_post,
            )

        if not open_out.get("ok") or not open_out.get("post_detected"):
            failed_nav += 1
            post_rec["outcome"] = "open_failed"
            fr_open = str(open_out.get("failure_reason") or "")
            if fr_open == "opened_foreign_profile_instead_of_post":
                pass
            elif (
                fr_open == "post_viewer_not_detected"
                and open_out.get("tap_x") is not None
                and open_out.get("tap_y") is not None
            ):
                fr_open = "post_viewer_not_detected_after_tap"
            post_rec["failure_reason"] = fr_open
            per_post.append(post_rec)
            _likes_perf_ctx["failure_reason"] = fr_open
            log(
                "warning",
                "post_follow_post_like_open_failed",
                visual_candidate_id=vcid,
                source_profile_username=src,
                follower_username=cand,
                failure_reason=fr_open,
                tap_x=open_out.get("tap_x"),
                tap_y=open_out.get("tap_y"),
            )
            return _finish(
                phase_outcome="failed_safe_continue",
                skipped_reason="likes_failed_open_post_safe_continue",
                skipped=False,
                ok=False,
                attempted_count=attempted_count,
                liked_count=liked_count,
                skipped_already_liked_count=skipped_already,
                failed_navigation_count=failed_nav,
                per_post=per_post,
            )

        log(
            "info",
            "post_follow_post_like_open_success",
            visual_candidate_id=vcid,
            source_profile_username=src,
            tap_x=open_out.get("tap_x"),
            tap_y=open_out.get("tap_y"),
        )

        t_al_run0 = time.perf_counter()
        al_pre = visual_post_already_liked(
            d,
            source_profile_username=src,
            heart_bounds=None,
            post_follow_primary_precheck=True,
            expected_follower_username=cand,
        )
        _likes_perf_ctx["already_liked_decision_ms"] = round(
            (time.perf_counter() - t_al_run0) * 1000.0, 2
        )
        if al_pre.get("open_proof_reused"):
            _likes_perf_ctx["already_liked_decision_reused"] = True
            _likes_perf_ctx["already_liked_recheck_reason"] = str(
                al_pre.get("already_liked_decision_reason")
                or "post_follow_open_like_proof_reused_not_liked"
            )[:160]
        else:
            _likes_perf_ctx["already_liked_decision_reused"] = False
            _likes_perf_ctx["already_liked_recheck_reason"] = "runner_primary_precheck"
        if al_pre.get("already_liked"):
            skipped_already += 1
            post_rec["outcome"] = "already_liked"
            post_rec["detection_method"] = al_pre.get("detection_method")
            per_post.append(post_rec)
            log(
                "info",
                "post_follow_post_like_already_liked_skipped",
                visual_candidate_id=vcid,
                source_profile_username=src,
                follower_username=cand,
                detection_method=al_pre.get("detection_method"),
                confidence=al_pre.get("confidence"),
                semantic_like_state=al_pre.get("semantic_like_state"),
                already_liked_decision_reason=al_pre.get(
                    "already_liked_decision_reason"
                ),
                crop_bounds=al_pre.get("crop_bounds"),
                red_ratio=al_pre.get("red_ratio"),
            )
            _t_ret_p0 = time.perf_counter()
            ret_p = visual_return_to_profile_from_post(d, source_profile_username=src)
            _likes_perf_ctx["return_to_profile_ms"] = round(
                (time.perf_counter() - _t_ret_p0) * 1000.0, 2
            )
            _likes_perf_ctx["return_success"] = bool(ret_p.get("ok"))
            if ret_p.get("ok"):
                log(
                    "info",
                    "post_follow_post_likes_return_to_profile_success",
                    visual_candidate_id=vcid,
                    source_profile_username=src,
                )
            else:
                log(
                    "warning",
                    "post_follow_post_likes_return_to_profile_failed",
                    visual_candidate_id=vcid,
                    source_profile_username=src,
                    failure_reason=ret_p.get("failure_reason"),
                )
            try:
                log(
                    "info",
                    "post_follow_post_likes_perf_return_to_profile_done",
                    visual_candidate_id=vcid,
                    source_profile_username=src,
                    follower_username=cand,
                    return_to_profile_total_ms=_likes_perf_ctx.get(
                        "return_to_profile_ms"
                    ),
                    return_success=_likes_perf_ctx.get("return_success"),
                    return_profile_poll_count=ret_p.get("return_profile_poll_count"),
                    return_profile_fast_confirmed=ret_p.get(
                        "return_profile_fast_confirmed"
                    ),
                    elapsed_from_phase_start_ms=_likes_perf_elapsed_ms(
                        _likes_perf_ctx.get("phase_t0")
                    ),
                )
            except Exception:
                pass
            return _finish(
                phase_outcome="skipped",
                skipped_reason="likes_skipped_already_liked",
                skipped=True,
                ok=True,
                attempted_count=attempted_count,
                liked_count=0,
                skipped_already_liked_count=skipped_already,
                failed_navigation_count=failed_nav,
                per_post=per_post,
            )

        _like_accum: dict[str, Any] = {}
        t_like_wall0 = time.perf_counter()
        like_out = visual_like_open_post(
            d,
            source_profile_username=src,
            expected_profile_context=profile_baseline,
            post_opened_via_profile_grid=True,
            expected_follower_username=cand,
            likes_perf_like_accum=_like_accum,
            likes_perf_phase_t0=_likes_perf_ctx.get("phase_t0"),
            already_liked_precheck=al_pre,
        )
        _likes_perf_ctx["like"] = dict(like_out.get("likes_perf_like") or {})
        _likes_perf_ctx["like"]["runner_visual_like_open_wall_ms"] = round(
            (time.perf_counter() - t_like_wall0) * 1000.0, 2
        )
        try:
            log(
                "info",
                "post_follow_post_likes_perf_like_target_and_tap_done",
                visual_candidate_id=vcid,
                source_profile_username=src,
                follower_username=cand,
                elapsed_from_phase_start_ms=_likes_perf_elapsed_ms(
                    _likes_perf_ctx.get("phase_t0")
                ),
                already_liked_decision_ms=_likes_perf_ctx.get("already_liked_decision_ms"),
                like_target_detection_ms=_likes_perf_ctx["like"].get(
                    "like_target_detection_ms"
                ),
                already_liked_decision_inner_ms=_likes_perf_ctx["like"].get(
                    "already_liked_decision_inner_ms"
                ),
                already_liked_decision_reused=_likes_perf_ctx["like"].get(
                    "already_liked_decision_reused"
                ),
                already_liked_recheck_reason=_likes_perf_ctx["like"].get(
                    "already_liked_recheck_reason"
                ),
                like_tap_dispatch_ms=_likes_perf_ctx["like"].get("like_tap_dispatch_ms"),
                like_tap_sent=bool(like_out.get("real_tap_sent")),
                already_liked=bool(al_pre.get("already_liked")),
            )
        except Exception:
            pass
        if like_out.get("real_tap_sent"):
            log(
                "info",
                "post_follow_post_like_tap_sent",
                visual_candidate_id=vcid,
                source_profile_username=src,
                tap_x=like_out.get("tap_x"),
                tap_y=like_out.get("tap_y"),
            )

        verify_on = bool(
            getattr(config, "POST_FOLLOW_POST_LIKES_VERIFY_AFTER_TAP", True)
        ) or bool(getattr(config, "VISUAL_POST_LIKE_VERIFY_AFTER_TAP", True))
        liked_verified = False
        if (
            bool(getattr(config, "ENABLE_REAL_VISUAL_POST_LIKE", False))
            and like_out.get("ok")
            and like_out.get("real_tap_sent")
            and verify_on
        ):
            t_ver = time.perf_counter()
            ver = visual_verify_post_liked(
                d,
                source_profile_username=src,
                tap_x=like_out.get("tap_x"),
                tap_y=like_out.get("tap_y"),
                detect_confidence=like_out.get("confidence"),
                post_tap_screenshot_path=like_out.get("post_tap_screenshot_path"),
                pre_tap_like_button_bounds=like_out.get("like_button_bounds"),
                like_button_state_before=like_out.get("like_button_state_before"),
            )
            timings[f"verify_post_{post_idx}_ms"] = round(
                (time.perf_counter() - t_ver) * 1000, 2
            )
            liked_verified = bool(ver.get("liked_verified"))
            post_rec["verification_method"] = ver.get("verification_method")
            _likes_perf_ctx["like_verify_ms"] = timings[f"verify_post_{post_idx}_ms"]
            _likes_perf_ctx["verify_attempts_count"] = ver.get("verify_attempts_count")
            _likes_perf_ctx["verification_method"] = ver.get("verification_method")
            _likes_perf_ctx["verify_success"] = bool(liked_verified)
            _likes_perf_ctx["like_verify_failure_reason"] = (
                None if liked_verified else "verify_failed"
            )
            try:
                log(
                    "info",
                    "post_follow_post_likes_perf_like_verify_done",
                    visual_candidate_id=vcid,
                    source_profile_username=src,
                    follower_username=cand,
                    like_verify_total_ms=_likes_perf_ctx.get("like_verify_ms"),
                    verify_attempts_count=_likes_perf_ctx.get("verify_attempts_count"),
                    verification_method=_likes_perf_ctx.get("verification_method"),
                    verify_success=bool(liked_verified),
                    verify_early_exit_strict_ui=bool(
                        ver.get("verify_early_exit_strict_ui")
                    ),
                    failure_reason=_likes_perf_ctx.get("like_verify_failure_reason"),
                    elapsed_from_phase_start_ms=_likes_perf_elapsed_ms(
                        _likes_perf_ctx.get("phase_t0")
                    ),
                )
            except Exception:
                pass
            if liked_verified:
                log(
                    "info",
                    "post_follow_post_like_verify_success",
                    visual_candidate_id=vcid,
                    source_profile_username=src,
                )
            else:
                log(
                    "info",
                    "post_follow_post_like_verify_failed",
                    visual_candidate_id=vcid,
                    source_profile_username=src,
                )
        elif like_out.get("ok") and (
            like_out.get("real_tap_sent") or like_out.get("dry_run")
        ):
            liked_verified = bool(like_out.get("ok"))
            _likes_perf_ctx["verify_success"] = bool(liked_verified)
            _likes_perf_ctx["verification_method"] = "skipped_verify_dry_or_config"
            _likes_perf_ctx["like_verify_ms"] = None

        if liked_verified:
            liked_count += 1
            post_rec["outcome"] = "liked"
            per_post.append(post_rec)
        else:
            failed_nav += 1
            post_rec["outcome"] = "verify_failed"
            post_rec["failure_reason"] = str(like_out.get("failure_reason") or "")
            per_post.append(post_rec)
            _t_ret_pf0 = time.perf_counter()
            ret_pf = visual_return_to_profile_from_post(d, source_profile_username=src)
            _likes_perf_ctx["return_to_profile_ms"] = round(
                (time.perf_counter() - _t_ret_pf0) * 1000.0, 2
            )
            _likes_perf_ctx["return_success"] = bool(ret_pf.get("ok"))
            try:
                log(
                    "info",
                    "post_follow_post_likes_perf_return_to_profile_done",
                    visual_candidate_id=vcid,
                    source_profile_username=src,
                    follower_username=cand,
                    return_to_profile_total_ms=_likes_perf_ctx.get(
                        "return_to_profile_ms"
                    ),
                    return_success=_likes_perf_ctx.get("return_success"),
                    return_profile_poll_count=ret_pf.get("return_profile_poll_count"),
                    return_profile_fast_confirmed=ret_pf.get(
                        "return_profile_fast_confirmed"
                    ),
                    elapsed_from_phase_start_ms=_likes_perf_elapsed_ms(
                        _likes_perf_ctx.get("phase_t0")
                    ),
                )
            except Exception:
                pass
            if ret_pf.get("ok"):
                log(
                    "info",
                    "post_follow_post_likes_return_to_profile_success",
                    visual_candidate_id=vcid,
                    source_profile_username=src,
                )
            else:
                log(
                    "warning",
                    "post_follow_post_likes_return_to_profile_failed",
                    visual_candidate_id=vcid,
                    source_profile_username=src,
                    failure_reason=ret_pf.get("failure_reason"),
                )
            return _finish(
                phase_outcome="failed_safe_continue",
                skipped_reason="likes_failed_verify_safe_continue",
                skipped=False,
                ok=False,
                attempted_count=attempted_count,
                liked_count=liked_count,
                skipped_already_liked_count=skipped_already,
                failed_navigation_count=failed_nav,
                per_post=per_post,
            )

        _t_ret_ok0 = time.perf_counter()
        ret_ok = visual_return_to_profile_from_post(d, source_profile_username=src)
        _likes_perf_ctx["return_to_profile_ms"] = round(
            (time.perf_counter() - _t_ret_ok0) * 1000.0, 2
        )
        _likes_perf_ctx["return_success"] = bool(ret_ok.get("ok"))
        try:
            log(
                "info",
                "post_follow_post_likes_perf_return_to_profile_done",
                visual_candidate_id=vcid,
                source_profile_username=src,
                follower_username=cand,
                return_to_profile_total_ms=_likes_perf_ctx.get("return_to_profile_ms"),
                return_success=_likes_perf_ctx.get("return_success"),
                return_profile_poll_count=ret_ok.get("return_profile_poll_count"),
                return_profile_fast_confirmed=ret_ok.get(
                    "return_profile_fast_confirmed"
                ),
                elapsed_from_phase_start_ms=_likes_perf_elapsed_ms(
                    _likes_perf_ctx.get("phase_t0")
                ),
            )
        except Exception:
            pass
        if ret_ok.get("ok"):
            log(
                "info",
                "post_follow_post_likes_return_to_profile_success",
                visual_candidate_id=vcid,
                source_profile_username=src,
            )
        else:
            log(
                "warning",
                "post_follow_post_likes_return_to_profile_failed",
                visual_candidate_id=vcid,
                source_profile_username=src,
                failure_reason=ret_ok.get("failure_reason"),
            )
            return _finish(
                phase_outcome="failed_safe_continue",
                skipped_reason="likes_return_to_profile_failed",
                skipped=False,
                ok=liked_count > 0,
                attempted_count=attempted_count,
                liked_count=liked_count,
                skipped_already_liked_count=skipped_already,
                failed_navigation_count=failed_nav + 1,
                per_post=per_post,
            )

    out_liked = liked_count
    if out_liked >= target_count and target_count > 0:
        log(
            "info",
            "post_follow_post_likes_phase_success",
            visual_candidate_id=vcid,
            source_profile_username=src,
            liked_count=out_liked,
            target_count=target_count,
        )
        try:
            from followers_inter_candidate_perf import inter_candidate_on_likes_phase_success

            inter_candidate_on_likes_phase_success(
                follower_username=cand,
                source_profile_username=src,
            )
        except Exception:
            pass
        return _finish(
            phase_outcome="success",
            skipped=False,
            ok=True,
            attempted_count=attempted_count,
            liked_count=out_liked,
            skipped_already_liked_count=skipped_already,
            failed_navigation_count=failed_nav,
            per_post=per_post,
        )
    if out_liked > 0:
        log(
            "info",
            "post_follow_post_likes_phase_partial",
            visual_candidate_id=vcid,
            source_profile_username=src,
            liked_count=out_liked,
            target_count=target_count,
        )
        return _finish(
            phase_outcome="partial_success",
            skipped=False,
            ok=True,
            attempted_count=attempted_count,
            liked_count=out_liked,
            skipped_already_liked_count=skipped_already,
            failed_navigation_count=failed_nav,
            per_post=per_post,
        )
    log(
        "info",
        "post_follow_post_likes_phase_skipped",
        visual_candidate_id=vcid,
        source_profile_username=src,
        reason="no_verified_likes",
    )
    return _finish(
        phase_outcome="skipped",
        skipped_reason="no_verified_likes",
        attempted_count=attempted_count,
        liked_count=0,
        skipped_already_liked_count=skipped_already,
        failed_navigation_count=failed_nav,
        per_post=per_post,
    )


def run_visual_candidate_post_follow_phase(
    d: u2.Device,
    *,
    pkg: str,
    source_profile_username: str,
    visual_candidate_id: str,
    follower_username: str,
    follow_success_verified: bool,
    follow_state_after: str,
    skipped_tap: bool,
    det: dict[str, Any] | None,
    session_likes_used: int = 0,
    own_unified_xml_list: bool = False,
) -> dict[str, Any]:
    """
    Post-follow: observe UI, optional real mute, controlled return to CT followers list.
    Does not modify follow / harvester / row mapping.
    """
    from navigation_engine import NavigationEngineState, observe_instagram_state

    pkg = pkg or str(getattr(config, "INSTAGRAM_PACKAGE", "") or "")
    vcid = str(visual_candidate_id or "").strip()
    src = str(source_profile_username or "").strip()
    cand = str(follower_username or "").strip()
    fs_after = str(follow_state_after or "").strip()

    mute_out: dict[str, Any] = {
        "ok": False,
        "skipped": True,
        "skipped_reason": None,
        "failure_reason": None,
        "mute_started": False,
    }

    log(
        "info",
        "post_follow_flow_started",
        visual_candidate_id=vcid,
        source_profile_username=src,
        follower_username=cand,
        follow_success_verified=bool(follow_success_verified),
        follow_state_after=fs_after,
        skipped_tap=bool(skipped_tap),
        own_unified_xml_list=bool(own_unified_xml_list),
        pick_mode=(
            "own_unified_xml_list" if own_unified_xml_list else "visual_candidate"
        ),
    )

    det_use: dict[str, Any] = dict(det) if isinstance(det, dict) else {}
    try:
        det_fresh = detect_followers_list_screen(d, source_profile_username=src)
        if isinstance(det_fresh, dict) and det_fresh:
            det_use = det_fresh
    except Exception:
        pass

    nav_obs: dict[str, Any] = {}
    try:
        nav_obs = observe_instagram_state(
            d,
            expected_package=pkg,
            last_known_state=NavigationEngineState.CANDIDATE_PROFILE.value,
            context={
                "phase": "post_follow_observe",
                "visual_candidate_id": vcid,
                "source_profile_username": src,
                "det": det_use,
                "disable_followers_visual_fallback": True,
                "expected_state": "CANDIDATE_PROFILE",
            },
        )
    except Exception as e:
        nav_obs = {"state": "UNKNOWN", "confidence": 0.0, "reason": str(e)}

    overlay = _post_follow_overlay_ui_hints(d)
    fp = _post_follow_screen_fingerprint(
        d, nav_state=str(nav_obs.get("state") or ""), det=det_use
    )
    obs_reason = "ok"
    if overlay.get("likely_mute_toggle_sheet"):
        obs_reason = "overlay_mute_sheet_like"
    elif any(
        overlay.get(k)
        for k in (
            "suggested_for_you",
            "discover_people",
            "notification_prompt",
            "turn_on_notifications",
        )
    ):
        obs_reason = "overlay_suggestion_or_system_prompt"
    elif str(nav_obs.get("state") or "") == NavigationEngineState.MUTE_SHEET.value:
        obs_reason = "navigation_mute_sheet"

    log(
        "info",
        "post_follow_state_observed",
        visual_candidate_id=vcid,
        source_profile_username=src,
        navigation_state=str(nav_obs.get("state") or ""),
        navigation_confidence=float(nav_obs.get("confidence") or 0.0),
        navigation_reason=str(nav_obs.get("reason") or ""),
        observation_note=obs_reason,
        overlay_hints=overlay,
        fingerprint_id=fp.get("fingerprint_id"),
        screen_class=fp.get("screen_class"),
        action_bar_title=str(det_use.get("action_bar_title") or "")[:120],
    )

    flow_on = bool(getattr(config, "ENABLE_VISUAL_FOLLOW_MUTE_FLOW", False))
    real_mute = bool(getattr(config, "ENABLE_REAL_VISUAL_MUTE_AFTER_FOLLOW", False))
    follow_priv = bool(getattr(config, "FOLLOW_PRIVATE_ACCOUNTS", False))
    pending_rq = fs_after == "requested"

    should_mute = bool(
        follow_success_verified
        and flow_on
        and real_mute
        and not skipped_tap
        and not (pending_rq and follow_priv)
    )
    mute_decision_reason = "mute_eligible"
    if not follow_success_verified:
        mute_decision_reason = "follow_not_verified_in_runner_context"
        should_mute = False
    elif not flow_on or not real_mute:
        mute_decision_reason = "mute_disabled_by_config"
        should_mute = False
    elif skipped_tap:
        mute_decision_reason = "skipped_tap_already_connected"
        should_mute = False
    elif pending_rq and follow_priv:
        mute_decision_reason = "private_follow_request_pending_skip_mute"
        should_mute = False

    log(
        "info",
        "post_follow_mute_decision",
        visual_candidate_id=vcid,
        source_profile_username=src,
        should_mute=should_mute,
        reason=mute_decision_reason,
        ENABLE_VISUAL_FOLLOW_MUTE_FLOW=flow_on,
        ENABLE_REAL_VISUAL_MUTE_AFTER_FOLLOW=real_mute,
    )

    if should_mute:
        if not _vision_validation_post_follow_before_mute(
            screenshot_path="",
            det=det_use,
            nav_obs=nav_obs,
            overlay=overlay,
            fp=fp if isinstance(fp, dict) else {},
            visual_candidate_id=vcid,
            source_profile_username=src,
        ):
            should_mute = False
            mute_decision_reason = "vision_validation_post_follow_blocked"

    if not follow_success_verified:
        log(
            "info",
            "post_follow_mute_skipped",
            visual_candidate_id=vcid,
            source_profile_username=src,
            reason="follow_not_verified",
        )
    elif not flow_on or not real_mute:
        log(
            "info",
            "post_follow_mute_skipped",
            visual_candidate_id=vcid,
            source_profile_username=src,
            reason="mute_disabled_by_config",
        )
    elif skipped_tap:
        log(
            "info",
            "post_follow_mute_skipped",
            visual_candidate_id=vcid,
            source_profile_username=src,
            reason="already_following_skipped_tap",
        )
    elif pending_rq and follow_priv:
        log(
            "info",
            "post_follow_mute_skipped",
            visual_candidate_id=vcid,
            source_profile_username=src,
            reason="private_follow_request_pending",
        )
    elif should_mute:
        mute_out["mute_started"] = True
        log(
            "info",
            "post_follow_mute_started",
            visual_candidate_id=vcid,
            source_profile_username=src,
            engine="mute_engine_v2",
        )
        v2 = run_mute_engine_v2(
            d,
            pkg=pkg,
            source_profile_username=src,
            visual_candidate_id=vcid,
            follower_username=cand,
            follow_state_after=fs_after,
            det_hint=det_use if isinstance(det_use, dict) else None,
        )
        outcome = str(v2.get("outcome") or "")
        mute_out = {
            "ok": bool(v2.get("ok")),
            "skipped": False,
            "skipped_reason": None,
            "failure_reason": v2.get("failure_reason"),
            "mute_started": True,
            "mute_engine_v2": True,
            "mute_v2_outcome": outcome,
            "mute_v2_abort_reason": v2.get("abort_reason"),
            "mute_v2_partial": bool(v2.get("partial")),
            "timings_ms": v2.get("timings_ms") or {},
            "posts_verified": bool(v2.get("posts_verified")),
            "stories_verified": bool(v2.get("stories_verified")),
        }
        if outcome == "success":
            log(
                "info",
                "post_follow_mute_success",
                visual_candidate_id=vcid,
                source_profile_username=src,
                mute_engine_v2=True,
                timings_ms=v2.get("timings_ms") or {},
            )
            _post_mute_state_checkpoint(
                d,
                pkg=pkg,
                source_profile_username=src,
                visual_candidate_id=vcid,
            )
        elif outcome == "partial_success":
            log(
                "info",
                "post_follow_mute_success",
                visual_candidate_id=vcid,
                source_profile_username=src,
                mute_engine_v2=True,
                mute_partial=True,
                timings_ms=v2.get("timings_ms") or {},
            )
            _post_mute_state_checkpoint(
                d,
                pkg=pkg,
                source_profile_username=src,
                visual_candidate_id=vcid,
            )
        else:
            log(
                "warning",
                "post_follow_mute_failed",
                visual_candidate_id=vcid,
                source_profile_username=src,
                phase="mute_engine_v2",
                failure_reason=str(v2.get("failure_reason") or outcome or ""),
                mute_v2_outcome=outcome,
                mute_v2_abort_reason=v2.get("abort_reason"),
                timings_ms=v2.get("timings_ms") or {},
            )

    likes_out: dict[str, Any] = _post_follow_post_likes_out_template()
    if follow_success_verified and cand:
        likes_out = run_post_follow_post_likes_phase(
            d,
            pkg=pkg,
            source_profile_username=src,
            follower_username=cand,
            visual_candidate_id=vcid,
            follow_success_verified=follow_success_verified,
            follow_state_after=fs_after,
            skipped_tap=skipped_tap,
            session_likes_used=int(session_likes_used or 0),
        )

    mute_ok = bool(mute_out.get("ok"))
    mute_attempted = bool(mute_out.get("mute_started"))
    compact_post_follow_return = bool(
        follow_success_verified and (bool(vcid) or own_unified_xml_list)
    )
    if compact_post_follow_return:
        if should_mute and mute_ok and bool(mute_out.get("mute_v2_partial")):
            compact_reason_str = "follow_verified_mute_partial"
        elif should_mute and mute_ok:
            compact_reason_str = "follow_verified_mute_success"
        elif should_mute and mute_attempted:
            compact_reason_str = "follow_verified_mute_attempted"
        elif should_mute:
            compact_reason_str = "follow_verified_mute_attempted"
        else:
            compact_reason_str = "follow_verified_visual_candidate"
    else:
        compact_reason_str = ""

    log(
        "info",
        "post_follow_return_ct_started",
        visual_candidate_id=vcid,
        source_profile_username=src,
        follower_username=cand,
        compact_after_follow_verified_mute=compact_post_follow_return,
        compact_reason=compact_reason_str or None,
        mute_attempted=mute_attempted,
        mute_ok=mute_ok,
        should_mute=bool(should_mute),
        follow_success_verified=bool(follow_success_verified),
    )
    try:
        from followers_inter_candidate_perf import inter_candidate_on_post_return_ct_started

        inter_candidate_on_post_return_ct_started()
    except Exception:
        pass
    ok_ret, how_ret, fail_re = post_follow_controlled_return_to_followers_list(
        d,
        pkg=pkg,
        source_profile_username=src,
        follower_username=cand,
        visual_candidate_id=vcid,
        det=det_use,
        max_rounds=1 if compact_post_follow_return else 4,
        compact_after_follow_verified_mute=compact_post_follow_return,
        compact_reason=compact_reason_str if compact_post_follow_return else None,
    )
    try:
        from followers_inter_candidate_perf import inter_candidate_on_post_return_ct_finished

        inter_candidate_on_post_return_ct_finished()
    except Exception:
        pass
    if ok_ret:
        log(
            "info",
            "post_follow_return_ct_success",
            visual_candidate_id=vcid,
            source_profile_username=src,
            how=str(how_ret or ""),
        )
        try:
            from followers_inter_candidate_perf import inter_candidate_on_post_return_ct_success

            inter_candidate_on_post_return_ct_success()
        except Exception:
            pass
    else:
        log(
            "warning",
            "post_follow_return_ct_failed",
            visual_candidate_id=vcid,
            source_profile_username=src,
            failure_reason=str(fail_re or ""),
            how=str(how_ret or ""),
        )

    _vf_ev_out = _post_follow_return_take_pending_visual_evidence_for_runner()
    _out: dict[str, Any] = {
        "mute": mute_out,
        "likes": likes_out,
        "return_ok": bool(ok_ret),
        "return_how": str(how_ret or ""),
        "return_failure_reason": fail_re,
        "follow_success_verified": bool(follow_success_verified),
        "navigation_observed": nav_obs,
        "overlay_hints": overlay,
    }
    for _k in ("return_list_screenshot_path", "return_visual_fallback_detail"):
        if _k in _vf_ev_out:
            _out[_k] = _vf_ev_out[_k]
    return _out


def return_to_followers_list(
    d: u2.Device,
    source_profile_username: str,
    pkg: str | None = None,
    *,
    max_retries: int | None = None,
) -> tuple[bool, str]:
    """Back from follower profile to followers list; optional reopen from source profile."""
    pkg = pkg or getattr(config, "INSTAGRAM_PACKAGE", "") or ""
    retries = max_retries
    if retries is None:
        retries = int(getattr(config, "FOLLOWERS_LIST_RETURN_MAX_RETRIES", 2))
    for attempt in range(max(0, retries) + 1):
        try:
            d.press("back")
        except Exception:
            pass
        time.sleep(0.38)
        det = detect_followers_list_screen(d, source_profile_username=source_profile_username)
        if det.get("is_followers_list"):
            log(
                "info",
                "followers_list_recovered",
                source_profile_username=source_profile_username,
                attempt=attempt,
                method="back",
            )
            return True, "back"
    log(
        "warning",
        "followers_list_reopen_fallback",
        source_profile_username=source_profile_username,
    )
    if verify_profile(d, source_profile_username):
        followers_session_clear_list_committed_open(source_profile_username)
        ok_reopen, _reopen_meta = open_followers_list_from_profile(
            d, source_profile_username, pkg, profile_verified=True
        )
        if ok_reopen:
            log(
                "info",
                "followers_list_recovered",
                source_profile_username=source_profile_username,
                method="reopen_from_source_profile",
            )
            return True, "reopen_from_source_profile"
    log("error", "followers_list_return_failed", source_profile_username=source_profile_username)
    return False, "failed"


def visual_flow_final_return_to_ct_followers_list(
    d: u2.Device,
    *,
    source_profile_username: str,
    pkg: str,
    candidate_username: str | None = None,
    source_account_context: str | None = None,
) -> dict[str, Any]:
    """
    Leave an opened follower-candidate profile and restore the source (CT) followers list.
    Thin wrapper over return_to_followers_list; never raises.
    """
    _ = source_account_context
    try:
        log(
            "info",
            "visual_flow_final_return_to_ct_followers_list_started",
            source_profile_username=source_profile_username,
            candidate_username=candidate_username,
        )
        ok, how = return_to_followers_list(d, source_profile_username, pkg or "")
        out = {
            "final_return_ok": bool(ok),
            "how": str(how or ""),
            "restart_required": False,
            "reset_ok": False,
            "reset_performed": False,
        }
        log(
            "info",
            "visual_flow_final_return_to_ct_followers_list_complete",
            source_profile_username=source_profile_username,
            candidate_username=candidate_username,
            **out,
        )
        return out
    except Exception as e:
        log(
            "warning",
            "visual_flow_final_return_to_ct_followers_list_failed",
            source_profile_username=source_profile_username,
            candidate_username=candidate_username,
            error=str(e),
        )
        return {
            "final_return_ok": False,
            "how": "exception",
            "restart_required": False,
            "reset_ok": False,
            "reset_performed": False,
        }


def verify_followers_list_surface_is_ct_account(
    d: u2.Device,
    *,
    source_profile_username: str,
    follower_candidate_username: str | None = None,
    det: dict[str, Any] | None = None,
) -> bool:
    """
    Best-effort: True if current screen looks like the CT source account's followers list.
    Never raises. Uses detect_followers_list_screen + action bar / header hints.

    When ``det`` is a dict from a fresh ``detect_followers_list_screen`` call, it is reused
    instead of re-scanning the hierarchy (same decision logic).
    """
    try:
        reused_provided_det = isinstance(det, dict)
        if reused_provided_det:
            det_use: dict[str, Any] = det  # type: ignore[assignment]
        else:
            det_use = detect_followers_list_screen(
                d, source_profile_username=source_profile_username
            )
        if reused_provided_det:
            try:
                log(
                    "debug",
                    "verify_followers_list_surface_is_ct_account",
                    reused_provided_det=True,
                    source_profile_username=str(source_profile_username or "")[:160],
                    is_followers_list=bool(det_use.get("is_followers_list")),
                )
            except Exception:
                pass
        if not bool(det_use.get("is_followers_list")):
            return False

        src = _normalize_handle(source_profile_username or "")
        ab_raw = str(det_use.get("action_bar_title") or "").strip()
        ab = _normalize_handle(ab_raw)
        cand = _normalize_handle(follower_candidate_username or "")

        if cand and ab and ab == cand:
            return False

        if not src:
            return True

        if ab and ab == src:
            return True

        if ab and ab != src:
            return False

        for t in (det_use.get("visible_header_texts") or [])[:30]:
            if _normalize_handle(str(t)) == src:
                return True

        return bool(det_use.get("title_match")) or bool(det_use.get("strict_list_open"))
    except Exception:
        return True


def reset_instagram_to_canonical_state(
    d: u2.Device,
    *,
    reason: str,
    source_profile_username: str = "",
    source_account_context: str | None = None,
) -> dict[str, Any]:
    """
    Best-effort cold restart of Instagram (force-stop → launch → foreground check).
    Never raises; returns a dict with at least ``ok`` for runner compatibility.
    """
    _ = source_account_context
    pkg = str(getattr(config, "INSTAGRAM_PACKAGE", "") or "com.instagram.android")
    out: dict[str, Any] = {
        "ok": False,
        "reason": str(reason or ""),
        "reset_performed": False,
        "package": pkg,
        "source_profile_username": source_profile_username,
        "foreground_after_reset": False,
    }
    try:
        log(
            "info",
            "instagram_canonical_reset_started",
            reset_reason=out["reason"],
            package=pkg,
            source_profile_username=source_profile_username,
        )
        code, _stdout, _stderr = shell(d, f"am force-stop {pkg}")
        out["force_stop_exit_code"] = int(code)
        time.sleep(0.4)
        try:
            d.app_start(pkg, stop=False)
        except Exception as e_app:
            out["app_start_error"] = str(e_app)
            shell(d, f"monkey -p {pkg} -c android.intent.category.LAUNCHER 1")
        time.sleep(0.85)
        fg = bool(verify_app_foreground(d, pkg))
        out["foreground_after_reset"] = fg
        out["reset_performed"] = True
        out["ok"] = fg
        if fg:
            try:
                invalidate_search_surface_cache(reason=f"canonical_reset:{reason}")
            except Exception:
                pass
        log(
            "info",
            "instagram_canonical_reset_complete",
            ok=out["ok"],
            reset_reason=out["reason"],
            foreground_after_reset=fg,
        )
        return out
    except Exception as e:
        out["error"] = str(e)
        log(
            "warning",
            "instagram_canonical_reset_failed",
            error=str(e),
            reset_reason=out["reason"],
            package=pkg,
        )
        return out


def recover_instagram_search_surface_after_launcher_mixup(
    d: u2.Device,
    *,
    phase: str,
    detail: str,
    source_profile_username: str = "",
    source_account_context: str | None = None,
) -> bool:
    """
    Cold-restart Instagram after we detected launcher/universal-search confusion.
    Caller should call open_search afterward. Does not log wrong_search_surface_detected
    (caller already did when applicable).
    """
    invalidate_search_surface_cache("wrong_search_surface_launcher_mixup")
    rr = reset_instagram_to_canonical_state(
        d,
        reason=f"launcher_search_surface_mixup:{phase}:{detail}",
        source_profile_username=source_profile_username,
        source_account_context=source_account_context,
    )
    if not rr.get("ok"):
        log(
            "error",
            "search_surface_wrong_app_launcher",
            phase=phase,
            stage="canonical_reset_failed",
            reset_reason=rr.get("reason"),
            foreground_package=_current_foreground_package(d),
        )
        return False
    log(
        "info",
        "instagram_recovery_after_launcher_search",
        phase=phase,
        detail=detail,
        foreground_after_reset=bool(rr.get("foreground_after_reset")),
    )
    return True


def ensure_global_search_surface(
    d: u2.Device,
    *,
    intended_username: str = "",
    source_profile_username: str = "",
    source_account_context: str = "",
) -> dict[str, Any]:
    """
    Ensure Instagram is foreground and the bottom-nav Search surface is usable.
    Compatible with runner / canonical-reset reentry (keys: ok, reason).
    """
    _ = source_account_context
    pkg = str(getattr(config, "INSTAGRAM_PACKAGE", "") or "com.instagram.android")
    meta: dict[str, Any] = {
        "ok": False,
        "reason": "init",
        "package": pkg,
        "intended_username": intended_username,
        "source_profile_username": source_profile_username,
    }
    try:
        log(
            "info",
            "ensure_global_search_surface_started",
            package=pkg,
            intended_username=intended_username,
            source_profile_username=source_profile_username,
        )
        if not verify_app_foreground(d, pkg):
            try:
                d.app_start(pkg, stop=False)
            except Exception:
                shell(d, f"monkey -p {pkg} -c android.intent.category.LAUNCHER 1")
            time.sleep(0.55)
            if not verify_app_foreground(d, pkg):
                meta["reason"] = "instagram_not_foreground"
                return meta
        if open_search(d):
            meta["ok"] = True
            meta["reason"] = "open_search_ok"
            mark_search_surface_fresh_for_follow_ct()
            log(
                "info",
                "instagram_search_surface_verified",
                phase="ensure_global_search_surface",
                detail="open_search_ok",
            )
            return meta
        if is_lightweight_search_screen(d, pkg):
            if apply_search_surface_reuse_metrics(d, pkg, "ensure_global_fallback"):
                meta["ok"] = True
                meta["reason"] = "lightweight_search_screen"
                log(
                    "info",
                    "instagram_search_surface_verified",
                    phase="ensure_global_search_surface",
                    detail="lightweight_search_screen",
                )
                return meta
        meta["reason"] = "open_search_failed"
        return meta
    except Exception as e:
        meta["reason"] = f"exception:{type(e).__name__}"
        meta["error"] = str(e)
        return meta


def visual_profile_metrics_pass_filter(metrics: dict[str, Any]) -> tuple[bool, str]:
    """
    (passes, reason). When extraction is weak or thresholds are unset, default pass (do not skip target).
    Thresholds: optional VISUAL_PROFILE_METRICS_* on config.
    """
    if not isinstance(metrics, dict):
        return True, "metrics_invalid_skip_filter"

    min_followers = getattr(config, "VISUAL_PROFILE_METRICS_MIN_FOLLOWERS", None)
    max_followers = getattr(config, "VISUAL_PROFILE_METRICS_MAX_FOLLOWERS", None)
    min_posts = getattr(config, "VISUAL_PROFILE_METRICS_MIN_POSTS", None)
    max_posts = getattr(config, "VISUAL_PROFILE_METRICS_MAX_POSTS", None)
    min_following = getattr(config, "VISUAL_PROFILE_METRICS_MIN_FOLLOWING", None)
    max_following = getattr(config, "VISUAL_PROFILE_METRICS_MAX_FOLLOWING", None)

    active_thresholds = [
        x is not None
        for x in (
            min_followers,
            max_followers,
            min_posts,
            max_posts,
            min_following,
            max_following,
        )
    ]
    if not any(active_thresholds):
        return True, "no_metrics_thresholds_configured"

    if not metrics.get("extraction_ok", False):
        return True, "metrics_extraction_failed_skip_filter"

    fc = metrics.get("followers_count")
    pc = metrics.get("posts_count")
    flc = metrics.get("following_count")

    def _chk(
        val: Any,
        lo: Any,
        hi: Any,
        below_reason: str,
        above_reason: str,
    ) -> tuple[bool, str] | None:
        if val is None:
            return None
        try:
            v = int(val)
        except (TypeError, ValueError):
            return None
        if lo is not None and v < int(lo):
            return False, below_reason
        if hi is not None and v > int(hi):
            return False, above_reason
        return None

    for val, lo, hi, br, ar in (
        (fc, min_followers, max_followers, "below_min_followers", "above_max_followers"),
        (pc, min_posts, max_posts, "below_min_posts", "above_max_posts"),
        (flc, min_following, max_following, "below_min_following", "above_max_following"),
    ):
        res = _chk(val, lo, hi, br, ar)
        if res is not None:
            ok_r, reason_r = res
            if not ok_r:
                return False, reason_r
    return True, "metrics_thresholds_pass"


def visual_profile_stats_posts_count(d: u2.Device) -> int | None:
    """Posts count from header stats strip; None if unknown."""
    try:
        m = visual_extract_profile_metrics(d, source_profile_username="")
        pc = m.get("posts_count")
        return int(pc) if pc is not None else None
    except Exception:
        return None


def read_current_profile_username_for_follow_gate(d: u2.Device) -> str:
    """Action-bar / header username on current profile screen (best-effort, short retry)."""
    max_tries = int(
        getattr(config, "PROFILE_ACTION_BAR_USERNAME_READ_MAX_TRIES", 3) or 3
    )
    max_tries = max(1, min(max_tries, 5))
    delay_s = float(
        getattr(config, "PROFILE_ACTION_BAR_USERNAME_READ_RETRY_DELAY_S", 0.25) or 0.25
    )
    delay_s = max(0.12, min(delay_s, 0.45))
    last = ""
    for attempt in range(max_tries):
        try:
            last = str(_visual_read_action_bar_username(d) or "").strip().lstrip("@")
        except Exception:
            last = ""
        if last:
            if attempt > 0:
                try:
                    log(
                        "info",
                        "profile_action_bar_username_read_retry_success",
                        attempt_index=attempt + 1,
                        max_tries=max_tries,
                    )
                except Exception:
                    pass
            return last
        if attempt + 1 < max_tries:
            time.sleep(delay_s)
    return ""


def _visual_raw_follow_invite_visible_quick(d: u2.Device) -> bool:
    """Lightweight Follow / Suivre probe (mirrors runner CT-list raw invite helper)."""
    try:
        if d(text="Follow").exists(timeout=0.07):
            return True
        if d(text="Suivre").exists(timeout=0.05):
            return True
        if d(textContains="Follow").exists(timeout=0.05):
            return True
        if d(description="Follow").exists(timeout=0.04):
            return True
    except Exception:
        return False
    return False


def visual_candidate_follow_pre_follow_screen_guard(
    d: u2.Device,
    *,
    source_profile_username: str,
    pkg: str,
    pick: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """
    Before ``perform_follow_safe(profile_already_open=True)``, confirm we are not back on the
    source (CT) profile or followers list, and that a follow invite is visible on the current surface.
    """
    from navigation_engine import NavigationEngineState, observe_instagram_state

    src_raw = str(source_profile_username or "").strip()
    p = dict(pick) if isinstance(pick, dict) else {}
    vcid = str(p.get("visual_candidate_id") or "").strip()
    exp_pkg = str(pkg or getattr(config, "INSTAGRAM_PACKAGE", "") or "").strip()

    ab_title = ""
    try:
        ab_title = read_current_profile_username_for_follow_gate(d)
    except Exception:
        ab_title = ""

    sn = _normalize_handle(src_raw)
    an = _normalize_handle(ab_title)

    out: dict[str, Any] = {
        "ok": False,
        "reason": "init",
        "action_bar_title": ab_title,
        "navigation_state": "",
        "navigation_confidence": 0.0,
        "navigation_reason": "",
        "follow_header_state": "",
        "followers_list_xml_hint": False,
        "raw_follow_invite_visible": False,
        "visual_candidate_id": vcid,
        "source_profile_username": src_raw,
    }

    nav = observe_instagram_state(
        d,
        expected_package=exp_pkg,
        last_known_state=NavigationEngineState.CANDIDATE_PROFILE.value,
        context={
            "phase": "visual_follow_pre_follow_guard",
            "visual_candidate_id": vcid,
            "source_profile_username": src_raw,
            "disable_followers_visual_fallback": True,
            "expected_state": "CANDIDATE_PROFILE",
        },
    )
    out["navigation_state"] = str(nav.get("state") or "")
    out["navigation_confidence"] = float(nav.get("confidence") or 0.0)
    out["navigation_reason"] = str(nav.get("reason") or "")

    try:
        det_fresh, _pre_follow_fresh_hier_xml = detect_followers_list_screen_fresh(
            d, source_profile_username=src_raw
        )
        try:
            log(
                "info",
                "visual_follow_pre_follow_guard_fresh_detect_used",
                source_profile_username=src_raw,
                visual_candidate_id=vcid or None,
                followers_detect_hierarchy_source=str(
                    det_fresh.get("followers_detect_hierarchy_source") or ""
                ),
                is_followers_list=bool(det_fresh.get("is_followers_list")),
            )
        except Exception:
            pass
        out["followers_list_xml_hint"] = bool(
            det_fresh.get("is_followers_list")
            and (
                bool(det_fresh.get("strict_list_open"))
                or bool(det_fresh.get("relaxed_list_open"))
            )
        )
    except Exception:
        out["followers_list_xml_hint"] = False

    try:
        out["follow_header_state"] = _follow_ui_state_snapshot(d)
    except Exception:
        out["follow_header_state"] = "unknown"

    out["raw_follow_invite_visible"] = _visual_raw_follow_invite_visible_quick(d)

    if sn and an and sn == an:
        out["ok"] = False
        out["reason"] = "current_screen_is_source_profile"
        return out

    if out["followers_list_xml_hint"]:
        out["ok"] = False
        out["reason"] = "current_screen_is_followers_list"
        return out

    if (
        out["navigation_state"] == NavigationEngineState.FOLLOWERS_LIST.value
        and out["navigation_confidence"] >= 0.45
    ):
        out["ok"] = False
        out["reason"] = "navigation_says_followers_list"
        return out

    if not out["raw_follow_invite_visible"] and out["follow_header_state"] != "follow":
        out["ok"] = False
        out["reason"] = "follow_invite_not_visible"
        return out

    out["ok"] = True
    out["reason"] = "candidate_profile_surface_ok"
    return out


def reacquire_target_profile_for_follow(
    d: u2.Device,
    *,
    target_username: str,
    source_profile_username: str,
    source_account_context: str = "",
    follower_candidate: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """
    Re-open the follower row profile when navigation drifted before follow/mute.
    """
    _ = source_account_context
    out: dict[str, Any] = {"ok": False, "method": "none"}
    try:
        tgt = _normalize_handle(target_username or "")
        cur = _normalize_handle(read_current_profile_username_for_follow_gate(d))
        if tgt and cur and cur == tgt:
            out["ok"] = True
            out["method"] = "already_on_target_profile"
            return out

        fc = follower_candidate if isinstance(follower_candidate, dict) else None
        if not fc or not str(fc.get("username") or "").strip():
            out["method"] = "missing_follower_candidate"
            return out

        pkg = getattr(config, "INSTAGRAM_PACKAGE", "") or ""
        if open_follower_profile_from_list(d, fc, source_profile_username, pkg):
            out["ok"] = True
            out["method"] = "follower_row_reopen"
        else:
            out["method"] = "open_follower_profile_failed"
        return out
    except Exception as e:
        out["method"] = "exception"
        out["error"] = str(e)
        return out


def send_dm_safe(
    d: u2.Device,
    username: str,
    draft_text: str,
    dm_state: str,
    *,
    target_row: Any = None,
) -> dict[str, Any]:
    global _LAST_DM_SEND_RESULT
    _ = target_row
    msg = str(draft_text or "")
    enable_real = bool(getattr(config, "ENABLE_REAL_DM_SEND", False))
    out: dict[str, Any] = {
        "target_username": username,
        "thread_state": dm_state,
        "enable_real_send": enable_real,
        "message_len": len(msg),
        "precheck_ok": True,
        "sent": False,
        "reason": None,
        "blocked_event": None,
        "failure_event": None,
    }

    if not enable_real:
        out["blocked_event"] = "dm_send_blocked_config_disabled"
        _LAST_DM_SEND_RESULT = dict(out)
        return out

    if dm_state == "existing_thread" and bool(
        getattr(config, "SEND_DM_SKIP_EXISTING_THREAD", True)
    ):
        out["blocked_event"] = "dm_send_blocked_existing_thread"
        _LAST_DM_SEND_RESULT = dict(out)
        return out

    composer = _dm_find_focus_composer(d)
    if composer is None:
        out["precheck_ok"] = False
        out["reason"] = "no_composer"
        _LAST_DM_SEND_RESULT = dict(out)
        return out

    try:
        cur = composer.get_text() or ""
    except Exception:
        cur = ""
    out["composer_text_len_before_send"] = len(cur)
    draft_ok = cur.strip() == msg.strip()
    out["draft_matches_before_send"] = draft_ok

    btn, status, meta = wait_for_dm_send_button_after_draft(
        d,
        composer,
        thread_state=dm_state,
        draft_matches_expected=bool(draft_ok),
    )
    out["send_button_candidate_count"] = meta.get("send_button_candidate_count", 0)
    out["coordinate_fallback_used"] = bool(meta.get("send_button_coordinate_fallback"))
    w, h = _dm_screen_size_for_dm(d)
    cb = _dm_composer_bounds_u2(composer)

    if status != "ok" or btn is None:
        out["precheck_ok"] = False
        out["reason"] = "send_button_missing"
        try:
            _ensure_debug_dirs()
            stem = f"dm_send_missing_{int(time.time() * 1000)}"
            ss_path = str(_SCREENSHOTS_DIR / f"{stem}.png")
            xml_path = str(_XML_DIR / f"{stem}.xml")
            screenshot(d, ss_path)
            try:
                hier = d.dump_hierarchy(compressed=False)
            except Exception:
                hier = d.dump_hierarchy()
            with open(xml_path, "w", encoding="utf-8") as fh:
                fh.write(hier)
            art = _dm_send_button_debug_artifacts(
                hierarchy_xml=hier,
                composer_bounds=cb or {},
                screen_w=w,
                screen_h=h,
                debug_screenshot_path=ss_path,
                debug_xml_path=xml_path,
            )
            out.update(art)
        except Exception as e:
            out["debug_screenshot_error"] = str(e)
        _LAST_DM_SEND_RESULT = dict(out)
        return out

    try:
        btn.click()
        out["sent"] = True
    except Exception as e:
        out["failure_event"] = "dm_sent_failed"
        out["reason"] = str(e)
    _LAST_DM_SEND_RESULT = dict(out)
    return out


def clear_dm_draft(d: u2.Device) -> bool:
    t0 = time.perf_counter()
    ed = _dm_find_focus_composer(d)
    if ed is None:
        _perf["dm_draft_clear_ms"] = (time.perf_counter() - t0) * 1000
        return False
    try:
        ed.click()
        time.sleep(0.05)
        try:
            ed.clear_text()
        except Exception:
            ed.set_text("")
    except Exception:
        _perf["dm_draft_clear_ms"] = (time.perf_counter() - t0) * 1000
        return False
    try:
        left = (ed.get_text() or "").strip()
    except Exception:
        left = "?"
    _perf["dm_draft_clear_ms"] = (time.perf_counter() - t0) * 1000
    return len(left) == 0


def finalize_dm_draft_before_back(d: u2.Device) -> bool:
    t0 = time.perf_counter()
    kt0 = time.perf_counter()
    try:
        _try_dismiss_keyboard_light(d)
    except Exception:
        pass
    _perf["keyboard_hide_ms"] = (time.perf_counter() - kt0) * 1000
    _perf["finalize_before_back_ms"] = (time.perf_counter() - t0) * 1000
    return True


def return_to_profile_from_dm(d: u2.Device, username: str, pkg: str | None = None) -> bool:
    t0 = time.perf_counter()
    try:
        _try_dismiss_keyboard_light(d)
    except Exception:
        pass
    pkg = pkg or config.INSTAGRAM_PACKAGE
    deadline = time.monotonic() + float(getattr(config, "DM_BACK_TO_PROFILE_MAX_WAIT_S", 3.0))
    t_back = time.perf_counter()
    presses = 0
    max_backs = 18
    while time.monotonic() < deadline and presses < max_backs:
        if verify_profile(d, username):
            _perf["back_press_ms"] = (time.perf_counter() - t_back) * 1000
            _perf["profile_detect_wait_ms"] = (time.perf_counter() - t0) * 1000
            _perf["dm_back_to_profile_ms"] = (time.perf_counter() - t0) * 1000
            return True
        try:
            d.press("back")
            presses += 1
        except Exception:
            break
        time.sleep(float(getattr(config, "DM_BACK_TO_PROFILE_POLL_S", 0.08)))
    _perf["back_press_ms"] = (time.perf_counter() - t_back) * 1000
    _perf["profile_detect_wait_ms"] = (time.perf_counter() - t0) * 1000
    _perf["dm_back_to_profile_ms"] = (time.perf_counter() - t0) * 1000
    return False


def cleanup_dm_after_send_button_missing(d, pkg=None) -> bool:
    """
    Best-effort cleanup after send button missing.
    Must not send anything.
    Goal:
    - clear draft if possible
    - hide keyboard if possible
    - go back to profile if currently in DM
    - return True/False but never raise
    """
    try:
        clear_dm_draft(d)
    except Exception:
        pass
    try:
        finalize_dm_draft_before_back(d)
    except Exception:
        pass
    try:
        p = str(pkg or config.INSTAGRAM_PACKAGE or "")
        return bool(return_to_profile_from_dm(d, "", p))
    except Exception:
        pass
    return False


def verify_app_foreground(d: u2.Device, package: str | None = None) -> bool:
    package = package or config.INSTAGRAM_PACKAGE
    try:
        cur = d.app_current()
        pkg = (cur or {}).get("package", "")
        ok = pkg == package
        log("info", "app_foreground_check", package=package, current=pkg, ok=ok)
        return ok
    except Exception as e:
        log("error", "app_foreground_check_failed", error=str(e))
        return False

